// ─────────────────────────────────────────────────────────────────────────────
// top.v · L11 唯一顶层（**M0 范围**：时基 + 安全态）
//
// 本版只做 M0 需要的东西，刻意最小：
//   ① `clk_gen` 产生全部节拍     ② `i2s_tx` 把样点送到板载 DAC
//   ③ ⭐ **安全态**：`PA_EN_n` 驱动**高**（Console 上是 `SD_MODE`，⚠️ 低 = `Shutdown`）、无窄脉冲
//   ④ ⭐ **板级"活体见证"**：一个心跳 LED —— 系统时钟留在板载域，
//      即使别的模块出问题，**心跳仍活着 ⇒ 故障可观测**（上一个项目踩过"全设计换 PLL 时钟后板子全死、
//      连 UART 都没输出"的坑，见 `files/20-代码/已知问题与风险清单.md` `K-41` / 经验库 `L31`）
//
// ⭐ 引脚全部来自**官方 60K 引脚约束**（`files/开发板原理图/tang_mega_60K_pins.cst`，本地、被 gitignore）：
//    `clk=V22`(LVCMOS33) `rst_n=AA13`(LVCMOS15/PULL_UP)
//    `HP_BCK=Y17` `HP_WS=AB17` `HP_DIN=AA16`
//    🔴 **`PA_EN_n=Y14`**（⚠️ **2026-09-22 换板后改**：⛔ **不是 `AB16`** —— 那是 `USB_TERM_RXDN`）
//       ⚠️ `Y14` 属 **`BANK9` = 1.5 V** ⇒ ⛔ **必须 `LVCMOS15`**；⭐ `PULL_MODE=UP`
//       🔴 它接 **`MAX98357A` 的 `SD_MODE`** ⇒ ⭐ **高 = 出声（Left），低 = `Shutdown`**
//          ⇒ ⭐ **"驱动高"是本设计出声的前提**（⚠️ 旧的"低有效"语义已作废）
//    ⭐ `led_heartbeat=V13`（⚠️ **2026-09-22 换板后改**：⛔ **不是 `T18`** —— 那是 `SDRAM1_D6`）
//
// ⚠️ 复位：**同步复位、低有效**（`files/20-代码/W3接口冻结表.md` §〇 约定 2）。
//    ⚠️ 但同步复位意味着**上电到第一个时钟沿之间寄存器是未定义的** —— 对 `PA_EN_n` 这种
//    "必须上电就是正确电平"的脚，靠的是**引脚上拉**：`.cst` 里给 `PA_EN_n` 设 `PULL_MODE=UP`
//    ⇒ FPGA **配置期间**它被上拉为高，而 ⭐ **高在 Console 上恰好是"出声"那一侧** ⇒ ⭐ **依然是安全态**。
//
// ⛔ 本版**还没有**（按第一周范围，属后续任务）：
//    · ⚠️ **结构上还没按"三个包顶层"接**：`files/20-代码/代码总览图.md` 的最终形态是
//      `top.v` → `w3a_top` / `w3b_top` / `w3c_top`。本版 `w3c_top` 还不存在，
//      所以**直接例化 `i2s_tx`**；等 `w3c_top` 落地后改成例化包顶层即可（M0 判据不受影响）
//    · `test_mode` 测试音源（T20 / 乙）—— 现在 `i2s_tx` 送的是**静音 0**，所以**上板听不到声音**
//    · `note_manager` / `voice` / `mixer`（T8~T10 / 乙）
//    · `adc_spi_master` / `chan_scan`（T11/T12 / 丙）· LED 驱动 `tlc5916`（T5 / 丙）
//      ⇒ M0 判据里的 `OE_n=1 无窄脉冲` 那一条要等 `T5` 落地后再接进顶层（⛔ 不凭空编引脚）
// ─────────────────────────────────────────────────────────────────────────────
`timescale 1ns/1ps

module top #(
    // ⭐⭐ 功放使能策略（`R-16` / `K-42` / `K-61`）—— **默认值已按"交付用途"定**：
    //   · `1`（**默认**）= 复位释放并等待 `PA_ON_DELAY` 后**开功放** ⇒ ⭐ **交付/上板必须用这个**，
    //     否则板载 `NS4263` 永远关断 ⇒ **喇叭与耳机都没声音**，而且**这种"没声音"很难查**
    //     （波形全对、I2S 全对、DAC 也有信号，只是功放被关着）。
    //   · `0` = 功放**永远关断**（0 个下降沿）⇒ ⭐ **这是 M0 的"安全态"验证档**，
    //     由 `tb/top/tb_top_m0.sv` 显式传 `0` 来验"上电不该开功放、不该有窄脉冲"。
    //   📌 为什么默认改成 1：`top.v` 是**交付顶层**，默认值必须让板子**能出声**；
    //     "安全态"是**测试配置**，⛔ 不该当成交付默认值（那等于把"没声音"设成默认行为）。
    parameter integer PA_ON_AFTER_RESET = 1,
    // 开功放前的等待周期数（避免上电"啪"一声；默认 ~21 ms @50 MHz）
    // ⚠️ 用【无位宽】字面量：`20'd1_048_576` 会被截成 20 位 ⇒ 变成 0（2^20 需要 21 位）
    parameter integer PA_ON_DELAY       = 1_048_576,
    // ⭐ 心跳 LED 翻转周期（clk 数；默认 0.5 s @50 MHz。tb 会传小值以便快速验证）
    parameter integer HEARTBEAT_DIV     = 25_000_000,
    // 与 `clk_gen` / `i2s_tx` 保持一致的音频参数
    parameter integer SAMPLE_W          = 24,
    parameter integer DATA_BITS         = 16,
    // ⭐⭐ T57（2026-09-21）：**开机自检音**（⛔ 不依赖任何传感器）
    //   · `1`（**默认**）= 复位后自动起一个 **3 音和弦**（A4 / C#5 / E5）⇒
    //     ⭐ **上板就能听到声音**，用于证明"整条出声链在真硅片上通了"。
    //   · `0` = **完全静音** ⇒ ⭐ 这是 **M0 安全态/静音验证档**，
    //     由 `tb/top/tb_top_m0.sv` 显式传 `0` 来验"静音就是真的静音"。
    //   📌 为什么默认是 1：`top.v` 是**交付顶层**，默认值必须让板子**能出声**；
    //     "静音"是**测试配置**，⛔ 不该当交付默认值（同 `PA_ON_AFTER_RESET` 的 `R-16` 教训）。
    parameter integer DEMO_CHORD_ON     = 1,
// ⭐⭐ 2026-10-04（codex 只读评审「阶段 1」）：**Test Mode 编译期开关（双码流）**
//   🔴 动机（实测）：当前最差 setup 前三条全部是
//      `g_sound.tm_enable_r_s3/Q → …u_adsr/env_level_o_*`
//      （按 19.417 ns 余量预算计 +0.267/+0.356/+0.420）⇒
//      ⭐ **Test Mode 的高扇出选择锥就是第一瓶颈**。
//   ✅ `1`（**默认**，诊断码流）= 行为与改动前**逐字一致**（现有测试台与上板习惯不变）；
//      `0`（旧资源对照档，非竞赛正式码流）= 整条 Test Mode 通路**不进网表**（⛔ 不是"运行时拉低 enable"
//      —— 那样逻辑还在、锥还在）。
//   ⚠️ 两个配置必须**显式记录**（本参数值 + 其它参数），⛔ 不能依赖 IDE 上次留下的值。
//   2026-10-13 更正：正式码流保持 1；只有显式资源对照构建才改为 0。
// 2026-10-13 correction: Test Mode is a competition feature, not debug-only.
// 0 is retained solely for explicitly labeled resource/timing comparisons.
parameter integer TEST_MODE_EN       = 1,
    // 与 w3b 链路一致的参数（改这里要同时核对 `POLY_TARGET`）
    parameter integer POLY_TARGET       = 32,
    parameter integer OSC_PER_VOICE     = 2,
    // ⭐ 开机自检音的**起音延时**（clk 数；默认 ≈40 ms @50 MHz）
    //    ⚠️ 提成参数是为了**让 tb 能改小** —— 否则 tb 要跑 200 万拍才能听到音，
    //       仿真会慢到超时（实测 120 s 都不够）。
    parameter integer DEMO_NOTE_DELAY   = 2_000_000,
    // ⭐⭐ 开机自检音的**保持时长**（clk 数；默认 **50_000_000 = 1 秒** @50 MHz）
    //   ⭐ 用户 2026-09-23 拍板：⭐ **"让每个和弦响 1s，只起到自检作用"**。
    //   🔴 **为什么必须让它停**（⭐ 实测发现）：
    //      ⚠️ 原来自检和弦 **"一响就不停"**（⛔ 不发 `note_off`）
    //      ⇒ 🔴 **它的 voice 一直占着、声音一直在** ⇒
    //         ⚠️ 手弹时听到的是 **"自检和弦 + 我弹的音" 混在一起**
    //         （⭐ `SOURCE_A_SEL=0` 只切了"新音符从哪来"，⚠️ 切不掉已经起音的和弦）。
    //      ⭐ 实测证据：e2e tb 里 `nm_gate = 0x08000000`（⭐ 一个 voice 恒 held）
    //         ⇒ ⭐ 等它"自己安静"**永远等不到**。
    //   ⭐ 改后：⭐ 响 1 秒 ⇒ ⭐ **逐个发 `note_off`**（⭐ 轴 0/1/2）⇒
    //      ⭐ 之后 `demo_fired` 自锁 ⇒ ⛔ 不再发任何音 ✅
    //   📌 它仍然完成"自检"使命：⭐ 上电听得到 ⇒ ⭐ **证明出声链通了**。
    parameter integer DEMO_HOLD_CYC     = 50_000_000,

    // ⭐⭐ evt_merge 源 A 的来源选择（2026-09-23 新增，见下方 §源 A 仲裁）
    //   🔴 **2026-09-26 更新**：⭐ 源 A 现在是 **`seq_arb` 三级仲裁**（手弹/曲谱/演示）
    //      ⇒ ⭐ 本参数**只在"强制档"时才管用**（⭐ 见下方 §源 A 仲裁）：
    //        · 0 => ⭐ **走 `seq_arb` 自动仲裁**（⭐ **默认** —— 手弹 + 曲谱可叠加）
    //        · 1 => ⚠️ **强制演示和弦**（⭐ 保留给 `T57` 的 `tb_top_sound` 验收）
    //   📌 **为什么保留它**：⭐ `tb_top_sound`（`T57` 验收）依赖"演示和弦独占源 A"
    //      ⇒ ⚠️ 删了它**等于自己废掉一张验收单**（⭐ `R-16`/`K-69` 的教训）。
    parameter integer SOURCE_A_SEL      = 0,

    // ⭐⭐ 源 B：节拍器 / 鼓机【二选一】（⭐ 2026-09-26 新增 · `T34`/`U-8`）
    //   · 0 => ⭐ **节拍器**（⭐ **默认** —— ⭐ 上板听的就是这个拍子声）
    //   · 1 => ⭐ **鼓机**（Kick/Snare/HiHat/Clap + 16 步音序器）
    //   ⭐ 用户 2026-09-24 拍板："鼓机和节拍器是**二选一**的
    //      —— 使用节拍器时不会用鼓机，用鼓机不用节拍器"
    //   ⚠️ **为什么是编译期参数而⛔ 不是运行时切换**：
    //      ⚠️ 那需要改 `calib_cmd`（⭐ **上板要测的模块**）⇒ ⭐ 本轮⛔ 一行不碰它。
    //      📌 将来要"现场切" ⇒ ⭐ 只需把 `sel_drum` 换成寄存器即可（⭐ 结构已就绪）。
    //   ⭐⭐ **2026-09-30 深夜：默认档 = 【1 = 鼓机】**（⭐ 用户明确裁定 ✅）
    //      📌 **历史（⭐ 保留，⛔ 别删）**：⭐ 本参数在 **09-30 白天**曾被裁定回 **0（节拍器）** ——
    //         起因：⭐ 鼓机 worktree 为了**出鼓机诊断档的 `.fs`** 把它设成 1，
    //         ⚠️ cherry-pick 进主树时**没改回 0** ⇒ 主树默认档一度变成鼓机
    //         ⇒ 🔴 默认档下节拍器不出声（⭐ 源 B 二选一）⇒ `tb_met_start_top` T6 变红 ✅
    //      ✅ **现在（⭐ 09-30 深夜 · ⭐ 用户："上板 PnR 默认烧鼓机"）**：⭐ **默认 = 1（鼓机）** ✅
    //      ⭐ **为什么这次不会再出那次事故**（⭐ 已实测，⛔ 不是推测）：
    //         ① 那次事故的**根因是 tb 依赖顶层默认值** ⇒ ⭐ 而 09-30 的纪律**已经修好了它**：
    //            `tb_met_start_top` 显式 `.SEL_DRUM(0)`（`:90`）·
    //            `tb_drum_timbre_top` 显式 `.SEL_DRUM(1)`（`:87`）
    //            ⇒ ⭐ **T6 不会因本行改动而变红** ✅
    //         ② ⭐ 源 B 仍被**运行时** `met_on_r` 串住（⭐ 复位 = 关 ⇒ 本文件的 `met_on_r`）⇒
    //            ⭐ 换默认档**不会让鼓机上电就响**（⭐ 要发串口 `'B'`）⇒ 行为可预期 ✅
    //      ⚠️ **代价（⭐ 必须知道）**：⭐ 凡**未显式声明**本档、又例化 `top` 的 tb，
    //         从此测的是**鼓机源**（⭐ 而不再被综合扫掉）⇒ ⭐ 若某个 tb 是在"验节拍器那一路"，
    //         ⭐ **必须由它自己补 `.SEL_DRUM(0)`** —— ⭐ 这正是下面那条纪律的要求 ✅
    //      📌 **纪律（⭐ 保留，⭐ 与默认值取什么无关）**：⭐ 凡"验某一路"的 tb **必须显式声明
    //         自己需要的档**（⭐ `.SEL_DRUM(0)` / `.SEL_DRUM(1)`），
    //         ⛔ 不依赖顶层默认值 —— ⚠️ 默认值一变，tb 就测了**别的**源，
    //         而判据是**红的**，看起来像被测模块坏了（⭐ 白查半天 ✅）
    parameter integer SEL_DRUM          = 1,
    // ⭐⭐ **静音节拍器**（⭐ 2026-09-26 新增 · 用户上板实测后要求）
    //   · 0 => 🔇 **节拍器【完全不出声】**（⭐ 只听键盘）
    //   · 1 => ⭐ **正常**（⭐ **默认** —— 交付行为不变）
    //
    //   🔴🔴 **为什么要这个参数**（⭐ 用户上板实测）：
    //      ⚠️ 用户反馈"**只听键盘**"时**节拍器一直在响** ⇒ ⭐ 无法单独判断键盘音色/音量。
    //      📌 **调音阶段必须能把节拍器静音** —— ⚠️ 否则任何"键盘是不是太小/太破"
    //         的判断都被节拍器干扰（⭐ 它就是本轮"按键音量偏小"的主诉背景）。
    //
    //   ⭐⭐ **为什么用【编译期参数】而⛔ 不是 `force` / 运行时开关**：
    //      · ⚠️ `force` 是**纯仿真手段**（⛔ 不综合）⇒ 🔴 **上板根本用不了**
    //      · ⚠️ 运行时切换要改 `calib_cmd`（⭐ **上板要测的模块**）⇒ ⭐ 本轮⛔ 一行不碰它
    //      · ⭐ 编译期参数**零风险**：⭐ 不改任何接口、⭐ 不动冻结的事件格式、
    //         ⭐ 且**默认值 1 保证交付行为逐位不变**。
    //
    //   ⭐ **实现方式（⭐ 关键）**：⭐ 把它**与进 `src_b_valid`**
    //      ⇒ ⭐ 节拍器仍然**照常运行**（`beat_gen`/`metronome` 内部状态不变），
    //        ⭐ 但**事件被挡在 `evt_merge` 之外** ⇒ ⭐ **确实不出声**。
    //      📌 **为什么不直接停 `beat_gen`**：⚠️ 那样 `bg_beat` 也会停
    //         ⇒ 🔴 **心跳 LED 不闪**（⭐ 本文件的 `blink_i(bg_beat)`）
    //         ⇒ ⭐ 上板会以为"板子死了"。⭐ 本做法**心跳照常** ✅
    //      📌 且 `drum_gen`（⭐ 源 B 另一档）也共用 `beat_gen` ⇒ ⭐ 不动它更安全。
    //
    //   ⭐ **怎么用（⭐ 上板调音时的推荐配置）**：
    //      ```
    //      .METRONOME_ON (0)      // 🔇 节拍器静音 ⇒ 只听键盘
    //      ```
    //      ⇒ ⭐ 重新 PnR + 烧写 ⇒ ⭐ **上板就是纯键盘声** ⇒ ⭐ 可单独判断
    //        "单音够不够响 / 破不破 / 力度有没有层次"。
    //      ⚠️ **调完记得改回 1** —— ⭐ 节拍器是**评分项**（⭐ 恢复时重跑 PnR）。
    //      📌 **建议**：⭐ 与 `RESERVED_N` 无关（⭐ 事件被挡 ⇒ 不占 voice）
    //         ⇒ ⭐ **⛔ 不用同步改任何别的地方** ✅
    //
    //   🔴🔴 **2026-09-28 改动：`0` ⇒ `1`（⭐ 用户要求"把节拍器加回来"）**
    //      ⭐ **为什么必须改成 1**：⭐ 本参数是**编译期总闸**，
    //         ⚠️ 若仍为 0 ⇒ 🔴 **按键打开了 `met_on_r` 也照样没声**
    //         （⭐ 因为 `src_b_valid` 被这里恒 0 挡住）。
    //      ⭐ **改成 1 不会自己响**：⭐ 现在由**运行时信号 `met_on_r`** 再串一级
    //         ⇒ ⭐ 上电默认关（`met_on_r` 复位 = 0）⇒ ⭐ **行为与改动前一致** ✅
    //      📌 即：`METRONOME_ON` = **编译期总闸**；`met_on_r` = **运行时开关**。
    parameter integer METRONOME_ON      = 1,
    // ⭐⭐ **`|Δpos|` 诊断开关**（⭐ 2026-09-28 新增，⭐ **默认【关】**）
    //
    //   ⭐ **它做什么**：⭐ 在 FPGA 侧统计**全轴 `max|Δpos|` + 出峰轴号**，
    //      通过 `'P'` 命令回一个 `Q<轴号><dpos>` 包（⭐ 见 `u_pos_probe_dpos`）。
    //   🔴 **为什么要它**：⭐ 串口轮询只有 **~4 Hz/轴**（⭐ 实测 247 ms）
    //      ⇒ ⛔ **看不到 20 ms 的按压瞬态** ⇒ ⭐ 只能在 FPGA 侧测。
    //
    //   ⚠️⚠️ **默认必须是 0**（⭐ 用户 2026-09-28 拍板："代码留着，但不要放进工程综合"）：
    //      · ⭐ 它**每拍**跑 16 组比较器 ⇒ 🔴 **吃时序余量**（⭐ 实测 Fmax 52.576 → **50.578**，
    //        余量 **5.2% → 1.2%**）
    //      · ⭐ 它还会**拖慢所有顶层 tb 的仿真** ⇒ 🔴 `tb_e2e`/`tb_top_sound` **超时**
    //      ⇒ ⭐ **它是【临时工具】，⛔ 不是交付内容** ⇒ ⭐ 默认关，⭐ 要用时临时改 1 再 PnR。
    //
    //   📌 **综合时怎么被去掉**：⭐ `DPOS_DIAG=0` 是**编译期常量** ⇒
    //      ⭐ 仲裁器里那一项恒 0 ⇒ ⭐ `u_pos_probe_dpos` 的输出**无人使用**
    //      ⇒ ⭐ 整块（含 16 组比较器 + 3 级寄存器）**被优化掉** ✅
    //  ⚠️⚠️ **2026-09-29 实测教训：⭐ 这个位⛔ 不要为了"顺手"长期置 1** ——
    //     ⭐ 置 1 会让那 **16 组峰值比较器**在**每一个顶层 tb** 里都真跑
    //     ⇒ 🔴 **顶层仿真明显变慢** ⇒ ⭐ `tb_e2e_key_to_sound` **撑爆 300 s 超时预算**
    //        （⭐ 日志里其实已有 `PASS:` ⇒ ⚠️ **是超时预算太紧，⛔ 不是功能失败**）✅
    //  ⭐ **正确用法**：⭐ 默认 **0** ✅ ⇒ ⭐ **只在【要出诊断 bitstream 的那一次 PnR】前临时改成 1**，
    //     ⭐ PnR 完**立刻改回 0** ✅
    //  📌 见 `files/20-代码/已知问题与风险清单.md` 的 `K-161` ✅
    parameter integer DPOS_DIAG        = 0,   // ⭐ 0 = 关（默认）· ⭐ 1 = 开（仅出诊断 bitstream 时临时用）
    // ⭐⭐ **失谐开关**（⭐ 2026-09-27 新增，⭐ 问 A/B 对比用）
    //   · 0 => ⚠️ **关闭失谐**（⭐ 两 lane 同频同相 ⇒ 相干 ×2 ⇒ 旧行为）
    //   · 1 => ⭐ **开启失谐**（⭐ **默认** ⇒ 440.0 / 441.7 Hz，拍频 1.72 Hz）
    //
    //   🔴 **为什么要做成可切**：⭐ 用户反馈 *"按键的声音比较低沉浑厚，
    //      跟印象里听到的 wav 好像不太一样"*
    //      ⇒ ⭐ 怀疑是**失谐的拍频**造成的（⭐ 每秒 1.72 次音量起伏）
    //      ⇒ ⭐ **必须能 A/B 对比才知道**（⭐ 主观听感⛔ 不能靠推理）。
    //   📌 **透传给 `oscillator_bank.DETUNE_ON`**（⭐ 见下方例化）。
    parameter integer DETUNE_ON         = 1,
    // ⭐⭐ **2026-09-28 新增：⭐ 失谐深度 `DETUNE_SH`**（⭐ `Minimal-A` 的第 ① 项）
    //   ⭐ 语义：⭐ 第二个 osc 的增量 = `base_inc + (base_inc >> DETUNE_SH)`
    //      ⇒ ⭐ **越大 ⇒ 偏移越小 ⇒ 两 lane 的拍【越慢】**（`T ≈ 2^DETUNE_SH / f`）
    //   ⭐ **改 8 → 9**：⭐ 拍周期 `T = 256/f` → **`512/f`**
    //      ⇒ ⭐ 当前音域 **1.85 ~ 4.65 s**（原 0.92 ~ 2.33 s）
    //      ⇒ ⭐ **3 秒的音符里不到一个完整周期** ⇒ 起伏不再是"一鼓一鼓"
    //   ⚠️ **必须与 lane 加权【一起做】**（⭐ 见 `tdm_render_mixer` 的 `LANE_W0/W1`）：
    //      · ⭐ 只变慢不变量 ⇒ 拍谷仍是 **−∞ dB**（声音仍会周期性**消失**）
    //      · ⭐ 只变浅不变慢 ⇒ 起伏仍在，只是幅度小些
    //   📌 **透传给 `oscillator_bank.DETUNE_SH`**（⭐ 见下方例化；⭐ 命名参数覆盖是合法用法 ⇒ 队友文件一字不改）
    //   📌 依据：`files/20-代码/失谐拍频与长音起伏-方案分析-20260928.md` §15.1
    parameter integer DETUNE_SH         = 9,
    // ⭐⭐ 鼓机的内置节奏型（⭐ 0~3，⭐ 见 `drum_gen.step_mask_of`）
    //   · 0 = **BASIC** · 1 = **HOUSE** · 2 = **ROCK** · 3 = **DANCE_FILL**
    //     （⭐ 全部 4/4 · 16 步 · 见 `drum_gen.v` 的 `step_mask_of` 里 `DRUM_0`~`DRUM_3` 的命名原文）
    //   🔴 **2026-10-01 更正**：旧注释写"0=四拍基本型(Rock) · 1=八分摇滚 ·
    //      2=十六分放克 · 3=圆舞曲(3/4)" ⇒ ⚠️ **过时**（⭐ 2026-09-30 已按用户给的表全部换掉，
    //      ⛔ **没有"圆舞曲"那一型**）。
    //   ⭐⭐ **2026-09-29：⭐ 它从【编译期参数】降级为【上电默认值】** ✅
    //      ⭐ 真正生效的选择现在是**运行时寄存器 `drum_pattern_r`**
    //         （⭐ 串口 `'D'` ⇒ 循环 `0→1→2→3→0`，⭐ 见下方 §节奏型寄存器）
    //      ⇒ ⭐ 本参数**只决定复位后的初值**（⭐ 默认 0 ⇒ ⭐ 上电行为与改动前逐位一致 ✅）
    //      📌 **为什么必须改成运行时**：⭐ 用户上板要求"鼓机节奏型要能**现场切**"——
    //         ⚠️ 编译期参数意味着"换一个节奏型就得重新 PnR + 烧写"（⭐ 一次 ~10 分钟）
    //         ⇒ ⭐ 上板试听 4 个型**根本没法比**（⭐ 这正是用户提这个需求的原因）。
    parameter integer DRUM_PATTERN_ID   = 0,

    // ⭐⭐ **鼓机 / 节拍器的固定音色**（⭐ 2026-09-29 新增 · 修"鼓跟着键盘音色变"的 bug）
    //
    //   🔴 **问题（⭐ 用户上板实测）**：⭐ 换键盘音色（⭐ 串口 `'I'` / S2 按键）时
    //      **鼓的声音也跟着变** ⇒ ⭐ 鼓机和键盘**听起来像同一件乐器**。
    //   🔎 **根因**：⭐ 源 B（节拍器/鼓机）原来把 `timbre_valid` **恒接 `1'b0`**
    //      ⇒ ⭐ `note_manager` 走
    //         `new_timbre = cur_timbre_valid ? cur_timbre : default_timbre_i`
    //         （⭐ `note_manager.v` 的 `default_timbre_i`）的**兜底分支**
    //      ⇒ ⭐ 拿到的是 `default_timbre_i = timbre_sel_r`（⭐ **键盘当前音色**，⭐ 本文件的 `timbre_sel_r`）
    //      ⇒ 🔴 **鼓的音色 = 键盘的音色** —— ⛔ 完全不是我们要的（鼓必须有自己的音色）。
    //
    //   ⭐ **修法**：⭐ 给源 B 一个**自己的、固定的**音色 ⇒ ⭐ 与键盘**彻底解耦**
    //      （⭐ 键盘怎么切都⛔ 不影响鼓）。
    //   ⭐ 取值 **2 = PIANO**（⭐ `wavetable_bank.v:3`：`0=BASS 1=GUITAR 2=PIANO 3=PAD`（行号可能漂移，以符号为准））：
    //      ⭐ PIANO 是 **zero-DC 25% 脉冲** ⇒ ⭐ 谐波最丰富、**起音最"脆"**
    //      ⇒ ⭐ 最接近打击乐（⭐ 而 BASS/GUITAR/PAD 都是**持续音**音色，⭐ 敲下去像"按了个和弦"）。
    //   📌 **为什么做成参数**：⭐ 鼓的音色是**主观听感**（⭐ 必须能 A/B 对比，⛔ 不能靠推理）——
    //      ⭐ 上板改一个数字重烧即可重听（⭐ 与 `DETUNE_ON` / `METRONOME_ON` 同一手法 ✅）。
    //   ⚠️ **它同时管住节拍器**（⭐ 源 B 是二选一）⇒ ⭐ 语义上叫"源 B 音色"更准
    //      —— ⭐ 节拍器本来就是"打击乐式的拍子声"，⭐ 同样**不该跟着键盘走** ✅
    parameter [1:0] DRUM_TIMBRE = 2'd2,
    // ⭐⭐ 上电自动零点标定的**等待时间**（clk 数；默认 10M ≈ **200 ms** @50 MHz）
    //   ⭐ `calib_autotare` 用它决定"等多久才开始标定"。
    //   ⚠️ **太短 ⇒ 霍尔供电/LDO 还没稳 ⇒ 🔴 零点记错**（⚠️ 而且**不可察觉**：
    //      表现为"松手位置不对"，⭐ 会被误当成阈值设错）。
    //   📌 **提成参数**是为了**让 tb 能改小** —— ⚠️ 否则仿真要跑 10M 拍。
    parameter integer AUTOTARE_DELAY_CLK = 10_000_000,

    // ⭐⭐ `calib_span` 的**三个可调参数**（⭐ 2026-09-24 新增）
    //   🔴 **为什么必须提出来**：⚠️ 原来 `calib_span` 直接用模块默认值
    //      ⇒ `WAIT_TIMEOUT_CLK = 50_000_000`（= **1 秒**仿真时间 @50 MHz）
    //      🔴 而 tb **改不了** ⇒ ⚠️ 每次跑到"等按键"的超时兜底就要烧 1 秒
    //      📌 **实测**：`tb_top_sound` 因此跑了 **108 秒**（其余 tb 都是几秒）
    //   📌 **手法照抄上面的 `AUTOTARE_DELAY_CLK`**（⭐ 先例就在旁边）
    //   ⚠️ **上板默认值 = 真值**（⛔ 不要改这几个默认值）
    //
    //   🔴🔴 **2026-09-24 上板实测后调整（⭐ 重要）**：
    //      ⭐ 现象：⭐ 发 `'S'` 后**每次都回 `!`（被拒）**，⭐ 每个隔 1 秒（= 超时）。
    //      ⭐ 诊断：⭐ 用新增的 `'P'` 命令读 `af0_pol` ⇒ **实测读数**：
    //         · 松手：⭐ 2746 ~ 2904（⭐ Δ ≈ **158**）
    //         · 按住不动：⭐ 2880 ~ 2903（⭐ Δ ≈ **23**）
    //      🔴 而原来的 `STABLE_TOL = 8` ⇒ ⚠️ **按住时也超**（⭐ 23 > 8）
    //         ⇒ ⭐ `stable_cnt` 每帧被清零 ⇒ 🔴 **永远攒不到 24 帧 ⇒ 必超时**
    //      📌 对照仿真：⭐ `tb_e2e` 里 `af0_pol = 2854` ⇒ ⭐ **与实测同一量级** ✅
    //      ⇒ ✅ **修法：⭐ 放宽容限**（⭐ 不是改逻辑）：
    //         · `SPAN_STABLE_TOL`：8 → **48**（⭐ 覆盖实测 23，⭐ 留 2 倍余量）
    //         · `SPAN_STABLE_NEED`：24 → **8**（⭐ 8×500µs = 4 ms，⭐ 够快又够稳）
    //         · `SPAN_VOTE_N`：32 → **8**
    //         · `SPAN_VOTE_TOL`：16 → **96**（⭐ 覆盖按住时的抖动）
    parameter integer SPAN_WAIT_TIMEOUT_CLK = 50_000_000,
    parameter integer SPAN_STABLE_NEED      = 8,
    parameter integer SPAN_VOTE_N           = 8,
    parameter [11:0]  SPAN_STABLE_TOL       = 12'd48,
    parameter [11:0]  SPAN_VOTE_TOL         = 12'd96,

    // T18: P4 right-hand ADC is optional until its cable and MCP3208 are
    // physically installed. Keeping this 0 prevents an open MISO line from
    // being interpreted as full-depth vibrato on today's two-ADC setup.
    parameter integer RIGHT_ADC_ENABLE       = 1,   // ⭐ 2026-10-09 用户指令：默认右手板联调档（⛔ 不再用 =0 当基线）
    //  ⭐⭐ 2026-09-29 合并（⭐ 队友 `t31b-final-6db-s2`）：⭐ **满行程失真的二分诊断** ✅
    //   ⭐ 打开后：⭐ 按键位置**只控 note on/off**，⭐ 每个键盘音用**固定力度**
    //      ⇒ ⭐ 行程深度**无法**再影响音量 ⇒ ⭐ 用来二分"失真来自力度通路还是别处" ✅
    parameter integer FIXED_VELOCITY_DIAG    = 0,
    parameter [7:0]   FIXED_VELOCITY_VALUE   = 8'd96,

    //  ⭐ 板载 S2 音色按键的**去抖时间**（⭐ 参数化 ⇒ ⭐ 仿真里能快速跑完整按键流程 ✅）
    parameter integer TIMBRE_BTN_DB_MS        = 5,
    // ⭐⭐ 2026-10-04（T5）：⭐ **延音踏板去抖时间**（ms）—— ⭐ 与按键同一量级
    //   ⚠️ 机械踏板（⭐ 尤其脚踏开关）抖动比按键大 ⇒ ⭐ 上板若发现"踩一下跳两下"就加大它 ✅
    parameter integer PEDAL_DB_MS             = 5,

    // ═══════════════════════════════════════════════════════════════════════
    //  ⭐⭐ 2026-10-04：⭐ **T3 实时变调总闸**（⭐ 交付档 = **开**）
    //
    //  ⭐ 出处：⭐ `files/20-代码/T3-后续计划-20261003.md` §P5 ＋ ⭐ 用户裁定
    //     （⭐ 2026-10-04：「⭐ **最终效果没问题就行**」⇒ ⭐ 采用**影子数组**架构）
    //
    //  ⭐ 语义：⭐ 本参数**原样透传**给 `u_note_manager.T3_EN`：
    //     · `= 1`（⭐ **本档 = 交付**）⇒ ⭐ 变调核心**参与综合**（⭐ 影子数组版）
    //     · `= 0`                ⇒ ⭐ 变调核心**整段不展开**，`voice_phase_inc_o` 回到 T2 原式
    //
    //  📌 **为什么做成 top 参数而⛔ 不是改 `note_manager` 的默认值**：
    //     ⭐ 那样会让**所有不传 `T3_EN` 的模块级 tb** 一起变成『开着 T3』
    //     ⇒ ⚠️ 它们的判据范围被动扩大（⭐ 与『一次只改一个变量』冲突）
    //     ⇒ ⭐ 现在只有**顶层构建**打开它，⭐ 模块级 tb 一个都不受影响 ✅
    //
    //  ⚠️ **`transpose_semi_i` 已经接好**（⭐ `u_fader_gear.transpose_semi_o`）：
    //     ⭐ 上电 `gear = 档 1（颤音）` ⇒ `semi = 0` ⇒ ⭐ **输出与 T2 相同**（⭐ 见 T1 判据）
    //     ⭐ 要真正变调：⭐ `'J'` 切到**档 0**，⭐ 再动推子 / 发 `'F'`/`'G'`/`'H'` ✅
    //
    //  ⭐ **为什么是『影子数组』而⛔ 不是『数组 ＋ 输出 mux』**（⭐ 实测）：
    //     · 数组＋输出 mux：`T_Lut 33040` · `CLS 85%` · 🔴 **`PR0004` 490 根不布通**
    //     · ⭐ 影子数组　：`T_Lut 29622`（⭐ 比 T3 关的基线 **还低 1417**）· ⛔ **没有输出 mux**
    //     ⇒ ⭐ 详见 `sim/evidence/t3-probe-shadow-20261004/README.md` ✅
    // ═══════════════════════════════════════════════════════════════════════
    parameter integer T3_ENABLE               = 1,
    //  ⭐ 2026-10-09（乙）：HDMI 显示模式 —— ⛔ 端口一个没变，只加【参数】
    //    SCOPE_MODE = 0 → 波形（原行为）· 1 → 李萨如（XY，交付默认）
    //    依据 files/20-代码/李萨如显示-设计-20261009.md
    //  ⚠️⚠️ 必须声明在【端口参数表】里，⛔ 不能声明在 module 体内 ——
    //      iverilog 会报 "Parameter cannot be overriden in the scope it has been declared in"
    //      ⇒ tb 无法覆盖 ⇒ 音频 tb 会被迫跑 XY 路径 ⇒ 仿真超预算（实测踩到）
    parameter integer SCOPE_MODE              = 1,
    parameter integer XY_DELAY                = 64,     // Y 取延迟 64 个样本（≈1.3 ms）
    parameter integer XY_GAIN                 = 8       // XY 增益（⭐ 图形大小 ∝ 它；台阶 = 它/8 像素）
) (
    input  wire clk,             // V22 · 50 MHz
    input  wire rst_n,           // AA13 · 低有效（同步复位）

    // ── ⭐⭐ 节拍器开关按键（⭐ 2026-09-28 新增 · `S2` / `AB13`）───────────
    //   ⭐ 用户拍板：**用 AB13 的 S2 做节拍器开关**（按一下开、再按一下关）。
    //   🔴 **`AB13` 属 `BANK9` = 1.5 V**（与 `rst_n`/`AA13` **同 bank**）
    //      ⇒ ⭐ `.cst` 必须写 `LVCMOS15` + `BANK_VCCIO=1.5`（⛔ 写 3.3 V 会冲突）。
    //   ⚠️ **跨线冲突（已向用户报告）**：ESP32 线原计划把 `AB13` 当"起播按键"
    //      ⇒ ⭐ 本轮**先给节拍器用**，那边文档已标注"暂时占用，后续可能改"。
    //  ⭐⭐ 2026-09-29 合并（⭐ 用户裁定 = 方案 B）：⭐ **`AB13`/S2 改做【音色切换】按键** ✅
    //   · ⭐ 节拍器**不再占用 S2** ⇒ ⭐ 改走**串口命令 `'B'`**（⭐ `CMD_METRONOME` ✅）
    //   · ⭐ 本端口与串口 `'I'` **并存**：⭐ 两者都让 `timbre_sel_r` 循环 `0→1→2→3→0` ✅
    //   · ⭐ **Z-safe**：⭐ 本端口**未连接时是 `Z`** ⇒ ⭐ 按"未按下"处理（⭐ 现有 tb 不用改 ✅）
    input  wire timbre_btn_i,    // AB13 · S2 · 低有效（上拉 ⇒ 按下 = 0）

    // ── 音频（板载 DAC = `MAX98357A`，⛔ 不需要 MCLK）──────────────
    //   ⭐ 2026-09-22 换板 Tang Console 60K：`PT8211`+`NS4263` → `MAX98357A`
    //      （I2S 输入 + 内置 DAC + D 类功放，三合一）
    output wire HP_BCK,          // Y17 · 位时钟 3.125 MHz（= 64 × fs）
    output wire HP_WS,           // AB17 · 帧时钟 48.828125 kHz（低 = 左）
    output wire HP_DIN,          // AA16 · 串行数据（⭐ 标准 I2S 左对齐）
    output wire PA_EN_n,         // 🔴 Y14（⛔ 不是 AB16）· 接 MAX98357A 的 SD_MODE ⇒ ⭐ **高 = 出声**，见下方说明

    // ── ⭐⭐ 音频（外置 DAC = `PCM5102A` 模块，⭐ 2026-09-25 新增）──────────
    //   🔴 **为什么加**（⭐ `U-26`）：⭐ 用户**没有喇叭** ⇒ ⭐ 必须走外置 DAC 接有源音箱。
    //
    //   ⭐⭐ **路线 A：两路并存**（⭐ 用户拍板）
    //      · ⭐ **板载 `MAX98357A` 通路【完全不动】** ⇒ ⭐ 两路同时可用
    //      · ✅ 现有 I2S 回归判据（`tb_i2s_tx*` / `tb_top_m0` / `tb_e2e`）**全部不受影响**
    //      · ⚠️ 代价：⭐ 多占 3 个引脚
    //
    //   ⭐ **引脚**（⭐ `PMOD1`，⭐ 已两处核对：引脚预算表 + Console 原理图 行 466/471/473）：
    //      · `F20` = `PMOD1_IO3` · `E22` = `PMOD1_IO4` · `D22` = `PMOD1_IO5`
    //      📌 `PMOD1_IO0/1/2`（`W19`/`W20`/`F19`）**已被 SPI 占用** ⇒ ⚠️ `IO3/4/5` 是空着的 ✅
    //
    //   ⚠️ **数据源与板载完全同源**（`sample_mono` + 同一组 `bclk_en`/`frame_start`）
    //      ⇒ ⭐ 两路**天然同步**，⛔ 不需要额外的相位对齐。
    //   ⚠️ **`PCM5102A` 可以不接 `MCLK`**（⭐ 内部 PLL 从 BCK 恢复）
    //      ⇒ 🔴 **前提：⭐ 模块必须带板载晶振**（`U-26`）⇒ ⛔ 否则会没声/爆音。
    output wire I2S2_BCK,        // F20 · PMOD1_IO3 · 外置 DAC 位时钟
    output wire I2S2_LRCK,       // E22 · PMOD1_IO4 · 外置 DAC 帧时钟
    output wire I2S2_DIN,        // D22 · PMOD1_IO5 · 外置 DAC 串行数据

    // ── T15 · 右手拨弦比较器（P4 的 LM393，开漏上拉后高有效）─────────────
    //   PMOD1_IO6/7 是当前唯一冻结且未占用的一对相邻 3.3 V GPIO。
    input  wire pluck_up_i,      // E21 · PMOD1_IO6 · TRIG_UP
    input  wire pluck_down_i,    // D21 · PMOD1_IO7 · TRIG_DN

    // ── 板级活体见证 ────────────────────────────────────────────────
    // H5: passive master_mix waveform display.
    output wire [2:0] tmds_d_p_0, tmds_d_n_0,
    output wire tmds_clk_p_0, tmds_clk_n_0, hpd_en,
    output wire led_heartbeat,   // V13 · CFG_LED 绿路（SYS_ACT）

    // ── ⭐⭐ W3a 采集链 · 左手区 ADC（MCP3208 ×2）────────────────────────
    //   ⭐ **2026-09-23 新增** —— ⭐ **"按琴键出声"的物理入口**。
    //   ⚠️ 走 **`J9` 排针**（⛔ 不是 PMOD —— 那 16 根已分完），
    //      ⭐ 6 根**连续相邻**（`SDRAM0_D2..D7`）。
    //   🔴 **`MISO` 两根独立**（`K-06`）—— ⚠️ 因为 `adc_farm` 是**并行锁步**，
    //      ⛔ "共享 MISO 靠未选中片高阻"在同时选中时不成立（会推挽对打）。
    //   ⚠️ **⛔ 用这些脚就不能插 `SDRAM` 模块**（`0Ω` 二选一）
    // ⭐⭐ SPI 组（⭐ 2026-09-23 晚重排成【预留 6 片】的向量）
    //   ⭐ **为什么改成向量**（⭐ 用户要求"CS 共 6 根、MISO 也预留"）：
    //      ⭐ 现在硬件只有 **2 片**（左手板 L/R = 16 轴），⚠️ 但**扩展板计划加左手板**
    //      ⇒ ⭐ **端口先留 6 位** ⇒ ⚠️ 以后加片**只改 `.cst` + `N_ADC`**，
    //         ⛔ **不用再动端口**（⭐ 也就不用再改 tb）。
    //   📌 **`N_ADC` 仍为 2**（⭐ 实例化的片数）⇒ ⭐ 高 4 位【暂不接】，
    //      ⚠️ 它们有内部上拉 ⇒ ⭐ 不会悬空乱跳 ✅
    //   🔴 **`MISO` 必须每片独立**（⭐ `K-06`）：⭐ `adc_farm` 是【锁步并行】
    //      ⇒ ⚠️ 多片同时选中 ⇒ ⭐ 共享一根会**推挽对打**。
    //   ⭐ **引脚按"每片 `MISO`+`CS` 同排左右"排**（⭐ 扩展板好走线）：
    //      片0=`N3/N4` · 片1=`N5/N6` · 片2=`N7/N8` · 片3=`N9/N10`
    //      ⚠️ `N11/N12`=`+5V/GND` · 片4=`N13/N14` · 片5=`N15/N16`
    //   ⚠️ **⛔ 用这些脚就不能插 `SDRAM` 模块**（`0Ω` 二选一）
    output wire spi_sclk,         // E14 · J9 N1 · SDRAM0_D0
    output wire spi_mosi,         // E13 · J9 N2 · SDRAM0_D1
    input  wire [5:0] spi_miso,   // N3/N5/N7/N9/N13/N15（⭐ 每片一根，内部上拉）
    output wire [5:0] spi_cs_n,   // N4/N6/N8/N10/N14/N16（⭐ 每片一根）

    // ═══════════════════════════════════════════════════════════════════════
    // ⭐⭐ TLC5916（LED 演奏指引）—— ⭐ 2026-09-23 分配引脚
    //
    //   ⭐ **现状**：⭐ `rtl/drivers/tlc5916_driver.sv` **已存在**（⭐ 队友丙的 `T5`），
    //      ⚠️ 但 **⛔ 还没例化进本文件** ⇒ ⭐ **本版只把【引脚 + 顶层端口】加上**，
    //      ⭐ 驱动例化留给丙（⭐ 遵"一人一文件"，⚠️ 避免两边冲突）。
    //
    //   ⭐ **信号数与共享性**（⭐ 依据 `引脚预算核算.md`）：
    //      · ⭐ `SDI` / `CLK` / `LE` —— ⭐ **三根【共享】**（⭐ 所有片同一总线）
    //      · 🔴 `OE` —— ⭐ **每板独立**（⚠️ 用于"只点亮正在操作的那块板"）
    //
    //   ⭐ **为什么预留 5 根 `OE`**（⭐ 用户 2026-09-23 拍板）：
    //      ⭐ "板 B 还没画，但**预留 3 根甚至 5 根**，后续可能会加左手板"
    //      ⇒ ⭐ 现在只画/接实际用到的，⭐ 但**顶层端口先留够**
    //         —— ⚠️ 这样以后加板**只改 `.cst` 接线**，⛔ 不用改 RTL 端口。
    //
    //   📌 **`OE` 低有效**（⭐ `tlc5916` 的 `OE` = Output Enable，**低有效**）
    //      ⇒ ⭐ 端口名带 `_n`，⚠️ 与 `PA_EN_n` 同一命名习惯。
    //   🔴 **引脚来源**：⭐ 从 `J9` 取（⭐ 与 ADC 的 `D2..D7` 同组 ⇒ 走线近）
    //      ⚠️ `PMOD` 的 16 根**已全部分配完**（⭐ 见 `引脚预算核算.md` §3.1）。
    // ═══════════════════════════════════════════════════════════════════════
    output wire led_sdi,         // B21 · J9 N18 · SDRAM0_D8（⭐ 共享数据，可级联）
    output wire led_clk,         // B18 · J9 N19 · SDRAM0_A12（⭐ 共享时钟）
    output wire led_le,          // A21 · J9 N17 · SDRAM0_D9（⭐ 共享锁存）
    //   ⭐ `OE` ×5：⭐ 预留（⭐ 当前实际用 0~2 根，⚠️ 其余留空）
    //      ⭐ 低有效 ⇒ ⭐ 上电应为**高**（⭐ 不使能，灯全灭）
    output wire [4:0] led_oe_n,  // B17/C17/D17/A19/A18 · J9 N20..N24

    // ═══════════════════════════════════════════════════════════════════════
    // ⭐⭐ 串口（⭐ 2026-09-23 阶段C 新增）—— ⭐ 标定命令 + 曲谱事件的入口
    //
    //   🔴 **为什么现在才加**：⭐ `top.v` 此前**完全没有 UART 端口** ——
    //      ⚠️ 所以 `evt_uart_rx` / `calib_cmd` / `uart_rx` **全都接不进来**。
    //
    //   ⭐⭐ **当前走 J9 排针 + 外接 USB-TTL**：
    //      · USB-TTL TX → J9 N26 / D14 / `uart_rx`
    //      · USB-TTL RX ← J9 N25 / D15 / `uart_tx`
    //      · GND 必须共地；两根信号均为 LVCMOS33。
    //   ⚠️ Console 的 V14/U15 虽是板载 BL616 的 3.3 V UART，但该链路运行
    //      TangCore 固件且端口不便接线，故不是本设计的实际串口入口。
    //
    //   ⭐ `uart_rx`（⭐ 输入）：⭐ 串口**空闲是高电平**
    //      ⇒ ⚠️ 若 PC 没插，悬空会读到随机跳变 ⇒ 🔴 可能被当成假起始位持续误触发
    //      ⇒ ⭐ **`.cst` 里给它 `PULL_MODE=UP`**（⭐ 默认拉到空闲态）。
    //
    //   ⚠️ `uart_tx`（⭐ 输出）：⭐ **本版先只把引脚与端口加上，⛔ 不接任何逻辑**
    //      ⇒ 🔴 因为 `uart_tx.v` **不存在**（⭐ 要新写）
    //      ⇒ ⭐ **恒驱动 0**（⚠️ 串口线会一直处于"break"状态，⛔ 但无害 ——
    //         ⭐ 因为现在**没有任何东西在听它**；⭐ 且它不会被优化掉，
    //         ⚠️ 留给下一步直接接上）。
    //      📌 下一步：写 `uart_tx.v` ⇒ 把 `calib_span` 的进度回传出去
    //         （⚠️ 否则 16 轴 `span` 标定**没有进度提示、几乎没法操作**）。
    // ═══════════════════════════════════════════════════════════════════════
    input  wire uart_rx,         // D14 · J9 N26 · 外接 USB-TTL TX → FPGA
    output wire uart_tx,         // D15 · J9 N25 · FPGA → 外接 USB-TTL RX

    // ═══════════════════════════════════════════════════════════════════════
    // 🔴🔴 预留引脚 · 画板线申请单（🔴 **2026-10-03**）—— ⭐ **20 根 = 9 出 + 11 入**
    //
    //   ⭐ 出处：`files/10-硬件/引脚申请单-给FPGA线-20261003.md`（⭐ **§1 表格 = 真值**）
    //   🔴🔴 **ball 由画板侧座表 + PCB 布局锁定** ⇒ ⛔ **端口名可改，ball 不可改**。
    //   🔴🔴 **本段只加【顶层端口 + `.cst` 约束】—— ⭐ 背后逻辑【未接入】**
    //      ⇒ ⭐ 只为"**引脚预留**"（⭐ 申请单 §6 第 1 步：先只加脚 + 端口，跑 PnR 看是否仍 0 setup/0 hold）。
    //      ⚠️ **它们现在由【常量 / 异或归并寄存器】驱动**（⭐ 见文件末尾 `reserved_in_r` 段）
    //         —— 🔴 **这是必须的**：⭐ 否则综合会把**未用的输入**优化掉、
    //            **未用的输出**接死 ⇒ ⚠️ `constr/top.cst` 里的 `IO_LOC` 会**悬空**。
    //   📌 电平：⭐ 20 根**全部 3.3 V**（`BANK1`/`BANK2`/`BANK8`）
    //      ⇒ ⛔ **都不在 `BANK9`（1.5 V）** ⇒ ⭐ 全 `LVCMOS33`。
    //   ⭐ `.cst` 纪律：⭐ **输出才给 `DRIVE=8`**；⭐ 输入只写
    //      `IO_TYPE`/`PULL_MODE`/`BANK_VCCIO`（🔴 输入带 `DRIVE` 报 `CT1108`，⭐ `top.cst:216-221`）。
    //   ⭐ 11 个输入**全部 `PULL_MODE=UP`**（⭐ Console 板上无外部上拉）。
    //   🔴 **接入功能逻辑时**（⭐ 按申请单 §6 分批：矩阵 → 编码器/踏板 → ESP32 UART → WS2812）
    //      ⇒ ⭐ **必须把该端口在文件末尾的驱动行删掉**（⛔ 否则**多驱动** ⇒ 综合报错）。
    // ═══════════════════════════════════════════════════════════════════════
    // ── ① 控制板 · 4x4 矩阵（行出 / 列入）· `J9` 针 27/28/31/32/34/35/36/37 ──
    output wire [3:0] ctrl_row_o,   // D16/E16/E17/F16 · J9 针 27/28/31/32（出 · 矩阵行）
    input  wire [3:0] ctrl_col_i,   // F15/C20/D20/D19 · J9 针 34/35/36/37（入 · 矩阵列 · 上拉）
    // ── ② 控制板 · EC11 编码器 · `J9` 针 38/39/40 ─────────────────────────
    input  wire enc_a_i,            // E19 · J9 针 38 · SDRAM0_A1（入 · EC11 A 相 · 上拉）
    input  wire enc_b_i,            // C19 · J9 针 39 · SDRAM0_A2（入 · EC11 B 相 · 上拉）
    input  wire enc_sw_i,           // C18 · J9 针 40 · SDRAM0_A3（入 · EC11 按压 · 上拉）
    // ── ③ 控制板 · WS2812 数据 · `PMOD0` 针 5 ─────────────────────────────
    output wire ctrl_ws_o,          // C22 · PMOD0 针 5 · IO6（出 · 控制板灯带数据）
    // ── ④ 三键踏板 · `PMOD0` 针 7/8/6 ─────────────────────────────────────
    input  wire pedal_sus_i,        // F18 · PMOD0 针 7 · IO4（入 · 延音 · 上拉）
    input  wire pedal_loop_rec_i,   // E18 · PMOD0 针 8 · IO5（入 · looper 录/停 · 上拉）
    input  wire pedal_loop_play_i,  // B22 · PMOD0 针 6 · IO7（入 · looper 播 · 上拉）
    // ── ⑤ ESP32 独立 UART · `PMOD0` 针 9/10（⭐ 与串口屏【不抢】`uart_rx`）──
    output wire esp_uart_tx_o,      // G21 · PMOD0 针 9 · IO2（出 · → ESP32 的 RX）
    input  wire esp_uart_rx_i,      // G22 · PMOD0 针 10 · IO3（入 · ← ESP32 的 TX · 上拉）
    // ── ⑥ 拓展板 WS2812 三路 · `PMOD1` 针 11/12/9 ─────────────────────────
    output wire [2:0] ws_strip_o    // W19/W20/F19 · PMOD1 针 11/12/9 · IO0/IO1/IO2（出）
);

    // ── ⭐ R-08：外部复位先同步（异步输入 → 同步释放）──────────────────
    //    `rst_n` 来自板上按键，是**异步**输入；直接当同步复位分发，可能让不同 FF
    //    在释放沿采到不同值（一部分复位、一部分没复位，且各模块互相不一致）。
    //    `rst_sync` 把它过两级 FF ⇒ 释放沿在全设计里**严格同一个时钟沿**。
    //    ⚠️ 代价：复位生效晚 2 拍（40 ns），对本设计无影响。
    //    ⛔ 注意它**不**去抖按键抖动（那是 `debounce`/T14 的事）。
    wire rst_n_sync;
    rst_sync #(.STAGES(2)) u_rst_sync (
        .clk         (clk),
        .rst_n_async (rst_n),
        .rst_n_sync  (rst_n_sync)
    );

    // ═══════════════════════════════════════════════════════════════════════
    // ⭐⭐ 节拍器开关按键（⭐ 2026-09-28 新增 · `S2` / `AB13`）
    //
    //   ⭐ 需求（用户 2026-09-28 拍板）：⭐ 按一下 **开**、再按一下 **关**。
    //
    //   ⭐ 链路（⭐ 严格按 `debounce.sv` 头部关于 `sync_input` 的说明与 `K-62` 的纪律）：
    //      `met_btn_i`（板外异步）→ `sync_input`（打两拍）→ `debounce`（5 ms）
    //      → `key_down[0]`（按下沿，单周期脉冲）→ 翻转触发器 `met_on_r`
    //
    //   🔴 **为什么必须先同步再去抖**：`debounce` 在**端口层面不例化** `sync_input`
    //      （⭐ 它自己的注释就写明"由顶层负责同步"）⇒ ⚠️ 顺序反了会把亚稳态
    //      直接喂进去抖计数器 ⇒ ⭐ 可能整拍采错、甚至多计一次按下。
    //
    //   ⭐⭐ **`met_btn_s` 的 Z-safe 处理（⭐ 关键，⛔ 否则要改 ~9 个 tb）**：
    //      · 硬件：`PULL_MODE=UP` ⇒ 空闲 = 1、按下 = 0
    //      · 仿真：**未连接 ⇒ `Z`** ⇒ ⭐ 这里按"未按下(1)"处理
    //      ⇒ ⭐ `===` 能识别 `Z`/`X`（⛔ 普通 `==` 会得到 `x` 并传播）
    //      ⇒ ⭐ 现有 9 个例化 `top` 的 tb **一个都不用改** ✅
    //      📌 两边语义一致：**只有确确实实看到 `0` 才算按下**。
    // ═══════════════════════════════════════════════════════════════════════
    //  ⭐⭐ 2026-09-29 合并（⭐ 用户裁定 = 方案 B）：⭐ **节拍器不再用 S2 按键 ⇒ 改走串口命令 `'B'`** ✅
    //   🔴 原链路（⭐ `met_btn_i` → `sync_input` → `debounce` → `key_down` → 翻转）
    //      ⭐ 已**整体删除** ⇒ ⭐ 省一套同步 + 去抖逻辑 ✅
    //   ⭐ 新链路：⭐ 串口 `'B'`（⭐ `calib_cmd.CMD_METRONOME` ✅）⇒ `cmd_met_req`（⭐ **单周期脉冲** ✅）
    //      ⇒ ⭐ 翻转 `met_on_r`（⭐ 语义与原来**完全一致**：⭐ 一次开、再一次关 ✅）
    //   📌 为什么：⭐ 用户裁定 —— ⭐ **`AB13`/S2 让给音色切换按键** ✅
    //      （⭐ 节拍器改用串口 ⇒ ⭐ 上位机/串口屏都能开关它 ✅）

    //  ⭐⭐ 2026-09-29 合并（⭐ 方案 B）：⭐ **节拍器改走串口 `'B'`**（⭐ `AB13`/S2 让给音色按键 ✅）
    //   ⚠️ **必须在【使用之前】声明** —— ⭐ `default_nettype none` 下不存在隐式网线 ✅
    wire cmd_met_req;           // ⭐ 'B' ⇒ 节拍器 **开/关切换**

    // ⭐ 翻转触发器：发一次 `'B'` 开、再发一次关
    //   ⭐ 复位后默认【关】⇒ ⭐ 与"加节拍器之前"的行为完全一致（⛔ 不会自己响）
    reg met_on_r;
    always @(posedge clk) begin
        if (!rst_n_sync) met_on_r <= 1'b0;
        else if (cmd_met_req) met_on_r <= ~met_on_r;
    end

    //  ⭐⭐ 2026-09-29 合并（⭐ 队友版 + 方案 B）：⭐ **当前音色寄存器**
    //   ⚠️ **必须声明在【模块层】** —— ⭐ 队友的 `tb\top\tb_top_timbre_button.sv` 用
    //      ⭐ **`dut.timbre_sel_r`**（⭐ 模块层路径）观察它 ⇒ ⚠️ 放在 generate 里**绑不上**
    //      （⭐ 实测：8 条 `Unable to bind wire/reg/memory` ✅）
    //   ⭐ 驱动它的是 generate 里的 `'I'`/S2 逻辑（⭐ 模块层信号在 generate 内可读可写 ✅）
    reg [1:0] timbre_sel_r;

    //  ⭐ 串口 `'I'` 的音色脉冲（⭐ 提前声明 ⇒ ⭐ 下面的按键块要用它 ✅）
    wire cmd_timbre_req;
    wire cmd_scope_mode_req;   // ⭐ 2026-10-10（乙）：'Q' 显示模式切换

    //  ⭐⭐ 2026-09-29 合并（⭐ 队友版 + 方案 B）：⭐ **板载 S2 音色按键**
    //   ⚠️ **必须放在【模块层】** —— ⭐ 队友的 `tb\top\tb_top_timbre_button.sv` 用
    //      ⭐ **`dut.timbre_sel_r`** 观察它 ⇒ ⭐ 放 generate 里它**绑不上**（⭐ 实测 8 条 bind 错误 ✅）
    //   ⭐ 异步机械按键 ⇒ ⭐ **先同步、再去抖、只认一次按下** ✅
    //   ⭐ 与串口 `'I'` **并存**：⭐ 两者都循环 `0→1→2→3→0` ✅
    wire timbre_btn_s = (timbre_btn_i === 1'b0) ? 1'b0 : 1'b1;   // ⭐ Z-safe
    wire timbre_btn_sync;
    wire timbre_btn_down;
    sync_input #(
        .W         (1),
        .STAGES    (2),
        .RESET_VAL (1'b1)
    ) u_timbre_btn_sync (
        .clk      (clk),
        .rst_n    (rst_n_sync),
        .async_in (timbre_btn_s),
        .sync_out (timbre_btn_sync)
    );
    debounce #(
        .NKEY       (1),
        .CLK_HZ     (50_000_000),
        .DB_MS      (TIMBRE_BTN_DB_MS),
        .ACTIVE_LOW (1)
    ) u_timbre_btn_debounce (
        .clk        (clk),
        .rst_n      (rst_n_sync),
        .key_in     (timbre_btn_sync),
        .key_level  (),
        .key_down   (timbre_btn_down),
        .key_up     (),
        .enc_a      (1'b1),
        .enc_b      (1'b1),
        .enc_sw     (1'b1),
        .enc_a_lvl  (),
        .enc_b_lvl  (),
        .enc_sw_lvl (),
        .enc_sw_down(),
        .enc_sw_up  (),
        .enc_cw     (),
        .enc_ccw    (),
        .enc_state  (),
        .enc_err    ()
    );
    always @(posedge clk) begin
        if (rst_n_sync !== 1'b1)
            timbre_sel_r <= 2'd0;                       // ⭐ 上电 = BASS
        else if (cmd_timbre_req || timbre_btn_down)
            timbre_sel_r <= timbre_sel_r + 2'd1;
    end

    // ═══════════════════════════════════════════════════════════════════════
    // ⭐⭐ 2026-10-04（T5）：⭐ **延音踏板**（⭐ `pedal_sus_i` = F18 · PMOD0 针 7 · 上拉、低有效）
    //
    //   ⭐ 链路（⭐ 与音色按键**同一套纪律**：⭐ **先同步、再去抖**）：
    //      `pedal_sus_i`（板外异步）→ Z-safe 归一 → `sync_input`（打两拍）
    //      → `debounce`（`PEDAL_DB_MS`，低有效）→ ⭐ `sus_pedal_r`（**1 = 踩住**）
    //
    //   ⚠️ **Z-safe（⭐ 关键，⛔ 否则要改 ~13 个例化 `top` 的 tb）**：
    //      · 硬件：`PULL_MODE=UP` ⇒ 空闲 = 1、踩下 = 0
    //      · 仿真：**未连接 ⇒ `Z`** ⇒ ⭐ 这里按"未踩(1)"处理（⭐ 用 `===` 判 `0`）
    //      ⇒ ⭐ 现有 tb **一个都不用改** ✅（⭐ 与上面 `timbre_btn_s` **完全同款** ✅）
    //
    //   📌 **消费方**：⭐ `u_note_manager.sus_pedal_i`（⭐ 它在 `g_sound` 里读模块层这根线 ✅）
    //   📌 本模块**不再把 `pedal_sus_i` 并进 `reserved_in_xor`** —— ⭐ 它现在有真消费者了 ✅
    //      （⭐ 依据本文件末段 §"接入功能逻辑时"的纪律：⭐ 输入侧要把它从异或归并里摘掉 ✅）
    //   ⚠️ 语义细节（⭐ 为什么只影响手弹、松踏板为什么是"全放"）⇒ 见 `note_manager.v` 的端口注释 ✅
    // ═══════════════════════════════════════════════════════════════════════
    wire pedal_sus_s = (pedal_sus_i === 1'b0) ? 1'b0 : 1'b1;   // ⭐ Z-safe：未连接按"未踩"
    wire pedal_sus_sync;
    wire sus_pedal_r;                                          // ⭐ 1 = 踩住（低有效已翻正）
    sync_input #(
        .W         (1),
        .STAGES    (2),
        .RESET_VAL (1'b1)
    ) u_pedal_sus_sync (
        .clk      (clk),
        .rst_n    (rst_n_sync),
        .async_in (pedal_sus_s),
        .sync_out (pedal_sus_sync)
    );
    debounce #(
        .NKEY       (1),
        .CLK_HZ     (50_000_000),
        .DB_MS      (PEDAL_DB_MS),
        .ACTIVE_LOW (1)
    ) u_pedal_sus_debounce (
        .clk        (clk),
        .rst_n      (rst_n_sync),
        .key_in     (pedal_sus_sync),
        .key_level  (sus_pedal_r),
        .key_down   (),
        .key_up     (),
        .enc_a      (1'b1),
        .enc_b      (1'b1),
        .enc_sw     (1'b1),
        .enc_a_lvl  (),
        .enc_b_lvl  (),
        .enc_sw_lvl (),
        .enc_sw_down(),
        .enc_sw_up  (),
        .enc_cw     (),
        .enc_ccw    (),
        .enc_state  (),
        .enc_err    ()
    );

    // ═══════════════════════════════════════════════════════════════════════
    //  ⭐⭐ 2026-09-29：⭐ **鼓机节奏型寄存器**（⭐ 串口 `'D'` ⇒ 循环 `0→1→2→3→0`）
    //
    //  🔴 **为什么要有它**（⭐ 用户上板要求）：⭐ "鼓机的节奏型要能**现场切**"。
    //     ⚠️ 原来 `DRUM_PATTERN_ID` 是**编译期参数** ⇒ ⭐ 想听下一个型就得
    //        **重新 PnR + 烧写**（⭐ 一次 ~10 分钟）⇒ 🔴 **4 个型根本没法 A/B 对比**。
    //
    //  ⭐ **语义**：⭐ 与 `timbre_sel_r`（`'I'` 切音色）/ `met_on_r`（`'B'` 开关）
    //     **完全同一手法**：⭐ `calib_cmd` 出**单周期脉冲** ⇒ ⭐ 这里**加一**（⭐ 2 位自然回绕）。
    //  ⭐ **复位值 = `DRUM_PATTERN_ID`**（⭐ 上电默认型）⇒ ⭐ 不改 `'D'` 时
    //     **行为与改动前逐位一致** ✅（⭐ 这条是本轮"只加不改"的关键）。
    //
    //  ⚠️ **为什么必须声明在【模块层】**（⭐ 而不是 generate 里的 `g_sound`）：
    //     ⭐ 与 `timbre_sel_r` **同一个理由** —— ⭐ 队友/本轮的 tb 要能用
    //     **`dut.drum_pattern_r`**（⭐ 模块层路径）观察它；
    //     ⚠️ 放 generate 里**绑不上**（⭐ 实测过 8 条 `Unable to bind` ✅）。
    //     📌 `calib_cmd`/`drum_gen` 都在 `g_sound` 里 ⇒ ⭐ 模块层信号**在里面可读可写** ✅
    //  ⚠️ **`g_silent` 档不例化 `calib_cmd`** ⇒ ⭐ 那里 `cmd_drum_pattern_req` 悬空（`z`）
    //     ⇒ ⭐ `if (z)` 在仿真里**为假** ⇒ ⭐ **不会误加** ✅
    //     （⭐ 与 `met_on_r`/`cmd_met_req` 完全同一个既有模式，⛔ 不是新风险）
    // ═══════════════════════════════════════════════════════════════════════
    //   ⚠️ **必须在【使用之前】声明** —— ⭐ `default_nettype none` 下不存在隐式网线 ✅
    wire cmd_drum_pattern_req;      // ⭐ 'D' ⇒ 鼓机节奏型 **切下一个**
    // ⭐⭐ 2026-10-01：⭐ **键盘打鼓模式**（⭐ 'K'）—— ⚠️ 同上，必须在使用前声明 ✅
    wire cmd_keydrum_req;           // ⭐ 'K' ⇒ 键盘打鼓 **开/关切换**

    //   ⭐ `integer` 参数⛔ 不做位选（`K-91`）⇒ ⭐ 先【赋值】给定宽 localparam（自动截断）✅
    localparam [1:0] DRUM_PATTERN_INIT = DRUM_PATTERN_ID;

    reg [1:0] drum_pattern_r;
    always @(posedge clk) begin
        if (!rst_n_sync) drum_pattern_r <= DRUM_PATTERN_INIT;
        else if (cmd_drum_pattern_req) drum_pattern_r <= drum_pattern_r + 2'd1;
    end

    // ⭐⭐ 2026-10-01：⭐ **键盘打鼓模式开关**（⭐ `'K'` 串口命令，⭐ 与 `met_on_r` 同构）
    //   ⭐ **语义**：⭐ `1` = 键盘当鼓垫（⭐ 见下方 `src_a_*` 的覆盖）；
    //      `0` = 正常发音高（⭐ **默认**）✅
    //   📌 **为什么用寄存器而不是编译期参数**：⭐ 上板要"边听边切"——
    //      ⚠️ 编译期参数意味着换一次要重新 PnR（⭐ 一次 ~10 分钟）✅
    //   ⚠️ **复位 = 关**（⭐ 与 `met_on_r` 同一安全取向：⭐ 上电先不改变键盘语义）✅
    reg key_drum_r;
    always @(posedge clk) begin
        if (!rst_n_sync)           key_drum_r <= 1'b0;
        else if (cmd_keydrum_req)  key_drum_r <= ~key_drum_r;
    end

    // ═══════════════════════════════════════════════════════════════════════
    //  ⭐⭐ 2026-10-03（P2/P3）：⭐ **T3 变调控制量**（⭐ 串口 `'F'`/`'G'`/`'H'`/`'J'`）
    //
    //  ⭐ **来源**：⭐ `files/20-代码/T3-后续计划-20261003.md` §P2/§P3 ＋
    //     ⭐ `files/00-总览/T3变调与推子功能状态机-设计定稿-20261001.md` §四/§五 ✅
    //
    //  ⭐⭐ **2026-10-03（P3）：⭐ P2 的临时聚合逻辑【已经整体搬走】**
    //     🔴 P2 时这里有一段临时的 `trans_semi_r` 聚合（⭐ 编码 `0..24` ＋ clamp）。
    //     ⭐ P3 把它**整体挪进 `rtl/w3a/fader_gear.v`**，并与推子档位**共用同一个
    //        目标寄存器** ⇒ ⛔ 本文件**不再持有任何变调状态**（⭐ 一次只改一个变量 ✅）
    //
    //  ⭐ 本文件现在只做两件事：
    //     ① ⭐ 把 `calib_cmd` 的五根线**拉出到模块层**（⭐ 供 generate 里的
    //        `u_fader_gear` 读 —— ⭐ `default_nettype none` 下必须显式声明 ✅）
    //     ② ⭐ 把 `u_fader_gear.transpose_semi_o` 接到 `note_manager.transpose_semi_i`
    //
    //  ⚠️ **`g_silent` 档不例化 `calib_cmd` / `fader_gear`** ⇒ ⭐ 那里五根 `cmd_*`
    //     与 `transpose_semi` 都**悬空（`z`）**；⭐ 而 `g_silent` 里**没有任何消费者**
    //     （⭐ `u_note_manager` 在 `g_sound` 里）⇒ ⛔ 无影响 ✅
    //     （⭐ 与 `drum_pattern_r`/`key_drum_r` 完全同一个既有模式，⛔ 不是新风险 ✅）
    // ═══════════════════════════════════════════════════════════════════════
    //   ⚠️ **必须在【使用之前】声明** —— ⭐ `default_nettype none` 下不存在隐式网线 ✅
    wire cmd_trans_down_req;        // ⭐ 'F' ⇒ 降 1 半音（⭐ 单周期脉冲）
    wire cmd_trans_up_req;          // ⭐ 'G' ⇒ 升 1 半音（⭐ 单周期脉冲）
    wire cmd_trans_abs_req;         // ⭐ 'H' ⇒ 带帧绝对量：⭐ 值到达的那一拍
    wire [7:0] cmd_trans_abs_val;   // ⭐ 'H' ⇒ 该帧第一个载荷字节（⭐ 编码 0..24）
    wire cmd_gear_next_req;         // ⭐ 'J' ⇒ 推子档位切下一档（⭐ P3 起由 `u_fader_gear` 消费 ✅）
    //  ⭐⭐ 2026-10-11：⭐ `'Y'` ⇒ **录制回传导出**（⭐ 由 `g_sound` 里的 `u_rec_dump` 消费 ✅）
    //     📌 ⭐ **声明在模块层**（⭐ 与 `cmd_gear_next_req` 同一口径 ✅）——
    //        ⭐ 因为 `calib_cmd` 在 `g_sound` 里，⭐ 而模块层信号**在里面可读可写** ✅
    wire cmd_recdump_req;           // ⭐ 'Y' ⇒ 启动导出（⭐ 单周期脉冲 ✅）
    //  ⭐⭐ 2026-10-11：⭐ **录制回传导出 FSM 的线**（⭐ `u_rec_dump`，⭐ 在 `g_sound` 里 ✅）
    //     🔴 **必须声明在【模块层】**（⭐ 实测踩坑，⭐ 见 `u_rec_dump` 那里的注释 ✅）：
    //        ⚠️ `u_rec_dump` 与 `tx_req` 那两个块**不在同一个 generate 作用域**
    //        ⇒ ⭐ 声明在任一块里 ⇒ 🔴 另一块**绑不上**（`Unable to bind` ✅）
    //     📌 ⭐ 口径与 `cmd_gear_next_req` 一致：⭐ **模块层声明 ＋ generate 内读写** ✅
    wire        rd_dump_en;         // ⭐ 占用 `looper` 的读口 ✅
    wire [15:0] rd_dump_addr;       // ⭐ 导出地址 ✅
    wire        rd_push;            // ⭐ 推一个字节给 `u_tx_fifo` ✅
    wire [7:0]  rd_byte;
    wire        rd_busy;            // ⭐ 导出中 ✅
    wire        rd_done;            // ⭐ 导出完成（⭐ 单周期 ✅）
    wire        rd_pending;
    wire        rd_lock = rd_pending | rd_busy;
    wire [15:0] rd_reject_count;
    wire rd_notice_valid;
    //  ⭐⭐ **截断计数**（⭐ `K-106`：⛔ 不许静默失真 ✅）
    //     2026-10-13：两个累计计数已由导出 ASCII footer 消费，PC 可读。
    //     旧版只有 `syn_keep`、没有物理回包，不能算可观测。
    //     量化/越界损失经本次 ASCII footer 物理回传，不再只留内部线。
    (* syn_keep = 1 *) wire [15:0] rd_clip_cnt;
    (* syn_keep = 1 *) wire [15:0] rd_frame_cnt;

    //   ⭐ 半音偏移 `−12..+12`（⭐ 由 `g_sound.u_fader_gear` 驱动）
    //   📌 声明在**模块层**（⭐ 与 `drum_pattern_r` 同一理由）：
    //      ⭐ generate 里的 `u_note_manager` 读得到它 ✅
    wire signed [4:0] transpose_semi;

    // ⭐⭐ 2026-09-28：**开节拍器的那一刻，把音乐位置复位**（⭐ 用户要求"从第一拍开始响"）
    //
    //   🔴 **问题（⭐ 用户上板实测）**：*"节拍器是从第二拍开始响的，希望最好从第一拍开始响"*
    //   🔎 **根因**：⭐ `beat_gen` 是 **free-running**（`run_i = 1'b1`）
    //      ⇒ ⭐ 你按 S2 时，`beat_gen` 的 `tick_cnt_q` 可能停在 **1/2/3** 任意位置
    //      ⇒ ⭐ 下一个 tick **⛔ 不是 `bar_start`** ⇒ 🔴 **第一声是弱拍**。
    //
    //   ⭐ **修法**：⭐ 在 `met_on_r` 的**上升沿**给 `beat_gen.pos_reset_i` 发
    //      **1 拍脉冲** ⇒ ⭐ 相位 + `tick_cnt_q` 归零
    //      ⇒ ⭐ **下一个 tick 的 `tick_cnt_q == 0`** ⇒ `bar_start_o = 1`
    //      ⇒ ⭐ **第一声就是强拍** ✅
    //
    //   🔴 **为什么必须是【脉冲】**：⭐ `pos_reset_i` 是**电平**有效
    //      （`beat_gen.v` 的 `pos_reset_i` 端口注释：*"高有效，电平 ⇒ 相位+tick_cnt 归零"*）
    //      ⇒ ⚠️ 若常高 ⇒ 🔴 **相位永远停在 0，一个 tick 都不出**（⭐ 节拍器彻底不响）。
    //
    //   📌 **为什么不改成 `run_i = met_on_r`**（⭐ 看起来更直接）：
    //      ⚠️ 那样 `beat_gen` 停走 ⇒ `bg_beat` 停 ⇒ 🔴 **心跳 LED 不闪**
    //      （⭐ `led_blink = bg_beat`）⇒ ⭐ 上板会以为"板子死了"。
    //      📌 这是本设计**早就写明的取舍**（见 `METRONOME_ON` 的注释）
    //      ⇒ ⭐ 所以**只能复位相位，⛔ 不能停走**。
    //
    //   ⚠️ **代价**：⭐ 按下 S2 后**最多等一个拍周期**（120 BPM ⇒ 0.5 s）才响第一声
    //      —— ⭐ 这是"**从强拍开始**"的必然代价（⛔ 不可能既立刻响、又保证是强拍）。
    reg met_on_r_d;
    always @(posedge clk) begin
        if (!rst_n_sync) met_on_r_d <= 1'b0;
        else             met_on_r_d <= met_on_r;
    end
    wire met_start = met_on_r & ~met_on_r_d;   // ⭐ 开机脉冲（1 拍）

    // ── 时基 ────────────────────────────────────────────────────────
    wire tick_audio, mclk_en, bclk_en, bclk_half_en, lrclk, frame_start;

    clk_gen #(
        .CLK_PER_SAMPLE (1024),   // fs = 50 MHz ÷ 1024 = 48.828125 kHz
        .BCLK_DIV       (16),     // BCLK = 3.125 MHz（= 64 × fs）
        .MCLK_DIV       (4)       // MCLK = 12.5 MHz（板载 DAC 不用，留作观测）
    ) u_clk_gen (
        .clk          (clk),
        .rst_n        (rst_n_sync),
        .tick_audio   (tick_audio),
        .mclk_en      (mclk_en),
        .bclk_en      (bclk_en),
        .bclk_half_en (bclk_half_en),
        .lrclk        (lrclk),
        .frame_start  (frame_start)
    );

    // ═══════════════════════════════════════════════════════════════════════
    // ⭐⭐ T57（2026-09-21）· **接通出声链** —— 撤掉静音
    //
    // ⚠️ 为什么这一步是本项目最关键的一次改动：
    //   在此之前 `top.v` 送的是**常量 0**（静音）⇒ ⭐ **板子永远不出声**，
    //   而所有仿真结论（时基、I2S 时序、DAC 帧格式）**全都是对的** ⇒
    //   这种"全绿但没声音"极难定位（同 `R-16` 家族的教训）。
    //
    // ⭐ 链路（与 `代码总览图.md` 的最终形态一致，只是还没有 `w3b_top` 包顶层）：
    //     `note_manager` → `oscillator_bank`(64 lane) → `tdm_render_mixer` → `i2s_tx`
    //
    // ⭐ 时钟关系（全部单时钟域，⛔ 无派生时钟）：
    //    · `tick_audio`（每 1024 clk）驱动 `note_manager` / `oscillator_bank`
    //    · `oscillator_bank` 用 **66 拍** TDM 取回 64 个样本，然后 `osc_valid_o` 拉高一拍
    //    · ⭐ 用 `osc_valid_o` 当 `tdm_render_mixer.render_start_i`
    //      ⇒ mixer 再花 **POLY_TARGET+2 = 34 拍** 算完
    //    ⇒ 合计 **66 + 34 ≈ 100 拍**，远小于 1024 拍预算 ✅（`A6`）
    //
    // ⭐ 开机自检音（`DEMO_CHORD_ON=1`）：复位后自动起 **A4 + C#5 + E5** 三音和弦
    //    ⇒ ⭐ **不依赖任何传感器**就能证明"整条链在真硅片上通了"。
    //    ⚠️ 这只是**验证用**的固定音，⛔ 不是"预录 PCM"（是**实时合成**的三个振荡器）。
    // ═══════════════════════════════════════════════════════════════════════
    wire signed [SAMPLE_W-1:0] sample_mono;

    // ═══════════════════════════════════════════════════════════════════════
    // ⭐⭐ 串口前端（⭐ 2026-09-23 阶段C）
    //
    //   🔴 **三个消费者共用【同一个** `uart_rx` **】**（⭐ 这是本段最关键的设计）：
    //      ```
    //      uart_rx.rx_done_o ─┬─> evt_uart_rx  （⭐ 认 0xA5 帧 = 曲谱事件）
    //                         └─> calib_cmd    （⭐ 认帧外的 T/S/X = 标定命令）
    //      ```
    //   ⭐ **两者天然共存**，因为**各自维护独立的帧边界概念**：
    //      · `evt_uart_rx`：⭐ 只在 **`idx==0`** 位置看 `0xA5`（⭐ 不做扫描）
    //      · `calib_cmd`  ：⭐ **同样跟踪 `0xA5` 边界**，⭐ 帧内字母一律当载荷
    //      ⇒ ⭐ `'T'`(0x54) **不是** `0xA5` ⇒ ⭐ 两边**都不会误同步** ✅
    //
    //   ⚠️ **代价（⭐ 上板时要心里有数）**：
    //      🔴 **每发一条标定命令，`evt_uart_rx.hdr_err_cnt_o` 会 +1** ——
    //      ⭐ **这是正常的，⛔ 不是故障**。
    //
    //   ⚠️⚠️ **波特率必须四处一致**（⭐ 不一致会**静默收乱码**、⛔ 不报错）：
    //      ```
    //      uart_rx     #(.BAUD_DIV(100))      // 🔴 2026-09-24：from 1 Mbps → 500 kbps
    //      evt_uart_rx #(.BAUD(500_000))
    //      calib_cmd   #(.BAUD(500_000))
    //      uart_tx     #(.BAUD_DIV(100))      // ⭐ 回传方向也要同档
    //      ```
    //      ⭐ 切档时**四处一起改**（⭐ 依据 `uart_rx.v` / `evt_uart_rx.v` 顶部注释）。
    //
    //   🔴🔴 **2026-09-24 实测：1 Mbps 在这块板上【有误码】**
    //      · 现象：发 `'T'`(0x54) ⇒ 收到 **`FA 54`**（⭐ 预期是回 `74` = `'t'` 受理）
    //        ⇒ ⚠️ **`0x74` 被误拆成两个字节**（⭐ 而且"秒回"⇒ 不是完成回包）
    //      · 判据：⭐ **逻辑本身是对的**（`rep_byte` 的所有合法值里**没有 0xFA**）
    //        ⇒ ⭐ 所以是**线路/时序**问题，⛔ 不是 RTL bug
    //      · ⭐ **用户经验**：⭐ 招新题那块板 **1 Mbps 同样有问题，500 kbps 正常**
    //      ⇒ ⭐ **结论：本板 500 kbps 起步**；⚠️ 若要更高，必须**实测误码率**再说
    //      📌 **500 kbps 的 `BAUD_DIV = 100`**（⭐ 50 MHz ÷ 500 kbps = 100 **整除 ⇒ 误差 0**）
    //
    //   📌 **为什么放在 `generate` 之外**：⭐ 第 ①②③ 块是**顶层基础设施**
    //      （⭐ 命令还要喂进 `g_sound` 里的 `calib_span`）
    //      ⇒ ⚠️ 放外面才能被 `g_sound` 引用（⭐ 且 `g_silent` 档也能保留串口）。
    // ═══════════════════════════════════════════════════════════════════════

    // ── ⭐ ① 字节接收器（8N1 @ 500 kbps）───────────────────────────────────
    wire [7:0] ur_data;
    wire       ur_done;
    //  ⭐⭐ 2026-10-09（`P0-02`）：⭐ **uart_ui 的"正在收一帧"**（⭐ 见其端口注释）✅
    wire       ui_in_frame;

    uart_rx #(
        // ⭐ `BAUD_DIV = 50 MHz / 500 kbps = 100`（⭐ 整除 ⇒ 无误差）
        //   🔴 2026-09-24 从 1 Mbps 降到 500 kbps —— ⚠️ 实测 1 Mbps 下串口有误码
        //      （⭐ 收到 `54 FA 54` 而预期是 `74`）⇒ ⭐ 与招新题那块板同样的现象
        //   ⚠️ 必须与下面两个 `BAUD(500_000)` 一致（⭐ 否则静默乱码）
        .BAUD_DIV(100)
    ) u_uart_rx (
        .clk_i     (clk),
        .rst_n_i   (rst_n_sync),
        //   ⭐ D14 / J9 N26（`.cst` 里已给 `PULL_MODE=UP` ⇒ 空闲态稳定）
        .rx_i      (uart_rx),
        .rx_data_o (ur_data),
        .rx_done_o (ur_done)
    );

    // ═══════════════════════════════════════════════════════════════════════
    //  ⭐⭐⭐⭐ 2026-10-11：⭐ **ESP32 独立 UART**（⭐ 曲谱 ＋ 回传）✅
    //
    //  ⭐⭐ **接线方案（⭐ 用户 2026-10-11 明确）**：
    //     · ⭐ **`D15`/`D14` → `XH_SCREEN`** = **串口屏 ＋ 命令/调试**（⭐ **共用一条** ✅）
    //     · ⭐ **`G21`/`G22` → `XH_ESP32`**  = ⭐ **ESP32 独立一对** ✅
    //     📌 ⭐ 依据：⭐ `files/10-硬件/Console拓展板接线需求-20261003.md`
    //        · `:562` 命令/调试 UART 500000 8N1 → `XH_SCREEN` ✅
    //        · `:564` ESP32（BLE 回传/上位机）**独立 UART** → `XH_ESP32` ✅
    //        · `:610` *"串口屏与命令口撞字母（`P0-4`）… ⭐ **ESP32 那一路已给独立 UART，
    //          可作为规避手段**"* ✅
    //
    //  🔴🔴 **为什么必须这么分**（⭐ 这解决了两个真问题）：
    //     ① ⭐ **`P0-02` 那个门控【整条作废】** ✅
    //        ⚠️ 原状：⭐ 曲谱接收器与串口屏/命令**共用一条线** ⇒ 屏帧载荷里的 `0xA5`
    //           会被当帧头 ⇒ 🔴 **伪曲谱事件 ⇒ 永久挂音**（⭐ `P0-02` 修过）
    //        ⇒ ⭐ 而 `P0-02` 的修法是"别人帧内就不给曲谱字节" ⇒ ⚠️ **只能治标**
    //           （⭐ `0xA5` 落在帧间空隙仍可能误判 ⇒ 那条 P1 一直挂着 ✅）
    //        ✅ **现在曲谱走自己的线** ⇒ ⭐ **不可能再与屏帧/命令互相误判** ✅
    //     ② ⭐ **曲谱带宽不再受屏刷新挤占** ✅（⭐ 屏帧与 9 字节曲谱帧**不再抢线**）
    //
    //  ⭐ **ESP32 侧现状（⭐ 它自己的 `esp32/README.md`，⭐ 2026-09-30）**：
    //     · ⭐ 定位 = **"无线的 USB 线"**：⭐ PC 怎么发就原样照搬、⭐ **不看内容** ✅
    //     · ⭐ 波特率 = **500000** ⇒ ⭐ **与本模块同档**（⭐ `BAUD_DIV = 50 MHz / 500 kbps
    //       = 100`，⭐ **整除 ⇒ 零误差** ✅）
    //     · ⭐ **反向通路（FPGA→ESP32→BLE→PC）已打通并验收**：
    //       ⭐ 2000 字节 round-trip **逐字节一致** ✅
    //     ⇒ ⭐ **所以 FPGA 侧只要"真的收发"，端到端就通** ✅
    //
    //  ⚠️⚠️ **接入纪律（⭐ 本文件 `:5390` 那段自己写明的）**：
    //     · ⭐ **必须删掉** `assign esp_uart_tx_o = 1'b1;`（⛔ 否则**多驱动** ⇒ 综合报错 ✅）
    //     · ⭐ **必须把 `esp_uart_rx_i` 从 `reserved_in_xor` 里摘掉**（⭐ 交给本逻辑消费 ✅）
    //     📌 ⭐ 两条**都已在本轮做到** ✅
    // ═══════════════════════════════════════════════════════════════════════
    wire       esp_rx_done;
    wire [7:0] esp_rx_data;

    uart_rx #(
        //  ⭐ 与板载口**同档**（⭐ 也正好等于 ESP32 固件的 `BLE_BAUD 500000` ✅）
        .BAUD_DIV(100)
    ) u_uart_rx_esp (
        .clk_i     (clk),
        .rst_n_i   (rst_n_sync),
        //   ⭐ `G22` · PMOD0 针 10（⭐ `.cst` 里已给 `PULL_MODE=UP` ⇒ 空闲态稳定 ✅）
        .rx_i      (esp_uart_rx_i),
        .rx_data_o (esp_rx_data),
        .rx_done_o (esp_rx_done)
    );

    // ── 串口屏控制面：模式默认指板，触摸控件 0 切到/离开键盘模式 ─────────
    //   `uart_ui` 只消费 TJC 返回帧；演奏触发不经过 UART，因此 UI 的不确定
    //   延迟不会进入拨弦→发声通路。当前 UART 物理口也可先接 USB-TTL 调试。
    wire        ui_mode_piano;
    wire [6:0]  ui_base_semi;
    wire        ui_mode_commit, ui_base_commit;
    wire        ui_fx_en;
    wire [1:0]  ui_fx_sel;
    wire        ui_test_mode, ui_test_mode_commit;
    wire [1:0]  ui_test_mode_n;
    wire [15:0] ui_frame_cnt, ui_resync_cnt, ui_err_cnt;
    wire        ui_hb_ready;
    wire        ui_tx_start;
    wire [7:0]  ui_tx_data;

    uart_ui #(
        .CLK_HZ   (50_000_000),
        .BAUD     (500_000),
        .GAP_BYTES(16),
        //   ⭐⭐ **2026-09-27：⭐ 上电默认模式 = 钢琴（⭐ 交付/烧录用）**
        //      · `1` ⇒ ⭐ **轴事件直接发声，⛔ 不需要拨弦** ⇒ ⭐ **上电即弹即响**
        //      · 两种模式都保留 ⇒ ⭐ 串口屏仍可随时切到指板（⭐ 只改上电初值）
        //      📌 链路：⭐ `play_fretboard_mode = ~ui_mode_piano`
        //         ⇒ ⭐ 钢琴时 `= 0` ⇒ `play_mode_ctrl` 走 `if (!fretboard_mode_i)`
        //         ⇒ ⭐ 轴事件直接产生 `evt_valid_o` ✅
        //      🔴 **为什么必须改**：⭐ 原来硬编码默认指板 ⇒ ⚠️ 上板**按了没声音**
        //         （⭐ 指板模式要等 P4 的 LM393 拨弦比较器，⭐ 不接就永远不触发）
        .MODE_PIANO_DEFAULT(1)
    ) u_uart_ui (
        .clk_i         (clk),
        .rst_n_i       (rst_n_sync),
        .rx_done_i     (ur_done),
        .rx_data_i     (ur_data),
        .tx_busy_i     (1'b1),       // 本版只接收屏的控制帧
        .tx_done_i     (1'b0),
        .tx_start_o    (ui_tx_start),
        .tx_data_o     (ui_tx_data),
        .mode_o        (ui_mode_piano),
        .base_semi_o   (ui_base_semi),
        .mode_commit_o (ui_mode_commit),
        .base_commit_o (ui_base_commit),
        .fx_en_o       (ui_fx_en),
        .fx_sel_o      (ui_fx_sel),
        .test_mode_o   (ui_test_mode),
        .test_mode_n_o (ui_test_mode_n),
        .test_mode_commit_o(ui_test_mode_commit),
        .frame_cnt_o   (ui_frame_cnt),
        .resync_cnt_o  (ui_resync_cnt),
        .err_cnt_o     (ui_err_cnt),
        .hb_ready_o    (ui_hb_ready),
        //  ⭐⭐ 2026-10-09（`P0-02`）：⭐ **"uart_ui 正在收一帧"** ⇒ 顶层互斥门控用 ✅
        .in_frame_o    (ui_in_frame)
    );

    // `uart_ui`: 0=指板、1=钢琴；`axis_map`/T15 控制器则相反。
    wire play_fretboard_mode = ~ui_mode_piano;

    // ── ⭐ ② 控制命令解析（`'T'` / `'S'` / `'X'` / `'M'`）─────────────────
    //   🔴 **它自带 `0xA5` 帧边界跟踪** ⇒ ⭐ 帧内的 `T/S/X/M` 是**载荷**，⛔ 不当命令
    //      （⚠️ 否则**曲谱灌入会被误当标定命令** —— 灾难性）
    wire cmd_tare_req, cmd_span_req, cmd_abort_req, cmd_probe_req, cmd_vstat_req;
    //   ⭐ 'N' 诊断：⭐ 回传 `calib` 后的 `pos`（⭐ 2026-09-27 新增）
    wire cmd_posprobe_req;
    wire cmd_test_mode_req;
    wire [15:0] cmd_cnt, cmd_in_frame_cnt, cmd_resync_cnt, cmd_unknown_cnt;
    wire [3:0]  cmd_idx;
    //  ⚠️ **2026-10-11 起 `cmd_idx` 在 `top.v` 里【没有消费者】了**（⭐ 诚实标注）：
    //     ⭐ 它原来只喂 `P0-02` 的门控，⭐ 而那条门控**已被证明是错的并删除**
    //        （⭐ 理由见 `evt_rx_done` 上方那段长注释 ✅）
    //     ⇒ ⭐ 综合会把 `calib_cmd.idx_o` 这条锥**剪掉** ✅
    //     📌 ⭐ **可以接受**：⭐ 它与 `evt_uart_rx.idx_o`（`eu_idx`）**恒等**
    //        （⭐ 两者数的是**同一个 9 字节帧** ✅）⇒ ⭐ 信息没有丢 ✅
    //     📌 而它**不在** `P0-29` 那 6 条"必须有消费者"的关键观测线名单里 ✅

    // ⭐ 2026-09-29：looper 的三条命令（⭐ `calib_cmd` 新增 `'R'`/`'L'`/`'C'`）
    wire cmd_loop_rec_req;      // ⭐ 'R' ⇒ 录/停**切换**
    wire cmd_loop_play_req;     // ⭐ 'L' ⇒ 播放**切换**
    wire cmd_loop_clear_req;    // ⭐ 'C' ⇒ 清空该层
    //  ⭐ `cmd_timbre_req`（'I'）**已在上方模块层声明**（⭐ S2 按键块要用它 ✅）

    calib_cmd #(
        .CLK_HZ   (50_000_000),
        .BAUD     (500_000),        // ⚠️ 与 `uart_rx.BAUD_DIV=100` 同一档
        .GAP_BYTES(16)              // ⚠️ 与 `evt_uart_rx` 同值（⭐ 帧边界判断要一致）
    ) u_calib_cmd (
        .clk_i          (clk),
        .rst_n_i        (rst_n_sync),
        .rx_done_i      (ur_done),
        .rx_data_i      (ur_data),
        .tare_req_o     (cmd_tare_req),
        .span_req_o     (cmd_span_req),
        .abort_req_o    (cmd_abort_req),
        .probe_req_o    (cmd_probe_req),
        .vstat_req_o    (cmd_vstat_req),
        .posprobe_req_o (cmd_posprobe_req),
        .test_mode_req_o(cmd_test_mode_req),
        // ⭐ 2026-09-29：looper 三条命令
        .loop_rec_req_o (cmd_loop_rec_req),
        .loop_play_req_o(cmd_loop_play_req),
        .loop_clear_req_o(cmd_loop_clear_req),
        // ⭐ 2026-09-29：⭐ 切音色（⭐ 'I'）
        .timbre_req_o   (cmd_timbre_req),
        //  ⭐ 2026-10-10（乙）：⭐ 'Q' 显示模式切换（⭐ 第一步 = 冻结/恢复）
        .scope_mode_req_o (cmd_scope_mode_req),
        .met_req_o      (cmd_met_req),
        // ⭐ 2026-09-29：⭐ 鼓机节奏型切下一个（⭐ 'D'，⭐ 2026-09-29 新增）
        .drum_pattern_req_o(cmd_drum_pattern_req),
        // ⭐⭐ 2026-10-01：⭐ 键盘打鼓模式（⭐ 'K'）
        .keydrum_req_o  (cmd_keydrum_req),
        // ⭐⭐ 2026-10-03（P2）：⭐ **T3 变调控制面**（⭐ 'F'/'G'/'H'/'J'）
        //   ⭐ 五根线**都已在模块层声明**（⭐ 见 `cmd_trans_down_req` 那一段 ✅）
        //   ⚠️ `cmd_gear_next_req`（`'J'`）**本轮无人消费**（⭐ `P3` 才接档位状态机）
        //      ⇒ ⭐ 综合会把它剪掉（⭐ 省 LUT），⭐ **⛔ 不是漏接线** ✅
        .trans_down_req_o(cmd_trans_down_req),
        .trans_up_req_o  (cmd_trans_up_req),
        .trans_abs_req_o (cmd_trans_abs_req),
        .trans_abs_val_o (cmd_trans_abs_val),
        .gear_next_req_o (cmd_gear_next_req),
        //  ⭐⭐ 2026-10-11：⭐ `'Y'` 录制回传导出（⭐ 2026-10-11 新增第 19 条命令 ✅）
        .recdump_req_o   (cmd_recdump_req),
        .cmd_cnt_o      (cmd_cnt),
        .in_frame_cnt_o (cmd_in_frame_cnt),
        .resync_cnt_o   (cmd_resync_cnt),
        .idx_o          (cmd_idx),
        .unknown_cnt_o  (cmd_unknown_cnt)
    );

    // ── ⭐ ③ 曲谱事件帧解析（`0xA5` + 8 字节大端 = 64 bit 事件）──────────
    //   ⚠️ **本版只接"解析出来"，⛔ 还没接进 `evt_merge`** ——
    //      ⭐ 因为那要动事件合流与 `note_manager`（⚠️ 属另一批改动，
    //      且 `SOURCE_A_SEL` 的仲裁要一起考虑）
    //   ⇒ ⭐ **本轮先让通路"能收、可观测"，⛔ 不急着灌进合成链**
    //      （⭐ 一次只改一个变量 —— 上板在即）
    wire        eu_evt_valid;
    wire [63:0] eu_evt_data;
    wire [15:0] eu_frame_cnt, eu_resync_cnt, eu_hdr_err_cnt, eu_drop_cnt;
    wire [3:0]  eu_idx;
    wire        eu_synced;

    //  ⭐⭐ 2026-10-09（`P0-02`）：⭐ **曲谱接收的互斥门控** ✅
    //   🔴 **缺陷**：⭐ `uart_ui`（串口屏）· `calib_cmd`（命令）· `evt_uart_rx`（曲谱）
    //      **共用同一条** `uart_rx` 的 `ur_done`/`ur_data`
    //      ⇒ ⚠️ 而 `evt_uart_rx` 的帧头是 `0xA5`，⛔ 它**看不到别人的帧边界**
    //      ⇒ 🔴 别人**合法载荷**里的 `0xA5` 落在它的 `idx==0` 上 ⇒ **伪曲谱事件**
    //      （⭐ 实测：8 个屏帧 ⇒ 8 条伪 `note_on`，`axis=15` 保留轴 · `kind=on`）
    //      ⇒ ⭐ `note_manager.note_off` 按 `(轴, 源)` 匹配 ⇒ 🔴 **手弹永远清不掉 `score` 源的 voice**
    //         ⇒ **永久挂音**（⭐ 用户实测："按同键不能清、按所有键也不能清、断电才清"）✅
    //   ✅ **修法**：⭐ **别人在帧内时，曲谱接收器【不看字节】** ✅
    //      · `uart_ui`   在帧内 ⇒ `ui_in_frame`（⭐ 新引出）
    //      · `calib_cmd` 在帧内 ⇒ `cmd_idx != 0`（⭐ 它**早就有**这个输出 ✅ 零改动）
    //   📌 **代价**：⭐ 1 个端口 + 2 条 AND（⭐ 纯组合，浅 ✅）
    //   ⚠️ **局限（诚实）**：⭐ 本门控只能挡"**别人帧内**"的字节；
    //      ⭐ 若 `0xA5` 出现在**帧间空隙**（⭐ 别人的帧已结束）⇒ ⚠️ 仍可能误判
    //      ⇒ ⭐ 根治方案是把曲谱挪到**独立 UART**（⭐ `esp_uart_rx_i` 现成，
    //         ⚠️ 但要 ESP32 侧配合 + 一次引脚 PnR）⇒ ⭐ 记入 P1 ✅
    //
    //  ⭐⭐⭐⭐ 2026-10-11：⭐ **`& (cmd_idx == 4'd0)` 这一条是【错的】，已删** ✅
    //
    //  🔴🔴 **为什么它错（⭐ 实测 + 读源码双重确认，⭐ ⛔ 不是推测）**：
    //     ⭐ `calib_cmd` 的 `idx_q` **只在一种情况下**离开 0 —— ⭐ **看到 `0xA5`** ✅
    //        （⭐ `calib_cmd.v:408-412` 原文：
    //          *"⭐ 帧外：这里只可能是帧头或命令 … if (byte_is_header) idx_q <= 4'd1;
    //            ⭐ 事件帧开始 ⇒ ⭐ 进入帧内，⛔ 之后 8 个字节一律不认命令"* ✅）
    //     ⭐ 而**命令**只在 `idx_q == 0` 时被识别，⭐ 且**不推进 `idx_q`**
    //        （⭐ `calib_cmd.v:447` 原文：*"`idx_q <= 4'd0;` ⭐ 命令不推进帧位置"* ✅）
    //     ⇒ ⭐⭐ **所以 `cmd_idx != 0` ⟺ "有一个 `0xA5` 事件帧正在收"** ✅
    //        —— ⚠️ 它**⛔ 完全不能**表示"别人（屏/命令）在帧内" ✅
    //     ⇒ 🔴 **后果（⭐ 实测）**：⭐ 曲谱帧的**第 1 个字节**（`0xA5`）通过门控
    //        ⇒ ⭐ `calib_cmd` 随即把 `idx_q` 推到 1 ⇒ 🔴 **门控在【曲谱自己的 8 个载荷字节】
    //          上全程关闭** ⇒ ⭐ `evt_uart_rx` 永远收不满一帧
    //        ⇒ 🔴 **曲谱链路【整体不可用】**（⭐ 实测：9 个字节只有 1 个过门，
    //           `eu_idx` 卡在 1、`eu_frame_cnt` 恒 0 ✅）
    //     📌 ⭐ 一句话：⭐ **这个门控把曲谱接收器【正好在它最需要的时候】关掉了** ✅
    //
    //  ✅ **修法**：⭐ **只留 `~ui_in_frame`** —— ⭐ 它才是 `P0-02` 真正要挡的东西
    //     （⭐ 实测的伪事件源是 **8 个【串口屏】帧**，⭐ 而屏帧由 `uart_ui` 认领 ✅）
    //     · ⭐ **`P0-02` 的保护【完整保留】**：⭐ 屏帧期间 `ui_in_frame == 1`
    //       ⇒ ⭐ 曲谱接收器**照样不看字节** ⇒ ⭐ **伪事件依然不可能发生** ✅
    //       📌 ⭐ 判据：⭐ `tb/w3c/tb_evt_uart_rx_gate.sv` 的 `G1`（8 个含 `0xA5` 的屏帧
    //          ⇒ ⭐ 曲谱侧 **0 条事件**）**一字未改、仍然全绿** ✅
    //     · ⭐ **曲谱恢复**：⭐ 载荷字节不再被挡 ⇒ ⭐ `evt_uart_rx` 能收满 9 字节 ✅
    //   ⚠️ **仍然存在的那条局限**（⭐ 诚实标注）：⭐ `0xA5` 出现在**帧间空隙**时仍可能误判
    //      ⇒ ⭐ 根治仍是"曲谱挪到独立 UART"（⭐ `P1`，⭐ 与本条**不冲突** ✅）
    //  ⭐⭐⭐⭐ 2026-10-11：⭐ **曲谱接收器改走【ESP32 独立 UART】** ✅
    //
    //  🔴🔴 **`P0-02` 那个门控【整条作废了】—— ⭐ 而这是好事** ✅
    //     ⚠️ 它当年存在，是因为曲谱与**串口屏/命令共用一条线** ⇒
    //        ⭐ 屏帧载荷里的 `0xA5` 会被当帧头 ⇒ 🔴 伪曲谱事件 ⇒ 永久挂音 ✅
    //     ⇒ ⭐ 而它的修法"别人帧内就不给曲谱字节"**只能治标**：
    //        ⚠️ `0xA5` 落在**帧间空隙**时仍可能误判（⭐ 那条 P1 一直挂着 ✅）
    //     ✅ **现在曲谱有自己的线**（⭐ `esp_uart_rx_i`，⭐ 见上方 `u_uart_rx_esp`）⇒
    //        · ⭐ 那条 P1 的**根因消失**（⭐ 不再与屏帧/命令共用线路 ✅）
    //        · ⭐ 而 `~ui_in_frame` 这个门控**反而必须删掉** ——
    //          🔴 否则串口屏每刷一帧，⭐ **曲谱字节就会被吞**（⭐ 两条线本该互不相干 ✅）
    //
    //  📌 ⭐ **保留 `ui_in_frame` / `cmd_idx` 的声明**（⭐ 不删）：
    //     ⚠️ 它们现在是**无消费者的观测线** ⇒ ⭐ 综合会剪掉 ✅
    //     📌 ⭐ 可接受：⭐ 串口屏的"在帧内"状态对**本板卡内部**没有别的用处 ✅
    //     （⭐ 而 `uart_ui` 自己的帧解析**照常工作** ✅）
    evt_uart_rx #(
        .CLK_HZ   (50_000_000),
        .BAUD     (500_000),        // ⚠️ 与 `uart_rx.BAUD_DIV=100` 同一档
        .GAP_BYTES(16)
    ) u_evt_uart_rx (
        .clk_i         (clk),
        .rst_n_i       (rst_n_sync),
        //  ⭐⭐ 2026-10-11：⭐ **改接 ESP32 独立 UART**（⛔ 不再是板载 `ur_done`）✅
        //     📌 ⭐ 这也**顺带删掉了 `P0-02` 的门控**（⭐ 理由见上方那段长注释 ✅）
        .rx_done_i     (esp_rx_done),   // ⭐ 来自 `u_uart_rx_esp`（⭐ `G22`）✅
        .rx_data_i     (esp_rx_data),
        .evt_valid_o   (eu_evt_valid),
        .evt_data_o    (eu_evt_data),
        .frame_cnt_o   (eu_frame_cnt),
        .resync_cnt_o  (eu_resync_cnt),
        .hdr_err_cnt_o (eu_hdr_err_cnt),
        .drop_cnt_o    (eu_drop_cnt),
        .idx_o         (eu_idx),
        .synced_o      (eu_synced)
    );

    // ═══════════════════════════════════════════════════════════════════════
    //  ⭐⭐ 2026-10-11：`U-19` 事件缓冲区 —— ⭐ **曲谱按 tick 播放的最后一块拼图** ✅
    //
    //  🔴 **为什么必须加**（⭐ 这是 `play_seq` 一直没能例化的**唯一**原因）：
    //     ⭐ `play_seq.v` 的读侧契约是**标准同步 FIFO** 语义
    //        （`evt_valid_i` = "有事件" ＋ `evt_data_i` = 队头 ＋ `evt_rd_o` = 取走）
    //     🔴 而 `evt_uart_rx.evt_valid_o` 是**单拍脉冲**（⭐ 它**不是** FIFO）
    //        ⇒ ⭐ 直接对接 ⇒ 🔴 **凡"tick 还没到"的事件【当拍就被丢掉】** ✅
    //     ⇒ ⭐ 中间必须有一级缓冲 ⇒ ⭐ 本模块 ✅
    //
    //  ⭐ **容量 = 8 KB / 1024 事件**（⭐ **已拍板**：⭐ `整曲缓冲大小定案.md` §2.3）
    //     · ⭐ 为什么不是最初的 2 KB：⭐ 2 KB = 256 事件**只够 8 拍**；
    //       ⭐ 8 KB 够**最密曲子（`夜洋风景` 99.3 事件/小节）的 8 小节** ＋ 33% 余量 ✅
    //     · ⭐ BSRAM：⭐ 1024 × 64 bit = 64 kbit ⇒ ⭐ **4 个 BSRAM**（⭐ 118 个里 ✅）
    //     📌 ⭐ 三个真实曲子的实测密度（⭐ 不是估算）：
    //        `09_Conjurer` 55.9 · `6.世界悲` 51.7 · `夜洋风景` **99.3**（最密）
    //     ⚠️ ⭐ **8 KB 也装不下整曲**（⭐ `09_Conjurer` 全曲 = **92.6 KB** = 只覆盖 8.6%）
    //        ⇒ ⭐ **必须滚动预灌**（⭐ PC 提前灌下一段）✅
    //
    //  ⭐ **数据流（⭐ 本块之后）**：
    //     `evt_uart_rx`（单拍脉冲）⇒ ⭐ **本缓冲** ⇒ `play_seq`（按 tick 吐）
    //        ⇒ ⭐ ① `seq_arb.score`（⭐ 出声）· ⭐ ② `guide_lamp`（⭐ LED 指引）✅
    //
    //  ⚠️ **作用域**：⭐ 本实例在 **`generate` 之外**（⭐ 模块级）——
    //     ⭐ 因为它只跟 `evt_uart_rx`（也是模块级）打交道 ✅
    //     ⭐ 而 `play_seq` **必须**放进 `g_sound`（⭐ 它要读 `bg_tick`、⭐ 又要驱动
    //        `beat_gen.tick_inc_i`）⇒ ⭐ 两边的线走**模块级中间量** ✅
    //     📌 ⭐ 与 `ee_key_on`（`P0-27`）/ `fault_any_w`（`P0-29`）**同一手法** ✅
    // ═══════════════════════════════════════════════════════════════════════
    wire        eb_rd_valid;      // ⭐ 缓冲非空（→ `play_seq.evt_valid_i`）
    wire [63:0] eb_rd_data;       // ⭐ 缓冲队头（→ `play_seq.evt_data_i`）
    wire        ps_evt_rd;        // ⭐ `play_seq.evt_rd_o`（→ 缓冲的 `rd_ack_i`）
    wire        ps_note_valid;    // ⭐ `play_seq.note_valid_o`（→ `seq_arb` ＋ `guide_lamp`）
    wire [63:0] ps_note_data;     // ⭐ `play_seq.note_data_o`
    wire        eb_ovf;           // ⭐ 缓冲溢出（sticky）
    wire [15:0] eb_drop;          // ⭐ 丢弃计数（饱和）
    wire [15:0] eb_cnt;           // ⭐ 当前深度
    wire        eb_low;           // ⭐ 低水位
    //  ⭐⭐ 2026-10-11：⭐ **高水位（sticky）** —— ⭐ "**还没丢，但余量告急**" ✅
    //     📌 ⭐ 依据：⭐ ESP32 侧清单 `FPGA侧对接清单-ESP32通路-20260922.md` §2.3 的 **L1**：
    //        *"它**在真正丢失【之前】**就置位 ⇒ ⭐ 调试时能在'还没丢'的时候就发现余量不够"* ✅
    //     📌 ⭐ **与 `eb_ovf` 的分工**：⭐ `eb_ovf` = **已经丢了** · ⭐ `eb_hw` = **快满了** ✅
    //     ⚠️ ⭐ **为什么⛔ 不 OR 进 `ovf_any`**（⭐ 想清楚了才这么做 ✅）：
    //        ⭐ `ovf_any` 驱动**心跳灯快闪**，⭐ 而那是**已交付语义**
    //        （⭐ 交接文档写明"**心跳灯快闪 = 丢过曲谱事件**" ✅）
    //        ⇒ ⚠️ 把"快满了"混进去 ⇒ 🔴 **改变既有指示的含义**（⭐ 而且**真丢了**与
    //           **快满了**在上板时是**必须分清**的两件事 ✅）
    //     ✅ **处置**：⭐ 引出为**顶层挂钩**（`syn_keep` 防剪 ✅），
    //        ⭐ 语义留给**将来的状态回包**（⭐ 与 `eb_cnt`/`eb_low` 同一处 ✅）
    //     📌 ⭐ 判据在**模块级**：⭐ `tb/w3c/tb_evt_buf.sv`（⭐ 直接验 `high_water_o` ✅）
    (* syn_keep = 1 *) wire eb_hw;

    evt_buf #(
        .DEPTH   (1024),          // ⭐ **已拍板 8 KB**（⛔ 不要改小 —— 见上面的容量账）
        .EVT_W   (64),
        .LOW_WM  (256),           // ⭐ 低水位 = 1/4（⭐ 供将来反向流控 ＋ 可观测）
        .HIGH_WM (768)            // ⭐ 高水位 = 3/4（⭐ 2026-10-11 新增，⭐ L1 要求）
    ) u_evt_buf (
        .clk_i       (clk),
        .rst_n_i     (rst_n_sync),
        .wr_valid_i  (eu_evt_valid),   // ⭐ 来自 `evt_uart_rx`（⭐ 单拍脉冲 ✅）
        .wr_data_i   (eu_evt_data),
        .rd_valid_o  (eb_rd_valid),
        .rd_data_o   (eb_rd_data),
        .rd_ack_i    (ps_evt_rd),      // ⭐ 由 `g_sound` 里的 `play_seq` 驱动 ✅
        .ovf_o       (eb_ovf),
        .drop_cnt_o  (eb_drop),
        .cnt_o       (eb_cnt),
        .low_o       (eb_low),
        .high_water_o(eb_hw),          // ⭐ 2026-10-11：⭐ L1 高水位 ✅
        //  ⚠️ 暂无消费者 ⇒ ⭐ 接 0 —— ⚠️ 但 **`ovf_o`/`drop_cnt_o` 有消费者**：
        //     ⭐ 下面 OR 进 `ovf_any` ⇒ ⭐ **心跳灯快闪 = 丢过曲谱事件** ✅（`K-106`）
        .ovf_clr_i   (1'b0)
    );

    // ── ⭐ ④ 串口发送器（⭐ 回传标定进度）─────────────────────────────────
    //   ⭐⭐ **为什么必须有**（⭐ 2026-09-23 阶段C 新增）：
    //      🔴 没有它，`span` 标定**没有任何进度回传** ——
    //         · 操作者不知道**现在标到第几个轴**
    //         · 不知道刚才是**通过**还是**被拒绝**
    //         ⇒ 🔴 **16 轴逐个按到底的流程几乎没法可靠完成**
    //   ⭐ 实现：⭐ 一个极简的发送调度器 ——
    //      ⭐ 波特率 500 kbps ⇒ ⭐ 一个字节 ≈ 20 µs
    //      ⇒ ⚠️ 人类根本感知不到延迟 ⇒ ⭐ **不需要 FIFO，直接串行发即可**。
    //
    //   ⭐ **本版回传的字符**（⭐ 单字节 ASCII，⭐ PC 串口助手直接能看）：
    //      | 时机 | 字符 | 含义 |
    //      |---|---|---|
    //      | ⭐ 收到 `'T'` | **`'t'`** | ⭐ 已受理 tare 请求 |
    //      | ⭐ 收到 `'S'` | **`'s'`** | ⭐ 已受理 span 请求 |
    //      | ⭐ 收到 `'X'` | **`'x'`** | ⭐ 已受理取消 |
    //      | ⭐ 收到 `'M'` | **`'4'/'8'/'A'/'B'/'0'`** | ⭐ Test Mode 已切至 4/8/16/32/关 |
    //      | ⭐ `span` 需要按键 | **`'0'~'9'`/`'A'~'F'`** | ⭐ **当前要求按哪个轴**（⭐ 十六进制一位） |
    //      | ⭐ 该轴通过 | **`'.'`** | ⭐ 这一轴标成功 |
    //      | 🔴 该轴被拒 | **`'!'`** | ⭐ 这一轴被拒（⭐ 手没按稳 / 没按到底） |
    //      | ⭐ 全部完成 | **`'D'`** | ⭐ 16 轴全标完 |
    //      | 🔴 放弃 | **`'E'`** | ⭐ 反复失败 ⇒ 放弃（⭐ `REJECT_MAX` 到顶） |
    //      ⚠️ **这套字符是【本项目自定义】的**（⭐ ESP32 侧已明确"标定命令由 FPGA 定"）
    //         📌 出处：`FPGA2026-esp32/.../ESP32侧串口命令格式-给FPGA侧-20260923.md` §1.3
    //      ⚠️ **⛔ 它不上 `0xA5` 帧** —— ⭐ 是**裸 ASCII**
    //         ⇒ ⚠️ 回传方向**只有 PC 在听**，⛔ 不影响下行帧解析。
    // ═══════════════════════════════════════════════════════════════════════
    //   ⭐⭐ **回传请求信号（⭐ 跨 `generate` 边界）**
    //      ⭐ 事件在 `g_sound` **内部**产生（⭐ `calib_span` 在里面），
    //      ⚠️ 而 `u_uart_tx` 在**外面** ⇒ ⭐ 信号必须引出。
    //      ⭐ **两个 `generate` 分支各自驱动它们**（⭐ 互斥 ⇒ ⛔ 不会冲突）：
    //        · `g_sound`  ⇒ ⭐ 驱动真事件
    //        · `g_silent` ⇒ ⭐ 驱动 0（⛔ 否则悬空成 `x`，⭐ 会误发垃圾字节）
    wire       tx_req;
    wire [7:0] tx_byte;
    // LED 链在 generate 之外；由两个互斥分支之一显式驱动，不能直接引用
    // `g_sound` 作用域内的 `bg_beat`。
    wire       led_blink;

    // ⭐⭐ 2026-10-03：⭐ **指示层（第 2 层）** 需要的【跨 generate 边界】状态线
    //   ⭐ 出处：`files/20-代码/WS2812指示层规格-20261003.md` §二 第 1 层
    //   🔴 为什么必须声明在这里（`generate` 之外）：⭐ 与 `led_blink`/`txf_ready` **同一理由** ——
    //      ⚠️ 消费者（`u_led_indicator`）在 `generate` 之外，⭐ 而**生产者**在 `g_sound` 里
    //      ⇒ ⭐ 必须由两个**互斥**分支各自驱动（⛔ 否则 `g_silent` 档悬空成 `x`）
    //   📌 `timbre_sel_r` / `met_on_r` / `key_drum_r` / `drum_pattern_r` /
    //      `play_fretboard_mode` **本来就在模块层** ⇒ ⛔ 不用引线（⭐ 直接读）✅
    localparam integer NCH_LED = 7;         // ⭐ 指示灯颗数（⭐ 一颗对一个东西）
    wire       led_beat;                    // ⭐ 拍点脉冲（`g_sound` 的 `bg_beat`，⭐ 单周期）
    wire [1:0] led_gear_st;                 // ⭐ 推子档位（`g_sound.u_fader_gear.gear_o`）
    wire [1:0] led_looper_st;               // ⭐ looper：0=空闲 · 1=录音 · 2=回放
    wire [NCH_LED*24-1:0] led_col_flat;     // ⭐ 7 颗灯的颜色（⭐ `u_led_indicator` 驱动）

    // ═══════════════════════════════════════════════════════════════════════
    //   🔴🔴 **`uart_tx_fifo`：回传的发送队列**（⭐ 2026-09-24 新增，修 `K-126`）
    //
    //   ⭐ **为什么必须加**（⭐ 上板实测）：
    //      ⚠️ 原来 `tx_req` **直连** `uart_tx.tx_start_i` ⇒ 🔴 **忙时直接丢**
    //      · 发 `'S'` ⇒ `top.v` **同一时刻**产生两个回包：
    //          ① `'s'`（受理，⭐ 20 µs 才发完）
    //          ② 轴号提示（⭐ `calib_span` 的 `need_press`，⭐ **只高 1 拍 = 20 ns**）
    //      ⇒ 🔴 **20 ns 落在 20 µs 的发送窗口里 ⇒ 必然丢，⛔ 永不重发**
    //      ⇒ ⭐ 现象：⭐ **只收到 `s`，⭐ 之后没有任何轴号** ⇒ ⚠️ 不知道该按哪一轴
    //
    //   ⭐ **本模块把"忙就丢"改成"排队"** ⇒ ⭐ 上游随时可推，⭐ 它负责逐个喂
    //   ⭐ 深度 8（⭐ 最坏"一次 `'S'` 变 3 个回包"，⭐ 8 足够）
    //   🔴 **溢出可观测**（⭐ `K-106`）：⭐ `ovf_o` sticky + `drop_cnt_o` 饱和计数
    //      ⛔ **没有这两个输出就【等于没修】** —— ⚠️ 只是换了个地方悄悄丢
    //
    //   📌 **代价**：⭐ 回包**晚一个字节**（⭐ 20 µs）—— ⚠️ 人眼无感，✅ 可接受
    // ═══════════════════════════════════════════════════════════════════════
    wire       txf_start;        // ⭐ FIFO → uart_tx
    wire [7:0] txf_data;
    wire       txf_ovf;
    // 🔴 **`txf_ready` 必须在这里（`generate` 之外）声明** ——
    //    ⚠️ 它由 `u_tx_fifo`（⭐ 外面）驱动，⭐ 而 `u_pos_probe`（⭐ 在 `g_sound` 里）读它
    //    🔴 **第一版我把它放在 `g_sound` 里** ⇒ Gowin 综合报
    //       `Undeclared symbol 'txf_ready', assumed default net type 'wire'`
    //    ⚠️ **恰好它真的是 1 位 ⇒ 看起来能跑** ——
    //       但这正是 `L66` 警告过的那类"隐式建 wire"的隐患，⛔ 不能放过。
    wire       txf_ready;
    wire       txf_idle;         // ⭐ 队列空且发送器停（⭐ 2026-09-24）
    wire [7:0] txf_drop;
    wire       txf_busy;         // ⭐ 来自 uart_tx
    wire       board_uart_busy, esp_uart_busy;
    wire pp_busy, vp_busy, np_busy, dp_busy;
    wire pp_active, vp_active, np_active, dp_active;
    // Pending Y lets already-started reply producers finish. Actual export
    // starts only after producers AND FIFO/UART are idle, then pauses them.
    wire       normal_tx_ready = txf_ready & ~rd_busy;
    wire       shared_tx_start = rd_busy ? rd_push : txf_start;
    wire [7:0] shared_tx_data = rd_busy ? rd_byte : txf_data;
    assign txf_busy = board_uart_busy | esp_uart_busy;
// ⭐⭐ 2026-10-01 BATCH 8.3（⭐ 修 `implicit definition` 警告）：⭐ **`fault_any_w` 必须在【模块级】声明** ⚠️
//   🔴 **原来错在哪**：⭐ 我把它声明在**心跳灯那段**（⭐ `fault_any_w` 的声明）⚠️，⭐ 而 `assign` 在 `fault_any_w` 的赋值处
//      ⇒ 🔴 **声明晚于使用** ⇒ ⭐ 工具**隐式创建**了这条 wire ⇒ ⚠️ `warning: implicit definition`
//      ⚠️ 综合/PnR/108 个 tb **都过了** ⇒ ⭐ 行为是对的 ✅，⭐ 但这是**真代码异味** ⚠️：
//      🔴 在 `default_nettype none` 下它会变成**硬错误** ✅
//   ✅ **修法**：⭐ 声明挪到**模块级、且在 `generate` 块之前** ✅
//   📌 **作用域要点**：⭐ 本信号由 `g_sound` 块内的 `assign` 驱动（⭐ 那里 `af_fault`/`mx_fault` 可见 ✅），
//      ⭐ 而心跳灯逻辑（⭐ 模块级）**只读它** ⇒ ⭐ 两边都能看到 ✅
wire       fault_any_w;

//  ⭐⭐ 2026-10-09（`P0-27`）：⭐ **`event_extract.key_on[]` 的打包版**（⭐ 跨作用域）✅
//   📌 **作用域要点（⭐ 与上面 `fault_any_w` 同一手法）**：
//      ⭐ `u_event_extract` **在 `generate` 区里**（⭐ `g_sound`，⭐ `endgenerate` 在下面很远处）
//      ⭐ 而 `u_led_data` **在 generate 区【外】**（⭐ 模块级）
//      ⇒ 🔴 **不能让 `u_led_data` 直接读 generate 里的信号**（⭐ 作用域不可见）
//      ⇒ ⭐ 所以本信号声明在**模块级**，⭐ 由 `g_sound` 分支驱动、⭐ 由模块级的 `u_led_data` 读 ✅
//   📌 **为什么需要它**：⭐ `led_data.key_active_i` 原来是**占位 `16'd0`**
//      ⇒ 🔴 `key_pattern` 恒 0 ⇒ `pattern_changed` 恒假 ⇒ `commit_r` 恒 0
//      ⇒ ⭐ `tlc5916_bank` 一轮都不跑 ⇒ 🔴 **24 路灯永久全灭** ✅
wire [15:0] ee_key_on;

//  ⭐⭐ 2026-10-09（P0-29）：⭐ **"丢事件/溢出"汇合位**（⭐ 模块级 ⇒ 跨 generate 作用域）✅
//   🔴 **原缺陷**：⭐ top.v 里 **60+ 条**可观测性线**只出现 2 次**（声明 + 端口连接）
//      ⇒ ⭐ **没有消费者** ⇒ 🔴 **综合把整个观测锥剪掉** ✅
//      ⇒ ⭐ 三个模块为 K-106 写的 overflow_o（sticky）在**交付位流里一个都不存在**
//      ⇒ 🔴 **上板永远看不到"溢出/丢弃/相撞"** —— ⭐ 而 event_extract 的 FIFO 只有 4 深、
//        seq_arb/evt_merge 只有 6 深、looper 有 EVT_MAX=2048 上限
//        ⇒ ⭐ **丢事件是设计内的可能事件**，⭐ 现在它 100% 静默 ✅
//   ✅ **修法（⭐ 审查推荐的最省方案）**：⭐ 把它们 **OR 进已有的 `fault_any_w`**
//      ⇒ ⭐ **心跳灯快闪 = 丢过事件** ✅（⭐ 只加 1 个 LUT ✅）
//   📌 **为什么用中间 wire**：⭐ `fault_any_w` 的赋值在 L1773，⭐ 而这些源在 L3177+
//      ⇒ ⭐ Verilog **先声明后使用** ⇒ ⭐ 必须用模块级中间量 ✅
//   ⚠️ **诚实标注**：⭐ `fault_sticky` 是"**只复位才清**"（⭐ 现有注释说明是有意为之 ✅）
//      ⇒ ⭐ 它会**掩盖后续正常帧**（⭐ 想看"最近一次"要复位 ✅）
wire ovf_any;

    uart_tx_fifo #(.DEPTH(8)) u_tx_fifo (
        .clk_i     (clk),
        .rst_n_i   (rst_n_sync),
        .push_i    (tx_req),        // ⭐ 上游：⭐ 单拍也可（⭐ 当拍即入队）
        .data_i    (tx_byte),
        .ready_o   (txf_ready),     // ⭐ `'P'` 诊断要用（⭐ 见 `u_pos_probe`）
        .idle_o    (txf_idle),      // ⭐ 队列真空了（⭐ 包边界用）
        .tx_start_o(txf_start),
        .tx_data_o (txf_data),
        .busy_i    (txf_busy | rd_busy),
        .ovf_o     (txf_ovf),
        .drop_cnt_o(txf_drop),
        .ovf_clr_i (1'b0)           // ⚠️ 本版不清（⭐ 置位后保持 ⇒ 上板可观测）
    );

    uart_tx #(
        // ⚠️ 必须与 `uart_rx.BAUD_DIV` **同一档**（⭐ 否则对端收乱码）
        .BAUD_DIV(100)
    ) u_uart_tx (
        .clk_i     (clk),
        .rst_n_i   (rst_n_sync),
        .tx_start_i(shared_tx_start),
        .tx_data_i (shared_tx_data),
        .tx_o      (uart_tx),        // ⭐ 引脚 `D15`（⭐ J9·N25）
        .busy_o    (board_uart_busy),
        .tx_done_o ()
    );

    //  ⭐⭐⭐⭐ 2026-10-11：⭐ **ESP32 独立 UART 的【发送】—— 与板载口【镜像同一份回包】** ✅
    //
    //  ⭐ **为什么用"镜像"而⛔ 不是"另起一个 FIFO"**：
    //     · ⭐ `u_tx_fifo` 的 `busy_i` 握手**只挂在板载口上**（⭐ 那是它的流控源 ✅）
    //     · ⭐ 若给 ESP32 也接一个 FIFO ⇒ ⚠️ 两条链要各自流控 ⇒ **复杂且无必要** ✅
    //     ⇒ ⭐ **镜像**：⭐ 同一份 `txf_start`/`txf_data` **同时**喂两个 `uart_tx`
    //        ⇒ ⭐ 两个口**逐字节发出同样的内容** ✅
    //
    //  ⭐ **镜像谁**：⭐ 现在 `u_tx_fifo` 的内容是**标定回包 ＋ 探针**
    //     （⭐ `'s'`/轴号 · ⭐ `'P'`/`'V'`/`'N'`/`'Q'` ✅）
    //     ⇒ ⭐ 于是 **PC（经 BLE）也能看到这些诊断** ✅
    //     📌 ⭐ **这正是 ESP32 反向通路要的东西** ——
    //        ⭐ 它自己的 README 写着"反向通路（FPGA→ESP32→BLE→PC）**已打通并验收**"
    //        （⭐ 2000 字节 round-trip 逐字节一致 ✅）⇒ ⭐ **FPGA 侧只要真的发** ✅
    //
    // 2026-10-13 更正：两口 busy 合并参与流控，保证镜像字节同时受理。
    //     📌 ⭐ 两者速率相同（⭐ 同 `BAUD_DIV=100`）⇒ ⭐ **不会积压** ✅
    //
    //  📌 ⭐ **将来的"录制回传"就挂在这条路上**（⭐ 把 looper 的 dump 推给 `u_tx_fifo` ✅）
    //     —— ⚠️ 那需要先给 `looper` 加一个读出口（⭐ 见 `P1` 清单 ✅）
    uart_tx #(
        .BAUD_DIV(100)               // ⭐ 与 ESP32 固件 `BLE_BAUD 500000` 同档 ✅
    ) u_uart_tx_esp (
        .clk_i     (clk),
        .rst_n_i   (rst_n_sync),
        .tx_start_i(shared_tx_start),
        .tx_data_i (shared_tx_data),
        .tx_o      (esp_uart_tx_o),  // ⭐ 引脚 `G21`（⭐ PMOD0 针 9）
        .busy_o    (esp_uart_busy),
        .tx_done_o ()
    );

    // ═══════════════════════════════════════════════════════════════════════════
    // ⭐⭐ 位置式力度：**唯一的映射函数**（⭐ 2026-09-28 新增）
    //
    //   ⭐ 用户已定的参数（`files/20-代码/位置式力度-方案-20260928.md` §四）：
    //        ⭐ 线性：`vel = 64 + ((pos × 263) >> 10)`，⭐ 饱和到 255
    //
    //   ⭐ **为什么是 263**：行程 `pos ∈ [0, 744]`、力度 `vel ∈ [64, 255]`
    //        ⇒ 斜率 = 191/744 = 0.25672，而 263/1024 = 0.25684 ⇒ **误差 < 0.1%**
    //        ⇒ ⭐ `263 = 256 + 8 − 1` ⇒ ⭐ `(pos<<8) + (pos<<3) − pos`
    //        ⇒ ⛔ **不用乘法器**（⭐ 这正是选 263 而不是别的数的唯一理由）
    //
    //   ⭐⭐ **本函数是【两条通路】的唯一映射口径**（⭐ 必须逐位一致）：
    //        ① ⭐ **实时跟随流**（`vu_*`，见下方 `axis_snapshot` 例化之后）
    //        ② ⭐ **起音力度**（`w3a_evt_vel`）
    //      ⇒ ⛔ 不许在别处把公式再写一遍（⭐ 两份实现必然漂移 ⇒ 起音与跟随口径不一致）
    //
    //   ⚠️ **位宽纪律（⭐ 这里有一个真陷阱，⛔ 不是"写得啰嗦"）**：
    //      · ⭐ Verilog 的移位**左操作数位宽由上下文决定** ⇒
    //        若把 `(p<<8)` 直接放进一个**窄**上下文（如 12/13 位），
    //        综合/仿真会**先截断再移位** ⇒ 🔴 **静默算出完全错的值**（⛔ 不报任何错）。
    //      · ⇒ ⭐ 这里**显式零扩展到 22 位**再移位（⛔ 不依赖上下文推导）。
    //      · ⭐ 22 位的依据：`pos` 的满量程**取决于标定档位** ——
    //          只 `tare`（上电默认）⇒ 744 · 做过 `span`（归一化）⇒ 4095
    //        ⇒ `4095 × 263 = 1076985 < 2^21` ✅
    //      · ⚠️ **中间结果取 13 位（⛔ 不是参考实现里的 9 位）**：
    //          `pos = 4095` ⇒ `(pos×263)>>10 = 1051` ⇒ `64 + 1051 = 1115`
    //          ⇒ 🔴 **9 位存不下（>511）⇒ 会【回绕】成 91，⛔ 而不是"饱和到 255"**
    //        ⇒ ⭐ 13 位（≤8191）在**两种标定档位下都正确饱和**；
    //          📌 而在当前档位（`pos ≤ 744`）下两者**结果逐位相同**（⛔ 不是行为改动）
    // ═══════════════════════════════════════════════════════════════════════════
    function [7:0] pos_to_vel;
        input [11:0] p;
        reg   [21:0] p22;
        reg   [21:0] prod;
        reg   [12:0] v13;
        begin
            p22        = {10'd0, p};                        // ⭐ 显式零扩展（见上方位宽纪律）
            // ⭐⭐ 2026-10-01 返工：⭐ 斜率 `48` → **`263`**（⭐ 与【实际行程 744】对齐 ✅）
            //   🔴 **为什么回退**（⭐ 上板实测驱动，⛔ 不是理论推演）：⭐ BATCH 4 把斜率改成 `48`
            //      是**按"跑过 `'S'` 之后的 4095 档"**配的 ⇒ ⚠️ 而未标定档 `pos` 只到 **≈744**
            //      ⇒ 🔴 `pos_to_vel(744) = 64 + (744×48)>>10 = 64 + 34 =` **`98`**
            //      ⇒ ⭐ **① 总音量掉到 38%**（⭐ 255 → 98）
            //      ＋ ⭐ **② 力度动态范围只剩 64~98（34 个码）** ⇒ **跟随听不出来**
            //      ＋ ⭐ **③ 包络峰值 ∝ velocity ⇒ 低 2.6× ⇒ release 距离短 2.6×** ⇒ **尾音变短**
            //   ⭐ **二分实测证据（⭐ 决定性）**：
            //      · ⭐ `AN`（只有阈值变、`POS_FULL`/斜率未变）⇒ ⭐ **①②④ 全正常** ✅
            //      · ⭐ `AP`/`AU`（`POS_FULL=4095` ＋ 斜率 48）⇒ ⭐ **①②④ 全坏** ✅
            //   ⭐ **正确性验算**：⭐ `744 × 263 >> 10 = 191` ⇒ `64 + 191 = 255`
            //      ⇒ ⭐ **满行程【恰好饱和】** ✅（⛔ 不是早饱和、⛔ 不是到不了顶）
            //   ⚠️ `48 = 32+16` 与 `263 = 256+8-1` **都是移位相加** ⇒ ⛔ 都不用乘法器 ✅
            //   ⚠️ `p22` 是 `{10'd0, p}`（⭐ 零扩展到 22 位）⇒ ⭐ `4095 × 263 = 1076985 < 2^21` ✅ 位宽够
            prod       = (p22 << 8) + (p22 << 3) - p22;    // ⭐ ×263（⛔ 无乘法器）
            v13        = 13'd64 + prod[21:10];              // ⭐ >>10 再 +64（⭐ 力度下限 64）
            pos_to_vel = (FIXED_VELOCITY_DIAG != 0) ? FIXED_VELOCITY_VALUE
                       : (v13 > 13'd255) ? 8'd255 : v13[7:0];   // ⭐ 饱和到 255
        end
    endfunction

    // ⭐⭐ 2026-09-28：**|Δpos| 绝对值**（⭐ `'Q'` 诊断用，⭐ 见 `u_pos_probe_dpos`）
    //   🔴 **为什么用【模块级函数】**：⭐ `g_sound` 已经在 `generate` 块里
    //      ⇒ ⛔ 不能再嵌 `generate`（⭐ 实测报 "generate/endgenerate regions
    //      cannot nest"）⇒ ⭐ 用函数代替循环里的临时变量 ✅
    //   ⭐ **用大减小**（⛔ 不用有符号减法 ⇒ ⚠️ 避免符号位/位宽陷阱）
    //   ⭐ 返回 **12 位**：⭐ `|Δ| ≤ 4095` 本来就装得下（⭐ `pos` 是 12 位）
    //      ⚠️ **⛔ 不要写成 13 位再位选** —— 🔴 Verilog-2001 **不允许对函数返回值
    //         直接位选**（`func(...)[11:0]` 会报 syntax error，⭐ 已实测踩到）
    //      ✅ 要加宽就在**调用处用拼接**：`{1'b0, dpos_abs_f(...)}`（⭐ 合法）
    function [11:0] dpos_abs_f;
        input [11:0] a;
        input [11:0] b;
        begin
            dpos_abs_f = (a > b) ? (a - b) : (b - a);
        end
    endfunction

    //  ⭐ 2026-10-09（乙）：HDMI 显示模式参数已在【端口参数表】声明（见 `module top #(`）
    //    ⛔ 这里不再重复声明 —— 声明在 module 体内会导致 tb 无法覆盖（iverilog 报错）
    //
    //  ⚠️⚠️ 2026-10-10（乙）：⭐ 第二步「运行时切换」**三次实测均失败，已回退** ——
    //     ① 两个独立内存           : ❌ 布线卡死
    //     ② 共用一个内存（B）      : ❌ 布线卡死
    //     ③ 共用 + 波形数据通路桩掉 : ❌ 仍然卡死（隔离实验，2026-10-10）
    //     ⇒ ⭐ 真凶 = 把 `SCOPE_MODE` 变成【运行时信号】这件事本身（5 个宽 mux + 两套 FSM 并存），
    //        ⛔ 不是波形数据通路（减法器/比较器都桩掉了还是卡）。
    //     `SCOPE_MODE` 恢复为【编译期参数】；串口 `'Q'` 保留【冻结/恢复】语义。
    //     📌 重设计思路见 `files/20-代码/显示模式切换-重新设计-20261010.md`
    reg scope_mode_r;
    always @(posedge clk) begin
        if (!rst_n_sync)             scope_mode_r <= (SCOPE_MODE != 0);
        else if (cmd_scope_mode_req) scope_mode_r <= ~scope_mode_r;
    end

    wire signed [23:0] scope_sample;
    wire scope_valid;
    hdmi_scope #(.XY_DELAY(XY_DELAY), .XY_GAIN(XY_GAIN))
    u_hdmi (.clk(clk), .rst_n(rst_n_sync),
        .SCOPE_MODE(scope_mode_r),     // ⭐ 运行时显示模式（串口 'Q'）
        .sample_i(scope_sample), .valid_i(scope_valid),
        .tmds_d_p_0(tmds_d_p_0), .tmds_d_n_0(tmds_d_n_0),
        .tmds_clk_p_0(tmds_clk_p_0), .tmds_clk_n_0(tmds_clk_n_0),
        .hpd_en(hpd_en));

    generate
    if (DEMO_CHORD_ON == 0) begin : g_silent
        // ⭐ `'P'` 诊断：⭐ 静音档没有 `af0_pol` ⇒ ⭐ 恒无回传
        //   ⚠️ **必须声明成 `wire` 再 `assign`** ——
        //      🔴 两个 `generate` 分支各自声明同名信号（⭐ 互斥 ⇒ ⛔ 不冲突）
        wire       pp_push;
        wire [7:0] pp_data;
        assign pp_push = 1'b0;
        assign pp_data = 8'h00;
        // ── M0 安全态/静音档：⛔ 不例化合成链，直接送 0 ──────────────────
        //    ⭐ 为什么**整条链都不例化**而不是"接了但喂 0"：
        //       ① 省资源；② ⭐ **静音就是结构上的静音**，⛔ 不给"某个内部节点
        //       意外产生数据"留任何可能（`tb_top_m0` 的 E 判据要 `HP_DIN` 恒 0）。
        assign scope_sample = 24'sd0;
        assign scope_valid = tick_audio;
        assign sample_mono = {SAMPLE_W{1'b0}};
        //   ⭐ 静音档：⭐ 没有 `calib_span` ⇒ ⭐ 回传恒"无请求"
        //      ⚠️ **必须显式驱动** —— 否则 `tx_req` 悬空成 `x`
        //         ⇒ 🔴 `uart_tx` 可能把 `x` 当启动脉冲，⭐ 发出垃圾字节
        //   📌 两个 `generate` 分支**互斥**（⭐ 只例化一个）
        //      ⇒ ⭐ 各自驱动同名信号 **⛔ 不会冲突** ✅
        assign tx_req  = 1'b0;
        assign tx_byte = 8'h00;
        assign rd_pending = 1'b0;
        assign rd_busy = 1'b0;
        assign rd_push = 1'b0;
        assign rd_byte = 8'd0;
        assign rd_reject_count = 16'd0;
        assign rd_notice_valid = 1'b0;
        assign led_blink = 1'b0;
        //   ⭐ 指示层：⭐ 静音档没有节拍器 / looper / 推子档位
        //      ⇒ ⭐ 三根线**显式给 0**（⛔ 否则悬空成 `x` ⇒ ⚠️ 指示灯随机亮）
        assign led_beat      = 1'b0;
        //  🔴 **`led_gear_st` 必须是 `2'd3`（= "无" ⇒ 灭），⛔ 不是 `2'd0`** ——
        //     ⚠️ `2'd0` 在指示层的表里是 **"变调"（紫）** ⇒ 🔴 **指示灯会说谎**
        //     （⭐ 这一档**根本没有推子**；⭐ 由 `tb/top/tb_top_led_strip.sv` 的 (3d) 钉住 ✅）
        assign led_gear_st   = 2'd3;
        //  📌 `led_looper_st` 仍是 `2'd0`（= 空闲 ⇒ 暗蓝）——
        //     ⭐ 因为用户的 looper 语义里**没有"无"这一档**（只有 空闲/录音/回放）
        //     ⇒ ⭐ "没有 looper" 与"looper 空闲"在**灯上是同一个状态**（⭐ 也是它的复位态）✅
        assign led_looper_st = 2'd0;
        //  ⭐⭐ 2026-10-09（`P0-06`）：⭐ **`fault_any_w` 必须在这里也驱动** ✅
        //   🔴 **原缺陷**：⭐ `g_silent` 分支逐个显式驱动了 **10 根**跨分支共享线
        //      （`pp_push`/`pp_data`/`scope_sample`/`scope_valid`/`sample_mono`/
        //       `tx_req`/`tx_byte`/`led_blink`/`led_beat`/`led_gear_st`/`led_looper_st`）
        //      ⚠️ **唯独漏了 `fault_any_w`** ⇒ 🔴 本档下它是 **`z`** ✅
        //   🔴 **后果（⭐ 为什么是 P0）**：
        //      · ⭐ **仿真**：⭐ `if (fault_any_w)` 判成 **X** ⇒ `fault_sticky` 变 X
        //        ⇒ ⭐ `hb_div_eff` 变 X ⇒ `hb_cnt >= hb_div_eff - 1` **恒为 X（判假）**
        //        ⇒ 🔴 **`hb` 永不翻转 ⇒ 心跳灯死** ✅
        //        ⇒ ⭐ **M0「活体见证」**（⭐ 本设计**唯一**的故障可观测手段）**在静默档上完全失效** ✅
        //      · ⭐ **硅片**：⭐ 综合对"无驱动网线"通常接 0（⭐ 一条极易被刷屏淹没的 warning）
        //        ⇒ ⭐ `fault_sticky` 恒 0 ⇒ 🔴 **故障指示永远不亮**
        //        ⇒ ⭐ `adc_farm` SPI 挂了 / `tdm_render_mixer` 超时了也**没人知道** ✅
        //   ✅ **修法**：⭐ 静音档两个故障源（`af_fault`/`mx_fault`）**都不存在**
        //      ⇒ ⭐ 明确声明 **"无故障"**（⛔ 不是留空让它悬空）✅
        //   📌 **代价**：⭐ 1 行、**0 资源** ✅
        //   📌 **机械旁证**：⭐ `Select-String 'assign\s+fault_any_w'` **必须返回 2 行**（两分支各 1）✅
        assign fault_any_w   = 1'b0;
        //  ⭐⭐ 2026-10-09（`P0-27`）：⭐ 静音档没有 `event_extract` ⇒ ⭐ 按键状态恒 0 ✅
        //   📌 与上面 `fault_any_w` 同一条纪律：⭐ **两个互斥分支各自显式驱动** ✅
        assign ee_key_on     = 16'd0;
        //  ⭐⭐ 2026-10-11（`U-19`）：⭐ 静音档没有 `play_seq` ⇒ ⭐ 三条跨作用域线**显式驱动** ✅
        //   📌 ⭐ 同一条纪律（⭐ 两个互斥分支各自显式驱动，⛔ 不留悬空）——
        //      ⚠️ 悬空 = `z` ⇒ 🔴 会顺着 `evt_buf.rd_ack_i` / `guide_lamp` 传播 `x` ✅
        assign ps_evt_rd     = 1'b0;
        assign ps_note_valid = 1'b0;
        assign ps_note_data  = 64'd0;
    end else begin : g_sound
        // ═══════════════════════════════════════════════════════════════════════
        //   ⭐⭐ `'P'` 诊断：⭐ 回传 `pos` 读数（⭐ 2026-09-24 新增）
        //
        //   🔴 **为什么加**（⭐ 上板实测）：
        //      ⭐ 跑 `'S'`（span）时只回 `s` + 一次轴号，🔴 之后全是 `!`（被拒）
        //      ⭐ 每个 `!` **正好隔 1 秒** ⇒ ⭐ `WAIT_TIMEOUT_CLK` ⇒ 🔴 **是超时**
        //      ⇒ ⚠️ 超时意味着"`calib_span` 在 `S_SETTLE` 等不到稳定读数"
        //      ⇒ 🔴 **而串口完全看不到 `pos`** ⇒ ⚠️ 没法判断"帧不来"还是"读数在抖"
        //
        //   ⭐ 本模块：⭐ 发 `'P'` ⇒ ⭐ 回一行 `P<4位十进制>\r\n`（⭐ 7 个字节）
        //      ⇒ ⭐ 连发几次 ⇒ ⭐ **看这个数抖不抖** ⇒ ✅ 一眼定位
        //
        //   📌 **回的是 `af0_pol`** —— ⭐ 与 `calib_span.raw_i` **同一路**
        //      ⇒ ⭐ **看到的就是它判稳定的那个数** ✅
        //   ⚠️ **它走 `u_tx_fifo`**（⛔ 不直连 `uart_tx`）
        //      📌 这正是 `K-126` 的教训：⭐ **别假设"下游有空"**


        // ── 出声链 ────────────────────────────────────────────────────────
        wire [POLY_TARGET-1:0]         nm_gate;
        wire [POLY_TARGET-1:0]         nm_active;
        //  ⭐ 重触发/抢占时命令包络先归零（→ envelope_bank.retrig_reset_i）
        //     ⚠️ 修的是"重触发时从残余电平重新 Attack ⇒ 幅度叠加成偶发尖音"，
        //        详见 note_manager.v 的 voice_retrig_reset_o 注释。
        wire [POLY_TARGET-1:0]         nm_retrig_reset;
        wire [POLY_TARGET*4-1:0]       nm_axis;
        wire [POLY_TARGET*32-1:0]      nm_phase;
        wire [POLY_TARGET*8-1:0]       nm_vel;
        wire [POLY_TARGET*2-1:0]       nm_timbre;
        //  ⭐⭐ 2026-09-29 新增（⭐ 鼓机噪声波表 · 阶段 2a）：⭐ **每 voice 的"是鼓吗"**
        //     ⭐ 来源：⭐ `note_manager.voice_drum_o`（⭐ = `(src_r[i] == SRC_AUX)` ✅，见 `note_manager.v` 的 `assign voice_drum_o[g]`）
        //     ⭐ 去向：⭐ `oscillator_bank.voice_drum_i` ⇒ ⭐ 保留池（⭐ 节拍器 /
        //       鼓机，⭐ 即来源 `SRC_AUX`）的 voice **改读第 10 张表（宽带噪声）** ✅
        //     🔴 为什么必须由 `top` 直连：⭐ 这条标志是**跨模块**的
        //        （⭐ `note_manager` 知道"谁在发声"，⭐ `oscillator_bank` 才知道"该读哪张表"）
        //        ⇒ ⭐ `top` 是唯一的连接点 ✅
        wire [POLY_TARGET-1:0]         nm_drum;
        //  ⭐⭐ 2026-10-08（`A3` 正确修法）：⭐ **每 voice 2 位的鼓分类**（⭐ `note_manager` → `oscillator_bank`）
        //   ⭐ 编码：⭐ `[v*2+1]` = 底鼓 · `[v*2+0]` = 嗵鼓 ✅
        //   📌 由 `note_manager` 在**提交那一刻**算好 ⇒ ⭐ `oscillator_bank` **当拍可用**
        //      ⇒ ⭐ **零窗口**（⛔ 不再受 `phase_tr` 轮转 ≤32 拍的影响）✅
        //   📌 它一接上 ⇒ `oscillator_bank` 里那 **64 个常量比较器整段不综合**（⭐ 净省 ~500 LUT）✅
        wire [POLY_TARGET*2-1:0]       nm_drum_cls;
        wire [POLY_TARGET*16-1:0]      nm_age;
        wire                           nm_alloc_valid;
        wire [4:0]                     nm_alloc_voice;

        wire [POLY_TARGET*OSC_PER_VOICE*16-1:0] ob_samples;
        wire                           ob_valid;
        wire [31:0]                    ob_phase_dbg;

        wire                           mx_valid;
        wire signed [SAMPLE_W-1:0]     mx_sample;
        wire                           mx_fault;
        //   ⭐ 2026-09-26 新增：⭐ 复音归一化的可观测输出（⭐ 当前活跃 voice 数）
        //      ⚠️ 未引到引脚 ⇒ ⭐ 综合时**不要**被优化掉：⭐ 它驱动的是寄存器树
        //         （⭐ 与 `mg_*` 那组同一手法）⇒ ⭐ 会保留，⭐ 上板可用调试核读。
        wire [$clog2(POLY_TARGET):0]   mx_n_active;

        // ⭐ 包络：`envelope_bank` 每 voice 一份 ADSR（与 `note_manager` 的 gate 对接）
        wire [POLY_TARGET*16-1:0]      env_level;
        wire [POLY_TARGET-1:0]         env_active;

        // ── ⭐ T43：实体 Test Mode（板载 USB-C UART 的 'M' 命令 + 串口屏触摸）─
        //   顺序：关 → 4 → 8 → 16 → 32 → 关。状态放在顶层而不是
        //   `calib_cmd`，确保串口控制的状态与实际音频链使用的是同一个寄存器。
        //   ⭐ 2026-09-27 丙：串口屏触摸控件 2（`ui_test_mode_commit`）与
        //      'M' 命令（`cmd_test_mode_req`）**并联**，两个入口驱动同一状态机。
        //      ⚠️ `ui_test_mode`/`ui_test_mode_n` 仅作可观测镜像（⛔ 非权威），
        //         权威状态是本 `tm_enable_r`/`tm_n_code_r`（接 `test_mode_ctrl`）。
        //  ⭐⭐ 2026-10-04（codex 只读评审「阶段 1」）：**`TEST_MODE_EN` 双码流**
        //  📌 诊断码流（`TEST_MODE_EN=1`）**行为与改动前逐字一致**；默认值保持 1，
        //     以免影响现有测试台与上板习惯。
        //  ⚠️ ⛔ 这里**不能**再套 `generate`/`endgenerate`：本块已在外层 `g_sound`
        //     的 generate 区里，嵌套会报 `Generate/endgenerate regions cannot nest`
        //     （2026-10-03 实测踩过）。
        wire                             tm_enable_r;
        wire [1:0]                       tm_n_code_r;
        wire [POLY_TARGET-1:0]           tm_gate;
        wire [POLY_TARGET*8-1:0]         tm_vel;
        wire [POLY_TARGET*OSC_PER_VOICE-1:0] tm_lane_active;
        wire [POLY_TARGET*OSC_PER_VOICE*32-1:0] tm_phase_inc;
        wire [5:0]                       tm_active_n;

        if (TEST_MODE_EN != 0) begin : g_test_mode
            // ── 诊断码流：原行为，一字不改 ─────────────────────────────────
            reg       tm_enable_q;
            reg [1:0] tm_n_code_q;
            assign tm_enable_r = tm_enable_q;
            assign tm_n_code_r = tm_n_code_q;

            always @(posedge clk) begin
                if (!rst_n_sync) begin
                    tm_enable_q <= 1'b0;
                    tm_n_code_q <= 2'b00;
                end else if (cmd_test_mode_req || ui_test_mode_commit) begin
                    if (!tm_enable_q) begin
                        tm_enable_q <= 1'b1;
                        tm_n_code_q <= 2'b00;  // 4 voices
                    end else if (tm_n_code_q == 2'b11) begin
                        tm_enable_q <= 1'b0;
                        tm_n_code_q <= 2'b00;
                    end else begin
                        tm_n_code_q <= tm_n_code_q + 2'b01;
                    end
                end
            end

            test_mode_ctrl #(
                .POLY_TARGET   (POLY_TARGET),
                .OSC_PER_VOICE (OSC_PER_VOICE),
                .PHASE_W       (32),
                .VEL_W         (8)
            ) u_test_mode_ctrl (
                .clk_i              (clk),
                .rst_n_i            (rst_n_sync),
                .sample_tick_i      (tick_audio),
                .enable_i           (tm_enable_r),
                .n_code_i           (tm_n_code_r),
                .test_voice_gate_o  (tm_gate),
                .test_velocity_o    (tm_vel),
                .test_lane_active_o (tm_lane_active),
                .test_phase_inc_o   (tm_phase_inc),
                .active_n_o         (tm_active_n)
            );
        end else begin : g_no_test_mode
            // ── 正式码流：整条 Test Mode 通路**不进网表** ─────────────────
            //    ⭐ 所有输出给确定常量 ⇒ 下游选择器被常量传播折叠掉，
            //       那条扇出 769 的长网**不存在**。
            //    📌 M 命令反馈会自然回 "关"（`tm_enable_r`=0）⇒ ⛔ 不会误报"已进入测试模式"。
            assign tm_enable_r    = 1'b0;
            assign tm_n_code_r    = 2'b00;
            assign tm_gate        = {POLY_TARGET{1'b0}};
            assign tm_vel         = {POLY_TARGET*8{1'b0}};
            assign tm_lane_active = {POLY_TARGET*OSC_PER_VOICE{1'b0}};
            assign tm_phase_inc   = {POLY_TARGET*OSC_PER_VOICE*32{1'b0}};
            assign tm_active_n    = 6'd0;
        end

        // ── ⭐ 开机自检音（A4+C#5+E5）的驱动信号 ──────────────────────────
        //    ⚠️ 必须**先声明后使用**（Verilog 不允许先用后声明）
        //    ⭐ 相位增量由 `f × 2^32 / fs` 精确算出（fs = 48828.125 Hz）：
        //       A4=440Hz    → 0x024E8ED9
        //       C#5=554.365Hz → 0x02E80E5D
        //       E5=659.255Hz  → 0x0374D64B
        //    ⚠️ `DEMO_NOTE_DELAY` 是顶层参数（tb 可改小以便快速仿真）
        localparam [31:0] INC_A4  = 32'h024E_8ED9;
        localparam [31:0] INC_CS5 = 32'h02E8_0E5D;
        localparam [31:0] INC_E5  = 32'h0374_D64B;

        // ⚠️ 计数器位宽必须够装下【两个延时里的大者】（⛔ 不要写死 24 位）
        //   🔴 **⚠️ 2026-09-23 踩到**：⭐ 原来只按 `DEMO_NOTE_DELAY`（默认 2M
        //      ⇒ 21 位）算，🔴 而 `DEMO_HOLD_CYC` 默认 **50M ⇒ 需要 26 位**
        //      ⇒ ⚠️ 若沿用 21 位 ⇒ 🔴 **计数器会【静默回绕】** ⇒
        //         ⭐ 保持时长变成错的（⚠️ 不报错、不警告）。
        //      📌 `K-107`/`K-34` 同族：⭐ **宽度不够 ⇒ 静默算错**。
        localparam integer DEMO_MAX = (DEMO_NOTE_DELAY > DEMO_HOLD_CYC) ? DEMO_NOTE_DELAY : DEMO_HOLD_CYC;
        localparam integer DEMO_CW = (DEMO_MAX < 2) ? 1 : $clog2(DEMO_MAX + 1);
        localparam [DEMO_CW-1:0] DEMO_DELAY_V = DEMO_NOTE_DELAY[DEMO_CW-1:0];
        localparam [DEMO_CW-1:0] DEMO_HOLD_V  = DEMO_HOLD_CYC[DEMO_CW-1:0];

        reg [DEMO_CW-1:0] demo_cnt;
        reg        demo_fired;
        reg [2:0]  demo_step;   // 3 bits: 0..7 (was 2 bits, max 3)
        reg        demo_note_valid;
        reg [3:0]  demo_note_axis;
        reg [31:0] demo_note_inc;
        reg [7:0]  demo_note_vel;
        reg [1:0]  demo_note_kind;

        envelope_bank #(
            .POLY_TARGET (POLY_TARGET),
            .VEL_W       (8),
            .ENV_W       (16)
        ) u_envelope_bank (
            .clk_i         (clk),
            .rst_n_i       (rst_n_sync),
            .sample_tick_i (tick_audio),
            // Test Mode takes ownership of gate/velocity, so old live/demo
            // notes cannot leak into the deterministic FFT acceptance signal.
            .gate_i        (tm_enable_r ? tm_gate : nm_gate),
            .velocity_i    (tm_enable_r ? tm_vel  : nm_vel),
            //  ⭐⭐ 2026-09-29 合并：⭐ **把音色送进包络**（⭐ 队友 `adsr` 按音色取 A/D/R 步长 ✅）
            //     ⭐ 逐 voice 取 2 bit（⭐ 与 `note_manager` 起音锁存的音色**同源** ✅）
            .timbre_i      (nm_timbre),
            //  ⭐ 重触发清零：Test Mode 不用（它自己控 gate），故只在普通通路生效。
            .retrig_reset_i(tm_enable_r ? {POLY_TARGET{1'b0}} : nm_retrig_reset),
            .env_level_o   (env_level),
            .env_active_o  (env_active)
        );

        // ═══════════════════════════════════════════════════════════════════
        // ⭐⭐ T33b: musical clock + metronome
        //
        // ⭐ The metronome is NOT a second audio path.  It emits ordinary
        //    note_evt_t events on the SAME path as the fingers do, so there is
        //    zero new audio routing and zero new compliance surface.
        //
        // ⚠️  Scope of THIS step: beat_gen + metronome are instantiated and the
        //     metronome's events reach note_manager.  The tempo is a constant
        //     today; U-7 (see the unfinished-work ledger) will drive
        //     tick_inc_i from tempo events in the score instead.
        // ═══════════════════════════════════════════════════════════════════
        // ⭐ 120 BPM at PPQN=960 on a 50 MHz clock:
        //     round(2^32 x 120/60 x 960 / 50e6) = 164927  (verified by hand)
        localparam [31:0] TICK_INC_120BPM = 32'd164927;

        wire        bg_tick;
        wire [15:0] bg_tick_cnt;
        wire        bg_bar_start;
        wire        bg_beat;
        wire        bg_transport;
        wire [15:0] bg_bar_cnt;
        wire        bg_wrap;
        // A beat is a one-clock event, not a visible lamp level.
        reg [22:0] guide_flash_count;
        always @(posedge clk) begin
            if (!rst_n_sync) guide_flash_count <= 0;
            else if (bg_beat) guide_flash_count <= 23'd6_250_000;
            else if (guide_flash_count != 0) guide_flash_count <= guide_flash_count - 1'b1;
        end
        assign led_blink = (guide_flash_count != 0);
        //   ⭐ 指示层：⭐ 拍点脉冲也引给"节拍器指示灯"（⭐ 与心跳灯**同一个** `bg_beat`）
        //      📌 `beat_o` 是**单周期**脉冲 ⇒ ⭐ 拉伸（亮多久）由 `led_indicator` 自己做 ✅
        assign led_beat  = bg_beat;

        // ═══════════════════════════════════════════════════════════════════
        //  ⭐⭐ 2026-10-11：`play_seq` —— ⭐ **曲谱按 tick 播放 ＋ 处理换速** ✅
        //
        //  🔴 **为什么现在才能例化**：⭐ 它的读侧要的是**标准同步 FIFO**
        //     （⭐ `evt_valid_i` ＋ `evt_data_i` ＋ `evt_rd_o`），
        //     ⚠️ 而 `evt_uart_rx` 只给**单拍脉冲** ⇒ ⭐ 中间必须有 `U-19` 缓冲
        //     ⇒ ⭐ 缓冲已在模块级建好（`u_evt_buf`）⇒ ⭐ **本块终于能落地** ✅
        //
        //  ⭐ **它在这里的两个职责**：
        //     ① ⭐ **按音乐位置吐事件**：⭐ `evt_tick <= cur_tick_r` 才发
        //        （⭐ 修掉"每个 tick 只取一条 ⇒ 和弦被拉成琶音"那个缺陷 ✅）
        //     ② ⭐⭐ **驱动 `beat_gen.tick_inc_i`**：⭐ `kind=2` 事件 ⇒ **硬件换速**
        //        （⭐ 相位连续 ⇒ 不跳拍、不断音 ✅ —— `beat_gen` ⛔ 不用改，已核实 ✅）
        //
        //  ⚠️⚠️ **`run_i` 必须与 `beat_gen.run_i` 【同一个值】**：
        //     ⭐ 契约原文：*"`cur_tick_r` 必须与 `beat_gen` 的音乐位置严格同步推进"*
        //        （⭐ 两者都靠**同一个 `tick_i`** 推进、⭐ 靠**同一个 `pos_reset_i`** 归零 ✅）
        //     🔴 而 `top.v` 的 `beat_gen` 是 **free-running（`run_i = 1'b1`）**
        //        —— ⚠️ 这是**有意的**（⭐ 停了 `bg_beat` ⇒ 🔴 心跳 LED 不闪，⭐ 见 L756 的长注释）
        //     ⇒ ⭐ 所以本模块也**必须**接 `1'b1`，⛔ **不能**接成别的"transport"信号
        //        （⭐ 否则两边位置**静默错位**：⭐ 事件按错误的时间播放，⭐ 且**不报错** ✅）
        //
        //  ⚠️ **`pos_reset_i` 接 `met_start`** —— ⭐ 与 `beat_gen.pos_reset_i` **同一个信号** ✅
        //     📌 ⭐ 这正是契约的硬要求（⭐ 见上），⭐ 且它顺带给了用户一个**可用的工作流**：
        //        **"先按 S2（位置归零）⇒ PC 再灌谱子 ⇒ 谱子从头按拍播放"** ✅
        //     🔴 **已知局限（⭐ 诚实标注）**：⭐ **播放中按 S2** ⇒ `cur_tick_r` 归零
        //        ⇒ ⚠️ 缓冲里"未来"的事件**全部立刻到期** ⇒ 🔴 **一次性地吐出来** ✅
        //        ⇒ ⭐ 正确用法：⭐ **起拍之后不要中途按 S2**（⭐ 要重放就让 PC 重灌 ✅）
        //
        //  📌 **`tick_inc_o` 是【寄存器输出】**（⭐ 契约 §2.1 专门确认过）
        //     ⇒ ⭐ `play_seq → beat_gen → play_seq` **不成组合环** ✅
        //  📌 **复位默认 = `TICK_INC_DEFAULT` = 164927 = 120 BPM**
        //     ⇒ ⭐ **与原来的常量 `TICK_INC_120BPM` 逐位相同**
        //     ⇒ ⭐ **没有曲谱时行为一字不变** ✅（⭐ 这是本次改动最重要的安全性论据 ✅）
        // ═══════════════════════════════════════════════════════════════════
        wire [31:0] ps_inc32;         // ⭐ `play_seq.tick_inc_o`（→ `beat_gen.tick_inc_i`）
        wire        ps_tempo_applied;
        wire        ps_underrun;
        wire [15:0] ps_evt_cnt;
        wire [15:0] ps_tempo_cnt;
        wire [19:0] ps_cur_tick;

        play_seq #(
            .EVT_W(64)
        ) u_play_seq (
            .clk_i          (clk),
            .rst_n_i        (rst_n_sync),
            .tick_i         (bg_tick),        // ⭐ 与 `beat_gen.tick_o` **同源** ✅
            .run_i          (1'b1),           // ⭐ **必须与 `beat_gen.run_i` 相同**（见上）
            .pos_reset_i    (met_start),      // ⭐ **与 `beat_gen.pos_reset_i` 同一个信号** ✅
            .tick_inc_o     (ps_inc32),       // ⭐ → `beat_gen.tick_inc_i` ✅
            .evt_valid_i    (eb_rd_valid),    // ⭐ 来自 `U-19` 缓冲（⭐ 模块级）✅
            .evt_data_i     (eb_rd_data),
            .evt_rd_o       (ps_evt_rd),      // ⭐ **组合**取数选通（⭐ 契约 §2.3.3 硬要求）✅
            .note_valid_o   (ps_note_valid),
            .note_data_o    (ps_note_data),
            .tempo_applied_o(ps_tempo_applied),
            .evt_underrun_o (ps_underrun),
            .evt_cnt_o      (ps_evt_cnt),
            .tempo_cnt_o    (ps_tempo_cnt),
            .cur_tick_o     (ps_cur_tick)
        );

        beat_gen #(
            .PPQN          (960),
            .BEATS_PER_BAR (4),
            .PHASE_W       (32),
            .TICK_INC_W    (32)
        ) u_beat_gen (
            .clk_i           (clk),
            .rst_n_i         (rst_n_sync),
            .run_i           (1'b1),            // free-running
            // ⭐⭐ 2026-09-28：**开节拍器时复位音乐位置** ⇒ ⭐ 第一声就是【强拍】
            //    🔴 原来是 `1'b0`（"no transport seek"）⇒ ⚠️ 按 S2 时 `tick_cnt_q`
            //       可能停在 1/2/3 ⇒ 🔴 **第一声是弱拍**（⭐ 用户上板实测反馈）
            //    ⚠️ `met_start` 是 **1 拍脉冲**（⛔ 不能常高 —— `pos_reset_i` 是电平，
            //       常高会让相位永远停在 0 ⇒ 节拍器彻底不响）
            //    📌 `beat_gen` 仍 **free-running**（⛔ 没改成 `met_on_r`）
            //       ⇒ ⭐ **心跳 LED 照常闪** ✅（见 `led_blink = bg_beat`）
            //    ⭐⭐ 2026-10-11（`U-19`）：⭐ **本信号同时喂 `play_seq.pos_reset_i`** ✅
            //       —— ⭐ 契约硬要求"两者必须接同一个信号"（⭐ 否则位置静默错位 ✅）
            .pos_reset_i     (met_start),
            //  ⭐⭐ 2026-10-11（`U-19`）：⭐ **速度由 `play_seq` 驱动**（⛔ 不再是常量）
            //     ⭐ `play_seq` 复位默认 = `164927` = **120 BPM** = 原来的常量
            //     ⇒ ⭐ **没有曲谱（没有 `kind=2` 事件）时，本行与改前逐位相同** ✅
            //     ⭐ 有 `kind=2` 时 ⇒ **硬件换速**（⭐ 相位连续、不跳拍 —— `beat_gen` 不用改 ✅）
            .tick_inc_i      (ps_inc32),
            .tick_o          (bg_tick),
            .tick_cnt_o      (bg_tick_cnt),
            .bar_start_o     (bg_bar_start),
            .beat_o          (bg_beat),
            .transport_o     (bg_transport),
            .bar_cnt_o       (bg_bar_cnt),
            .tick_cnt_wrap_o (bg_wrap)
        );

        wire        met_evt_valid;
        wire [3:0]  met_evt_axis;
        wire [31:0] met_evt_inc;
        wire [7:0]  met_evt_vel;
        wire [1:0]  met_evt_kind;
        wire [15:0] met_beat_cnt;
        wire [15:0] met_accent_cnt;
        wire        met_cfg_warn;

        metronome #(
            // ⭐ AXIS_ID stays 4'hE (14) as the metronome's event id -- PAIRED
            //    with note_manager.RESERVED_N above.  cfg_warn_o asserts if the
            //    two are inconsistent, so a mismatch is observable rather than
            //    silent (K-106 family).
            //    🔴 2026-10-01 更正：⭐ **保留池按【来源】选**（`src == SRC_AUX(3'd3)`，
            //       见 `note_manager.v` 的 `assign pool_mask[pg]`）⇒ ⛔ **不按轴号** —— ⭐ 旧文"so the event
            //       lands in the reserved pool by that axis" 已被代码推翻。
            .AXIS_W     (4),
            .PHASE_W    (32),
            .VEL_W      (8),
            .AXIS_ID    (14),
            .RESERVED_N (5),
            //  ⭐⭐ 2026-10-01：⭐ **节拍器抬 +1.75 dB**（⭐ 用户："背景的节拍器稍微大声一点"）
            //   ⭐ 原值 `180 / 108`（⭐ 模块默认，⭐ 保持不动）⇒ ⭐ 这里覆盖成 `220 / 132`
            //   ⭐ **为什么是 220 而⛔ 不是更高**（⭐ 余量算式，⭐ 与 `metronome.v` 的 `LIM_TH_W`/`KNEE_W` 余量算式同一口径）：
            //      ⭐ 软膝阈值 `T = 0x700000 = 7/8 FS = 87.5%`、⭐ 膝宽 `W = 2^20`（12.5% FS）⇒ ⭐ 天花板 `T + W/2 = 0x780000 = 15/16 FS = 93.75%`
            //         （⭐ 以代码为准：`tdm_render_mixer.v` 的 `LIM_TH_W`、`KNEE_W`、`ceil_w`；⭐ `sh24 = sh <<< 8` 同放大值与满幅 ⇒ 百分比不变）
            //      ⭐ 最坏"节拍器强拍 V + 键盘打满 255"：⭐ 分子 = 两路包络峰值之和 `(V + 255) × 256`、⭐ 再 `× 2^-OUTPUT_HEADROOM_SH`(=1) ⇒ `(V + 255) × 128`；⭐ 分母 = 满幅 FS = `2^16 = 65536`（⭐ 占 FS 的**线性百分比**，⛔ 不是 dB）：
            //         · `V=180` ⇒ `435 × 128 = 55680` ⇒ **`55680/65536 = 85.0% FS`** ⇒ ✅ **低于阈值 87.5%**（⭐ 余量 2.5% FS）
            //         · `V=220` ⇒ `475 × 128 = 60800` ⇒ **`60800/65536 = 92.7% FS`** ⇒ 🔴 **高于阈值 87.5% ⇒ 已进膝区**（⭐ 距天花板 93.75% 仅 1.0% FS；⭐ 膝内输出 ≈ 91.7% FS）
            //      ⇒ 🔴 **结论方向已变**：⭐ `220` **⛔ 不再是"不越膝"的上限**（⭐ 按现值阈值，不越膝的上限 = `V ≤ 193`，⭐ 因 `448 × 128 = 57344 = 87.5%` 恰好到阈值）；⭐ `230` ⇒ `485 × 128 = 62080` = **94.7% FS** ⇒ 🔴 超天花板 ⇒ 被夹到 `93.75%` ⛔
            //   📌 比例仍是 **5:3**（⭐ `220/132 = 5/3`）⇒ ⭐ 强拍:弱拍 的语义**一字未改** ✅
            //   ⚠️ **连带**：⭐ `tb/w3c/tb_met_start_top.sv:42-46` 的镜像**必须同步**（⭐ 已同步）✅
            .VEL_ACCENT (8'd220),
            .VEL_NORMAL (8'd132)
        ) u_metronome (
            .clk_i          (clk),
            .rst_n_i        (rst_n_sync),
            .beat_i         (bg_beat),
            .bar_start_i    (bg_bar_start),
            .transport_i    (bg_transport),
            .evt_valid_o    (met_evt_valid),
            .evt_axis_o     (met_evt_axis),
            .evt_phase_inc_o(met_evt_inc),
            .evt_velocity_o (met_evt_vel),
            .evt_kind_o     (met_evt_kind),
            .beat_cnt_o     (met_beat_cnt),
            .accent_cnt_o   (met_accent_cnt),
            .cfg_warn_o     (met_cfg_warn)
        );

        // ═══════════════════════════════════════════════════════════════════
        //   ⭐⭐ 鼓机（`drum_gen`，⭐ 2026-09-26 新增 · `T34`/`U-8`）
        //
        //   ⭐ **它做什么**：⭐ 纯合成鼓机（Kick/Snare/HiHat/Clap）+ **16 步音序器**
        //      ⇒ ⭐ **只吐事件**（⛔ 不碰音频通路）⇒ ⭐ 零新增合规风险。
        //   ⭐ **16 步音序器【合并】在本模块内**（⭐ 用户 2026-09-26 拍板）
        //      ⇒ ⛔ **不另做 `seq_16step.v`**（⭐ 少一个模块、少一层接口）。
        //
        //   🔴 **与节拍器【二选一】**（⭐ 用户 2026-09-24 拍板）：
        //      · `SEL_DRUM = 0` ⇒ ⭐ **节拍器**（⭐ **默认** —— 上板听的拍子声）
        //      · `SEL_DRUM = 1` ⇒ ⭐ **鼓机**
        //      ⇒ ⭐ **两者都例化**，⭐ 用 `sel_drum` 选谁接到 `evt_merge` 源 B。
        //      📌 **为什么不做成"运行时切换"**（⭐ 原设计）：
        //         ⚠️ 那需要改 `calib_cmd`（⭐ **明天上板要测的模块**）
        //         ⇒ ⭐ **本轮先做编译期参数**（⛔ 一行不碰 `calib_cmd`）；
        //            ⭐ 将来要现场切，⭐ 再加串口命令即可（⭐ 接口已就绪）。
        //
        //   ⭐ **`AXIS_ID = 15`**（⭐ 与节拍器的 14 分开）：
        //      ⚠️ `AXIS_W = 4` ⇒ ⭐ **≥ `RESERVED_AXIS_BASE`(14) 只有 14/15**（⭐ 进保留池按**来源** `SRC_AUX`，⛔ 不按轴号）
        //      ⇒ ⭐ 4 个乐器**共用 15**、⭐ 靠 `PHASE_INC` 区分音色
        //      （🔴 ⛔ 不改 `AXIS_W` —— 那会动**冻结的 64 bit 事件格式**）。
        //
        //   ⚠️ **`RESERVED_N` 的账**：⭐ 节拍器 1 + 鼓机 1（⭐ 共用轴号）⇒ **需要 2**
        //      ⇒ ✅ **当前 `RESERVED_N = 5` 够用**（⛔ 不用改 `note_manager` 例化）。
        // ═══════════════════════════════════════════════════════════════════
        wire        drm_evt_valid;
        wire [3:0]  drm_evt_axis;
        wire [31:0] drm_evt_inc;
        wire [7:0]  drm_evt_vel;
        wire [1:0]  drm_evt_kind;
        wire [15:0] drm_evt_cnt;
        wire [3:0]  drm_step_cnt;
        wire [3:0]  drm_hit_cnt;
        wire [15:0] drm_step_evt_cnt;
        wire        drm_cfg_warn;

        drum_gen #(
            .AXIS_W         (4),
            .PHASE_W        (32),
            .VEL_W          (8),
            // ⭐ 15 = 4'hF（⭐ 与节拍器的 14 分开 ⇒ 将来"同时用"不用返工）
            .AXIS_ID        (15),
            .N_DRUM         (4),
            .STEPS          (16),
            // ⭐ 16 分音符 = PPQN(960) / 4 = 240 tick
            .TICKS_PER_STEP (240),
            .RESERVED_N     (5),
            //  ⭐⭐ 2026-10-01：⭐ **鼓机抬偏轻的那几件**（⭐ 用户："背景的鼓机稍微大声一点"）
            //   ⭐ 原值（⭐ 模块默认，⭐ 保持不动）：`KICK 230 / SNARE 200 / HIHAT 140 / TOM 190`
            //   ⭐ 覆盖后：⭐ `SNARE 235` · ⭐ `HIHAT 175` · ⭐ `TOM 220`（⭐ `KICK` **不覆盖**）
            //   🔴 **底鼓为什么【故意不抬】**（⭐ 这是算过的，⛔ 不是省事）：
            //      ⭐ 最坏"底鼓 + 键盘打满 255"：⭐ `(230+255) × 256 × 2^-1 = `**`94.7% FS`**
            //         ⇒ ⚠️ **94.7% FS 已越过软膝【阈值 87.5%】**（⭐ 93.75% 是**天花板**、⛔ 不是阈值）（⭐ 本项目接受的取舍 ——
            //            `tb_velocity_headroom` 的判据**故意只判 `vel <= 200`**，⭐ 即 >200 的演奏峰值豁免）
            //      ⇒ ⭐ 再抬底鼓**只会让它更顶限幅器**（⚠️ `L83` 的教训：软限幅一直工作 = 听感"破"）
            //      ⇒ ⭐ **"背景更响"的收益应该做在【偏轻的那几件】上** ✅
            //   📌 顺序仍保持 **底鼓 > 军鼓 > 嗵鼓 > 踩镲**（⭐ `230 > 235`? ⚠️ 见下）
            //   ⚠️ **注意**：⭐ 抬完之后 **军鼓(235) 略高于 底鼓(230)** —— ⭐ 这是**有意**的：
            //      ⭐ 底鼓是低频、⭐ 听感响度本来就高；⭐ 军鼓偏中频、⭐ 抬到 235 才"打得出来" ✅
            //      📌 若上板觉得军鼓抢拍 ⇒ ⭐ **只改这一个数**（⭐ 保持 ⛔ 不动别的）✅
            .VEL_SNARE      (8'd235),
            .VEL_HIHAT      (8'd175),
            .VEL_TOM        (8'd220)
        ) u_drum_gen (
            .clk_i          (clk),
            .rst_n_i        (rst_n_sync),
            // ⭐⭐ 2026-09-29：⭐ 节奏型改成**运行时输入**（⭐ 串口 `'D'` 切）
            //   ⚠️ 原来是**参数** `.PATTERN_ID(DRUM_PATTERN_ID)`（⭐ 编译期常量）
            //      ⇒ 🔴 换型要重新 PnR（⭐ 见上方 §节奏型寄存器）
            //   📌 `DRUM_PATTERN_ID` 现在**只当复位初值**（⭐ 见 `DRUM_PATTERN_INIT`）✅
            //   🔴 **它现在是【端口】而⛔ 不是参数**（⭐ 所以必须写在**这里**，
            //      ⚠️ 写进上面的 `#(...)` 会报 `parameter pattern_id_i not found` —— 已实测）✅
            .pattern_id_i   (drum_pattern_r),
            //   ⭐ 与节拍器**同一个 `beat_gen`** ⇒ ⭐ 天然同拍（⛔ 不自己再分频）
            .tick_i         (bg_tick),
            .tick_cnt_i     (bg_tick_cnt),
            .bar_start_i    (bg_bar_start),
            .transport_i    (bg_transport),
            //  ⭐⭐⭐⭐ 2026-10-11（`P1-18`）：⭐ **位置复位必须与 `beat_gen` 同源** ✅
            //     🔴 **原缺陷**：⭐ `met_start` 只喂了 `beat_gen` ⇒
            //        ⭐ `beat_gen` 立刻把 `tick_cnt_o` 清 0，⚠️ 而 `drum_gen` **不知道**
            //        ⇒ 🔴 它的无符号差值法**下溢** ⇒ **假的步进** ⇒
            //        ⭐ 开鼓机时**强拍前一记多余鼓击**（⭐ 约 0.52 ms ⇒ **紧 flam** ✅）
            //     ✅ **现在两者同源** ⇒ ⭐ `drum_gen` 也清步进状态 ⇒ ⛔ 不发残余事件 ✅
            //     📌 ⭐ 而"**开鼓机从强拍开始**"照旧（⭐ 下一个 tick 的 `bar_start` 重新对齐 ✅）
            .pos_reset_i    (met_start),
            .evt_valid_o    (drm_evt_valid),
            .evt_axis_o     (drm_evt_axis),
            .evt_phase_inc_o(drm_evt_inc),
            .evt_velocity_o (drm_evt_vel),
            .evt_kind_o     (drm_evt_kind),
            .evt_cnt_o      (drm_evt_cnt),
            .step_cnt_o     (drm_step_cnt),
            .hit_cnt_o      (drm_hit_cnt),
            .step_evt_cnt_o (drm_step_evt_cnt),
            .cfg_warn_o     (drm_cfg_warn)
        );

        // ═══════════════════════════════════════════════════════════════════
        // ⭐⭐ W3a 采集链（⭐⭐ 2026-09-23 新增 —— "按琴键出声"的最后一环）
        //
        //   链路：`adc_farm` → 语义层（`axis_snapshot` → `axis_map`
        //          → `event_extract` / `param_extract`）→ `evt_merge` 源 A
        //
        //   ⭐ **为什么需要 `axis_snapshot`**：
        //      ⚠️ `adc_farm` 一次只给【一个通道】的样本
        //      ⇒ 🔴 **滑音/双音判据需要同时看相邻两轴** ⇒ ⭐ 必须先做**原子快照**。
        //
        //   ⚠️ **本版范围（⭐ MVP）**：
        //      ⭐ **单轴越阈 → `note_on`/`note_off`** ⇒ ⭐ **按琴键出声**
        //      ⚠️ **滑音/双音**：⭐ 接口已预留（`slide_*`/`two_note_*`），⛔ 本版恒 0。
        // ═══════════════════════════════════════════════════════════════════

        // ── ⭐ ① `adc_farm`：左手 2 片 + 可选 P4 右手 1 片 ────────────────
        wire        af_sample_valid;
        wire [2:0]  af_sample_ch;
        wire        af_frame_done;
        localparam integer ADC_N = (RIGHT_ADC_ENABLE != 0) ? 3 : 2;
        wire [ADC_N-1:0]  af_fault;
        wire [ADC_N*12-1:0] af_data;      // ⭐ packed：片 i = [i*12 +: 12]
        wire [ADC_N-1:0] af_cs_n, af_sclk, af_mosi;
        // ⭐ 默认只接前 2 片；P4 接线与 MCP3208 均确认后，才设
        //   RIGHT_ADC_ENABLE=1 让片 2 的 CH2/CH3 成为颤音控制。
        //   ⚠️ **端口留 6 位**（⭐ 为将来加左手板）⇒ 其余位【暂不接】，
        //      它们有内部上拉 ⇒ ⭐ 不会悬空乱跳 ✅
        wire [ADC_N-1:0] af_miso = spi_miso[ADC_N-1:0]; // 每片独立 MISO（K-06）

        adc_farm #(
            .N_ADC            (ADC_N),
            .CLK_HZ           (50_000_000),
            .SCLK_HZ          (1_000_000),
            .CHANNEL_RATE_HZ  (2_000)
        ) u_adc_farm (
            .clk              (clk),
            .rst_n            (rst_n_sync),
            .enable           (1'b1),     // ⭐ 常开（上电即采）
            .adc_cs_n         (af_cs_n),
            .adc_sclk         (af_sclk),
            .adc_mosi         (af_mosi),
            .adc_miso         (af_miso),
            .sample_valid     (af_sample_valid),
            .sample_ch        (af_sample_ch),
            .sample_data_packed(af_data),
            .sample_data0     (),
            .sample_data1     (),
            .sample_data2     (),
            .frame_done       (af_frame_done),
            .fault            (af_fault)
        );

        // ⭐⭐ 2026-10-01 BATCH 8.3（⭐ **重做**）：⭐ **把两个故障源汇成一条【模块级可见】的信号** ✅
        //   🔴 **第一次尝试为什么失败**（⭐ `ab133ac`，⭐ 已 `git revert` 为 `2857cc8`）：
        //      ⭐ 我在**模块级**直接引用了 `af_fault`/`mx_fault` ⚠️，
        //      ⭐ 而它们**声明在本 `generate` 块【内部】** ⇒
        //      🔴 `ERROR (EX3872): 'af_fault' is not declared` ⇒ ⭐ **综合门直接拦下** ✅
        //      ⭐⭐ **这正是"改 RTL 必须走综合门"的实证** —— ⭐ tb 不一定抓得到作用域错 ✅
        //   ✅ **正确做法**：⭐ 在**块内**汇成一条 `fault_any_w`（⭐ 它在块【外】声明）
        //      ⇒ ⭐ 模块级的心跳灯逻辑**只引 `fault_any_w`** ⇒ ⭐ 作用域就通了 ✅
        //   📌 两个源：⭐ `af_fault` = `adc_farm` 的 SPI/片选故障（⭐ 多位，⭐ 取或 ✅）
        //              ⭐ `mx_fault` = `tdm_render_mixer.deadline_fault_o`（⭐ 单 bit ✅）
        assign fault_any_w = (|af_fault) | mx_fault | ovf_any;   // ⭐ P0-29：把"丢事件/溢出"也 OR 进来 ✅

        // ⭐ 同源扇出 ⇒ 只用片 0 的 SCLK/MOSI 引到引脚
        //   ⚠️ `adc_farm` 内部已把片 1 扇出成与片 0 相同 ⇒ 这里取 `[0]` 即可
        assign spi_sclk = af_sclk[0];
        assign spi_mosi = af_mosi[0];
        //   ⭐ 片选：仅已启用的 ADC 被驱动；其余恒为不选中（1）。
        //      （⭐ `CS` 低有效 ⇒ 1 = 不选中）
        assign spi_cs_n[ADC_N-1:0] = af_cs_n;
        assign spi_cs_n[5:ADC_N] = {(6-ADC_N){1'b1}};

        // ── 右手控制入口：CH1=主音量、CH2=深度、CH3=颤音速率 ────────────
        // `right_analog_ctrl` 的 CH1 高 6 位经 64 点对数 LUT，直接产生
        // `master_mix` 所需的 Q1.15 增益；CH3 后一拍提交颤音参数。
        // ADC 未启用时，音量保持 unity、颤音控制为 0，保持现有两 ADC 板可用。
        wire [11:0] right_adc_data;
        if (RIGHT_ADC_ENABLE != 0) begin : g_right_adc_data
            assign right_adc_data = af_data[2*12 +: 12];
        end else begin : g_no_right_adc_data
            assign right_adc_data = 12'd0;
        end
        wire [15:0] master_gain;
        wire [11:0] vib_depth_raw, vib_rate_raw;
        wire        vib_ctrl_valid;
        right_analog_ctrl u_right_analog_ctrl (
            .clk_i            (clk),
            .rst_n_i          (rst_n_sync),
            .enable_i         (RIGHT_ADC_ENABLE != 0),
            .sample_valid_i   (af_sample_valid),
            .sample_ch_i      (af_sample_ch),
            .sample_data_i    (right_adc_data),
            .master_gain_o    (master_gain),
            .vibrato_depth_o  (vib_depth_raw),
            .vibrato_rate_o   (vib_rate_raw),
            .param_valid_o    (vib_ctrl_valid)
        );

        // ── ⭐⭐ 2026-10-03（P3）：⭐ **推子档位状态机**（`rtl/w3a/fader_gear.v`）──
        //
        //   ⭐ 来源：`files/20-代码/T3-后续计划-20261003.md` §P3 ＋ 定稿 §四
        //
        //   ⭐ 档位表（⭐ 用户裁定，⛔ 不许改）：
        //       档 0 = 变调（⭐ 左推子只管降、⭐ 右推子只管升，⭐ 各占半程）
        //       档 1 = 颤音（⭐ **上电默认** ⇒ ⭐ 与现状逐位一致 ⇒ 零回归 ✅）
        //       档 2/3 = 预留摇把 ⇒ ⭐ 结构上**不可达**（⭐ 见 `fader_gear.v` 的 'J' 处理）
        //
        //   ⭐ 接线（⭐ 一次只改一个变量：⛔ 不动 `right_analog_ctrl` 本身）：
        //       · `ch2_i`/`ch3_i` ← ⭐ `u_right_analog_ctrl` 的原始 CH2/CH3 输出
        //         （⭐ 即**现状语义**的颤音深度/速率 —— ⭐ 档 1 时逐位透传回去 ✅）
        //       · `gear_next_i`   ← ⭐ `'J'`（⭐ P2 拉出的那根线，⭐ 此前无人消费）
        //       · `trans_*`       ← ⭐ `'F'`/`'G'`/`'H'`（⭐ 与推子**共用目标寄存器**）
        //       · `transpose_semi_o` → ⭐ 模块层 `transpose_semi` → `note_manager`
        //       · `vibrato_depth_o`/`vibrato_rate_o` → ⭐ 下游 `u_vibrato_lfo`
        //       · `gear_o` → ⭐ 模块层 `led_gear_st` → ⭐ **指示层 led5**（推子功能）
        //         📌 2026-10-03 起有消费者了（⭐ 原来空着；⭐ 语义见 `led_indicator.v`）✅
        wire [11:0] vib_depth_sel, vib_rate_sel;
        fader_gear u_fader_gear (
            .clk              (clk),
            .rst_n            (rst_n_sync),
            .gear_next_i      (cmd_gear_next_req),
            .ch2_i            (vib_depth_raw),
            .ch3_i            (vib_rate_raw),
            .trans_down_i     (cmd_trans_down_req),
            .trans_up_i       (cmd_trans_up_req),
            .trans_abs_i      (cmd_trans_abs_req),
            .trans_abs_val_i  (cmd_trans_abs_val),
            .gear_o           (led_gear_st),   // ⭐ 2026-10-03：⭐ 引出给指示层 led5
            .transpose_semi_o (transpose_semi),
            .vibrato_depth_o  (vib_depth_sel),
            .vibrato_rate_o   (vib_rate_sel)
        );

        // ── ⭐ ② `calib` ×2：逐通道零点/灵敏度标定 ───────────────────────
        //   ⚠️ `calib` 是**单片 8 通道**的 ⇒ ⭐ **每片一份**（⭐ 设计草案 `D1`）
        //   ⚠️ **本版先【旁路】标定**（⭐ `tare`/`span` 未接 ⇒ 输出 = 输入）
        //      ⇒ ⭐ 因为上电自校需要**实物配合**（⚠️ 硬件未到手）
        //      🔴 **TODO（上板后）**：接上电自校序列（`tare`/`span` 打拍）
        wire [11:0] cal0_val, cal1_val;
        wire [2:0]  cal0_ch,  cal1_ch;
        wire        cal0_vld, cal1_vld;
        //   ⭐⭐ 2026-09-23 阶段B：`busy`/`err` 从【空连接】改为**接出**
        //      🔴 接入前它们悬空 ⇒ ⭐ `calib_span` **看不到标定是否失败**
        //      ⇒ ⚠️ 那正是"静默卡死"缺陷 ③ 的现场（⭐ 见总账 §十）。
        //      ⚠️ 两片**只取片 0** —— ⭐ 因为两片锁步 ⇒ 行为一致
        //         （⭐ 与 `tb_calib_autotare` 里"一片就够"的理由相同）。
        wire        cal0_busy, cal0_err;
        wire        cal1_busy, cal1_err;

        //   ⭐⭐ 2026-09-30：⭐ 修「`cal1_err` / `cal1_busy` 盲区」
        //
        //   🔴 **病灶**：⭐ 上面这两个 `wire` 从 2026-09-23 起就**只接出、⛔ 从未被读** ——
        //      `u_calib_span` 的 `.cal_busy_i` / `.cal_err_i` **只接了片 0**
        //      ⇒ ⭐ **片 1（左手板 2）的 span 失败【完全不可见】** ⚠️
        //
        //   🔴 **后果（⭐ 就是"板 2 比板 1 小声"的机制）**：
        //      ⭐ `calib_span.span_o` 是**两片同拍广播**（`span_o <= {N_ADC{1'b1}}`），
        //         且 `cal_ch_mux` **两片共用** ⇒ ⭐ 标"轴 8"时片 1 的 ch0 也同时被标。
        //      ⭐ 若只按板 1 ⇒ 片 1 那一路 `raw <= zero` ⇒ ⭐ 片 1 走 `err` 分支
        //         ⇒ 🔴 它的增益被写成 1.0（⭐ 未归一化），
        //         ⚠️ **而回包仍然是 `.`** ⇒ ⭐ **看似成功、实际没归一化** ✅
        //      ⇒ ⭐ 板 2 的 `pos` 一直按"裸行程"走 ⇒ ⭐ **比板 1 小声** ✅
        //
        //   ✅ **修法**：⭐ **两片都成功才算成功、任一片失败都算失败** ✅
        //      ⭐ 即 `cal1_err` 也纳入失败判据、`cal1_busy` 也纳入成功条件。
        //   ⚠️ **代价（⭐ 必须知道）**：⭐ 片 1 未接时它的 `raw` 恒为 4095（MISO 被上拉）
        //      ⇒ ⭐ `err` 恒高 ⇒ ⭐ **`'S'` 会一直回 `!`** ⇒ ⚠️ 单板现场请按下方
        //      `cal_err_any` / `cal_busy_all` 两行的注释改成"只看片 0"再重编译。
        //   ⭐ 开关（⭐ 1 = 两片都必须成功 · 0 = 只看片 0）：
        //      ⭐ 当前 = 【1】双板现场 ⇒ 两片都必须成功 ✅
        //      ⚠️ 单板现场（⭐ 片 1 未接 ⇒ 它的 `err` 恒高 ⇒ `'S'` 会一直回 `!`）
        //         ⇒ ⭐ 把下面两行改成 `= cal0_err;` / `= cal0_busy;` 后重编译即可 ✅
        //   ⭐⭐ 2026-09-30（紧急修复）：⭐ **开关落成 `localparam`**，⛔ 不再靠"手改逻辑行"
        //     ⚠️ 上一版把它写成"把这两行改成 `cal0_err`/`cal0_busy` 再重编译"
        //        ⇒ ⚠️ 现场容易改错、且**不可追溯**（⭐ 改了哪版说不清）✅
        //     ⭐ 语义（⭐ 已核到代码级）：
        //       · ⭐ `calib_span.S_NEXT` **先判 `cal_err_i`、后判 `cal_busy_i`**
        //         （⭐ `calib_span` 的 `S_NEXT` 里判 `cal_err_i` / `cal_busy_i` 那两处）⇒ ⭐ **"任一片失败 ⇒ 拒绝"这条与 `&`/`|` 无关** ✅
        //       · ⭐ 而"通过"这条路**只在两片都成功时**才需要 ⇒
        //         ⭐ 两片都成功 ⇒ 两片 `busy` **同拍为 1**（⭐ 两片锁步）⇒ `&` 与 `|` **等价** ✅
        //       ⇒ ⭐ 所以 `&` **不会**堵住通过路径 ✅
        //       ⇒ ⭐ 而 `|` 反而会在"片 0 成功、片 1 既没 `busy` 也没 `err`"时
        //         **把一次可疑的标定误判成通过** ⚠️（⭐ 那就又回到"静默失败"了）
        //       ⇒ ⭐⭐ **结论：保留 `&`** —— ⭐ 它是最保守、也是唯一不会静默放行坏片的选择 ✅
        //     ⭐ 开关（⭐ 1 = 两片都必须成功【⭐ 双板现场 · 默认】· 0 = 只看片 0【⭐ 单板现场】）：
        //       ⚠️ 单板现场（⭐ 片 1 未接 ⇒ 它的 `raw` 恒 4095 ⇒ `err` 恒高 ⇒ `'S'` 会一直回 `!`）
        //          ⇒ ⭐ 把下面这一行改成 `= 0` 再重编译即可 ✅（⛔ 不用动逻辑行）
        localparam integer SPAN_CHECK_BOTH = 1;
        //  ⭐⭐ 2026-10-09（`P0-10`，⭐ 用户拍板选 A）：⭐ **归并式挪到下面**
        //   🔴 **为什么挪**：⭐ 新的归并式要按片选（⭐ 用 `sp_cur_axis[3]`）
        //      ⚠️ 而 `sp_cur_axis` **在下面才声明**（⭐ 见 `wire [3:0] sp_cur_axis, sp_done_cnt;`）
        //      ⇒ ⭐ Verilog **先声明后使用** ⇒ ⛔ 不能写在这里（⭐ 否则 `Unable to bind`）✅
        //   📌 新定义见 `sp_cur_axis` 声明之后 ✅

        // ═══════════════════════════════════════════════════════════════════
        // ⭐⭐ 上电自动零点标定（⭐ `calib_autotare`，2026-09-23 接入）
        //
        //   🔴 **为什么必须做**：⚠️ `calib` 未标定时 `zero = 0`
        //      ⇒ ⭐ **松手时读到的不是 0**（⭐ 实测松手 1.60 V ≈ **1985 码**）
        //      ⇒ 🔴 `event_extract` 的触发阈**按错的基准判**
        //         ⚠️ 松手就被判成"按下"（挂音）、⚠️ 或要按很深才触发。
        //
        //   ⭐ **它做什么**：⭐ 上电等 ~200 ms（让霍尔供电稳定），
        //      ⭐ 然后**逐个通道发一次 `tare`** ⇒ ⭐ 把每个轴的"松手位"记为零点。
        //
        //   🔴🔴 **关键难点**：⭐ `calib.v` 的 `if (tare) zero_r[cal_ch] <= raw;`
        //      ⇒ ⚠️ **`raw` 是【当拍输入】**（⭐ 芯片当前送来的那个通道的值）
        //      ⇒ 🔴 **`tare` 必须与 `sample_ch` 对得上**，否则会把**别的通道**的值
        //         记成这个通道的零点 —— ⭐ **而且没有任何报错**（`K-87` 同族）。
        //      ⭐ `calib_autotare` 用"**等 `sample_ch == cur_ch`**"来对齐
        //         ⇒ ⚠️ 该判据已用**反向变异**验证：⭐ 错一拍 ⇒ tb 立刻红。
        //
        //   ⛔ **不做 `span`** —— ⚠️ 它需要人把每个轴按到底 ⇒ ⭐ 留给"校准模式"。
        //   📌 依据：`files/20-代码/上电自动tare-设计方案-20260923.md`
        // ═══════════════════════════════════════════════════════════════════
        wire [1:0] at_tare;
        wire [2:0] at_ch;
        wire       at_busy, at_done;

        // ═══════════════════════════════════════════════════════════════════
        // 🔴🔴 **2026-09-26 上板实测修复：⭐ `at_done` 放行【必须延迟】**
        //
        //   ⭐ **上板症状**（⭐ 用户实测）：⭐ *"只有那个空灵沉闷的水怪低吼"* +
        //      ⭐ 示波器 *"波动，最高 1.4V，有时有负值"*
        //
        //   ⭐⭐ **探针实测（⭐ 决定性，`build/exp/dbg_when.sv`）**：
        //      ```
        //      at_done 上升沿 = cycle 109821
        //      —— 之后 5~19 拍内，event_extract 连发 8 个 note_on ——
        //      #  cycle   at_done  ee_valid  axis   pos
        //      0  109826     1        1       0    2110   ← 🔴 pos = 未 tare 的脏值!
        //      1  109828     1        1       1    2109
        //      ...                                   2110 = 4095 - 1985
        //      7  109840     1        0      11    2107
        //      ```
        //      ⇒ 🔴 **8 个 `note_on`，且【没有对应 `note_off`】**
        //      ⇒ ⭐ `nm_active = 0xff`（8 个 voice 恒 held）
        //      ⇒ 🔴 **8 个 voice 一直在响 ⇒ 就是那个"水怪低吼"** ✅
        //
        //   🔴 **根因：⭐ `done_o` 与 `tare` 同拍，而 `zero` 要晚 2 拍才生效**
        //      ⭐ `calib_autotare.v`：
        //         ```verilog
        //         tare_o   <= {N_ADC{1'b1}};              // ⭐ T 拍发出
        //         if (cur_ch == (NCH-1)) state <= ST_DONE; // ⭐ 同拍 ⇒ done_o 立刻置起
        //         ```
        //      ⭐ `calib.sv` 的 `zero_r` / `prod_r` 赋值：
        //         ```verilog
        //         if (tare) zero_r[cal_ch] <= raw;                       // ⭐ T+1 才写入
        //         prod_r <= (raw > zero_r[ch]) ? ... : 0;                // 🔴 T+1 用【旧 zero】算!
        //         ```
        //      ⇒ ⭐ 时序：⭐ `T` 发 tare · ⭐ `T+1` 写 zero **且 `enable_i` 已放行（用脏值）** ·
        //         ⭐ `T+2` `prod_r` 才正确
        //      ⇒ 🔴 **`event_extract` 抢在 `zero` 生效前用脏 `pos` 判按键**
        //         （⭐ `pos = 2110 ≫ TRIG_TH = 192` ⇒ ⭐ **16 个轴全被判"按下"**）
        //
        //   ⭐⭐ **修法：⭐ `enable_i` 用【延迟后】的 `at_done`**
        //      · ⭐ 延迟 `AT_EN_DELAY` 拍（⭐ 默认 16，⛔ 只多 16 拍 = 320 ns，⭐ 无感）
        //      · ⭐ **只改 `enable_i` 这一处** ⇒ ⚠️ `at_done` 本身（⭐ UART 回传等）不变
        //      📌 **为什么给 16 拍而⛔ 不是精确 2 拍**：
        //         ⚠️ 除了 `zero`/`prod_r`，⭐ 后面还有 `axis_snapshot` 的采集与
        //            `as_valid` 的帧同步 ⇒ ⭐ **留足余量，⛔ 不抠那两拍**。
        //         ⭐ 代价：⭐ 上电后晚 320 ns 才响应按键 ⇒ ⚠️ 完全不可感知。
        //      ⭐ **`enable_i=0` 期间 `event_extract` 会持续清 `key_on`/`refr`**
        //         ⇒ ⭐ 延迟结束后**从干净的"全松开"状态开始** ✅（⭐ 语义不变）
        // ═══════════════════════════════════════════════════════════════════
        localparam integer AT_EN_DELAY = 16;
        reg [AT_EN_DELAY-1:0] at_done_dly;
        always @(posedge clk) begin
            if (!rst_n_sync) at_done_dly <= {AT_EN_DELAY{1'b0}};
            else             at_done_dly <= {at_done_dly[AT_EN_DELAY-2:0], at_done};
        end
        //   ⭐ 延迟后仍要求 `at_done` 为 1（⭐ 移位链满 ⇒ 连续 16 拍都为 1）
        wire at_en_ready = at_done_dly[AT_EN_DELAY-1];

        // ═══════════════════════════════════════════════════════════════════
        // ⭐⭐ `calib_span` 的端口信号 —— 🔴 **必须在 `u_autotare` 【之前】声明**
        //
        //   🔴🔴 **这是一个真实的踩坑记录（⭐ 2026-09-23，与 `af0_pol` 同族）**：
        //      ⚠️ 我原先把这些 `wire` 声明写在 `u_calib_span` **例化之前**，
        //         ⭐ 但 `u_autotare.retrig_i` 用到了 `sp_busy`（⭐ 互锁门控），
        //         ⚠️ 而 `u_autotare` **在 `u_calib_span` 之前** ⇒ 🔴 **先用后声明**
        //      ⇒ 🔴 iverilog 只报 **`warning: implicit definition of wire 'sp_busy'`**
        //         ⚠️ **不是 error！** ⇒ ⭐ 它会把 `sp_busy` **隐式建成 1 位 wire**
        //         🔴 而真正的 `sp_busy` 也是 1 位 ⇒ ⚠️ **这个例子里恰好无害**，
        //            ⭐ 但**换成一个多位信号就会被静默截断**（⭐ `83 号` 那个坑：
        //            `wire` 不写位宽就是 1 位）⇒ 🔴 **完全可能悄悄坏掉**
        //      📌 **纪律**：⭐ **`implicit definition` 的 warning 必须当 error 对待** ——
        //         ⚠️ 它意味着"声明顺序错了"，⛔ 不要因为"看起来能跑"就放过。
        //   ⭐ 修法：⭐ 把所有 `sp_*` 声明**统一提到 `u_autotare` 之前**
        //      （⭐ 即"谁先用到，谁之前就得声明"）。
        // ═══════════════════════════════════════════════════════════════════
        wire [1:0] sp_span;          // ⭐ 逐片（⭐ 锁步 ⇒ 同拍）
        wire [2:0] sp_ch;
        //  ⭐⭐ 2026-10-09（`P0-09`）：⭐ `calib_span` 的投票代表值（⭐ 只在 `sp_span` 那拍有效）✅
        wire [11:0] sp_span_val;
        //  ⭐⭐ 2026-10-09（`P0-10`，⭐ 用户拍板选 A）：⭐ **反馈按片选** ✅
        //   🔴 **原缺陷**：⭐ 原来归并两片（`cal0_err | cal1_err` / `cal0_busy & cal1_busy`）
        //      ⚠️ 而 span 是**两片同拍广播**的 ⇒ ⭐ 标轴 8 时片 0 的 ch0 也被标
        //      ⇒ 🔴 片 0 没按下 ⇒ `cal0_err=1` ⇒ ⭐ **整轴被拒** ⇒ 必须**双手同按** ✅
        //      ＋ 🔴 另一片的 `den_r` 来自**未经静止判定**的采样 ⇒ 增益误差可达 **74%** ✅
        //   ✅ **修法**：⭐ span 已改成按片单发（`calib_span`）⇒ ⭐ 反馈也必须按片选
        //      ⇒ ⭐ 只看**目标轴所在那片**的 `err`/`busy` ✅
        //   📌 `SPAN_CHECK_BOTH` 现在**失去意义**（⭐ 一次只有一片被标）——
        //      ⚠️ 保留 `localparam` 只为 ⛔ 不改动别处的引用 ✅
        //   ⚠️⚠️ **位置纪律**：⭐ 必须在 `sp_cur_axis` **声明之后**（⭐ 见下面那一行）
        //      —— 🔴 我第一次放在声明前 3 行 ⇒ iverilog 直接 `Unable to bind wire/reg/memory`
        //      （⭐ 而 ⚠️ **Gowin 综合却报 0 ERROR** ⇒ ⭐ 只有 iverilog 抓得到）✅
        wire       sp_busy, sp_done, sp_need_press, sp_reject;
        wire [3:0] sp_cur_axis, sp_done_cnt;
        wire cal_err_sel  = sp_cur_axis[3] ? cal1_err  : cal0_err;
        wire cal_busy_sel = sp_cur_axis[3] ? cal1_busy : cal0_busy;
        // ⭐⭐ 2026-09-30 新增：`calib_autotare` 的"跳过/失败"指示
        //   🔴 **必须在 `u_autotare` 之前声明**（⭐ 同 `sp_*` 的理由：
        //      ⚠️ 否则 iverilog 只报 `implicit definition` warning
        //      ⇒ 🔴 **隐式建成 1 位 wire**，`at_skip` 会被静默截断）
        wire [7:0] at_skip;
        wire       at_fail;
    // ⭐⭐ 2026-09-24 新增：⭐ span 的内部状态（⭐ 供 `'P'` 诊断回传）
    wire [2:0] sp_state;
    wire [3:0] sp_rej_cnt;
    // ⭐⭐ 2026-09-30 新增：⭐ `calib_span` 的**拒绝原因码**（⭐ 上板诊断用）
    //   ⭐ 见 `calib_span.v` 的 `RJ_*` 与端口 `rej_why_o`
    wire [2:0] sp_rej_why;
        //   ⭐ `'S'` 的门控（⭐ 与 autotare 做互锁）—— ⚠️ 同样必须先声明
        //   ⭐⭐ 2026-09-30 修：⛔ 原来用 `~at_busy` —— 而 `at_busy` 只在 `ST_SWEEP` 为高
        //      ⇒ ⚠️ 复位后 200 ms 的 `ST_WAIT` 期间发 `'S'` 【不被拒】
        //      ⇒ 🔴 autotare 随后进 `ST_SWEEP`，它的 `tare` 会把【正在被 span 标的那个轴】
        //         的 `zero_r` 写成按下值 ⇒ 破坏零点 ⇒ `raw <= zero` ⇒ err ⇒ 全拒
        //      ⇒ ⭐ 改用【现成的 `at_done`】（⭐ `state == ST_DONE`）
        //         ⇒ ⭐ 只有标定【全部完成后】才放行；⭐ `'T'` 重标期间 `at_done` 落 0 ⇒ 自动再互锁 ✅
        //      📌 与 handoff §6.2 的"200 ms 内发 'S' 会被忽略、回 '!'"一致 ✅
        wire       sp_start_gated = cmd_span_req & at_done;
        wire       sp_start_rejected = cmd_span_req & ~at_done;

        calib_autotare #(
            .NCH      (8),
            .N_ADC    (2),
            //   ⚠️ 可调：`AUTOTARE_DELAY_CLK` ⭐ 默认 10M 拍 ≈ 200 ms @50 MHz
            //     ⚠️ 提成参数是为了**让 tb 能改小**（⭐ 否则仿真要跑 10M 拍）
            .DELAY_CLK(AUTOTARE_DELAY_CLK),
            //   ⭐⭐ 2026-09-30 新增：「静止才捕获」守卫的参数
            //     ⭐ 判静止用【逐通道 `raw` 帧间差】（⛔ 不用 `pos` —— 那是自指）
            //     ⭐ 超时按 `clk` 计（⛔ 不用帧计数 —— ADC 停流时永不到期）
            .STILL_EN     (1),
            .DW           (12),
            .STILL_TOL    (48),        // ⭐ 帧间 `raw` 变化 ≤ 48 码算"没动"
                                       //   ⭐ 2026-10-01 由用户裁定从 8 提到 48（= `calib_span` 侧的 `STABLE_TOL`）
                                       //   🔴 为什么：⭐ 8 太苛刻 —— 实测"键按住不动时 raw 的帧间 |Δ| 仍可达 ~23 码"
                                       //      （⭐ 这正是 `calib_span` 当初把 `STABLE_TOL` 定成 48 的原因）
                                       //   ⇒ ⚠️ 在 8 之下，⭐ 守卫会把【正常按住】判成"在动" ⇒ 该轴永不捕获
                                       //      ⇒ 🔴 标定被跳过 ⇒ 全体挂音（⭐ `R1` 风险，已在任务书登记）
                                       //   ⚠️ 若上板实测"全体挂音"仍出现 ⇒ ⭐ 说明 48 还不够，
                                       //      下一步应查【是不是 raw 抖动本身异常】⛔ 不是继续往上加
            .STILL_FRAMES (4),         // ⭐ 连续 4 帧静止才允许捕获（4 帧 ≈ 2 ms）
            .WAIT_MS      (1000),      // ⭐ 单通道最长等待 1 s ⇒ 到期跳过该轴
            .CLK_HZ       (50_000_000)
        ) u_autotare (
            .clk           (clk),
            .rst_n         (rst_n_sync),
            .sample_valid_i(af_sample_valid),
            .sample_ch_i   (af_sample_ch),
            //   ⭐⭐ 判"静止"用的原始码：⭐ **【所有片】打包**（⭐ 2026-09-30 夜 修 `N13`）
            //      （⭐ `af_data` 的声明在其上方，⭐ **早于本例化** ⇒ 可用 ✅）
            //   ⚠️ 极性反相是**镜像** ⇒ `|Δraw|` **极性无关** ⇒ ⭐ 用反相前的码等价 ✅
            //   🔴 **为什么必须给【全部片】**：⭐ `tare_o` 是 `{N_ADC{1'b1}}`
            //      ⇒ ⭐ **两片【同拍锁步】一起发**（⭐ 见 `calib_autotare` 的逐通道 `tare` 扫描）
            //      ⇒ ⚠️ 若只给片 0，则【板 2 的键"按住不动"】对守卫**完全不可见**
            //      ⇒ 🔴 板 2 把【按下位】记成零点 ⇒ ⭐ **那个键永远触发不了**
            //      （⭐ 这正是用户实测的"板2 某几个键不响"）
            //   ⚠️ `af0_pol`/`af1_pol` 的声明在其**下方**（⭐ **晚于**本例化）⇒ ⛔ 用不了，
            //      只能用打包的原始码（⭐ 上一条已说明极性无关）✅
            .sample_data_i (af_data[ADC_N*12-1:0]),
            // ⭐⭐ `retrig_i`：⭐ 接 `'T'` 命令（⭐ 2026-09-23 阶段C 接通）
            //   🔴 **互锁（⭐ 与 `'S'` 对称）**：⭐ `span` 忙时**忽略 `'T'`**
            //      ⚠️ 否则 `tare` 与本轴的 `span` 同拍 ⇒ 🔴 **增益算错**（⭐ 见 `cal_ch_mux`）
            //   ⚠️ 被拒时不额外回传（⭐ `'T'` 本来就有 `'t'` 回执，⭐ 够用）
            .retrig_i      (cmd_tare_req & ~sp_busy),
            .tare_o        (at_tare),
            .cal_ch_o      (at_ch),
            //   ⭐⭐ 2026-09-30：⭐ 超时被跳过的轴（⭐ 1 = 本轴从未成功标定）
            //      ⚠️ 必须有可观测指示 —— ⛔ 否则"跳过"是静默的
            .skip_mask_o   (at_skip),
            .fail_o        (at_fail),
            .busy_o        (at_busy),
            .done_o        (at_done)
        );

        // ═══════════════════════════════════════════════════════════════════
        // ⭐⭐ 满行程（`span`）标定 —— ⚠️ **例化体在下方**（⭐ 见 `af0_pol` 之后）
        //
        //   🔴 **为什么不能写在这里**（⭐ 2026-09-23 踩到）：
        //      ⚠️ `calib_span.raw_i` 必须接 **`af0_pol`**（⭐ 反相后、`calib` 前那一路）
        //      🔴 而 `af0_pol` 由 `axis_polarity()` 函数算出，
        //         ⭐ 那个函数**定义在 `calib` 之前**（⭐ 见下方）
        //      ⇒ 🔴 **Verilog 里"声明必须先于使用"** ⇒ ⚠️ 写在这里会报
        //         `Unable to bind wire/reg/memory 'af0_pol'`
        //      📌 这正是本项目的老坑（⭐ 交接文档也记了"声明必须先于使用"）。
        //   ⇒ ⭐ 完整说明与例化体见 `af0_pol` 声明【之后】那一段。
        // ═══════════════════════════════════════════════════════════════════

        // ═══════════════════════════════════════════════════════════════════
        // ⭐⭐ 霍尔极性反相 —— ⭐ **位置在 `calib` 【之前】**（2026-09-23 第 2 版）

        // ═══════════════════════════════════════════════════════════════════
        // ⭐⭐ 霍尔极性反相 —— ⭐ **位置在 `calib` 【之前】**（2026-09-23 第 2 版）
        //
        //   🔴🔴 **为什么必须放在 `calib` 之前（⭐ 实测踩过）**：
        //      ⭐ `calib.sv` 的 `prod_r` 公式是
        //         `prod_r <= (raw > zero_r[ch]) ? ((raw - zero_r[ch]) * gain) : 0`
        //      ⇒ ⚠️ **它【内建假设】"按下 ⇒ raw 变大"**。
        //      ⚠️ 而实测是 **"按下 ⇒ raw 变小"**（松手 1985 → 触底 1241）。
        //
        //      ⇒ 🔴 **若把反相放在 `calib`【之后】**（⭐ 我第一版就是这么写的）：
        //         · `tare` 记下松手位 `zero = 1985`
        //         · 松手 ⇒ `1985 > 1985` 假 ⇒ out = **0**
        //         · 触底 ⇒ `1241 > 1985` 假 ⇒ out = **0**（⭐ 负差被钳到 0）
        //         ⇒ 🔴 **整段行程都是 0** ⇒ ⭐ 反相后 `pos ≡ 4095`
        //         ⇒ 🔴 **永远触发、分不出按下与松手** ⇒ ⛔ **完全无法演奏**。
        //      ⭐ 实测证据：`[rest] pos=4095` 与 `[press] pos=4095` **完全相同**。
        //
        //   ⭐⭐⭐ **两个改动【单独都对、合起来错】**（⭐ 这是本条的教训）：
        //      · `INVERT_AXIS` 单独看 ✅（把下降变上升）
        //      · `autotare`     单独看 ✅（清零点偏置）
        //      · 🔴 **合起来** ⇒ 全 0 —— ⚠️ 因为 `calib` 的**减法方向**是错的。
        //      ⚠️ 更隐蔽的是：**没 `tare` 时反而"正常"**（`zero=0` ⇒ `raw-0=1985`）
        //         ⇒ 🔴 **加了 `autotare` 反而破坏原本能工作的链路**。
        //
        //   ⭐ **正解：反相放到 `calib` 之前** ⇒ ⭐ 让送进 `calib` 的 `raw'`
        //      满足它的方向假设（"按下 ⇒ `raw'` 变大"）：
        //         · 松手 `1985` ⇒ `raw' = 2110` ⇒ `tare` 记 `zero = 2110`
        //         · 触底 `1241` ⇒ `raw' = 2854` ⇒ out = `2854-2110 = 744` ✅
        //         · 松手 ⇒ out = **0** ✅
        //      ⇒ ⭐ **得到干净的 `0..744` 行程、方向向上** ✅
        //      ⭐ 而阈值 `TRIG_TH = 2259` 正是按这套码值算的 ⇒ ✅ 落在行程内。
        //
        //   📌 **`INVERT_AXIS = 0`（磁铁装反）时**：⭐ 直通 ⇒ `calib` 的假设天然成立。
        // ═══════════════════════════════════════════════════════════════════
        localparam integer INVERT_AXIS = 1;
        localparam [11:0]  ADC_FULL    = 12'hFFF;      // ⭐ 12 位满量程

        function [11:0] axis_polarity;
            input [11:0] v;
            begin
                // ⚠️ 三元表达式 ⇒ ⭐ 综合成"取反 + 常数"，⛔ 无乘法、零延迟
                axis_polarity = INVERT_AXIS ? (ADC_FULL - v) : v;
            end
        endfunction

        // ⭐ 两片的原始码，各做一次极性校正（⭐ 在 `calib` 之前）
        wire [11:0] af0_pol = axis_polarity(af_data[0*12 +: 12]);
        wire [11:0] af1_pol = axis_polarity(af_data[1*12 +: 12]);
    // ⭐⭐ 2026-09-30 修 K-127：⭐ `calib_span.raw_i` 原来**恒接片 0** ⇒
    //   🔴 **轴 8~15（板 2）的"按稳"门控看的是【板 1】的读数**
    //   ⇒ ⚠️ 板 2 的 span 标定**不可靠**（⭐ 这正是"用 `'S'` 对齐两块板"的硬前置）。
    //   ⭐ 修法：⭐ 用**当前要标的轴** `sp_cur_axis[3]` 选片
    //      （⭐ bit3 = 片号：轴 0~7 = 片 0、轴 8~15 = 片 1）。
    //   ⚠️ `sp_cur_axis` 是 `calib_span` 的**寄存器输出**（`output reg cur_axis_o`）
    //      ⇒ ⭐ 它比内部 `cur_axis` 晚 1 拍，⭐ 但**同一帧内**就追上了
    //      （⭐ 帧 = 500 µs = 25000 拍）⇒ ⭐ **不会影响"连续 N 帧静止"的判定**
    //      ⇒ ⛔ **不构成组合环**（⭐ 这是本项目实测过的坑：见 `sp_busy_r` 的说明）。
    wire [11:0] sp_raw_sel = sp_cur_axis[3] ? af1_pol : af0_pol;

        // ═══════════════════════════════════════════════════════════════════════
        wire       pp_push;
        wire [7:0] pp_data;
        // ⚠️ `txf_ready` **已在 `generate` 之外声明**（⭐ 见 `u_tx_fifo` 那段）——
        //    🔴 这里⛔ **不能重复声明**（⭐ 否则又变成"局部隐式 wire"）

        // ⭐⭐ 2026-10-01 BATCH 8.1：⭐ **`'P'` 探针【按轴轮转】** —— ⭐ 修"只回片 0" 🔴
        //   🔴 **原缺陷**：⭐ `.pos_i(af0_pol)` **只接片 0** ⚠️，⭐ 而 `pos_probe` 只有
        //      一个 12 位 `pos_i` ＋ ⭐ 一个 4 位 `ch_i` ⇒ ⭐ **该模块没有"片"这个维度** ✅
        //      ⇒ 🔴 **`'P'` 永远只报片 0** ⇒ ⚠️ **诊断板 2 时会给出【错误答案】**
        //         （⭐ 比"看不到"更危险 —— ⭐ 会让人以为板 2 的轴是好的 ✅）
        //   ⭐ **修法**：⭐ 每次 `'P'` 请求就把"探针轴" +1 ⇒ ⭐ 16 次一轮，⭐ 覆盖**两片** ✅
        //   ⭐ **选片手法与 `sp_raw_sel`（⭐ 见上方）完全一致**：⭐ 用 `axis[3]` 选片 ✅
        //      ⚠️ 这样 `pos_i` 与 `ch_i` **同源** ⇒ ⭐ 回包里的通道号与位置**必然对得上** ✅
        //   📌 **格式不变**：⭐ 仍是 `P<5 位><CRLF>`（⭐ 8 字节）✅ —— ⭐ `'P'` 是调试命令，
        //      ⭐ 轮转 + ⭐ 文档说明就够用 ⇒ ⛔ 不改格式（⭐ 免得与 ESP32 侧协调 ⚠️）✅
        reg  [3:0] pp_axis_r;
        always @(posedge clk) begin
            if (!rst_n_sync)         pp_axis_r <= 4'd0;
            else if (cmd_probe_req)  pp_axis_r <= pp_axis_r + 4'd1;
        end
        wire [11:0] pp_raw_sel = pp_axis_r[3] ? af1_pol : af0_pol;

        pos_probe #(.N_BYTES(8), .QUEUE_WHEN_BLOCKED(1)) u_pos_probe (
            .clk_i      (clk),
            .rst_n_i    (rst_n_sync),
            .probe_req_i(cmd_probe_req),
            .pos_i      (pp_raw_sel),   // ⭐ 2026-10-01：⭐ 由 `af0_pol` 改为**按轴选片** ✅
            //  ⭐⭐ 2026-10-09（`P1-80`）：⭐ **4 位直传**（⭐ bit3 = 片号，⭐ bit2:0 = 片内通道 ✅）
        //   🔴 **原写法**：⭐ `{1'b0, pp_axis_r[2:0]}` ⇒ ⭐ 打印值 = **`axis mod 8`** ✅
        //      ⇒ 🔴 片 0（轴 0~7）与片 1（轴 8~15）**共用同一串通道号** ✅
        //      ⇒ 🔴 **片 1 的读数会被读成片 0 的某个轴**（⭐ "给出错误答案比看不到更危险" ✅）
        //      📌 实测（⭐ 审查亲跑）：⭐ `P7256`（轴 7 片 0）与 `P72048`（轴 15 片 1）
        //        ⇒ ⭐ **两个不同轴的 `ch` 字段都是 `'7'`** ✅
        //   ✅ **修法**：⭐ `pos_probe` 的 `tx_byte_c` 本来就是**十六进制一位（0~F）**
        //      ⇒ ⭐ **⛔ 不用改它**，⭐ 只要把 4 位原样传进去 ✅
        //      ⇒ ⭐ 轴 7 ⇒ `'7'` · ⭐ 轴 15 ⇒ **`'F'`** ✅
        //   📌 **代价 = 0**（⭐ 一根线 3→4 位 ✅）
        .ch_i       (pp_axis_r),
            .push_o     (pp_push),
            .data_o     (pp_data),
            .ready_i    (normal_tx_ready),
            .idle_i     (txf_idle && !np_busy && !vp_busy && !dp_active),
            .busy_o     (pp_busy), .packet_active_o(pp_active)
        );

        //   ⭐⭐ `'N'` 诊断（⭐ 回传 `calib` 后的 `pos`）—— ⚠️ 实例化在 `as_pos` 声明【之后】，
        //      见下方 §`'N'` 诊断。⭐ 这里只声明线网（⛔ `as_pos` 此时还没声明）。
        wire       np_push;
        wire [7:0] np_data;


        // ═══════════════════════════════════════════════════════════════════
        //   ⭐⭐ `'V'` 诊断：⭐ 回传 `calib_span` 的【内部状态】（⭐ 2026-09-24 新增）
        //
        //   🔴 **为什么加**：⭐ 上板发 `'S'` 后是一长串 `!`，
        //      ⚠️ 而 `calib_span` 有 8 个状态，⭐ **任何一个卡住都会回 `!`**
        //      ⇒ ⭐ 从串口**看不出卡在哪一步**。
        //   ⭐ 发 `'V'` ⇒ ⭐ 回 `V<state><axis><rej>CRLF`（⭐ 7 字节）
        //      · `<state>` ⭐ 最有用：
        //         `2`=SETTLE（⭐ 稳定判定过不去）· `3`=VOTE（⭐ 收不齐帧）
        //         `1`=PROMPT（⭐ 反复重试）· `7`=DONE（⭐ 已放弃）
        //   ⚠️ **走同一个 `u_tx_fifo`**，⭐ 且等 `idle_i` 才开新包
        //      ⇒ ⭐ 不会与 `'P'`/`'T'`/`'S'` 的回包撞车（⭐ `K-126` 的教训）
        // ═══════════════════════════════════════════════════════════════════
        wire       vp_push;
        wire [7:0] vp_data;

        span_probe #(.N_BYTES(7), .QUEUE_WHEN_BLOCKED(1)) u_span_probe (
            .clk_i      (clk),
            .rst_n_i    (rst_n_sync),
            .req_i      (cmd_vstat_req),   // ⭐ `'V'` 命令
            .state_i    (sp_state),        // ⭐ calib_span.state_o
            .axis_i     (sp_cur_axis),     // ⭐ 当前轴
            .rej_i      (sp_rej_cnt),      // ⭐ 拒绝计数
            .push_o     (vp_push),
            .data_o     (vp_data),
            .ready_i    (normal_tx_ready),
            .idle_i     (txf_idle && !np_busy && !pp_active && !dp_active),
            .busy_o     (vp_busy), .packet_active_o(vp_active)
        );

        // ═══════════════════════════════════════════════════════════════════
        // ⭐⭐ 满行程（`span`）标定（⭐ `calib_span`，2026-09-23 阶段B 接入）
        //
        //   ⭐ **它做什么**：⭐ 把某个轴"按到底"的位置记为满行程点
        //      ⇒ ⭐ `calib` 算出增益 `gain = (4095<<8)/(raw_底 − zero)`
        //      ⇒ ⭐ **把 744 码的行程拉伸到 4095（满量程）** ⇒ ⭐ 分辨率 ×5.5。
        //
        //   ⭐⭐ **为什么值得做**（⭐ 实测的账）：
        //      | | 只有 `tare` | `span` 之后 |
        //      | `pos` 行程 | **744** 码 | ⭐ **4095** |
        //      | 阈值 | `149`（⚠️ **依赖行程**） | ⭐ **`819`（固定 20%）** |
        //      🔴 **关键收益：阈值不再依赖定位板高度** ——
        //         ⚠️ 现在 `TRIG_TH=0x095` 是按"行程 744"算的，而**用户正在调定位板
        //         ⇒ 行程一定会变 ⇒ 那两个阈值必须重算**（⭐ 见 `event_extract` 的注释）。
        //         ⭐ 做完 `span` 就不用再重算了。
        //
        //   🔴🔴 **本版接线的两个关键点（⭐ 都踩过坑）**：
        //
        //   **① `raw_i` 必须用【反相后、`calib` 前】那一路**（`af0_pol`）
        //      ⚠️ 与 `u_calib0.raw` **同一路** ⇒ ⭐ 否则记的"满行程码"与
        //      `calib` 内部减零点的那个码**不在同一空间** ⇒ 🔴 增益算错（⭐ 静默）。
        //      🔴 **⚠️ 这里有一个真实的顺序陷阱**（⭐ 2026-09-23 踩到）：
        //         ⭐ `af0_pol` 由 `axis_polarity()` 函数算出来，
        //         ⚠️ 而那个函数**定义在 `calib` 实例【之前】**（⭐ 见上方）
        //         ⇒ 🔴 **本模块的例化必须放在 `af0_pol` 声明【之后】**
        //         ⇒ ⚠️ 否则 iverilog 报 `Unable to bind wire/reg/memory 'af0_pol'`
        //            （⭐ 本项目的老坑：**Verilog 里声明必须先于使用**）。
        //      📌 所以本段**物理位置在 `af0_pol` 之后**，⛔ 不是紧跟 `u_autotare`。
        //
        //   **② `cal_ch` 必须【同拍仲裁】**（🔴 本模块与 `calib_autotare` 都要驱动它）
        //      ⭐ `calib.sv` 的 `den_r`/`zero_r` 用的 `raw` 是**当拍输入**
        //      ⇒ 🔴 `cal_ch` 与 `tare`/`span` 错一拍 ⇒ **把别的通道的值记成本通道的**
        //         （⭐ `K-87` 同族：**静默**，没有任何报错）。
        //      ⭐ **仲裁规则**：⭐ **谁在忙用谁的**（⭐ 见 `cal_ch_mux`）。
        //      ⚠️ **两者天然互斥**：⭐ `at_busy` 期间 `calib_span` 不会启动
        //         （⭐ 本版 `start_i` 接常量 0 ⇒ 根本不会启动）；
        //         阶段 C 接上 `'S'` 后，⭐ 必须在 `calib_cmd` 层加互锁。
        //
        //   ⚠️ **本版 `start_i` / `abort_i` 接常量 0** ——
        //      🔴 因为触发源（`uart_rx` + `calib_cmd`）属**阶段 C**。
        //      ⇒ ⭐ **行为与接入前完全一致**（⛔ 一个 `span` 都不发）。
        //
        //   ⭐ **超时兜底**（⭐ 2026-09-23 修 3 个"静默卡死"缺陷时加的）：
        //      ⚠️ 若 `adc_farm` 停扫（SPI 挂/排线松）⇒ 采样永不来
        //      ⭐ 状态机会**超时 ⇒ 拒绝 ⇒ 重试**（⛔ 不静默卡死）。
        //
        //   📌 依据：`files/20-代码/标定链接入top实施方案-20260923.md`
        //           + `files/00-总览/未完成工作总账.md` §十（三个真缺陷）
        // ═══════════════════════════════════════════════════════════════════
        //   ⭐⭐ 端口信号 `sp_*` **已在 `u_autotare` 之前声明**（⭐ 见那里的说明）
        calib_span #(
            .NCH        (8),
            .N_ADC      (2),
            .AXIS_TOTAL (16),            // ⭐ = NCH × N_ADC（⚠️ 参数自检要求相等）
            //   ⭐ 稳定性 / 投票参数
            //      ⚠️ 2026-09-24：⭐ 原来这里写"用模块默认" ⇒ 🔴 **tb 改不了**
            //         ⇒ ⚠️ `WAIT_TIMEOUT_CLK` 的 50M 拍（1 秒仿真时间）无法缩短
            //         ⇒ 🔴 实测让 `tb_top_sound` 跑了 108 秒
            //      ✅ 现在从顶层参数传下去 ⇒ ⭐ **tb 能改小**（⭐ 见 `top` 的参数表）
            .STABLE_NEED      (SPAN_STABLE_NEED),
            .VOTE_N           (SPAN_VOTE_N),
            .WAIT_TIMEOUT_CLK (SPAN_WAIT_TIMEOUT_CLK),
            //   🔴 2026-09-24 实测后新增：⭐ 容限必须能从顶层调 ——
            //      ⚠️ 原来没传 ⇒ 用模块默认（8 / 16）⇒ 🔴 按住时也超（实测 Δ≈23）
            .STABLE_TOL       (SPAN_STABLE_TOL),
            .VOTE_TOL         (SPAN_VOTE_TOL),
            .POS_W      (12)
        ) u_calib_span (
            .clk           (clk),
            .rst_n         (rst_n_sync),
            // ⭐⭐ 2026-09-23 阶段C：接上**真正的触发源**（⭐ 原来接常量 0）
            //   ⭐ `start_i` = `'S'` 命令（⭐ 逐轴 span）
            //   ⭐ `abort_i` = `'X'` 命令（⭐ 取消）
            //   🔴 **互锁**：⭐ `'S'` 到达时若 `autotare` 还在忙 ⇒ ⭐ **必须忽略**
            //      （⚠️ 否则 `span` 与 `tare` 同拍 ⇒ `calib` 先记零点又拿它算增益
            //        ⇒ 🔴 **增益算错** —— 见 `cal_ch_mux` 的注释）
            //      📌 实现见下方 `sp_start_gated`
            .start_i       (sp_start_gated),
            .abort_i       (cmd_abort_req),
            //   ⭐ 与 `u_autotare` **同一路**（⭐ 都用 `adc_farm` 的采样握手）
            .sample_valid_i(af_sample_valid),
            .sample_ch_i   (af_sample_ch),
            //   ⭐⭐ **必须用 `af0_pol`/`af1_pol`**（⭐ 反相后、`calib` 前）—— 见上方关键点 ①
            //   ⭐⭐ 2026-09-30 修 K-127：⭐ 改为**按当前轴选片**（⛔ 原来恒接 `af0_pol`）
            .raw_i         (sp_raw_sel),
            .span_o        (sp_span),
            //  ⭐⭐ 2026-10-09（`P0-09`）：⭐ **投票代表值接出来**（⭐ 只在 `span_o` 那拍有效）✅
            //   🔴 **原缺陷**：⭐ `calib_span.vote_lo` **只被写、从不被读** ⇒ ⭐ 综合剪掉
            //      ⇒ 🔴 真正进 `calib` 的是发脉冲那一拍的**当拍活采样** ✅
            //      ⇒ ⭐ 增益散布 **6.5%**（⭐ 满行程 pos 误差 **266 码**，⭐ 是触发阈值 37~89 码的 3~7 倍）
            //      ⇒ 🔴 **"同一批键有的灵敏有的要按到底"** ✅
            .span_val_o    (sp_span_val),
            .cal_ch_o      (sp_ch),
            //   ⭐ `calib` 的反馈（⭐ 修"静默卡死"缺陷时新增的连接）
            //      ⚠️ 接入前这两个是【空连接】⇒ 标定失败**无法感知**
            //   ⭐⭐ 2026-10-09（`P0-10`）：⭐ **改为按片选**（⭐ span 已按片单发 ⇒ 反馈必须同片）✅
            .cal_busy_i    (cal_busy_sel),  // ⭐ P0-10：只看目标轴那一片
            .cal_err_i     (cal_err_sel),   // ⭐ P0-10：只看目标轴那一片
            .busy_o        (sp_busy),
            .done_o        (sp_done),
            .cur_axis_o    (sp_cur_axis),
            .need_press_o  (sp_need_press),
            .reject_o      (sp_reject),
            .done_cnt_o    (sp_done_cnt),
            //   ⭐ 2026-09-24 诊断输出（⭐ 让 `'P'` 能回传"卡在哪一步"）
            .state_o       (sp_state),
            .rej_cnt_o     (sp_rej_cnt),
            //   ⭐⭐ 2026-09-30：⭐ 拒绝原因码（⭐ 上板诊断用 —— ⛔ 原来只能看到 `!`）
            .rej_why_o     (sp_rej_why)
        );

        //   ⭐⭐ **`cal_ch` 仲裁** —— 🔴 **2026-09-24 移到下方**（⭐ 见 `sp_busy_r` 附近）
        //      🔴 **为什么移**：⭐ 原来用 `sp_busy`（⭐ 组合输出）⇒ ⭐ 与 `calib`/`calib_span`
        //         形成**跨模块组合环** ⇒ 🔴 **仿真在时间 0 挂死**（⭐ 见
        //         `files/20-代码/待查异常-tb挂死-20260924.md`）
        //      ✅ **修法**：⭐ 改用**打过一拍的** `sp_busy_r` ⇒ ⭐ **打断环**
        //         📌 且 `sp_busy_r` **已经存在**（⭐ 原本用于边沿检测，⭐ 白捡一个）

        // ═══════════════════════════════════════════════════════════════════
        // ⭐⭐ `'S'` 命令的【互锁】（⭐ 2026-09-23 阶段C）
        //
        //   🔴 **为什么必须有**：⭐ `calib` 是**一个共享资源**（两片锁步），
        //      而 `tare` 与 `span` **都要驱动它**：
        //        · `calib.sv` 的 `zero_r` 赋值  `if (tare) zero_r[cal_ch] <= raw;`
        //        · `calib.sv` 的 `den_r` 赋值  `den_r <= raw - zero_r[cal_ch];`
        //      ⚠️ 若两者**同拍拉高** ⇒ 🔴 **先记零点、又立刻拿这个零点算满量程**
        //         ⇒ ⭐ `den_r` 变成"满量程码 − 刚记的零点" ⇒ 🔴 **增益完全错**
        //         （⭐ 而且是**静默**的：不报错、`calib.err` 也未必触发）
        //
        //   ⭐ **互锁规则**：⭐ **`autotare` 忙（`at_busy`）时，忽略 `'S'`**。
        //      ⚠️ 代价：⭐ 操作者在上电 200 ms 内敲 `'S'` 会**没反应**
        //      ⇒ ⭐ 所以下面**回传一个 `'!'`** 让操作者知道被拒了（⛔ 不静默）。
        //   ⚠️ 反向（`span` 忙时收到 `'T'`）**同理要拦** —— ⭐ 见 `tr_retrig` 的门控。
        //   📌 依据：`files/20-代码/标定链接入top实施方案-20260923.md` §2.1
        // ═══════════════════════════════════════════════════════════════════
        //   ⭐⭐ `'S'` 的门控**已在 `u_autotare` 之前声明**（⭐ 见那里的说明）
        //       · `sp_start_gated`   = ⭐ 放行（⭐ `at_busy` 时不放）
        //       · `sp_start_rejected` = 🔴 被拒（⭐ 用于回传 `'!'`，⛔ 不静默吞）

        // ═══════════════════════════════════════════════════════════════════
        // ⭐⭐ 回传调度器（⭐ 2026-09-23 阶段C）
        //
        //   ⭐ 波特率 500 kbps ⇒ ⭐ 一个字节 ≈ 20 µs ⇒ ⚠️ 人类感知不到
        //      ⇒ ⭐ **不需要 FIFO**：⭐ 事件来了就发，⭐ 发之前等上一个发完即可。
        //   ⚠️ **代价（⭐ 诚实说明）**：⭐ 若两个事件**挨得极近**（<10 µs），
        //      ⚠️ 第二个会被**丢弃**（⭐ 因为 `tx_busy` 还没落）。
        //      ⭐ 本场景下事件间隔是"人按键的速度"（⭐ 毫秒级）⇒ ✅ 完全够用。
        //      📌 若将来要发连续数据（⭐ 如波形），⭐ 那时再加 FIFO。
        //
        //   ⭐ 优先级（⭐ 高 → 低）：⭐ 这保证"最要紧的信息先出去"
        //      ① ⭐ 轴号提示（⭐ `need_press`）—— 操作者**最需要知道**
        //      ② 🔴 拒绝 / 通过（⭐ `reject` / 轴完成）
        //      ③ ⭐ 完成 / 放弃
        //      ④ ⭐ 命令受理回执（`'t'`/`'s'`/`'x'`）
        // ═══════════════════════════════════════════════════════════════════
        //   ⭐ 把"哪一轴"编码成**一位十六进制 ASCII**（⭐ 0..9 → '0'..'9'，10..15 → 'A'..'F'）
        //      ⚠️ 16 轴 ⇒ ⭐ 一个字符就够（⭐ 简单、PC 串口助手直接可读）
        wire [7:0] axis_char = (sp_cur_axis < 4'd10)
                             ? (8'h30 + {4'd0, sp_cur_axis})          // '0'..'9'
                             : (8'h41 + ({4'd0, sp_cur_axis} - 8'd10)); // 'A'..'F'

        //   ⭐ 边沿检测：⭐ 把"单拍事件"变成"一个待发请求"
        //      ⚠️ 用 `*_r` 打一拍，⭐ 只在**上升沿**产生事件（⛔ 不重复发）
        reg sp_reject_r, sp_done_r, at_done_r, sp_busy_r;
        reg sp_need_r;
        always @(posedge clk) begin
            if (!rst_n_sync) begin
                sp_reject_r <= 1'b0;
                sp_done_r   <= 1'b0;
                at_done_r   <= 1'b0;
                sp_busy_r   <= 1'b0;
                sp_need_r   <= 1'b0;
            end else begin
                sp_reject_r <= sp_reject;
                sp_done_r   <= sp_done;
                at_done_r   <= at_done;
                sp_busy_r   <= sp_busy;
                sp_need_r   <= sp_need_press;
            end
        end

        // ═══════════════════════════════════════════════════════════════════
        //   ⭐⭐ **`cal_ch` 仲裁**（⭐ 2026-09-24 从上方移到这里）
        //
        //   ⭐ **语义不变**：⭐ `span` 忙 ⇒ 用它的通道；⭐ 否则用 `autotare` 的。
        //
        //   🔴🔴 **为什么必须用 `sp_busy_r`（⭐ 打过一拍）而不是 `sp_busy`**：
        //      ⚠️ `sp_busy` 是 `calib_span.busy_o`（⭐ **组合输出**）
        //      ⇒ ⭐ `cal_ch_mux` 随它**立即变化** ⇒ ⭐ 而 `cal_ch_mux` 又喂给 `calib`
        //      ⇒ 🔴 **`cal_ch_mux` → `calib` → 采集通路 → `calib_span` → `sp_busy`
        //         → `cal_ch_mux` 形成【跨模块组合环】**
        //      ⇒ 🔴 **`iverilog` 在时间 0 反复求值 ⇒ 不收敛 ⇒ 仿真挂死**
        //         （⭐ 实测：`tb_top_sound` / `tb_e2e_key_to_sound` **零输出超时**）
        //
        //   ✅ **修法**：⭐ 用 `sp_busy_r`（⭐ 寄存器）做选择 ⇒ ⭐ **环被切断**
        //      ⚠️ **代价**：⭐ 仲裁**晚一拍** —— ⭐ **可接受**（⭐ 因为 `tare`/`span`
        //         本来就是"谁先在忙"的语义，⭐ 相差一个 50 MHz 周期）
        //      📌 **`sp_busy_r` 原本就有**（⭐ 上面用于边沿检测）⇒ ⭐ 白捡
        //
        //   📌 **本缺陷的教训**（⭐ `L66`/`L67` 的新形态）：
        //      ⚠️ **"模块的 tb 全过" ⛔ 不等于 "接进顶层没问题"** ——
        //      🔴 **组合环只在【跨模块回路】里才成立**，⭐ 单模块测不出来。
        //      📄 完整定位过程：`files/20-代码/待查异常-tb挂死-20260924.md`
        // ═══════════════════════════════════════════════════════════════════
        wire [2:0] cal_ch_mux = sp_busy_r ? sp_ch : at_ch;

        wire ev_reject   = sp_reject & ~sp_reject_r;        // 🔴 本轴被拒
        wire ev_done     = sp_done   & ~sp_done_r;          // ⭐ 全部完成
        wire ev_need     = sp_need_press & ~sp_need_r;      // ⭐ 开始要求按某轴
        //   ⭐ 轴完成（⭐ `done_cnt_o` 加一）—— ⚠️ `done_cnt_o` 是 4 位计数器
        //      ⭐ 用"值变化"当事件（⭐ 它只会加、不回绕，⚠️ 16 轴到顶后自锁）
        reg [3:0] sp_done_cnt_r;
        always @(posedge clk) begin
            if (!rst_n_sync) sp_done_cnt_r <= 4'd0;
            else             sp_done_cnt_r <= sp_done_cnt;
        end
        wire ev_axis_ok = (sp_done_cnt != sp_done_cnt_r) & ~ev_done;

        //   ⭐⭐ 报告请求（⭐ 优先级编码）
        // 'M' reply is the newly selected state: '4'/'8'/'A'(16)/'B'(32)/'0'.
        // This is computed from the old register values because command request
        // and state update happen on the same clock edge.
        //  ⭐⭐ 2026-10-09（`P0-07`）：⭐ **本码流没有 Test Mode ⇒ 回包必须说实话** ✅
        //   🔴 **原缺陷**：⭐ 交付档 `TEST_MODE_EN = 0` ⇒ ⭐ `tm_enable_r ≡ 1'b0`（⭐ 编译期常量）
        //      ⇒ 🔴 `tm_reply_byte ≡ 8'h34 = '4'` ✅
        //      ⚠️ 而回传表（⭐ `top.v` 的回包定义）把 `'4'` 定义为 **"Test Mode 已切至 4"**
        //      ⇒ 🔴 操作者**每发一次 `'M'` 都收到 `'4'`，永远不变** ✅
        //      （⭐ `tm_n_code_q` 那套状态机在 `g_no_test_mode` 分支里**根本不存在**）✅
        //   🔴 **后果**：⭐ `tm_gate`/`tm_vel`/`tm_lane_active`/`tm_phase_inc` **全是常量 0**
        //      ⇒ ⭐ `test_mode_ctrl` **不进网表**（⭐ 实测 `Gowin2026.vg` 的 57 个 module 里没有它）
        //      ⇒ 🔴 **整条 FFT 验收通路在交付码流里是死的** ✅
        //      ⇒ ⭐ 上板做音频验收时 `'M'` 会告诉你"已进入测试模式"，⭐ **而实际没有测试音**
        //        ⇒ 🔴 **"全绿但没声音"家族**（⭐ `R-16`/`K-69` 同族）✅
        //   ✅ **修法（⭐ 1 行，⛔ 不改任何功能）**：⭐ 本码流直接回 **`'-'`（0x2D）** = **"本码流无 Test Mode"** ✅
        //      📌 ⭐ `TEST_MODE_EN` 是**编译期参数** ⇒ ⭐ 这个三元在综合期就定死 ⇒ ⭐ **零资源代价** ✅
        //      📌 ⭐ 诊断码流（`TEST_MODE_EN=1`）**行为逐字不变** ✅
        wire [7:0] tm_reply_byte = (TEST_MODE_EN == 0)  ? 8'h2D          // '-' = 本码流无 Test Mode
                                 : !tm_enable_r          ? 8'h34
                                 : (tm_n_code_r == 2'b00) ? 8'h38
                                 : (tm_n_code_r == 2'b01) ? 8'h41
                                 : (tm_n_code_r == 2'b10) ? 8'h42
                                                         : 8'h30;
        // ═══════════════════════════════════════════════════════════════════
        // ⭐⭐ 2026-09-30：**拒绝原因回包**（⭐ 上板诊断）
        //
        //   🔴 **为什么需要**：⭐ `'!'` 有【6 个来源】（⭐ 见 `calib_span.rej_why_o`）
        //      ⇒ ⚠️ 上板只看到 `!` 时**分不清**"没按稳"还是"片报 err"
        //      ⇒ 🔴 而两者**修法完全不同**（⭐ 前者教用户、后者查硬件）⇒ 必须能分辨。
        //
        //   ⭐ 编码（⭐ 每个来源一个字节）：
        //     · ⭐ `'!'` 0x21 —— R1 稳定判据超时（⭐ `span` 未发 · 最常见）
        //     · ⭐ `'o'` 0x6F —— R2 投票收帧超时（⭐ `span` 未发）
        //     · ⭐ `'w'` 0x77 —— R3 离散度超限（⭐ `span` 未发 · 手还在动）
        //     · ⭐ `'b'` 0x62 —— R4 等帧超时（⭐ `span` 未发）
        //     · ⭐ `'?'` 0x3F —— R6 `span` 已发但 `calib` 无响应（⭐ 接线 / `busy` 问题）
        //     · ⭐ `'0'`/`'1'`/`'2'` —— R5 ⭐ **`span` 已发 ＋ 片报 err**
        //        ⚠️ `'0'`/`'1'`/`'2'` 与**轴号字符同形** ⇒ ⭐ 读日志时按位置区分
        //           （⭐ 拒绝字节总是紧跟在一个轴号之后）
        //
        //   ⭐ 取片号的时机（⭐ 已论证，⛔ 不是"拿当下的粘滞值"）：
        //      ⭐ `calib.err` **只在 `span` 尝试或复位时**被写（⭐ `calib.sv` 里 `err` 的两处赋值）
        //      ⇒ ⭐ 从发脉冲到本条拒绝之间**没有第二次写** ⇒ ⭐ 这一拍的
        //         `cal0_err`/`cal1_err` **就是本轴本次尝试的结果** ✅
        //      ⚠️ 所以**不需要**给 `calib_span` 加逐片输入（⭐ 少一个端口 = 少一处风险）
        //      📌 R6 时它们可能是**上一轴的残值** ⇒ ⭐ 所以 R6 **一律回 `'?'`**，
        //         ⛔ 不报片号（⭐ 避免给出错误的片号）
        // ═══════════════════════════════════════════════════════════════════
        wire [1:0] cal_err_chip = {cal1_err, cal0_err};
        wire [7:0] rej_why_byte = (sp_rej_why == 3'd5)                              // R5：span 已发 + 片 err
                                ? ((cal_err_chip == 2'b01) ? 8'h30                  // '0' 片 0
                                 : (cal_err_chip == 2'b10) ? 8'h31                  // '1' 片 1
                                 : (cal_err_chip == 2'b11) ? 8'h32                  // '2' 两片
                                 :                            8'h3F)                // '?' 片号未知
                                : (sp_rej_why == 3'd6) ? 8'h3F                      // '?' R6 已发但无响应
                                : (sp_rej_why == 3'd3) ? 8'h77                      // 'w' R3 离散度
                                : (sp_rej_why == 3'd2) ? 8'h6F                      // 'o' R2 投票超时
                                : (sp_rej_why == 3'd4) ? 8'h62                      // 'b' R4 等帧超时
                                :                        8'h21;                     // '!' R1 稳定判据超时

        wire       rep_req  = ev_need   | ev_reject | ev_axis_ok | ev_done
                            | cmd_tare_req | cmd_span_req | cmd_abort_req | cmd_test_mode_req
                            | sp_start_rejected | (at_done & ~at_done_r)
                            | cmd_keydrum_req;   // ⭐ 'K' 键盘打鼓切换（⭐ 2026-10-01）
        wire [7:0] rep_byte = ev_need          ? axis_char        // ⭐ ① 轴号（⭐ 最要紧）
                            : ev_reject        ? rej_why_byte     // 🔴 被拒（⭐ 带原因码，见上）
                            : ev_axis_ok       ? 8'h2E            // '.' ⭐ 本轴通过
                            : ev_done          ? 8'h44            // 'D' ⭐ 全部完成
                            : sp_start_rejected? 8'h21            // '!' 🔴 'S' 被拒（正忙）
                            : (at_done & ~at_done_r) ? 8'h54      // 'T' ⭐ autotare 完成
                            : cmd_tare_req     ? 8'h74            // 't' ⭐ 受理 tare
                            : cmd_span_req     ? 8'h73            // 's' ⭐ 受理 span
                            : cmd_test_mode_req? tm_reply_byte    // M: 4/8/A/B/0
                            : cmd_keydrum_req  ? 8'h6B            // 'k' ⭐ 受理键盘打鼓切换
                            :                    8'h78;           // 'x' ⭐ 受理取消

        //   ⭐ 单拍请求 ⇒ 交给 `uart_tx`（⭐ 它忙时自动忽略 ⇒ ⚠️ 见上方"代价"）
        //   ⭐ `'P'` 诊断（⭐ 2026-09-24）：⭐ 与 `T/S/X` 的回包**共用** `u_tx_fifo`
        //      ⇒ ⭐ 上游二选一（⭐ 用 `pp_push` 优先 —— ⚠️ 它只在回传那几拍高）
        //      📌 **为什么要 or 而不是 mux**：⭐ 两者【不会同拍】（⭐ `'P'` 是独立命令，
        //         ⚠️ 而 `rep_req` 由 `calib_span` 事件驱动）⇒ ⭐ 直接 or 更简单
        //      🔴 **但字节要 mux**（⭐ 否则两个来源的数据会撞在一起）
        //   ⭐⭐ **2026-09-28：加上 `'Q'` 诊断（`dp_push`/`dp_data`）**
        //      ⚠️ **声明必须写在【本行之前】**（⭐ `L66`：声明先于使用）——
        //         🔴 我第一版把 `dp_push` 声明写在 `u_pos_probe_dpos` 旁边
        //         （⭐ 在 `cal_ch` 仲裁块**之后**）⇒ ⭐ 这里引用不到
        //      ⭐ 且 `dp_push` **⛔ 不会与 `pp_push` 同拍** ——
        //         ⭐ 它的 `probe_req` 是 `'P'` 到达后**延时 400 µs** 才发的
        //         （⭐ 见 `u_pos_probe_dpos` 上方的串行化说明）
        wire       dp_push;
        wire [7:0] dp_data;

        //   ⭐⭐ **`DPOS_DIAG` 门控（⭐ 2026-09-28）**：
        //      ⭐ `DPOS_DIAG = 0`（默认）⇒ ⭐ `dp_push` **恒 0**
        //      ⇒ ⭐ `u_pos_probe_dpos` 的输出**无人使用** ⇒ 🔴 **整块被综合器扫掉**
        //      ⇒ ⭐ **不占时序余量、也不拖慢仿真** ✅
        //      📌 要用诊断时：⭐ 把 `DPOS_DIAG` 改成 1 ⇒ 重新 PnR ✅
        wire normal_req_w = rep_req | pp_push | vp_push | np_push
                           | ((DPOS_DIAG != 0) ? dp_push : 1'b0);
        wire rd_notice_push = rd_notice_valid && txf_ready && !normal_req_w;
        // Export bypasses this FIFO and owns both UARTs until its footer ends.
        // Normal replies queue here; ready-aware producers pause during export.
        assign tx_req = normal_req_w | rd_notice_push;
        //   ⭐ 'N'（`np_push`）优先级最高 —— 它也是独立命令，与其余不同拍。
        //   ⭐ 'Q'（`dp_push`）次高 —— 它与 `'P'` **故意错开 400 µs**，⛔ 不同拍。
        // 2026-10-13: rd_push no longer shares this pulse-priority mux.
        // Binary frames + footer own both UARTs; normal replies stay queued.
        assign tx_byte = np_push ? np_data
                       : ((DPOS_DIAG != 0) && dp_push) ? dp_data
                       : vp_push ? vp_data : pp_push ? pp_data
                       : rep_req ? rep_byte : 8'h21; // '!' = operation rejected


        calib #(.NCH(8), .DW(12)) u_calib0 (
            .clk       (clk),
            .rst_n     (rst_n_sync),
            .valid     (af_sample_valid),
            .ch        (af_sample_ch),
            // ⭐ 送【极性校正后】的码 —— ⭐ 满足 `calib` 的"按下 ⇒ raw 变大"假设
            //  ⭐⭐ 2026-10-09（`P0-09`）：⭐ **本片被选中时，改用投票代表值（中位数）** ✅
            //   🔴 **原缺陷**：⭐ 原来恒送**当拍活采样** ⇒ ⭐ 组内 `(max−min)` 可达 `SPAN_VOTE_TOL=96`
            //      ⇒ ⭐ 用"最后一个采样"代替中位数 ⇒ 误差可达 **±48 码**
            //      ⇒ ⭐ 增益误差 **6.5%**（⭐ 满行程 pos 误差 **266 码**）
            //      ⇒ 🔴 **是触发阈值（37~89 码）的 3~7 倍** ⇒ ⭐ **"同一批键有的灵敏有的要按到底"** ✅
            //   ⚠️⚠️ **为什么必须加"本片被选中"这个条件**：⭐ `calib_span` 一次只标**一个轴**
            //      （⭐ `sp_cur_axis[3]` 选片），⭐ 而 `span` 是**两片同拍广播**的 ✅
            //      ⇒ 🔴 若把同一个投票值喂给两片 ⇒ ⭐ **非选中片会拿到【别的轴】的值** ⇒ ⭐ 比现状更差 ✅
            //      ⇒ ⭐ 所以只喂给**选中的那片**；⭐ 另一片保持原样（⭐ 不劣化）✅
            //   📌 **遗留（⭐ 诚实标注）**：⭐ 非选中片的那条轴**仍用活采样**
            //      ⇒ ⭐ 要彻底修，`calib_span` 必须**按片各记一套 `vmin`/`vmax`**
            //      （⭐ 即 `raw_i` 要带两片的值 + `span_val_o` 变 `N_ADC` 路）⇒ ⭐ 记入后续 ✅
            .raw       (sp_span[0] && (sp_cur_axis[3] == 1'b0) ? sp_span_val : af0_pol),
            // ⭐ 2026-09-23：由"硬接 0"改为接 `calib_autotare`（⭐ 上电自动零点）
            .tare      (at_tare[0]),
            // ⭐⭐ 2026-09-23 阶段B：接 `calib_span.（⭐ 原来硬接 0）
            //   ⚠️ `span` 与 `cal_ch` 是**配套**的（⭐ 见 `cal_ch_mux` 的仲裁）
            .span      (sp_span[0]),
            .cal_ch    (cal_ch_mux),      // ⭐ 仲裁后的通道（⭐ 与 tare/span 同拍）
            .busy      (cal0_busy),       // ⭐ 阶段B：从空连接改为接出
            .err       (cal0_err),        // ⭐ 同上（⭐ `calib_span` 的失败感知）
            .out_valid (cal0_vld),
            .out_ch    (cal0_ch),
            .out_val   (cal0_val)
        );

        calib #(.NCH(8), .DW(12)) u_calib1 (
            .clk       (clk),
            .rst_n     (rst_n_sync),
            .valid     (af_sample_valid),
            .ch        (af_sample_ch),
            //  ⭐⭐ 2026-10-09（`P0-09`）：⭐ 同 `u_calib0` —— ⭐ **本片被选中时用投票代表值** ✅
            //   📌 条件里的片号**必须与本实例一致**（⭐ 这是 `1` ⇒ `sp_cur_axis[3]==1`）✅
            .raw       (sp_span[1] && (sp_cur_axis[3] == 1'b1) ? sp_span_val : af1_pol),
            // ⭐ 2026-09-23：同 `u_calib0`，接 `calib_autotare`（⭐ 两片锁步、同时标）
            .tare      (at_tare[1]),
            // ⭐⭐ 2026-09-23 阶段B：同 `u_calib0`（⭐ 两片锁步 ⇒ 同时标）
            .span      (sp_span[1]),
            .cal_ch    (cal_ch_mux),      // ⭐ 同一个仲裁源（⭐ 两片锁步）
            .busy      (cal1_busy),       // ⭐ 阶段B：从空连接改为接出
            .err       (cal1_err),        // ⭐ 同上
            .out_valid (cal1_vld),
            .out_ch    (cal1_ch),
            .out_val   (cal1_val)
        );

        // ── ⭐ ③ `axis_snapshot`：16 轴原子快照 + 带符号 Δ ────────────────
        //   🔴 **⚠️ 位宽教训**：⭐ `pos` 是 **16 轴 × 12 位 = 192 位**，
        //      `delta` 是 **16 × 13 = 208 位** —— ⚠️ **⛔ 不是"16 位"**
        //      （⭐ 我第一版写窄了 ⇒ iverilog 报 "expects 192 bit(s), given 16"，
        //        ⚠️ 而它会**静默补高位 0** ⇒ 🔴 若没看 warning 就会**整条链全是 0**）
        wire [16*12-1:0] as_pos;
        wire [16*13-1:0] as_delta;
        wire        as_valid;
        wire [15:0] as_seen;

        // ═══════════════════════════════════════════════════════════════════
        // ⚠️ 两片 `calib` 的输出**同拍有效**（⭐ 都源自同一个 `sample_valid`）
        //   ⇒ ⭐ 拼成 `adc_farm` 的 packed 格式喂给快照
        //   ⭐ **注意**：极性校正已经【在 `calib` 之前】做过了（见 `afN_pol`）
        //      ⇒ ⭐ 这里【⛔ 不再反相】—— ⚠️ 否则会把行程再翻一次
        wire [2*12-1:0] cal_packed = {cal1_val, cal0_val};

        axis_snapshot #(
            .AXIS_N (16),
            .N_ADC  (2),
            .POS_W  (12),
            .DW     (13)
        ) u_axis_snapshot (
            .clk           (clk),
            .rst_n         (rst_n_sync),
            .sample_valid_i(cal0_vld),      // ⭐ 两片同拍 ⇒ 用一个即可
            .sample_ch_i   (cal0_ch),
            .sample_data_i (cal_packed),
            .frame_done_i  (af_frame_done),
            .snap_valid_o  (as_valid),
            .pos_o         (as_pos),
            .delta_o       (as_delta),
            .axis_seen_o   (as_seen)
        );

        // ═══════════════════════════════════════════════════════════════════
        // ⭐⭐ 位置式力度流（⭐ 2026-09-28 新增）
        //     —— ⭐ `note_manager.vel_upd_*` 的**唯一**驱动源
        //
        //   ⭐ 用户原话：
        //      「力度反馈也应该加回来，我思考了一下还是**只用位置式**吧，
        //        **音量实时跟随位置变化**，但是应该**只在按键按下的时候改变**，
        //        **抬起的时候不再改变力度**，如果松手就自然衰减」
        //
        //   ⭐ **三条语义分别由什么保证**（⭐ 逐条对应，⛔ 不是"看起来对"）：
        //     ① ⭐ **实时跟随** —— 每 `tick_audio` 扫**一个**轴（⭐ **16 轴轮转**）
        //        · `tick_audio` 周期 = 1024 clk @50 MHz = **20.48 µs**
        //        · 16 轴轮转 ⇒ ⭐ 每轴 **327.68 µs** ⇒ 响应 ~328 µs
        //          ⚠️ **2026-09-30 从 8 轴扩到 16 轴 ⇒ 单轴刷新率【减半】**（164 → 328 µs）
        //             🔴 **这是扩容的固有代价**（⭐ 想保住 164 µs 就得"每拍扫 2 个轴"，
        //             ⚠️ 那要多一份 `pos_to_vel` + 选择器 ⇒ ⭐ 与"浅逻辑"相悖 ⇒ ⛔ 不做）。
        //             📌 328 µs 仍是 ~3 kHz 的刷新 ⇒ ⭐ 听感上依然是"实时跟随" ✅
        //     ② ⭐ **只在按下时改变** —— 判据 `vu_pos > VEL_TRIG_TH`（= `TRIG_TH` = 64）
        //        · ⭐ 抬起后 `pos` 掉到 `REL_TH`(32) 以下 ⇒ 条件不成立 ⇒ ⭐ **力度冻结** ✅
        //        · ⭐ `note_manager` 那边还有第二道保险：`gate_mask`
        //          （`= gate_r & ~retrig_low`；⭐ 松手 ⇒ `gate_r=0` ⇒ 门关）
        //     ③ ⭐ **松手自然衰减** —— 本块⛔ **不发** `note_off`、⛔ **不清** `vel`
        //        · 释放完全交给 `event_extract`（`REL_TH`=32，⭐ 迟滞 32 ≫ 帧间噪声 Δ≤6）
        //          → `note_manager` 清 `gate_r` → `ADSR` 走 `RELEASE_STEP` ✅
        //
        //   ⭐ **死区 = 16 码**（⭐ 防"台阶声 / zipper noise"）：
        //      `|pos − 上次发出的 pos| >= 16` 才发。
        //      ⇒ ⭐ 按住不动时（⭐ 项目实测帧间噪声 Δ≤6）**一个包都不发** ⇒ 音量稳定 ✅
        //
        //   ⚠️ **`vu_valid_r` 必须是【恰好 1 个 clk 宽】的脉冲**：
        //      ⭐ `note_manager` 的 `(d)` 段是**逐 clk 采样** `vel_upd_valid_i`
        //      （⛔ **不是** `sample_tick` 门控 —— 见 `note_manager.v` 的 `(d)` 段）
        //      ⇒ 若保持成电平，会**每一拍重复写**同一个值（⚠️ 功能上"看起来也对"，
        //        但会让"按拍更新的语义"失真）。
        //      ⇒ 本块写法：**无条件先清 0、再条件置 1** ⇒ ⭐ 脉冲恰好一拍 ✅
        //
        //   ⚠️ **与 `param_extract` 的关系**：
        //      ⭐ 原来那条"**敲击速度**"式力度通路**已被本块取代**
        //      （⭐ 见下方 `note_manager` 例化处的说明）⇒ ⛔ `param_extract.v` 不动。
        //
        //   📌 **无新端口** —— `note_manager` 的 `vel_upd_*` 通路本来就是为此设计的。
        // ═══════════════════════════════════════════════════════════════════
        // ═══════════════════════════════════════════════════════════════════
        // ⭐⭐ **2026-09-28 修「双源真相」：触发阈值只留【一份定义】**
        //
        //   🔴 **原缺陷**：`event_extract` 的 `.TRIG_TH(12'd64)`（下方例化处）与
        //      这里的 `VEL_TRIG_TH = 12'd64` 是**两个各自独立的字面量**，
        //      注释写着"与 event_extract.TRIG_TH 同值"—— ⚠️ 却**没有任何机制强制**。
        //      ⇒ 🔴 将来只改一个 ⇒ **力度门控与触发窗口错位** ⇒
        //         出现「按下了但力度不跟随」或「抬起后还在跟随」这类**诡异且难查**的现象。
        //   ✅ **修法**：⭐ 只在这里定义一份，两处都**引用**它（⛔ 不再另写数字）。
        //   📌 两者同属 `g_sound` 块 ⇒ 作用域允许这样引用。
        // ═══════════════════════════════════════════════════════════════════
        // ⭐⭐ **2026-10-01 重算（用户裁定 B2："启动阈值可以更低一点"）**
        //
        //   ⚠️ **为什么原来的 64 不对**：⭐ 64 是在【跑 `'S'` 之前】那把尺子上定的
        //      （⭐ 那时 `pos ∈ 0..1023`，⭐ 而 `64/1023 = 6.3%`）。
        //   🔴 **跑过 `'S'` 之后**，⭐ `pos` 被归一到 **0..4095** ⇒ ⭐ 同样的 64 只剩
        //      **`64/4095 = 1.6%`** ⇒ ⭐ **轻碰就触发、且漂移易挂音** ⚠️（⭐ 这是已知的 `K-124` 族）
        //   ⇒ ⭐ 所以阈值**必须与量纲匹配**（⭐ 章程 §九④ 也是这个结论）。
        //
        //   ⭐ **取值（⭐ 用户要"更灵敏" ⇒ 比章程建议的 352 更低）**：
        //      · `TRIG_TH = 205` ⇒ ⭐ **`205/4095 = 5.0%`** ✅（⭐ 章程建议的是 8.6%）
        //      · `REL_TH  = 102` ⇒ ⭐ **`102/4095 = 2.5%`** ✅（⭐ 保持 2:1 的迟滞比 ✅）
        //
        //   ⭐⭐ 2026-10-01 返工：⭐ **本档就是【唯一档】**（⭐ ⛔ 不再要求"先跑 `'S'`" ✅）
        //   🔴 **为什么回退**（⭐ 上板实测驱动）：⭐ BATCH 2 把 `64/32` 改成 `205/102`
        //      是**按"跑过 `'S'` 之后的 4095 档"**算的 ⇒ ⚠️ 而实测行程档是 **≈744**
        //      ⇒ 🔴 `205/744 =` **`27.6%`** ⇒ ⭐ **要按掉四分之一行程才出声**（原值 8.6%）
        //   🔴 **⚠️ BATCH 2 自己就写明了这个前提**（⭐ 原文已随本次返工删除）：
        //      *"跑 `'S'` 之前（`pos ∈ 0..1023`）⇒ `205/1023 = 20%` ⇒ 默认档要按到 1/5 行程
        //        才出声 ⇒ 所以上板手册必须写【先跑 `'S'`】"* ✅
        //      ⇒ ⭐ **而那个前提从未发生**（⭐ 用户上板一直是默认档）⇒ ⭐ 这才是症状 ③ 的完整根因。
        //   ⭐ **二分实测证据（⭐ 决定性）**：⭐ `AN`（唯一改动就是本阈值）
        //      ⇒ ⭐ 用户实测 **"更不灵敏、按下更多才能触发"**，而 ①②④ 全正常 ✅
        //   ⭐ **原值依据（⭐ 2026-09-28 用户亲自裁定）**：
        //      · ⭐ `TRIG = 0.086 × 744 ≈ 64`（8.6%）· ⭐ `REL = 0.043 × 744 ≈ 32`（4.3%）
        //      · ⭐ 迟滞 `32` ≫ 项目实测单通道帧间噪声 `Δ≤6` ⇒ ✅ 噪声跨不过去
        //   📌 ⭐ **设计记录早已写明本档的正确值**（⭐ 见下方 `event_extract` 例化处）：
        //      *"若将来启用 `span`（归一化到 4095）⇒ `TRIG = 0.086×4095 ≈ 352`"*
        //      ⇒ ⭐ 即 **8.6% 是【不变量】、基数才是【变量】** ⇒ ⭐ 本档基数 = **744** ✅
        //   ⚠️ **代价（⭐ 必须知道）**：⭐ 换定位板高度 / 换板子 ⇒ 行程变
        //      ⇒ ⭐ 这四个数（`TRIG`/`REL`/`TRAVEL_TARE`/斜率）**必须一起重算**
        //      （⭐ 公式见 `param_extract` 例化处的注释）
        //  ⭐⭐ 2026-10-09（`P0-11`）：⭐ `EVT_TRIG_TH` / `EVT_REL_TH` **已改成【派生常量】**
        //   📌 定义处已**下移**到 `TRAVEL_TARE` 之后（⭐ Verilog 要求先声明后使用）——
        //      ⭐ 见下方 `TRAVEL_TARE` 声明处的 `P0-11` 块 ✅
        //   🔴 **原缺陷**：⭐ 这两个是**手写常量**（64/32），而 `TRAVEL_TARE` 另写一处
        //      ⇒ ⚠️ 两者可以**各自被改而互不知情** ⇒ 🔴 `TRAVEL_TARE = 0` 时：
        //      ⭐ 下方两条 N4 守卫的上下界**同时塌成 0** ⇒ `0*100 >= 5*0` ∧ `0*100 <= 12*0`
        //      ⭐ **全真** ⇒ 🔴 **整条守卫被绕过**（⭐ 6 道守卫全部放行）✅
        //      ⇒ 🔴 后果：⭐ `pos >= 0` 恒真 ⇒ 16 轴同时判"按下"（一帧 16 个 `note_on`）
        //         ＋ ⭐ `pos < 0` 恒假 ⇒ **16 个 voice 永久 held、永不释放** ✅
        //         （⭐ 与用户报过的"挂音几分钟不停"同族 ✅）

        //  ⭐⭐ 2026-10-01 BATCH 8.2：⭐ **满行程常量【单一来源】＋ 量纲自检** ⚠️
        //   🔴 **为什么要做**：⭐ 本项目已经**两次**栽在"常量与量纲脱钩"上 ✅
        //      · ⭐ BATCH 2：⭐ `EVT_TRIG_TH=64` 是在 **0..1023** 量纲上定的，
        //         而跑 `'S'` 后 `pos` 归一到 **0..4095** ⇒ ⭐ 同样的 64 只剩 **1.6%** ⚠️
        //      · ⭐ BATCH 4：⭐ `POS_FULL=744` / 斜率 `263` 是给**旧行程**配的 ⚠️
        //   🔴🔴 **2026-10-01 返工：⭐ BATCH 8.2 这一步【做错了】** —— ⭐ 它把两个**不同量纲**的量合并了 ✅
        //      · ⭐ `CALIB_FULL` = **跑过 `'S'` 之后的【归一一档】**（= `calib.FULL` = 4095）✅
        //      · ⭐ `POS_FULL`（⭐ `param_extract` 的入参）= ⭐ **【实际行程档】** = **744** ✅
        //      ⇒ 🔴 两者**不是同一个量** ⇒ ⭐ 把 `POS_FULL` 接到 `CALIB_FULL`
        //         ⇒ 🔴 `VEL_T1_EFF=2047` / `VEL_T2_EFF=3276` **全部越出 744** ⇒ ⭐ **力度恒定**（`K-124`）✅
        //   ⭐ **本次拆开**：⭐ `POS_FULL` 改引**下面新增的 `TRAVEL_TARE`**（⭐ 实际行程档）✅
        //      ⇒ ⭐ `CALIB_FULL` **保留**（⭐ 仍有用途：⭐ 标定档的参照 ＋ 自检①的对照）✅
        localparam [11:0] CALIB_FULL  = 12'd4095;  // ⭐ 归一档（= `calib.FULL`）—— ⛔ 不是 `POS_FULL`
        //  ⭐⭐ **实际行程档（⭐ 本版唯一使用的档）** —— ⭐ 四个"按行程定的量"【全部】由它派生
        //   ⭐ 实测依据：⭐ 上板 `'N'` 扫描 811 次 ⇒ `pos@松手 = 0`、`max = 752` ⇒ ⭐ 行程 ≈ **744**
        //   ⚠️ **换定位板高度 / 换板子 ⇒ 只改这一个数**，⭐ 但下面四个派生量要**一起重算**：
        //      · `EVT_TRIG_TH = 0.086 × 行程`（⭐ 8.6%）
        //      · `EVT_REL_TH  = 0.043 × 行程`（⭐ 4.3%，迟滞 4.3% ≫ 噪声 6 码）
        //      · `pos_to_vel` 的斜率 ⇒ ⭐ 要满足 `行程 × 斜率 >> 10 ≈ 191`（⭐ 使 `64+191 = 255` 恰好满）
        //      · ⭐ 本条 `TRAVEL_TARE` 自己
        //   📌 ⭐ **自检①b 会守它**（⭐ `> calib.MAX_TRAVEL(1023)` ⇒ 报 `ERROR`）✅
        localparam [11:0] TRAVEL_TARE = 12'd744;   // ⭐ 实际行程档（⭐ `POS_FULL` 的正确来源）

        //  ⭐⭐ 2026-10-09（`P0-11`）：⭐ **比例不变量 = 派生常量**（⭐ 堵住 `TRAVEL_TARE==0` 的绕过）✅
        //   ✅ **语义**：⭐ **8.6% / 4.3% 是【不变量】，行程才是【变量】** ⇒
        //      ⭐ 阈值**从行程派生** ⇒ ⛔ 结构上不可能"两个数各自漂" ✅
        //   📌 **数值逐位相同**（⭐ 四舍五入 +500 的整数除法）：
        //      · `744`  ⇒ ⭐ `64` / `32`   （⭐ 与改前手写值**完全相同**）✅
        //      · `4095` ⇒ ⭐ `352` / `176` （⭐ 与设计记录里的 `0.086×4095 ≈ 352` 一致 ✅）
        //   ⚠️ **为什么必须放在 `TRAVEL_TARE` 之后**：⭐ Verilog 先声明后使用 ✅
        //   📌 原来的 6 道守卫**全部保留**（⭐ 现在它们是"结构上恒真"的冗余防线 ✅）
        localparam [11:0] EVT_TRIG_TH = (TRAVEL_TARE * 32'd86 + 32'd500) / 32'd1000;  // ⭐ 8.6%
        localparam [11:0] EVT_REL_TH  = (TRAVEL_TARE * 32'd43 + 32'd500) / 32'd1000;  // ⭐ 4.3%（迟滞 2:1）

        //  ⭐ 量纲自检（⭐ 全部是 `localparam` ⇒ ⭐ **综合期即可判定** ✅）
        //   📌 与各模块的 `PARAM_OK` 同一套路：⭐ **⛔ 不许静默给错** ✅
        initial begin
            //  ⭐⭐ 2026-10-09（`P0-11`）：⭐ **绝对下界（⭐ 三道，都在最前面）** ✅
            //   🔴 **为什么必须有**：⭐ 上面把阈值改成"从行程派生"之后，
            //      ⭐ 比例不变量**结构上**成立了；⚠️ 但 `TRAVEL_TARE` 小到 **1** 时
            //      ⭐ 派生出来的阈值是 **0** ⇒ ⚠️ 又回到"`pos >= 0` 恒真"那个失效模式 ✅
            //   ⇒ ⭐ 这三条是**最后一道**：⭐ 任何一个为 0 ⇒ ⭐ **硬失败** ✅
            //   📌 **为什么用 `$fatal` 而⛔ 不是 `$display`**：⭐ 依据本项目 `U-2` 的教训 ——
            //      ⚠️ `$display` 时**仿真照跑完、综合照常进行** ⇒ 🔴 缺陷原样进板 ✅
            if (TRAVEL_TARE == 12'd0)
                $fatal(1, "ERROR [top] TRAVEL_TARE=0 => N4 守卫退化成 0/0（两条都不触发），且 pos>=0 恒真 => 16 轴恒 held (P0-11)");
            if (EVT_TRIG_TH == 12'd0)
                $fatal(1, "ERROR [top] EVT_TRIG_TH=0 => pos>=0 恒真 => 一上电 16 轴全部判按下 (P0-11)");
            if (EVT_REL_TH == 12'd0)
                $fatal(1, "ERROR [top] EVT_REL_TH=0 => pos<0 恒假 => 永不产生 note_off => 永久挂音 (P0-11)");
            //  ⭐ ① 触发阈值必须落在【实际行程档】内（⭐ 否则**永远触发不了** ⇒ ⭐ 全琴不响 ⚠️）
            //     ⚠️ 2026-10-01 返工：⭐ **必须比 `TRAVEL_TARE`(744)**，⛔ **不是 `CALIB_FULL`(4095)** ——
            //        🔴 拿 4095 比 ⇒ ⭐ 阈值就算填到 1000 也会"通过"，⭐ 而实际永远够不着 ✅
            if (EVT_TRIG_TH > TRAVEL_TARE)
                $display("ERROR [top] EVT_TRIG_TH(%0d) > TRAVEL_TARE(%0d) => 触发阈值超出实际行程，全琴不响",
                         EVT_TRIG_TH, TRAVEL_TARE);
            //  ⭐ ①b ⭐⭐ **锚定自检（⭐ 本轮新增 —— ⭐ 就是为了让这次的缺陷【能红】）**：
            //     🔴 **未做 `span` 时，`pos` 空间【不可能】超过 `calib.MAX_TRAVEL`**(1023)
            //        （⭐ `calib.sv` 的 `parameter integer MAX_TRAVEL` + `wire dlim`：`dlim = min(MAX_TRAVEL, span_r)` ⇒ ⭐ 结构上被夹住 ✅）
            //     ⇒ ⭐ 若 `TRAVEL_TARE` 被填成 4095（⭐ 即 BATCH 8.2 干过的事）
            //        ⇒ 🔴 `VEL_T2_EFF = 3276` **永远越不过** ⇒ ⭐ **力度恒定**（`K-124`）
            //        ＋ 🔴 斜率跟着错 ⇒ ⭐ **音量掉到 38%、尾音短 2.6×** ✅
            //     📌 **为什么原来抓不到**：⭐ `param_extract.v` 里 `VEL_T2_EFF > POS_FULL` 那条自检只比
            //        `VEL_T2_EFF ≤ POS_FULL` ⇒ ⭐ **它是【自洽】的**（`3276 ≤ 4095` 成立 ✅）
            //        ⇒ 🔴 **没有锚到【物理行程】** ⇒ ⭐ 本行补上这个锚 ✅
            if (TRAVEL_TARE > 12'd1023)
                $display("ERROR [top] TRAVEL_TARE(%0d) > calib.MAX_TRAVEL(1023) => 未做 span 时 pos 空间只有 ~744，力度/触发阈值会全部落空 (K-124)",
                         TRAVEL_TARE);
            //  ⭐ ①c ⭐⭐ **最具体的一条（⭐ 直接点名本次的缺陷）**：
            //     🔴 `TRAVEL_TARE` **⛔ 绝不许等于 `CALIB_FULL`** —— ⭐ 那正是 BATCH 8.2 的错：
            //        ⭐ 把「**归一档**」当成了「**实际行程档**」⇒ ⭐ `VEL_T1/T2_EFF` 越出行程 ⇒ 力度恒定 ✅
            //     📌 **本行也顺便让 `CALIB_FULL` 有【实际读点】** ⇒ ⛔ 不会变成"声明了却没人用"的死常量 ✅
            if (TRAVEL_TARE == CALIB_FULL)
                $display("ERROR [top] TRAVEL_TARE(%0d) == CALIB_FULL(%0d) => 你把【归一档】当成了【实际行程档】；未做 span 时 pos 空间只有 ~744 (K-124)",
                         TRAVEL_TARE, CALIB_FULL);
            //  ⭐ ② 释放阈值必须【严格小于】触发阈值（⭐ 否则**没有迟滞** ⇒ ⭐ 阈值附近抖动 ⚠️）
            if (EVT_REL_TH >= EVT_TRIG_TH)
                $display("ERROR [top] EVT_REL_TH(%0d) >= EVT_TRIG_TH(%0d) => 无迟滞 => 键在阈值附近会抖",
                         EVT_REL_TH, EVT_TRIG_TH);
            //  ⭐⭐ 2026-10-08（`N4`）：⭐ **量纲一致性 = 比例不变量** ✅
            //   🔴 **为什么 ①②①b①c 还不够**：⭐ 它们查的是【顺序】与【上界】——
            //      · ①  `TRIG <= 行程`（⭐ 太高 ⇒ 全琴不响）✅
            //      · ①b `行程 > 1023`（⭐ 拿归一档当行程档）✅
            //      · ①c `行程 == CALIB_FULL`（⭐ 同上，点名）✅
            //      · ②  `REL < TRIG`（⭐ 迟滞）✅
            //      ⇒ ⚠️ **但"阈值相对行程的比例"从来不是不变量** 🔴
            //   🔴 **反方向的静默错配**（⭐ 上面四条**全部放行**）：
            //      · 把 4095 档算出来的 `TRIG_TH = 205` 填进 744 档
            //        ⇒ ⭐ 触发点 = 205/744 = **27.5%** ⇒ 🔴 **要按到底才响**（演奏手感全废）
            //        ＋ ⭐ `REL_TH = 102/744 = 13.7%` ⇒ 迟滞比也错
            //      · 或把 `TRIG_TH = 64` 填进 4095 档
            //        ⇒ ⭐ 触发点 = **1.56%** ⇒ 🔴 **键没按就触发**（幻影音）
            //      ⇒ ⭐ 两种都是**静默**的（⚠️ 与 `N4` 描述的 744/4095 错配同族）✅
            //   ✅ **本守卫**：⭐ 把"阈值 = 行程的百分之几"钉成**不变量** ——
            //      ⭐ 两套已知正确的档位都必须落在带内：
            //        · `744/64/32`   ⇒ 触发 **8.6%** · 释放 **4.3%** ✅
            //        · `4095/205/102`⇒ 触发 **5.0%** · 释放 **2.5%** ✅
            //   📌 **用 `$fatal`（⛔ 不是 `$display`）**：⭐ 依据本项目 `U-2` 的教训 ——
            //      ⚠️ `$display` 时**仿真照跑完、综合照常进行** ⇒ 缺陷原样进板 🔴
            //      ⭐ 这是**配置错误**（不是警告）⇒ 必须硬失败 ✅
            //   📌 **位宽**：⭐ 乘 100 必须写 `32'd100` —— ⚠️ 两个 12 位相乘在 Verilog 里
            //      只保留 12 位 ⇒ `64×100` 会**溢出**（⭐ `K-91` 同族：位宽要显式）✅
            if (!((EVT_TRIG_TH * 32'd100 >= 32'd5  * TRAVEL_TARE) &&
                  (EVT_TRIG_TH * 32'd100 <= 32'd12 * TRAVEL_TARE)))
                $fatal(1, "ERROR [top] 触发点量纲错配(N4): EVT_TRIG_TH(%0d)/TRAVEL_TARE(%0d) = %0d%% 超出 [5%%,12%%] => 要么键没按就触发、要么要按到底才响",
                       EVT_TRIG_TH, TRAVEL_TARE, (EVT_TRIG_TH * 32'd100) / TRAVEL_TARE);
            if (!((EVT_REL_TH * 32'd100 >= 32'd2 * TRAVEL_TARE) &&
                  (EVT_REL_TH * 32'd100 <= 32'd7 * TRAVEL_TARE)))
                $fatal(1, "ERROR [top] 释放点量纲错配(N4): EVT_REL_TH(%0d)/TRAVEL_TARE(%0d) = %0d%% 超出 [2%%,7%%] => 迟滞比错，键会在阈值附近抖或粘",
                       EVT_REL_TH, TRAVEL_TARE, (EVT_REL_TH * 32'd100) / TRAVEL_TARE);
            //  ⭐ ③ ⭐ **`POS_FULL` 由 `TRAVEL_TARE` 派生**（⭐ 见下方 `.POS_FULL(TRAVEL_TARE)`）✅
            //     ⚠️ 2026-10-01 返工：⭐ 原写"由 `CALIB_FULL` 派生" ⇒ 🔴 **那是错的**（⭐ 已改正）。
            //     ⭐ **两个量的分工（⭐ 混用就是本轮返工的根因）**：
            //        · ⭐ `CALIB_FULL`(4095) = **归一档** ⇒ ⭐ 跑过 `'S'` 之后才成立
            //        · ⭐ `TRAVEL_TARE`(744) = **实际行程档** ⇒ ⭐ `POS_FULL` 唯一正确的来源 ✅
            //     ⚠️ **⛔ 这里【不能】直接比较 `POS_FULL`** —— ⭐ 它是**被例化模块 `param_extract`
            //        的参数**（⭐ 不是一个 `top` 的 `localparam`）⇒ ⭐ 在 `top` 里引用会**未声明** ❌
            //     📌 **所以结构性保证靠"端口不写数字"**：⭐ 只要例化处写 `TRAVEL_TARE`，
            //        ⭐ 就**不可能**出现第二个数 ✅（⭐ 改 `TRAVEL_TARE` 一处即全动 ✅）
            //     ⚠️ **残留风险**：⭐ `calib.sv` 的 `parameter integer FULL = 4095` 仍是**另一个默认值** ⚠️
            //        ⇒ ⭐ 它现在**是对的**（⭐ `FULL` 本来就该是归一档 4095），
            //        ⚠️ 但它与 `TRAVEL_TARE` **没有任何机械联系** ⇒ ⭐ 改一处不会自动带动另一处
            //        （⭐ 它是归一档、`TRAVEL_TARE` 是行程档 ⇒ ⭐ 本来就不该相等 ⇒ ⛔ 不构成"两处真相"）
        end

        // ═══════════════════════════════════════════════════════════════════
        //  ⭐⭐⭐⭐ 2026-10-11（`P1-53`）：⭐ **N4 参数的【综合期】硬失败守卫** ✅
        //
        //  🔴🔴 **为什么必须有它**（⭐ 2026-10-11 **实测证据**，⛔ 不是推测）：
        //     ⭐ 上面 `initial` 里那 **5 条 `$fatal`** ——
        //        ⚠️ **综合【完全不执行】** ✅
        //        ⭐ Gowin 自己的警告原文（⭐ 实测）：
        //        ```
        //        WARN (EX2488) : Elaboration system task 'fatal' is ignored for synthesis
        //        ```
        //        ⇒ ⭐ 而且 **`gw_sh` 的退出码仍然是 `0`** ✅
        //     ⇒ 🔴 **"门① 综合 `ERROR=0`"【拦不住】任何参数错配** ✅
        //        ⇒ ⭐ 也就是说：⭐ `TRAVEL_TARE` 被填成 0（⭐ `P0-11` 那个
        //           "**16 轴恒 held**"的失效模式）⇒ 🔴 **位流照样生成、照样上板** ✅
        //     📌 ⭐ 这不是 `P0-11` 修错了 —— ⭐ 是**它依赖的那道防线【只在仿真侧】** ✅
        //        （⭐ `sim/tb_all.ps1` 的回归**会**跑到它，⭐ 所以它**不是空的**；
        //          ⚠️ 但它**保护不了 `sim/gowin_build.ps1` 那条路** ✅）
        //
        //  ✅ **修法（⭐ 结构性 ⇒ 工具无关）**：⭐ **例化一个【故意不存在】的模块**，
        //     ⭐ 而**错误信息就写在模块名里** ✅
        //     · ⭐ 参数**合法** ⇒ ⭐ `if` 条件为假 ⇒ ⭐ 那一支**不参与详细阐述**
        //        ⇒ ⭐ **零代价**（⭐ 0 逻辑、⭐ 0 FF —— ⭐ 综合日志里连提都不提 ✅）
        //     · ⭐ 参数**非法** ⇒ ⭐ 综合与仿真**都**报
        //        `Unknown module type: <那一长串名字>`
        //        ⇒ 🔴 **构建失败**，⭐ 而**错误信息本身就在报错行里** ✅
        //     📌 ⭐ **为什么不用"在构建脚本里体检参数"**（⭐ `P1-53` 的备选方案 2）：
        //        ⚠️ 那要求脚本**再解析一遍** RTL 常量 ⇒ ⭐ 又多一处"**两处真相**"；
        //        ⭐ 而本写法**与 RTL 同源**（⭐ 条件就是那 5 条判据本身）⇒ ⭐ **不可能不同步** ✅
        //     📌 ⭐ **为什么不直接删掉 `initial` 里那 5 条**：⭐ **不删** ——
        //        ⭐ 它们给的是**带数字的可读信息**（⭐ `$fatal` 会打印百分比），
        //        ⚠️ 而本守卫只能给"模块名"⇒ ⭐ **两者互补**：⭐ 仿真看前者、⭐ 综合看后者 ✅
        // ═══════════════════════════════════════════════════════════════════
        //  ⭐ 把上面那 5 条判据合成**一个编译期常量**（⭐ 与 `initial` 里逐条一致 ✅）
        localparam integer N4_PARAM_OK =
               (TRAVEL_TARE  != 12'd0)
            && (EVT_TRIG_TH  != 12'd0)
            && (EVT_REL_TH   != 12'd0)
            && (EVT_TRIG_TH  <= TRAVEL_TARE)
            && (EVT_TRIG_TH * 32'd100 >= 32'd5  * TRAVEL_TARE)
            && (EVT_TRIG_TH * 32'd100 <= 32'd12 * TRAVEL_TARE)
            && (EVT_REL_TH  * 32'd100 >= 32'd2  * TRAVEL_TARE)
            && (EVT_REL_TH  * 32'd100 <= 32'd7  * TRAVEL_TARE);

        //  ⚠️ **⛔ 这里不套 `generate`/`endgenerate`** —— ⭐ 本块已在外层 `g_sound`
        //     （⭐ 与本文件 `g_test_mode` / `g_right_adc_data` 同一写法 ✅）
        if (N4_PARAM_OK == 0) begin : g_n4_param_bad
            P1_53_N4_PARAM_ERROR__TRAVEL_TARE_or_TRIG_TH_or_REL_TH_inconsistent__see_initial_block u_n4_guard();
        end

        localparam [11:0] VEL_TRIG_TH  = EVT_TRIG_TH;  // ⭐ **派生**，⛔ 不另写数字
        //  ⚠️ ⭐ 2026-09-29：⭐ **`VEL_DEADZONE` 已删除** ✅
        //   ⭐ 原因：⭐ 死区判据（`vu_last[]`）整体删掉了 —— ⭐ 见下方 `vu_*` 的说明 ✅
        //   📌 死区原本只为"防抖动/台阶声" ✅ ⇒ ⭐ 该职责已由 `note_manager` 的
        //      **±8/采样拍斜坡** 承担（⭐ 功能重复 ⇒ 删掉不丢能力 ✅）

        // ⭐⭐ **本块扫【全部 `VEL_AXIS_N` 个轴】**（⭐ 2026-09-30：8 → **16** ✅）
        //   ⭐ **为什么现在是 16**：⭐ 左手板有**两块**（⭐ 各 1 片 `MCP3208`，
        //      `ADC_N = 2`）⇒ 轴 0~7 = 板 1 · 轴 8~15 = 板 2
        //      ⇒ 🔴 **两块板必须【配置一致】** —— ⚠️ 否则板 2 的键
        //         「**起音有位置式力度、跟随却完全不动**」（⭐ 因为 `w3a_evt_vel`
        //         用的是任意轴的 `am_pos_in`，⭐ 起音通路**不受**本块限制）
        //         ⇒ ⭐ **半残且静默**（同族 `K-56`：全绿不证明任何事）✅
        //   ⚠️ **本次扩容的代价（⭐ 时序敏感：Fmax 余量只有 +0.18%）**：
        //      ① `vu_ax_r` 3 → 4 位 ⇒ ⭐ **+1 FF**（⭐ 本块**没有其它新增寄存器**）
        //      ② `as_pos[vu_ax_r*12 +: 12]` 从 **8 选 1** 变 **16 选 1**
        //         （⭐ 12 位宽 ⇒ 综合器用 `4:1` 原语拼 ⇒ ⭐ **16 选 1 与 8 选 1 同为两级**，
        //          ⭐ 组合深度**基本不变**，⭐ 只多几个 LUT ✅）
        //         ⚠️ **确切的门级/时序数字以 PnR 报告为准**（⭐ 本处只是量级判断）
        //      📌 **`vu_last[]` 死区数组早已删掉**（⭐ 见下）⇒ 🔴 **不再有那 96 FF**
        //         ⇒ ⭐ 本次的实际代价**远小于** 2026-09-30 注释里预估的那一版 ✅
        //   📌 本块末尾的 `initial` 守卫会在仿真启动时**核对**轴数（⭐ 不匹配就报）。
        localparam integer VEL_AXIS_N = 16;  // ⭐ 本块扫的轴数（= 系统的真实轴数）
        localparam integer VEL_AX_W   = 4;   // ⭐ = $clog2(VEL_AXIS_N)

        reg  [VEL_AX_W-1:0] vu_ax_r;              // ⭐ 本拍要扫的轴（0→15 轮转）
        //  ⭐⭐ 2026-09-29 治本：⭐ **删掉了 `vu_last[]` 死区数组** ✅
        //   🔴 **为什么删**（⭐ 用户上板症状："无论按下行程多少，音量都一样" ✅）：
        //      · ⭐ 死区是"**变化超过 16 才发**" ⇒ ⚠️ 若某次 `vel_upd` 在 voice 出现
        //        **之前**到达（⭐ `gate_mask=0` ⇒ 被丢掉 ✅），⭐ 而 `vu_last` **已更新**
        //        ⇒ 🔴 `vu_far` 之后**恒假** ⇒ **永不再发** ⇒ `vel` 卡在起音值 ✅
        //      · 🔴 它需要 **`vu_last[<变量索引>]`** 这种数组写 ⇒ ⚠️ 我上一版为它加的
        //        "note_on 清参考值"里对 `integer` 型 `localparam` 做了位选（⭐ 违反 `K-91` ✅）
        //        ⇒ 🔴 **上板 `Q_velrace` 完全静音** ✅
        //   ✅ **为什么删了也没关系**：⭐ 死区原本只为"防抖动/台阶声" ✅
        //      ⭐ 而 `note_manager` 的 **±8/采样拍斜坡** 已经在做这件事 ✅ ⇒ **功能重复** ✅
        //   ✅ **删掉的三重收益**：⭐ ① 竞态消失（⭐ 按下就持续发 ✅）
        //      ⭐ ② 不再有变量索引的数组写（⭐ 消掉静音风险 ✅）
        //      ⭐ ③ 省 **96 FF**（⭐ 8×12 ✅）
        //   📌 **发端节奏不再重要**：⭐ 收端（`note_manager`）已改成**每轴各记一个目标**，
        //      ⭐ 每个 voice 查**自己那个轴**的目标 ⇒ ⭐ 与"本拍扫到谁"无关 ✅
        reg         vu_valid_r;           // ⭐ 1 拍脉冲（见上方纪律）
        reg  [3:0]  vu_axis_r;            // ⭐ 轴号（4 位 —— 与 `note_manager` 接口一致）
        reg  [7:0]  vu_val_r;             // ⭐ 力度

        wire [11:0] vu_pos = as_pos[vu_ax_r*12 +: 12];
        //   ⭐⭐ 与**起音力度**用同一个函数 ⇒ ⛔ 公式只有一份（见 `pos_to_vel`）
        wire [7:0]  vu_vel = pos_to_vel(vu_pos);

        always @(posedge clk) begin
            if (!rst_n_sync) begin
                vu_ax_r    <= {VEL_AX_W{1'b0}};
                vu_valid_r <= 1'b0;
                vu_axis_r  <= 4'd0;
                vu_val_r   <= 8'd0;
            end else begin
                // ⭐ 默认清 0 ⇒ 下面置 1 时**恰好是 1 拍脉冲**
                vu_valid_r <= 1'b0;
                if (tick_audio) begin
                    // ⭐ 计数器**自然回绕** ⇒ 0→1→…→15→0，⭐ 就是"16 轴轮转"
                    //   📌 用 `+ 1'b1`（⛔ 不写死 `4'd1`）⇒ ⭐ 改 `VEL_AX_W` 时不用跟着改
                    vu_ax_r <= vu_ax_r + 1'b1;
                    //   ⭐⭐ **唯一条件**：⭐ `vu_pos > VEL_TRIG_TH` ⇒ "**按下中**" ✅
                    //      ⭐ 抬起后自动失效（⭐ 力度冻结 ✅）
                    //   📌 **不再有 `vu_far`** ⇒ ⭐ 按住的每个轴每 328 µs 发一次 ✅
                    if (vu_pos > VEL_TRIG_TH) begin
                        vu_valid_r <= 1'b1;
                        vu_axis_r  <= vu_ax_r;   // ⭐ 隐式零扩展到 4 位（⛔ 不写死位宽）
                        vu_val_r   <= vu_vel;
                    end
                end
            end
        end

        // ⭐⭐ 参数守卫（与各模块的 `PARAM_OK` 同一套路）
        //   🔴 **为什么必须有**：本块扫 `VEL_AXIS_N` 个轴，而系统的真实轴数由
        //      `event_extract` / `axis_snapshot` 的 `AXIS_N` 决定。
        //      ⚠️ 两者**不一致时是【静默】的** —— 少扫的轴只有"起音力度"、⛔ 没有"跟随"
        //      （⭐ 同族 `K-56`：全绿不证明任何事）。
        //   ⭐ **2026-09-30：判据从"允许只扫一部分"改成"必须扫满"** ✅
        //      🔴 因为左手板有**两块** ⇒ ⭐ **两块必须配置一致** ⇒
        //         ⭐ `VEL_AXIS_N != SYS_AXIS_N` **本身就是缺陷**（⭐ 不再是"已知限制"）✅
        //   ⇒ ⭐ 仿真启动时明确打印（⭐ 综合工具忽略 `initial` ⇒ 只是仿真侧防线）。
        localparam integer SYS_AXIS_N = 16;   // ⚠️ 必须与 `event_extract`/`axis_snapshot` 的 `AXIS_N` 一致
        initial begin
            if (VEL_AXIS_N != SYS_AXIS_N)
                $display("ERROR [top] VEL_AXIS_N=%0d != SYS_AXIS_N=%0d => %0d axis/axes get ATTACK velocity but NO follow (two identical left-hand boards require VEL_AXIS_N == AXIS_N; see the VEL_AXIS_N comment)",
                         VEL_AXIS_N, SYS_AXIS_N,
                         (VEL_AXIS_N < SYS_AXIS_N) ? (SYS_AXIS_N - VEL_AXIS_N) : 0);
            //   🔴 `VEL_AXIS_N > SYS_AXIS_N` 更糟：⭐ `as_pos` 只声明了 `SYS_AXIS_N*12` 位
            //      ⇒ ⭐ 选择器会**越界索引**（⭐ 综合/仿真行为都不可靠）
            if (VEL_AXIS_N > SYS_AXIS_N)
                $display("ERROR [top] VEL_AXIS_N=%0d exceeds SYS_AXIS_N=%0d => as_pos index OUT OF RANGE",
                         VEL_AXIS_N, SYS_AXIS_N);
            if ((1 << VEL_AX_W) != VEL_AXIS_N)
                $display("ERROR [top] VEL_AX_W=%0d does not match VEL_AXIS_N=%0d (must be $clog2)",
                         VEL_AX_W, VEL_AXIS_N);
        end

        // ═══════════════════════════════════════════════════════════════════
        //   ⭐⭐ `'N'` 诊断：⭐ 回传【`calib` 后的 `pos`】（⭐ 2026-09-27 新增）
        //
        //   🔴 **为什么必须再加一条**：
        //      · ⭐ `'P'` 回的是 `af0_pol` —— ⭐ **极性校正后的【原始码】**
        //      · 🔴 而 `event_extract` 判键用的是 **`pos`（`calib` 后的行程）**
        //        `pos = (raw − zero) × gain >> 8`
        //      ⇒ ⚠️ 从原始码**推断不出** `pos`（⭐ `zero` **只在上电 `tare` 时写一次**，
        //         它是否有效、有没有漂移，**只能直接看 `pos`** —— 实测 `af0_pol`
        //         静止值 ≈ 2150，⭐ 而它到底是"正常的原始码"还是"未标定的脏值"，
        //         ⛔ 从 `'P'` 根本分不出来）。
        //
        //   ⭐ 三个待查症状全部卡在"看不到 `pos`"上：
        //      ① **挂音** —— 松手后 `pos` 能否降到 `REL_TH`(80) 以下？
        //      ② **周期性音量起伏** —— 按住时 `pos` 是否在有规律地变化？
        //      ③ **`zero` 是否有效** —— 松手时 `pos` 应 ≈ 0，⭐ 而不是 ~2000
        //
        //   📌 **复用同一个 `pos_probe` 模块**（⭐ ⛔ 不改它的逻辑，只换输入源与前缀）
        //      ⇒ 回包格式：`N<通道号><4位十进制>CRLF`（8 字节）
        //      ⚠️ 前缀必须与 `'P'` 不同（⭐ 复用 `PREFIX` 参数改发 `'N'`），
        //         ⛔ 否则 PC 侧分不清"这个数是谁"。
        //   ⚠️ **输入取 `as_pos` 的【轴 0】** —— 与 `'P'` 的口径不同：
        //      · `'P'` = 当前正在采样的通道的**原始码**（⭐ 逐通道轮转）
        //      · `'N'` = **轴 0** 的**标定后行程**（⭐ 判键用的那个数）
        //      📌 只看轴 0 够用：⭐ 三个症状都能在轴 0 上观察到，
        //         且⛔ 不需要再加"选轴"的接口（⭐ 保持改动最小）。
        //   ⚠️ **必须放在 `as_pos` 声明【之后】**（⭐ `L66`：声明先于使用）——
        //      ⭐ 我第一版放在 `u_pos_probe` 旁边（⭐ 那里 `as_pos` 还没声明）。
        //
        //   🔴🔴 **2026-09-27 修正：⭐ 必须能【扫全部 16 轴】**
        //      ⚠️ 我第一版把输入写死成 `as_pos[0 +: 12]`（轴 0），
        //         理由是"三个症状都能在轴 0 观察到" —— 🔴 **这个假设是错的**：
        //         上板实测"回音在响、而轴 0 的 `pos` 恒为 0"，⭐ 说明卡住的 voice
        //         **不在轴 0** ⇒ ⚠️ 写死轴 0 等于**看不到出问题的地方**。
        //      ✅ 改法：⭐ **每次收到 `'N'` 就切到【下一个轴】**（0→1→…→15→0）
        //         ⇒ ⭐ 连发 16 次即可扫完全部轴 ⇒ **一眼看出哪个轴卡住**。
        //      📌 回包里的【通道号】字段 = 当前轴号（⭐ 十六进制）⇒ ⛔ 不会分不清是谁。
        reg [3:0] np_axis_r;
        always @(posedge clk) begin
            if (!rst_n_sync)           np_axis_r <= 4'd0;
            else if (cmd_posprobe_req) np_axis_r <= np_axis_r + 4'd1;   // ⭐ 自动轮转
        end

        pos_probe #(.N_BYTES(8), .PREFIX(8'h4E), .QUEUE_WHEN_BLOCKED(1)) u_pos_probe_cal (
            .clk_i      (clk),
            .rst_n_i    (rst_n_sync),
            .probe_req_i(cmd_posprobe_req),
            //   ⚠️ 用**当拍**的 `np_axis_r`（⭐ `pos_probe` 也是在 `probe_req_i`
            //      那一拍锁存输入 ⇒ ⭐ 两者口径一致，⛔ 不会错开一个轴）
            .pos_i      (as_pos[np_axis_r*12 +: 12]),   // ⭐ 轮转轴的标定后行程
            .ch_i       (np_axis_r),                    // ⭐ "通道号"= 轴号(hex)
            .push_o     (np_push),
            .data_o     (np_data),
            .ready_i    (normal_tx_ready),
            .idle_i     (txf_idle && !pp_active && !vp_active && !dp_active),
            .busy_o     (np_busy), .packet_active_o(np_active)
        );

        // ═══════════════════════════════════════════════════════════════════
        // ⭐⭐ `'Q'` 诊断：**全轴 |Δpos| 峰值 + 出峰轴号**（⭐ 2026-09-28 新增）
        //
        //   🔴 **为什么要它**：⭐ 用户反馈"**非常用力地敲打磁轴**时偶发尖音"，
        //      猜想是"**用力时霍尔变化快 / 不稳**"。
        //      ⚠️ 但 `'P'`/`'N'` 的串口轮询**每个轴只有 ~4 Hz**
        //      （⭐ 上板实测 **247 ms/轴**）⇒ 🔴 **根本看不到 20 ms 的按压瞬态**
        //      ⇒ ⭐ **必须在 FPGA 侧测**（⭐ 这就是本模块存在的理由）。
        //
        //   ⭐ **量什么**：⭐ `max |as_pos[i] - as_pos_d[i]|`（⭐ 全 16 轴取最大）
        //      · ⭐ 霍尔"干净" ⇒ 该值 ≈ **单帧真实位移**（几十 ~ 一两百）
        //      · 🔴 霍尔"抖 / 跳" ⇒ 该值会**接近满行程（700+）**，⭐ 且轴号会跳
        //   ⭐ **读走即清零** ⇒ ⭐ 每次发 `'P'` 就是一个**测量窗口**
        //
        //   ⚠️ **⛔ 不改协议、⛔ 不加命令**：⭐ 复用 `cmd_probe_req`（即 `'P'`）
        //      ⇒ ⭐ 发一次 `'P'` 回**三个**包：
        //         `P<ch><pos>`（原样）+ `N<ax><pos>`（原样）+ ⭐ **`Q<ax><dpos>`**
        //      ⚠️ 前缀必须与 `'P'`/`'N'`/`'D'` 都不同 —— 🔴 `'D'` **已被占用**
        //         （`'D'` = span 标定"16 轴全标完"）⇒ ⭐ 本诊断用 **`'Q'` (0x51)**。
        //
        //   ⚠️ **必须放在 `as_pos` 声明之后**（⭐ `L66`：声明先于使用）
        // ═══════════════════════════════════════════════════════════════════
        reg [11:0] as_pos_d [0:15];
        reg [11:0] dpos_pk_r;
        reg [3:0]  dpos_ax_r;
        integer    dpi;
        always @(posedge clk) begin
            if (!rst_n_sync) begin
                dpos_pk_r <= 12'd0;
                dpos_ax_r <= 4'd0;
                for (dpi = 0; dpi < 16; dpi = dpi + 1) as_pos_d[dpi] <= 12'd0;
            end else begin
                //  ⭐⭐ **`DPOS_DIAG` 门控**：⭐ `0` ⇒ 这是**编译期常量假** ⇒
                //     ⭐ 综合器把整个 16 组比较器 + `as_pos_d` 全折掉 ✅
                //     ⭐ 仿真器也不再跑这个循环 ⇒ ⛔ 不再拖慢顶层 tb ✅
                if (DPOS_DIAG != 0) begin
                for (dpi = 0; dpi < 16; dpi = dpi + 1) begin
                    //  ⭐ 比较时用**拼接**把两侧都加宽到 13 位
                    //     ⚠️ ⛔ 不能对函数返回值位选（⭐ Verilog-2001 限制）
                    if ({1'b0, dpos_abs_f(as_pos[dpi*12 +: 12], as_pos_d[dpi])}
                        > {1'b0, dpos_pk_r}) begin
                        dpos_pk_r <= dpos_abs_f(as_pos[dpi*12 +: 12], as_pos_d[dpi]);
                        dpos_ax_r <= dpi[3:0];
                    end
                    as_pos_d[dpi] <= as_pos[dpi*12 +: 12];
                end
                end
                //  ⭐ **读走清零**（⭐ 写在**最后** ⇒ 同块后写覆盖先写 ⇒ 清零赢）
                //     ⚠️ `pos_probe` 在 `probe_req_i` 那一拍锁存 `pos_i`
                //        ⇒ ⭐ 它锁到的是**清零前**的值 ✅（⭐ 正是我们要的）
                if (cmd_probe_req) begin
                    dpos_pk_r <= 12'd0;
                    dpos_ax_r <= 4'd0;
                end
            end
        end

        //  ⚠️ `dp_push`/`dp_data` **已在仲裁器之前声明**（⭐ `L66`：声明先于使用）

        //  🔴🔴 **2026-09-28 修（⭐ 第一版有两个真 bug，⭐ 上板实测"只有 P 包、没有 Q 包"）**：
        //
        //  ① 🔴 **`push_o`/`data_o` 接到了【死线】上** —— ⛔ 没接进 UART 仲裁器
        //     ⇒ ⭐ `Q` 包**永远发不出来**（⭐ 现象：串口只看到 `P`）
        //     ✅ 修法：⭐ 把 `dp_push`/`dp_data` 加进 `tx_req`/`tx_byte` 的仲裁
        //
        //  ② 🔴 **两个 probe 会【同拍抢 FIFO】** —— ⭐ 它们都由 `cmd_probe_req` 触发，
        //     各自要推 8 字节，⚠️ 而仲裁器**每拍只推 1 字节** ⇒ ⭐ 两个包**都会被踩坏**
        //     ✅ 修法：⭐ **串行化** —— ⭐ `'P'` 到达时先把 `Q` 的载荷【锁存】，
        //        等 ~400 µs（⭐ 8 字节 @500 kbaud = 160 µs，⭐ 留 2.5× 余量）
        //        再让 `Q` 那个 probe 开始推 ⇒ ⛔ 两者绝不重叠
        //
        //  📌 **教训**：⭐ **新增一个"会往共享总线上推东西"的模块时，必须问两句**：
        //     ① ⭐ **它的输出接上了吗？**（⛔ "我声明了线"不算接上）
        //     ② ⭐ **它和已有模块会同时推吗？**（⭐ 共享资源必须串行化）
        reg [11:0] dpos_hold_r;
        reg [3:0]  dpos_axh_r;
        reg [14:0] dp_wait_r;
        always @(posedge clk) begin
            if (!rst_n_sync) begin
                dpos_hold_r <= 12'd0;
                dpos_axh_r  <= 4'd0;
                dp_wait_r   <= 15'd0;
            end else begin
                if (cmd_probe_req) begin
                    //  ⭐ 锁存【清零前】的峰值（⭐ `dpos_pk_r` 在同一拍被清零）
                    dpos_hold_r <= dpos_pk_r;
                    dpos_axh_r  <= dpos_ax_r;
                    dp_wait_r   <= 15'd20000;      // ⭐ 20000 拍 = 400 µs @50 MHz
                end else if (dp_wait_r != 15'd0) begin
                    dp_wait_r <= dp_wait_r - 15'd1;
                end
            end
        end
        //  ⭐ `DPOS_DIAG=0` ⇒ 恒 0 ⇒ ⭐ probe 的 FSM 永远停在 IDLE
        //     ⇒ ⭐ 它的寄存器全变常量 ⇒ **被综合器扫掉** ✅
        wire dp_req = (DPOS_DIAG != 0) && (dp_wait_r == 15'd1);

        pos_probe #(.N_BYTES(8), .PREFIX(8'h51), .QUEUE_WHEN_BLOCKED(1)) u_pos_probe_dpos (
            .clk_i      (clk),
            .rst_n_i    (rst_n_sync),
            .probe_req_i(dp_req),
            .pos_i      (dpos_hold_r),
            .ch_i       (dpos_axh_r),     // ⭐ 回的是【出峰的轴号】，⛔ 不是 ADC 扫描通道
            .push_o     (dp_push),
            .data_o     (dp_data),
            .ready_i    (normal_tx_ready),
            .idle_i     (txf_idle && !np_busy && !vp_busy && !pp_busy),
            .busy_o     (dp_busy), .packet_active_o(dp_active)
        );

        // ── ⭐ ④ `axis_map`：轴位 → `phase_inc` ──────────────────────────
        //   ⚠️ **本版用法**：⭐ 用**触发到的那个轴**查表
        //      ⇒ ⭐ 因此 `axis_map` 的输入**逐轴驱动**（⭐ 见下方 `ee` 的配合）
        //   🔴 **TODO（阶段 2）**：⭐ 配合滑音 ⇒ 需要**同时算相邻两轴**的 `phase_inc`
        wire [31:0] am_inc;
        wire        am_valid;
        wire [3:0]  am_axis;

        // ═══════════════════════════════════════════════════════════════════
        // ⭐⭐ `axis_map` 的驱动：⭐ **把触发轴的位置送进去查表**
        //
        //   🔴 **⚠️ 本版的设计取舍（⭐ 说清楚，⛔ 不是最终形态）**：
        //      ⚠️ `event_extract` 一帧可能报多个事件，而 `axis_map` 只有一个入口
        //      ⇒ ⭐ 本版**用"事件携带的轴号"去 `as_pos` 里取那个轴的行程**
        //      ⇒ ⭐ **单键按下的路径是【完全正确】的**（⭐ 这正是本周硬指标）
        //      ⚠️ 同帧多键时，`note_on` 事件**不会丢**（⭐ `ee_valid` 保证），
        //         但**音高可能取到"最后一个轴"的值** —— ⚠️ 这是已知限制。
        //   🔴 **TODO（阶段 2）**：⭐ `axis_snapshot` 已给【16 轴同帧 pos】，
        //      ⭐ 应改成 **`axis_map` 逐轴查表并锁存 16 个 `phase_inc`**，
        //      再按事件轴号选取 ⇒ ⭐ 那样同帧多键也正确。
        //   📌 **依据**：⭐ `axis_map.fb_inc[0..15]` **已经是 16 轴全表**
        //      ⇒ ⭐ 阶段 2 只需把"选轴"这一步挪进 `axis_map`，⛔ 不用改它的表。

        // ── ⭐ ⑤ `event_extract`：触发 / 迟滞 / 不应期 ───────────────────
        wire        ee_valid;
        wire [3:0]  ee_axis;
        wire [1:0]  ee_kind;
        wire [11:0] ee_depth;
        wire        ee_slide_v, ee_two_v, ee_ovf;
        wire [7:0]  ee_lost;
        wire [3:0]  ee_slide_ax, ee_2a, ee_2b;
        wire signed [1:0] ee_slide_dir;

        event_extract #(
            .AXIS_N (16),
            .POS_W  (12),
            .DW     (13),
            .AXIS_W (4),
            // ── ⭐⭐ 阈值（⭐ 2026-09-23 第 2 次重设，⚠️ 起因是一个真缺陷）──────
            //
            //   🔴🔴 **为什么必须重设（⭐ 实测踩到）**：
            //      ⚠️ 我第 1 版设成 `TRIG=0x8D3(2259)` —— ⭐ 那是按【没 `tare`】的
            //         码值算的（松手 2110、触底 2854）。
            //      🔴 **但 `tare` 会把零点【减掉】** ⇒ ⭐ 实际码值是：
            //         · 松手 ⇒ **0**
            //         · 触底 ⇒ **744**（= 2854 − 2110）
            //      ⇒ 🔴 `2259` 在这个空间里 **【永远达不到】** ⇒ ⛔ **永远不触发**。
            //      ⭐ 实测证据（`tb_polarity_order`）：`rest pos=0`、`press pos=744`。
            //
            //   ⭐⭐⭐ **本条的教训（⭐ 我连着犯三次，同一个根因）**：
            //      🔴 **我按"静态码值"推算，没有把【链路各级的变换】串起来算**。
            //      ⭐ 正确做法：⭐ **阈值必须按 `pos` 空间设** ——
            //         ```
            //         raw →(反相) →(tare 减零点) →(span 增益) → pos
            //         ```
            //      ⚠️ 前面三次错误都是这一个根因：
            //        ① 反相放错级（`calib` 的减法方向假设不匹配）
            //        ② 忘了 `tare` 会减零点
            //        ③ 阈值按错的空间算（本条）
            //
            //   ⭐ **本次依据（⭐ 用户 2026-09-23 拍板："不要在中间，最高 20%"）**：
            //      · ⭐ **触发阈 = 行程的 20%** ⇒ `0.20 × 744 ≈ 149` = **`12'h095`**
            //      · ⭐ **释放阈 = 行程的 12%** ⇒ `0.12 × 744 ≈ 89` = **`12'h059`**
            //        （⭐ 迟滞 8% × 744 ≈ 60 码 ⇒ ⚠️ 防回弹抖动反复触发）
            //      📌 **`tare` 之后松手恒为 0** ⇒ ⭐ 阈值不再依赖"松手码"，⭐ 更稳。
            //
            //   ⚠️ **⚠️ 这些值依赖【行程 744 码】，⚠️ 而行程取决于定位板高度**：
            //      · ⭐ 用户正在调定位板 ⇒ ⭐ **行程一定变** ⇒ 🔴 **这两个必须跟着重算**
            //      · 📌 **重算法**：⭐ 先量 `pos@松手`（应 ≈0）与 `pos@触底` ⇒
            //        `TRIG = 0.26 × 行程`、`REL = 0.11 × 行程`
            //      · ⭐ 或更省事：⭐ **启用 `span` 增益标定**，⭐ 把行程归一到满量程 ⇒
            //        ⭐ 阈值就**不用再跟着行程变**（⭐ 见给队友的通知）。
            //
            //   🔴🔴 **2026-09-26 上板实测调整：⭐ 加厚迟滞（⭐ 修"触发反复"）**
            //      ⭐ **上板症状**（⭐ 用户实测）：
            //         *"先是按下后一点就触发；然后变成按下时不触发，
            //           回升到阈值时才触发。**在这两个情况反复循环**"*
            //      🔴 **根因：⭐ 迟滞太薄 + 触发点太浅**
            //         · ⭐ 原值 `TRIG=0x095(149)` / `REL=0x059(89)` ⇒ **迟滞仅 60**
            //         · ⭐ 行程实测 **744**（⭐ 静止 1985 → 按下 2729）
            //           ⇒ 迟滞只占 **8%** ⇒ 🔴 **读数在阈值附近抖动就会反复 on/off**
            //         · ⭐ 而 `TRIG=149` 只占行程 **20%** ⇒ ⚠️ "按一点就触发"
            //      🔴 **关键佐证**：⭐ 本项目实测过**单通道帧间噪声可达 Δ>48**
            //         （⭐ 见 `待查异常-span拒绝循环-定案-20260925.md`：
            //            正常通道 Δ≤6，⭐ 而 **ch2 的帧间跳变 >48**）
            //         ⇒ ⚠️ **60 的迟滞挡不住 48 的噪声** ⇒ ⭐ **必然反复**。
            //      ✅ **改法**（⭐ 保持"行程百分比"这个可重算的口径）：
            //         · `TRIG = 0.26 × 744 ≈ 192`（`0x0C0`）⇒ 按深一点才触发
            //         · `REL  = 0.11 × 744 ≈  80`（`0x050`）⇒ **迟滞 112**
            //         ⇒ ⭐ **112 ≫ 48** ⇒ ✅ **即使 ch2 那种噪声也跨不过去**
            //         ⇒ ⭐ 且 `192 < 744` ⇒ ✅ **够得着**（⭐ 不会按不出声）
            //      ⚠️ **若启用 `span`**（⭐ 行程归一化到 4095）⇒ ⭐ 这两个要**重算**：
            //         `TRIG = 0.26×4095 ≈ 1065`、`REL = 0.11×4095 ≈ 450`。
            //  ⭐⭐ **2026-09-28 上板实测调整：触发行程 25.8% → 8.6%**
            //  🔴 **用户反馈**：「按键的按下阈值是多少，我记得之前可以改到 5% 的样子，
            //     现在个人觉得**触发行程太长了**」
            //  📌 **实测依据**：满行程 `pos` ≈ 744（⭐ 上板 `'N'` 扫描 811 次的最大值 752）
            //     · 原值 `TRIG=192` ⇒ ⭐ 192/744 = **25.8%** ⇒ 要按掉【四分之一行程】才出声
            //     · 项目历史口径（`K124修法`）是 **20%**（149/744）⇒ ⭐ 192 比它还长
            //  ✅ **改为**：`TRIG = 0.086×744 ≈ 64` · `REL = 0.043×744 ≈ 32`
            //     · ⭐ 行程 **8.6%**（≈ 原来的 1/3）
            //     · ⭐ **迟滞 32** ≫ 单通道帧间噪声 Δ≤6（⭐ 项目实测）⇒ ✅ 噪声跨不过去
            //     · ⭐ **噪声余量 = 64/6 = 10.7×**（原值 32× ⇒ 收紧但仍充足）
            //     · ⭐ **附带好处**：起音力度范围从 `113~255`（7.1 dB）
            //        扩到 `80~255`（**10.1 dB**）—— 见 `位置式力度-方案-20260928.md`
            //  ⚠️ **必须知道的权衡**：`REL_TH` 同时是**挂音防线** ——
            //     若静止 `pos` 因漂移长期 ≥ `REL_TH` ⇒ 🔴 `note_off` 永不生成（= 之前的 E1 假说）
            //     · 上板实测：⭐ 16 轴静止 `pos` **全为 0** ⇒ ✅ 当前零漂移
            //     · 缓解：⭐ `calib_autotare` 每次上电重记零点 ⇒ 漂移每次开机清零
            //     · ⚠️ 风险：单次开机内若漂移 > 32 码 ⇒ 可能挂音（原值 80 码 ⇒ 容限缩到 40%）
            //  📌 **若将来启用 `span`**（行程归一化到 4095）⇒ ⭐ 这两个要**重算**：
            //     `TRIG = 0.086×4095 ≈ 352`、`REL = 0.043×4095 ≈ 176`。
            //  ⭐⭐ 2026-09-28：⭐ 改为**引用唯一定义**（⛔ 不再另写 `12'd64`）
            //     ⇒ ⭐ 与 `VEL_TRIG_TH` 由**同一个常量**派生 ⇒ 结构上不可能再错位。
            //     定义处见上方 `EVT_TRIG_TH` / `EVT_REL_TH`。
            .TRIG_TH   (EVT_TRIG_TH),
            .REL_TH    (EVT_REL_TH),
            // ⚠️ Δ 阈值（滑音/双音用）：⭐ 目前保持默认 8
            //   （⭐ 依据：滑动时每帧行程变约 8 码 ⇒ 见设计草案 §2.2b）
            //   🔴 2026-09-25 更正 + **改值**（⭐ `K-128`）：
            //      ⚠️ 原来写 150，注释声称"≈30 ms @196 µs/帧" ⇒ 🔴 **两个数都不对**：
            //         · ⭐ 帧周期实测 **500 µs**（⛔ 不是 196）—— 见 `sim/evidence/tb_adc_farm.log`
            //         · ⇒ 150 帧 实际 = **75 ms**（🔴 是期望的 2.55 倍）
            //      ⇒ 🔴 **触发不应期过长 ⇒ 快速连击会被吞**
            //      ✅ 改法：⭐ **保持"约 30 ms"这个设计意图**，⭐ 按真实帧周期反算帧数：
            //         30 ms / 500 µs = **60 帧** ⇒ ⭐ 取 60
            //      📌 为什么改帧数而不改 `CHANNEL_RATE_HZ`：
            //         ⚠️ 改采样率会连带影响 `VOTE_N`/`STABLE_NEED`/`debounce` 等
            //            全部时序常量 ⇒ 🔴 需重跑全量回归 + 变异测试 ⇒ ⛔ 不划算。
            .REFRACT_N (60)           // ⭐ ≈30 ms @500 µs/帧（原 150 实为 75 ms）
        ) u_event_extract (
            .clk              (clk),
            .rst_n            (rst_n_sync),
            // ⭐⭐ **标定完成前不判按键**（⭐ 2026-09-23 新增，🔴 修"开机误触发"）
            //
            //   🔴 **为什么**：⭐ `calib_autotare` 完成前 `pos` 是**未标定的脏值** ——
            //      ⚠️ 未 `tare` ⇒ `zero = 0` ⇒ `pos = 4095 − 1985 = 2110`
            //      ⭐ 而阈值是按**标定后空间**设的（`TRIG_TH = 149`）
            //      ⇒ 🔴 **2110 ≫ 149 ⇒ 16 个轴【全被判"按下"】**
            //      ⇒ 🔴 **开机瞬间起一堆音符，而它们根本没被按过**
            //         ⇒ ⭐ 松手也关不掉（⭐ 对应的"按下"从未发生）。
            //   ⭐ 实测证据（e2e tb）：⭐ `n_on = 8`（我一次都没按）、
            //      `nm_gate = 0x08000000`（⭐ **一个 voice 恒 held**）。
            //
            //   ⭐ **语义上本来就该这样**：⭐ "标定没做好 ⇒ 读数不可信 ⇒ 不判按键"。
            //   📌 `at_done` 来自 `calib_autotare` ⇒ ⭐ 标定完成后才放行 ✅
            //   ⚠️ `enable_i = 0` 时 `event_extract` **还会清掉 `key_on`/`refr`**
            //      ⇒ ⭐ 标定完成后**从"全松开"的干净状态开始**（⭐ 见该模块注释）。
            //
            //   🔴🔴 **2026-09-26 修正：⭐ 改用【延迟后】的 `at_en_ready`**
            //      ⚠️ 原来直接接 `at_done` ⇒ 🔴 **在 `zero` 生效前就放行**
            //         ⇒ ⭐ 拿未 tare 的脏 `pos`（2110）判按键
            //         ⇒ 🔴 **8 个 note_on 且无 off ⇒ 8 个 voice 恒响**
            //      📌 **完整根因与时序见上方 `AT_EN_DELAY` 那段注释**
            .enable_i         (at_en_ready),
            .snap_valid_i     (as_valid),
            .pos_i            (as_pos),
            .delta_i          (as_delta),
            .evt_valid_o      (ee_valid),
            .evt_axis_o       (ee_axis),
            .evt_kind_o       (ee_kind),
            .evt_depth_o      (ee_depth),
            //  ⭐⭐ 2026-10-09（`P0-27`）：⭐ **把按键状态接给 `led_data`**（⭐ 见模块级 `ee_key_on`）✅
            //   🔴 原缺陷：⭐ `led_data.key_active_i` 是**占位 `16'd0`**
            //      ⇒ ⭐ `key_pattern` 恒 0 ⇒ `pattern_changed` 恒假 ⇒ `commit_r` 恒 0
            //      ⇒ ⭐ `tlc5916_bank` 一轮都不跑 ⇒ 🔴 **24 路灯永久全灭** ✅
            //   ✅ 修法：⭐ 接 `event_extract` 内部已经在维护的 `key_on[]`（⭐ 零额外逻辑）✅
            .key_on_o         (ee_key_on),
            // ⚠️ 滑音/双音：⭐ 接口已接，⛔ 本版恒 0（⭐ 阶段 2 填）
            .slide_valid_o    (ee_slide_v),
            .slide_axis_o     (ee_slide_ax),
            .slide_dir_o      (ee_slide_dir),
            .two_note_valid_o (ee_two_v),
            .two_note_axis_a_o(ee_2a),
            .two_note_axis_b_o(ee_2b),
            .overflow_o       (ee_ovf),
            .lost_cnt_o       (ee_lost)
        );


        // ═══════════════════════════════════════════════════════════════════
        //   ⚠️ **声明与 always 放在 `event_extract` 之后** ——
        //      🔴 因为本块**引用了 `ee_valid`/`ee_kind`/`ee_axis`**
        //      ⇒ ⚠️ **Verilog 要求"先声明后使用"**（⭐ 否则 elaboration 报
        //         `Unable to bind wire/reg` —— ⭐ 这是我第一版犯的错）。
        // ═══════════════════════════════════════════════════════════════════
        // T15 · 两种演奏模式
        //   键盘：轴越阈/松开直接变成 note_on/note_off。
        //   指板：轴只选择音，UP/DOWN 比较器的边沿才产生 pluck；同拍 UP 优先。
        //   选音、异步采样与模式语义在此合流，之后的音高映射只看统一事件流。
        wire       pluck_valid;
        wire       pluck_up;
        wire       pm_valid;
        wire [3:0] pm_axis;
        wire [1:0] pm_kind;
        wire [11:0] pm_depth;

        async_pluck_capture #(
            // 50 MHz 下 1_500_000 周期 = 30 ms；比较器迟滞负责阈值抖动，
            // 此处只兜住摇杆回弹，不延迟首次拨弦。
            .REFRACT_CYC(1_500_000)
        ) u_async_pluck_capture (
            .clk_i             (clk),
            .rst_n_i           (rst_n_sync),
            .pluck_up_async_i  (pluck_up_i),
            .pluck_down_async_i(pluck_down_i),
            .pluck_valid_o     (pluck_valid),
            .pluck_up_o        (pluck_up)
        );

        play_mode_ctrl #(
            .AXIS_W (4),
            .DEPTH_W(12)
        ) u_play_mode_ctrl (
            .clk_i            (clk),
            .rst_n_i          (rst_n_sync),
            .fretboard_mode_i (play_fretboard_mode),
            .axis_valid_i     (ee_valid),
            .axis_i           (ee_axis),
            .axis_kind_i      (ee_kind),
            .axis_depth_i     (ee_depth),
            .pluck_valid_i    (pluck_valid),
            .pluck_up_i       (pluck_up),
            .evt_valid_o      (pm_valid),
            .evt_axis_o       (pm_axis),
            .evt_kind_o       (pm_kind),
            .evt_depth_o      (pm_depth)
        );

        // 音高映射流水寄存器。valid、axis、kind 与 phase_inc 必须同拍。
        reg [11:0] am_pos_in;
        reg [3:0]  am_axis_in;
        reg [1:0]  am_kind_in;
        reg        am_vld_in;
        reg        am_mode;            // 0 = 键盘模式 · 1 = 指板模式
        reg        am_vld_out;
        reg [3:0]  am_axis_out;
        reg [1:0]  am_kind_out;
        //  ⭐⭐ 2026-09-28 新增：m_inc 是 axis_map 对【当前 am_axis_in】的组合输出（0 拍），
        //  而 am_vld_out/am_axis_out 再延一拍 ⇒ 错一拍 ⇒ 同帧多键时前一条事件拿到后一条的音高。
        reg [31:0] am_inc_out;

        always @(posedge clk) begin
            if (!rst_n_sync) begin
                am_pos_in   <= 12'd0;
                am_axis_in  <= 4'd0;
                am_kind_in  <= 2'd0;
                am_vld_in   <= 1'b0;
                am_mode     <= 1'b1;
                am_vld_out  <= 1'b0;
                am_axis_out <= 4'd0;
                am_kind_out <= 2'd0;
                am_inc_out  <= 32'd0;
            end else begin
                am_vld_in <= 1'b0;
                if (pm_valid) begin
                    am_pos_in  <= as_pos[pm_axis*12 +: 12];
                    am_axis_in <= pm_axis;
                    am_kind_in <= pm_kind;
                    am_mode    <= play_fretboard_mode;
                    am_vld_in  <= 1'b1;
                end
                am_vld_out  <= am_vld_in;
                am_axis_out <= am_axis_in;
                am_kind_out <= am_kind_in;
                am_inc_out  <= am_inc;   // ⭐ 打一拍，与 am_vld_out/am_axis_out 严格同拍
            end
        end

        axis_map #(
            .AXIS_W  (4),
            .POS_W   (12),
            .PHASE_W (32),
            .N_KEY   (16)
        ) u_axis_map (
            .clk          (clk),
            .rst_n        (rst_n_sync),
            .pos_valid_i  (am_vld_in),
            .axis_id_i    (am_axis_in),
            .pos_i        (am_pos_in),
            .mode_i       (am_mode),
            .phase_inc_o  (am_inc),
            .phase_valid_o(am_valid),
            .axis_id_o    (am_axis)
        );
        // ── ⭐ ⑥ `param_extract`：力度（⛔ 结构上不产生音符）───────────────
        wire       pe_vel_v, pe_pitch_v;
        wire [3:0] pe_vel_ax, pe_pitch_ax;
        wire [7:0] pe_vel;
        wire [31:0] pe_pitch;

        param_extract #(
            .AXIS_N (16),
            .POS_W  (12),
            .AXIS_W (4),
            .VEL_W  (8),
            .PHASE_W(32),
            // ⭐⭐ 2026-09-24 新增：⭐ **`pos` 的满量程**（⭐ 修 `K-124`）
            //   🔴 **为什么必须传**：⚠️ 不传就用模块默认，⭐ 而模块**看不到行程**
            //      ⇒ 🔴 原来的 `VEL_T2 = 1536` **超过实际行程 744** 却【无人发现】
            //      ⇒ ⚠️ 上板表现：⭐ **深阈永远越不过 ⇒ 力度恒定**
            //         （⚠️ 而波形全对 ⇒ 🔴 极易被误判成"手感问题"）
            //   ⭐ **现在的语义**：⭐ 阈值 = `POS_FULL` 的百分比（⭐ `VEL_T1_PCT`/`VEL_T2_PCT`）
            //      ⇒ ⭐ **换档只改 `POS_FULL` 一个数**
            //   📌 **两档取值**（⭐ 与 `TRIG_TH`/`REL_TH` 的算法一致）：
            //      · ⭐ **只 `tare`（上电默认）** ⇒ `744`（⭐ **本行就是这一档**）
            //      · ⭐ **做过 `span`（归一化）** ⇒ `4095`
            //   ⚠️ **改成 `4095` 时**：⭐ 用户必须**先做 `span`**（⭐ 发串口 `'S'`）
            //      ⇒ ⚠️ 否则 `pos` 空间还是 744 ⇒ 🔴 阈值全落空
            //   📌 **自检会守**：⭐ 若 `VEL_T2_EFF > POS_FULL` ⇒ ⭐ **PARAM_OK=0 + 报错**
            // ⭐⭐ 2026-10-01 返工：⭐ `CALIB_FULL` → **`TRAVEL_TARE`**（⭐ `744`，⭐ = 实际行程档 ✅）
        //   🔴 **为什么必须回退**（⭐ 上板实测）：⭐ BATCH 8.2 把这里接到 `CALIB_FULL`(4095)
        //      ⇒ 🔴 `VEL_T1_EFF = 4095×50% = 2047` · ⭐ `VEL_T2_EFF = 4095×80% = 3276`
        //      ⇒ ⭐ 两者**全部越出实际行程 744** ⇒ 🔴 **都够不着 ⇒ `dt` 恒 0 ⇒ 力度恒定**（`K-124`）✅
        //   ⭐ **二分实测证据**：⭐ `AN`（`POS_FULL` 仍是 744）⇒ **力度反馈正常** ✅
        //      · ⭐ `AP`/`AU`（`POS_FULL=4095`）⇒ **力度跟随消失** ✅
        //   📌 `VEL_T1_PCT`/`VEL_T2_PCT` 是**百分比** ⇒ ⭐ 换基数自动跟随，⛔ 不用改 ✅
        //   📌 **改 `TRAVEL_TARE` 一处** ⇒ ⭐ 这里跟着动 ⇒ ⭐ ⛔ 不会漏 ✅
        .POS_FULL(TRAVEL_TARE)
        ) u_param_extract (
            .clk          (clk),
            .rst_n        (rst_n_sync),
            .snap_valid_i (as_valid),
            .pos_i        (as_pos),
            .evt_valid_i  (ee_valid),
            .evt_axis_i   (ee_axis),
            .evt_kind_i   (ee_kind),
            .vel_valid_o  (pe_vel_v),
            .vel_axis_o   (pe_vel_ax),
            .vel_value_o  (pe_vel),
            .pitch_valid_o(pe_pitch_v),
            .pitch_axis_o (pe_pitch_ax),
            .pitch_value_o(pe_pitch)
        );

        // ═══════════════════════════════════════════════════════════════════
        // ⭐⭐ `axis_map` 的驱动：⭐ **按 `event_extract` 报的轴号取该轴的行程**
        //
        //   🔴 **⚠️ 这是本版的一个【简化】**（⭐ 必须说清，⛔ 不是最终形态）：
        //      ⚠️ `event_extract` 一帧可能报多个事件，⭐ 而 `axis_map` 只有一个入口
        //      ⇒ ⭐ 本版**只把"当前事件"的轴喂给 `axis_map`**
        //      ⇒ ⚠️ **同帧多事件时，音高会取错**（⭐ 但事件本身不会丢 —— 那由 `ee_valid` 保证）
        //   🔴 **TODO（阶段 2）**：⭐ 改成 **`axis_map` 内部按 16 轴全表查**
        //      （⭐ 它的 `fb_inc[0..15]` **已经是 16 轴全表了** ⇒ ⭐ 只需把 `pos` 改成按轴选）
        //   📌 **本版的验收目标**：⭐ **"按琴键出声"** —— 单键按下的路径是**完全正确**的。
        // ═══════════════════════════════════════════════════════════════════
        // ═══════════════════════════════════════════════════════════════════
        // ⭐⭐ 源 A 的仲裁：**`evt_merge` 源 A 只有【一个】入口**
        //
        //   🔴 **⚠️ 这是 2026-09-23 接线时暴露出的真冲突**：
        //      · ⭐ `T57` 的验收（`tb_top_sound`）**靠"演示和弦"走源 A 出声**
        //        ⇒ ⭐ 那是**交付路径的证据**（"顶层真的出声"）
        //      · ⭐ 而 ESP32 清单 §四 说"**唯一对接点 = `evt_merge` 源 A**"
        //      · ⭐ 现在 **W3a 手弹**也要进源 A
        //      ⇒ ⚠️ **三者抢同一个入口**。
        //
        //   ⭐ **本版做法：用一个参数仲裁**（⭐ 而不是删掉演示和弦 ——
        //      ⚠️ 那样会让 `T57` 的判据**失去被测对象**，⭐ 等于自己废掉一张验收单）。
        //      · `SOURCE_A_SEL = 0` ⇒ ⭐ **W3a 手弹**（⭐ 上板/交付用的档）
        //      · `SOURCE_A_SEL = 1` ⇒ ⭐ **演示和弦**（⭐ `T57` 验收用的档）
        //   🔴 **TODO（曲谱接入时）**：⭐ 那时源 A 要有 **3 个来源**（手弹/曲谱/演示）
        //      ⇒ ⭐ 应改成 **`evt_merge` 前再加一级仲裁**（⭐ 或把源 A 也做成多路合流）。
        //   📌 **为什么不直接删演示和弦**：⭐ `R-16`/`K-69` 的教训 ——
        //      ⚠️ **"测试配置"和"交付默认值"要分开**，⛔ 不能为了接新功能而废掉验收手段。
        // ═══════════════════════════════════════════════════════════════════
        // `pm_*` 经一拍映射后，valid / axis / kind / phase_inc 仍严格同拍。
        // 因此 note_off 不会再被伪装成 note_on，能可靠释放同轴 voice。
        wire        w3a_evt_valid = am_vld_out;
        wire [3:0]  w3a_evt_axis  = am_axis_out;
        wire [1:0]  w3a_evt_kind  = am_kind_out;
        //   ⭐⭐ 2026-09-28：⭐ **起音力度也改成位置式**（⭐ 用户已定方案 §5.3）
        //
        //   ⭐ `am_pos_in` = ⭐ **触发那一刻、该轴的 `pos`**
        //      （⭐ `pm_valid` 时从 `as_pos[pm_axis*12 +: 12]` 锁存，见上方 `always`）
        //      ⇒ ⭐ 与下方位置式力度流**共用同一个函数** `pos_to_vel`
        //        （⛔ 不在这里重写公式 —— 两份实现必然漂移）
        //
        //   ⚠️ **为什么保留 `8'd200` 作兜底**（⭐ 这是一个有意的取舍）：
        //      · ⭐ **键盘模式**（`pos > TRIG_TH` 才产生 `note_on`）⇒
        //        `am_pos_in >= 65` ⇒ ⭐ **永远走位置式分支**，兜底用不上 ✅
        //      · ⚠️ **指板模式的 `pluck`** 是另一回事：`pos` 在那里是**"品位选择"**，
        //        ⛔ 与"按多重"无关，而且**可能 < `TRIG_TH`**（⭐ `play_mode_ctrl` 的
        //        `KIND_PLUCK` 分支只看 `selected_valid`，⛔ 不看 `pos` 深度）
        //      · ⚠️ 同一区间还会兜住"未标定/异常 `pm_valid`"
        //      ⇒ ⭐ 该区间用**旧的默认值 200**，⛔ 不让"位置"在**语义上不是力度**的
        //        事件上乱定力度（⭐ 否则指板模式会莫名其妙变很轻）。
        //   📌 **判据**：⭐ 键盘模式（本方案的验收场景）下，本行**恒等于**
        //      `pos_to_vel(触发那一刻该轴的 pos)` ✅
        localparam [7:0] VEL_DEFAULT = 8'd200;
        wire [7:0]  w3a_evt_vel   = (am_pos_in < VEL_TRIG_TH) ? VEL_DEFAULT
                                                             : pos_to_vel(am_pos_in);
        wire [31:0] w3a_evt_inc   = am_inc_out;   // ⭐ 必须与 w3a_evt_valid(=am_vld_out) 同拍

        // ═══════════════════════════════════════════════════════════════════
        //   ⭐⭐ 源 A 三级仲裁（`seq_arb`，⭐ 2026-09-26 新增）
        //
        //   🔴 **它补的是 `top.v` 自己的 TODO**（⭐ 原文保留在下方，⛔ 不删）：
        //      *"那时源 A 要有 3 个来源（手弹/曲谱/演示）
        //        ⇒ 应改成 `evt_merge` 前再加一级仲裁"*
        //
        //   ⭐ **三个来源**：
        //      ① ⭐ **手弹**（W3a 采集链）—— 最高优先（⭐ 人优先于机器）
        //      ② ⭐ **曲谱**（`evt_uart_rx` 经串口灌入）
        //      ③ ⭐ **演示**（`DEMO_CHORD_ON` 自检和弦）—— ⚠️ **自动让位**
        //
        //   ⚠️ **与旧 `SOURCE_A_SEL` 的关系**：
        //      · `SOURCE_A_SEL = 0`（⭐ 默认）⇒ ⭐ **走 `seq_arb`**（手弹+曲谱可叠加）
        //      · `SOURCE_A_SEL = 1` ⇒ ⚠️ **强制演示独占**（⭐ 保 `T57` 的 `tb_top_sound`）
        //      📌 旧 tb 依赖"演示和弦独占源 A"⇒ ⭐ **强制档不能删**。
        //
        //   🔴 **曲谱那一路的接法（⭐ 重要）**：
        //      ⚠️ `evt_uart_rx` 现在**只"解析出来"，⛔ 还没接进 `evt_merge`**
        //         ⇒ ⭐ 本块**把 `eu_evt_valid`/`eu_evt_data` 接到 `seq_arb` 的源 2**
        //         ⇒ ⭐⭐ **灌曲谱从此会响**（⭐ 这是本模块最直接的收益）。
        //
        //   🔴🔴 **64 bit 字段位域 —— ⭐ 已从【权威来源】核实（⛔ 不是凭印象）**：
        //      📌 权威 = `tools/mid2evt.py:124-128` 的**打包**常量（⭐ 发送端）
        //         ⇒ ⭐ 与 `tools/evt2uart.py:161` 的解包**互相印证**。
        //      ```
        //        tick  : bit[63:44]  20 bit   ← ⚠️ 由 play_seq 用，⛔ 不是本处
        //        inc   : bit[43:23]  21 bit   ← ⭐ phase_inc（⭐ 注意是 21 位！）
        //        axis  : bit[22:19]   4 bit
        //        vel   : bit[18:11]   8 bit
        //        kind  : bit[10:9]    2 bit
        //        timbre: bit[8:7]     2 bit   ← ⭐ B 方案（`U-27`）
        //      ```
        //      🔴 **我第一版写错了**（⚠️ 凭印象写成 `[63:60]`=axis / `[59:28]`=inc …）
        //         ⇒ ⭐ **实测 `mid2evt.py` 才发现** ⇒ ⚠️ 若照错的那样接，
        //            🔴 **曲谱会全部响成乱七八糟的音高/轴号**（⭐ 而且**不报错** ——
        //            ⚠️ `K-87` 同族：路径能错却不可见）。
        //      📌 **教训**：⭐ **跨模块的位域必须回到"打包那一侧"核实**，
        //         ⛔ 不能凭接口表的字段【顺序】去推位【位置】。
        //      ⚠️ `inc` 是 **21 位**（⛔ 不是 32）⇒ ⭐ 高位补 0 到 32 位给 `seq_arb`。

        // ⭐⭐ 2026-10-11（`U-19`）：⭐ **曲谱源从"裸 UART"改成"`play_seq` 的输出"** ✅
        //   🔴 **改前**：⭐ `eu_evt_valid`/`eu_evt_data` **直连** `seq_arb.score`
        //      ⇒ ⚠️ **`tick` 字段被完全忽略** ⇒ 🔴 **事件一到就响**（⭐ 整曲被"压扁"）
        //      ⇒ ⭐ 而 `play_seq`（⭐ 就是为"按 tick 播放"写的那个模块）**根本不在链上**
        //      ⇒ 🔴 **"按音乐位置播放"从未生效过** ✅
        //   ✅ **改后**：⭐ `evt_uart_rx ⇒ u_evt_buf ⇒ u_play_seq ⇒ seq_arb.score` ✅
        //      ⇒ ⭐ `tick` 被尊重（⭐ 修掉"每个 tick 只取一条 ⇒ 和弦被拉成琶音"✅）
        //      ＋ ⭐ `kind=2` 能真的换速（⭐ 驱动 `beat_gen.tick_inc_i`）✅
        //      ＋ ⭐ 同一 tick 上的全部事件**在一个 tick 内连续吐完** ✅
        //   📌 **位域与 `play_seq.v` / `guide_lamp.v` / `tools/mid2evt.py` 逐位一致** ✅
        //      （⭐ `tick [63:44]` · `inc [43:23]` · `axis [22:19]` · `vel [18:11]`
        //        · `kind [10:9]` · `timbre [8:7]` ✅）
        //   ⚠️ **`inc` 是 21 位**（⛔ 不是 32）⇒ ⭐ 高位补 0 到 32 位给 `seq_arb` ✅
        //   📌 ⭐ 注意：⭐ `kind=2`（换速）**不会**出现在这里 ——
        //      ⭐ `play_seq` 的 `note_valid_o` **只为 kind 0/1 拉高**（⭐ 契约 §一）
        //      ⇒ ⭐ 下游 `seq_arb`/`note_manager` **永远看不到换速事件** ✅
        //      （⭐ 这正是"换速不会被当成伪音符"的实现方式 ✅）
        wire [3:0]  ps_evt_axis   = ps_note_data[22:19];
        //  ⭐⭐⭐⭐ 2026-10-11：⭐ **曲谱音高必须按【采样率】换算** —— 🔴 **修一个 1024 倍的量纲错** ✅
        //
        //  🔴🔴 **原缺陷（⭐ 本轮发现，⭐ 从未有人听到过）**：
        //     ⭐ 原文是 `{11'd0, ps_note_data[43:23]}`（⭐ **21 位零扩展** ✅）
        //     · ⭐ `tools/mid2evt.py:115` 是 **`FS = 50_000_000.0`**
        //       ⇒ ⭐ 它给 MIDI 69（A4 = 440 Hz）写
        //          `inc = round(440 × 2^32 / 50e6) = **37791**` ✅
        //     · ⭐ 而 `oscillator_bank` 的相位**按 `sample_tick_i` 推进**
        //       （⭐ `oscillator_bank.v:725`：⭐ `phase_q <= phase_q + lane_inc`
        //         在 `sample_tick_i` 门控内 ✅）⇒ ⭐ 时钟是 **48.828125 kHz** ✅
        //     ⇒ 🔴 零扩展直接用 ⇒ ⭐ 实际频率 = `37791/2^32 × 48828.125 = **0.43 Hz**`
        //        ⇒ ⭐ **低 1024 倍（正好 10 个八度）** ⇒ 🔴 **整条曲谱变成次声波** ✅
        //
        //  📌 ⭐ **为什么一直没暴露**：⭐ 这条链路在 2026-10-11 之前
        //     **结构上不可能工作** —— ⭐ `play_seq` 从未被例化 ✅
        //     ＋ ⭐ `P0-02` 门控把曲谱载荷全挡掉 ✅ ⇒ ⭐ **从来没人听到过** ✅
        //
        //  📌 ⭐ **契约的洞**：⭐ `play_seq接口冻结契约.md:145-150` **只定义了
        //     `tick_inc`（速度）的量纲**（⭐ `2^32 × f / 50e6` ✅ —— ⭐ 那**是对的**，
        //     因为 `beat_gen` 的相位**按系统时钟**推进 ✅）
        //     ⇒ ⚠️ **`phase_inc`（音高）的量纲【没有定义】** ⇒ ⭐ 这就是漏洞的来源 ✅
        //
        //  ✅ **修法**：⭐ **左移 10 位** —— ⭐ `50e6 ÷ 48828.125 = 1024 = 2^10` ✅
        //     ⇒ ⭐ 正好把"50 MHz 口径"换成"采样率口径" ✅
        //     📌 ⭐ **精度**：⭐ 线上是 21 位 ⇒ ⭐ 移后是 **31 位有效** ✅
        //        ⇒ ⭐ 相对误差 ≤ `2^-21`（⭐ ≈ **0.0008 音分**）⇒ ⭐ **完全够** ✅
        //     📌 ⭐ **为什么⛔ 不改 PC 侧**：⭐ 若 `mid2evt` 直接用采样率算
        //        ⇒ ⭐ MIDI 127 要 `1.1e9` ⇒ 🔴 **31 位装不进 21 位字段** ✅
        //        ⇒ ⭐ **只有"FPGA 侧移位"这条路可行** ✅
        //
        //  ⛔⛔ **关键边界：⛔ 只能移【音高】这一条** ——
        //     ⚠️ `kind=2` 的 `inc` 是 **`tick_inc`**（⭐ 走 `play_seq.tick_inc_o` → `beat_gen`）
        //     ⇒ ⭐ **它的量纲本来就是对的**（⭐ `beat_gen` 按系统时钟 ✅）
        //     ⇒ ⛔ **不许移**（⭐ 移了节拍就会快 1024 倍 🔴）
        //     📌 ⭐ 判据：⭐ `tb/w3b/tb_top_score_path.sv` 的 **`Fa`**
        //        （⭐ `tick_inc_o` 必须仍等于 `kind=2` 事件里的原值 ✅）
        //        ＋ ⭐ **`H1`/`H2`**（⭐ 音高必须按采样率 ✅）
        wire [31:0] ps_evt_inc    = {1'b0, ps_note_data[43:23], 10'b0};
        wire [7:0]  ps_evt_vel    = ps_note_data[18:11];
        wire [1:0]  ps_evt_kind   = ps_note_data[10:9];
        // T31b: bits [8:7] are the existing score-frame timbre field.
        // Keep it as a sideband; the 64-bit UART transport and board I/O stay unchanged.
        wire        ps_evt_timbre_valid = ps_note_valid;
        wire [1:0]  ps_evt_timbre = ps_note_data[8:7];
        // ═══════════════════════════════════════════════════════════════════
        //   ⚠️ **旧的二选一写法（⭐ 保留痕迹，⭐ 已被 `seq_arb` 取代）**：
        //      wire src_a_valid = (SOURCE_A_SEL == 1) ? demo_note_valid : w3a_evt_valid;
        //      ...
        //   📌 **为什么保留注释**：⭐ 它是"源 A 只有一个人口"这个约束的**历史证据**
        //      ⇒ ⚠️ 删了就没人知道**为什么当初要仲裁**（⭐ `K-106` 纪律：保留痕迹）。

        wire        sa_valid;
        wire [3:0]  sa_axis;
        wire [31:0] sa_inc;
        wire [7:0]  sa_vel;
        wire [1:0]  sa_kind;
        wire        sa_timbre_valid;
        wire [1:0]  sa_timbre;
        //  ⭐⭐ 2026-09-29（A1）：⭐ `seq_arb` 导出的**来源标记**
        //     ⭐ 编码 = `seq_arb` 的 `SRC_*`（0=live 手弹 / 1=score 曲谱 / 2=demo 演示）
        //     ⭐ 一路传下去：`seq_arb.evt_src_o → evt_merge.a_src_i → note_manager.note_src_i`
        //  ⭐⭐ 2026-09-30：⭐ **位宽 2 → 3**（⭐ 编码表见 `seq_arb.evt_src_o` 的注释）
        wire [2:0]  sa_src;
        wire [15:0] sa_collision_cnt;
        wire [15:0] sa_merged_cnt;
        wire [15:0] sa_drop_cnt;
        wire        sa_overflow;
        wire [15:0] sa_live_cnt;
        wire [15:0] sa_score_cnt;
        wire [15:0] sa_demo_cnt;

        //  ⭐⭐ 曲谱 UART 通路开关（⭐ 2026-09-28 新增）
        //     🔴 **原风险（⭐ 仍然存在，⛔ 没有被本改动消除）**：
        //        `evt_uart_rx`（帧头 `0xA5`）与串口屏/命令**共用同一条 UART**
        //        ⇒ 其它两路的合法载荷里出现 `0xA5` 时会被误当事件包
        //        ⇒ 🔴 **注入 axis=14/15 的伪 note_on** ⇒ **永久挂音**（⭐ 已仿真证明）
        //     📌 详见 `seq_arb` 例化处 `score_valid_i` 的注释与
        //        `tb/w3c/tb_evt_uart_rx_screen.sv`。
        //
        //  ⭐⭐ **2026-09-30：默认由 `0` 改成 `1`**（⭐ 用户需求：曲谱与 looper **同时可用**）
        //     🔴 **为什么能改默认**：⭐ 原来 looper 与曲谱**抢同一个 `score` 口**
        //        ⇒ ⭐ 只能二选一；⭐ 现在 looper 有**自己的通路**（⭐ `evt_merge` 源 C，
        //        ⭐ 见下方 §事件域 Looper）⇒ ⭐ 这个开关**只再管"曲谱 UART 开不开"** ✅
        //     ⭐ **两档的语义（⭐ 清楚且互不干扰）**：
        //        · ⭐ `1`（⭐ **新默认**）⇒ ⭐ **曲谱 UART + looper 都可用**（⭐ 用户要的"两个都要"）
        //        · ⭐ `0`                ⇒ ⭐ **只关曲谱 UART**（⭐ 那一路接常量 0）
        //                                   ⭐ **looper 照常可用**（⭐ 通路与它无关）
        //          📌 用途：⭐ 若上板发现"串口屏/命令流被误当曲谱帧"（⭐ 见上方的 0xA5 风险）
        //             ⇒ ⭐ **把它置 0 即可**，⛔ **不会连带关掉 looper** ✅
        //     ⚠️ **遗留风险（⭐ 必须上板验证）**：⭐ 默认档下曲谱 UART 是**开着的**，
        //        而它与串口屏**共用一条线** ⇒ ⭐ 伪事件注入的**理论通路仍然存在**
        //        （⭐ 与 `SCORE_UART_ENABLE = 1` 在旧版里的含义完全相同）。
        //        ⇒ ⭐ 上板时要**专门试**"串口屏数值帧里带 0xA5"这一情形（⭐ 见
        //           `tb/w3c/tb_evt_uart_rx_screen.sv` 的用例）✅
        localparam integer SCORE_UART_ENABLE = 1;

        // ══════════════════════════════════════════════════════════════════
        // ⭐⭐ 2026-09-29 新增：⭐ 事件域 Looper（`T37` 单层录制+播放 · `T39` 边 loop 边弹）
        //
        //  ⭐⭐ **2026-09-30：接法改了 —— 重放走 `evt_merge` 的【源 C】** ✅
        //   🔴 **为什么改**（⭐ 用户需求：⭐ **曲谱 UART 与 looper 要【同时】可用**）：
        //      ⚠️ 原接法是"looper 与曲谱 UART **抢 `seq_arb` 的 `score` 口**"
        //         （⭐ `SCORE_UART_ENABLE` 编译期二选一）
        //      ⇒ 🔴 **两者结构上不可能同时出声** —— ⭐ 用户实测"灌曲谱没声音"正是它 ✅
        //   ⭐ **新接法**：⭐ 曲谱 UART 仍走 `seq_arb.score`（⭐ 源 A 的一路），
        //      ⭐ looper 重放改走 **`evt_merge` 的第三个输入 `c_*`** ⇒ ⭐ **互不相干** ✅
        //
        //   ⭐⭐ **为什么必须"另开一个口"而⛔ 不是"复用某个空闲编码"**：
        //      ⭐ `evt_merge` 的 A/B 两个口**都已经有主** ——
        //         · A = `seq_arb` 的输出（手弹 / 曲谱 / 演示）
        //         · B = 节拍器 / 鼓机（⭐ `SEL_DRUM` 二选一）
        //      ⇒ ⚠️ 让 looper 挤进任一口 ⇒ 🔴 **它和那个口的源就不能并存** ✅
        //      🔴 **而且不许"共用一个源标签"**：⭐ `note_manager` 的 `note_off`
        //         是按 **(轴, 源)** 匹配的 ⇒ ⭐ 标签一旦相同，
        //         🔴 **曲谱的 `note_off` 会清掉同轴 looper 的 voice**（⭐ 反之亦然）✅
        //      ⇒ ⭐ **给 looper 一个自己的标签 `3'd4`**（⭐ 源标记 2 → 3 位，⭐ 5 个值够用）
        //         ⭐ 见 `seq_arb.evt_src_o` 的编码表 ✅
        //
        //   ⭐⭐ **顺带把 `T39`（边 loop 边弹）做出来了**：
        //      ⭐ 手弹走源 A、⭐ looper 走源 C ⇒ ⭐ **由 `evt_merge` 真仲裁**
        //      （⚠️ ⛔ **不是**把两路直接"或"起来 —— 🔴 那会**同拍静默丢一条**，
        //         ⭐ 正是 `evt_merge`/`seq_arb` 当初要修的那个 bug）
        //
        //   ⭐ **与曲谱通路【完全解耦】**（⭐ 本改动的主要收益）：
        //      · ⭐ `SCORE_UART_ENABLE = 1`（⭐ **新默认**）⇒ ⭐ 曲谱 + looper **同时可用** ✅
        //      · ⭐ `SCORE_UART_ENABLE = 0`                ⇒ ⭐ 只关曲谱，⭐ **looper 照常** ✅
        //
        //   ⭐ 控制：⭐ 串口命令 `'R'`（录/停**切换**）· `'L'`（播放**切换**）· `'C'`（清空）
        //      ⚠️ 因为 `calib_cmd` 只吐**单周期脉冲**，⭐ 这里用寄存器记住"开/关"状态
        //      （⭐ 与 `met_on_r` 同一手法）✅
        //      📌 ⭐ `'C'` **同时把两个开关复位** —— ⚠️ 否则"录着的时候清空"会让
        //         `loop_rec_on_r` **卡在 1** ⇒ 🔴 下一次 `'R'` 发的是"停"而不是"录"（⭐ 状态错位）
        // ══════════════════════════════════════════════════════════════════
        reg loop_rec_on_r;
        reg loop_play_on_r;

        //  ⭐⭐ 2026-09-29 新增：⭐ **当前音色**（⭐ 串口 `'I'` 每按一次循环下一档 ✅）
        //   ⭐ 音色定义（⭐ `rtl/w3b/wavetable_bank.v:3` 原文（行号可能漂移，以符号为准））：
        //      ⭐ `0=BASS triangle` · ⭐ `1=GUITAR saw` · ⭐ `2=PIANO zero-DC 25% pulse` · ⭐ `3=PAD`
        //   🔴 **为什么加**：⭐ 原来 `note_manager.default_timbre_i` **写死 `2'd0`**
        //      ⇒ ⭐ **手弹永远只有 0 号（BASS 三角波）** ⇒ 🔴 **"4 个音色可以切换"这个需求没满足** ✅
        //      📌 ⭐ 而音色字段本来只有【曲谱帧 `[8:7]`】一个来源，⚠️ 而 `SCORE_UART_ENABLE = 0`
        //         ⇒ ⭐ **那条路是禁用的** ⇒ ⭐ 音色**根本无法切换** ✅
        //   ✅ **修法**：⭐ 用一个 2 位寄存器记住当前音色，⭐ `'I'` 每来一次就 `+1`
        //      ⇒ ⭐ **2 位自然回绕** ⇒ ⭐ `0→1→2→3→0` ✅（⭐ 与 `'R'`/`'L'` 同属"切换"语义 ✅）
        //   📌 ⭐ **为什么不接物理按键**：⭐ 见 `rtl/w3a/calib_cmd.v` 顶部的说明 ——
        //      ⭐ `*_req` 全是**单周期脉冲** ⇒ ⭐ 以后接按键**只需产生同样的脉冲** ✅
        //      ⇒ ⭐ **这个寄存器与来源无关**，⭐ 换来源**不用改这里** ✅
        //   📌 ⭐ **`timbre_sel_r` + S2 按键块都在【模块层】**（⭐ 见上方 `u_timbre_btn_sync`）——
        //      ⚠️ 队友的 tb 用 `dut.timbre_sel_r` 观察它 ⇒ ⭐ 必须模块层可见 ✅
        //      📌 本 generate 块**只读**它（⭐ `.default_timbre_i(timbre_sel_r)` 等 ✅）

        always @(posedge clk) begin
            if (!rst_n_sync) begin
                loop_rec_on_r  <= 1'b0;
                loop_play_on_r <= 1'b0;
            end else if (cmd_loop_clear_req && !rd_lock) begin
                loop_rec_on_r  <= 1'b0;
                loop_play_on_r <= 1'b0;
            end else begin
                if (cmd_loop_rec_req && !rd_lock)  loop_rec_on_r  <= ~loop_rec_on_r;
                if (cmd_loop_play_req && !rd_lock) loop_play_on_r <= ~loop_play_on_r;
            end
        end

        wire        looper_play_valid;
        wire [3:0]  looper_play_axis;
        wire [31:0] looper_play_inc;
        wire [7:0]  looper_play_vel;
        wire [1:0]  looper_play_kind;
        //  ⭐⭐ 2026-09-29 新增（⭐ 用户需求）：⭐ 回放携带的【录制时音色】✅
        //     ⇒ ⭐ 接到 `seq_arb.score_timbre_*`（⭐ 见下方 mux ✅）
        wire [1:0]  looper_play_timbre;
        wire        looper_play_timbre_valid;
        //  ⭐⭐ 2026-09-29 新增（⭐ 用户需求）：⭐ **回放的【插值更新】**（⭐ 端点 → 线性插值）
        //   ⭐ 语义：⭐ "该轴此刻的插值音高/力度" ⇒ ⭐ **或进** `note_manager` 的
        //      `pitch_upd_*` / `vel_upd_*`（⭐ 与手弹那两路**共用通路** ✅）
        //   🔴 修的缺陷（⭐ 用户上板报告）：⭐ *"loop 的声音比键盘小"*
        //      ＋ *"loop 回放没有 release 尾音"* —— ⭐ 根因都是
        //      **回放只带 `note_on` 那一个力度**（⭐ 而 `adsr` 的尾音长度 ∝ 力度）✅
        wire        lp_upd_valid;
        wire [3:0]  lp_upd_axis;
        wire [31:0] lp_upd_inc;
        wire [7:0]  lp_upd_vel;
        //  ⭐ 可观测（`K-106`：⛔ 不许静默失效）—— ⚠️ **暂未接上板观测口**
        //     📌 待办：⭐ 接到串口回传（⭐ 与 `'P'`/`'N'` 诊断同一套路）⇒ 现在先留线，⛔ 不悬空
        wire        looper_layer_state;
        wire [15:0] looper_evt_cnt;
        reg rd_pending_r;
        reg rd_notice_r;
        reg [15:0] rd_reject_r;
        wire rd_start_w = rd_pending_r && txf_idle &&
                          !pp_busy && !vp_busy && !np_busy && !dp_busy;
        wire rd_reject_event = (cmd_recdump_req &&
            (rd_lock || looper_layer_state || (looper_evt_cnt == 0))) ||
            (rd_lock && (cmd_loop_rec_req || cmd_loop_play_req || cmd_loop_clear_req)) ||
            (cmd_probe_req && pp_busy) || (cmd_posprobe_req && np_busy) ||
            (cmd_vstat_req && vp_busy);
        assign rd_pending = rd_pending_r;
        assign rd_notice_valid = rd_notice_r;
        assign rd_reject_count = rd_reject_r;
        always @(posedge clk) begin
            if (!rst_n_sync) begin
                rd_pending_r <= 0;
                rd_notice_r <= 0;
                rd_reject_r <= 0;
            end else begin
                if (cmd_recdump_req && !rd_lock && !looper_layer_state && (looper_evt_cnt != 0))
                    rd_pending_r <= 1;
                else if (rd_start_w)
                    rd_pending_r <= 0;
                if (rd_reject_event) begin
                    rd_notice_r <= 1;
                    if (rd_reject_r != 16'hffff) rd_reject_r <= rd_reject_r + 1'b1;
                end else if (rd_notice_push) rd_notice_r <= 0;
            end
        end
        //  ⭐⭐ 2026-10-11：⭐ **导出读口的线**（⭐ 录制回传 ✅）
        wire [63:0] looper_dump_data;    // ⭐ 线上 64 位（⭐ looper 内部已重打包 ✅）
        wire        looper_dump_clip;    // 本条相位增量转换存在量化或越界损失
        wire [15:0] looper_drop_cnt;
        wire        looper_overflow;

        looper #(
            .AXIS_W  (4),
            .PHASE_W (32),
            .VEL_W   (8),
            .KIND_W  (2),
            //  ⭐⭐ 2026-09-29 新增：⭐ 音色字段（⭐ 与 `note_manager.TIMBRE_W` 一致 ✅）
            .TIMBRE_W(2),
            .TICK_W  (20),
            .LAYERS  (1),        // ⚠️ 本版**单层**（⭐ `T40` 再扩）
            .EVT_MAX (2048),
            .CNT_W   (16)
        ) u_looper (
            .clk_i          (clk),
            .rst_n_i        (rst_n_sync),
            //  ⭐ 音乐时钟（⭐ 与 `drum_gen` **同一个源** ⇒ 天然对齐）
            .tick_i         (bg_tick),
            .tick_cnt_i     ({4'b0, bg_tick_cnt}),   // ⭐ 显式补零 ⇒ ⛔ 不留位宽警告
            .bar_start_i    (bg_bar_start),
            .transport_i    (bg_transport),
            //  ⭐ 手弹事件【旁路监听】—— ⚠️ **只读**，⛔ looper 不许驱动这条流
            .live_valid_i   (w3a_evt_valid),
            .live_axis_i    (w3a_evt_axis),
            .live_inc_i     (w3a_evt_inc),
            .live_vel_i     (w3a_evt_vel),
            .live_kind_i    (w3a_evt_kind),
            //  ⭐⭐ 2026-09-29 新增：⭐ **录制时记下"当前手弹音色"**
            //     ⇒ ⭐ 回放时用它，⛔ **不跟随**之后手弹切过的音色 ✅（⭐ 用户需求 ✅）
            .live_timbre_i  (timbre_sel_r),
            //  ⭐⭐ 2026-09-29 新增：⭐ **手弹位置式力度流**（⭐ 只读旁路监听）
            //   🔴 **为什么 looper 要"看"这条流**：⭐ 回放要复现"轻→重"的手势
            //      ⇒ ⭐ 必须知道**松手那一刻的力度** ✅
            //      ⚠️ 而 `live_vel_i`（`note_off` 事件自带）**不是它**：
            //         `w3a_evt_vel = (am_pos_in < VEL_TRIG_TH) ? VEL_DEFAULT : pos_to_vel(...)`
            //         ⭐ 而 `note_off` 是**松手**产生的 ⇒ `pos` 已落阈下
            //         ⇒ 🔴 **恒为 200**（⭐ 与"按住时有多重"无关）✅
            //   ⭐ 本端口接的就是 `note_manager.vel_upd_*` 的**同一个源** ✅
            //      ⇒ ⭐ 录到的端点与"手弹当时真正用的力度"**逐值一致** ✅
            .live_vel_valid_i (vu_valid_r),
            .live_vel_axis_i  (vu_axis_r),
            .live_vel_value_i (vu_val_r),
            //  ⭐ 重放（⭐ → `evt_merge` 的**源 C**，⭐ 见下方 `u_evt_merge` 的 `.c_*`）
            //  ⭐⭐ 2026-09-30：⭐ **不再接 `seq_arb.score`**（⭐ 那条口还给曲谱 UART）✅
            .play_valid_o   (looper_play_valid),
            .play_axis_o    (looper_play_axis),
            .play_inc_o     (looper_play_inc),
            .play_vel_o     (looper_play_vel),
            .play_kind_o    (looper_play_kind),
            .play_timbre_o  (looper_play_timbre),
            .play_timbre_valid_o(looper_play_timbre_valid),
            //  ⭐⭐ 2026-09-29 新增：⭐ **回放插值更新**（⭐ → 下方 `note_manager` 的参数通路）
            .play_upd_valid_o(lp_upd_valid),
            .play_upd_axis_o (lp_upd_axis),
            .play_upd_inc_o  (lp_upd_inc),
            .play_upd_vel_o  (lp_upd_vel),
            //  ⭐ 控制（⭐ 脉冲 / 电平）
            .rec_req_i      (cmd_loop_rec_req & ~loop_rec_on_r & ~rd_lock),
            .stop_req_i     (cmd_loop_rec_req &  loop_rec_on_r & ~rd_lock),
            .play_en_i      (loop_play_on_r),
            .clear_req_i    (cmd_loop_clear_req & ~rd_lock),
            //  ⭐ 可观测
            .layer_state_o  (looper_layer_state),
            .evt_cnt_flat_o (looper_evt_cnt),
            .full_o         (looper_full),
            .drop_cnt_o     (looper_drop_cnt),
            .overflow_o     (looper_overflow),
            //  ⭐⭐⭐⭐ 2026-10-11：⭐ **录制回传（导出读口）** —— ⭐ 由 `u_rec_dump` 驱动 ✅
            //     📌 ⭐ 接线口径：⭐ `'Y'` 命令 ⇒ ⭐ 导出 FSM ⇒ ⭐ 逐字节推 `u_tx_fifo`
            //        ⇒ ⭐ `u_uart_tx_esp` ⇒ ⭐ ESP32 ⇒ BLE ⇒ PC ✅
            //     ⚠️ ⭐ **导出期间读口归导出** ⇒ ⭐ 由 `idle_i` 保证只在层空闲时导 ✅
            .dump_en_i      (rd_dump_en),
            .dump_addr_i    (rd_dump_addr),
            .dump_data_o    (looper_dump_data),
            .dump_clip_o    (looper_dump_clip)
        );

        //  ═══════════════════════════════════════════════════════════════════
        //  ⭐⭐⭐⭐ 2026-10-11：⭐ **录制回传的导出 FSM**（⭐ 用户需求 ✅）
        //
        //  ⭐ **干什么**：⭐ `'Y'` 命令 ⇒ ⭐ 把该层**已录下的事件**按 **9 字节帧**
        //     （⭐ `0xA5` ＋ 8 字节大端 ✅）逐条推给 `u_tx_fifo`
        //     ⇒ ⭐ `u_uart_tx`（板载口）＋ ⭐ `u_uart_tx_esp`（ESP32 口）
        //     ⇒ ⭐ ESP32 ⇒ BLE ⇒ PC ✅
        //     📌 ⭐ **两个口同时发**（⭐ 镜像 ✅）⇒ ⭐ 板载口接 USB-TTL 也能抓 ✅
        //
        //  🔴🔴 **三条硬约束（⭐ 都在 `rec_dump.v` 与 `looper.v` 里写明）**：
        //     ① ⭐ **只在层空闲时导**（`idle_i = ~layer_state`）——
        //        ⚠️ 因为导出要**占用 `mem` 的读口**，⭐ 而放音也要用 ✅
        //        （⭐ BSRAM 只有 1 读口 ⇒ ⭐ 加第二个读口会**推不出 BSRAM** ✅）
        //     ② ⭐ **读是同步的** ⇒ ⭐ 给地址后等 **2 拍**（⭐ 由 FSM 的 `S_WAIT` 保证 ✅）
        //     ③ 同边沿 ready 节流；顶层导出独占双 UART，不进入正常回复 FIFO。
        //
        //  ⭐ **帧格式与收帧【同构】** ⇒ ⭐ **导出的东西能直接回灌** ✅
        //     ⇒ ⭐ "**录一段 → 回传 → 存成谱子 → 再灌回去**" 这条闭环成立 ✅
        //
        // 2026-10-13 更正：clip_cnt_o 统计量纲转换的量化/越界损失，
        // 并在本次导出 footer 回传；不能把低 21 位截取当成正确音高转换。
        //  ═══════════════════════════════════════════════════════════════════
        //  ⚠️ **这 8 根线声明在【模块层】**（⭐ 见 `cmd_recdump_req` 那里 ✅）——
        //     🔴 **实测踩坑**：⭐ 第一版把它们声明在**本 generate 块里**
        //        ⇒ ⚠️ `tx_req` 那个块（`top.v:2886`）**绑不上** `rd_push`
        //        （⭐ `Unable to bind wire/reg/memory rd_push` ✅）
        //        ⇒ ⭐ 说明两个块**不在同一个 generate 作用域** ✅
        //     📌 ⭐ 处置与 `cmd_gear_next_req` **同一口径**：⭐ **模块层声明，
        //        在 generate 里可读可写** ✅
        rec_dump #(
            .ADDR_W (16),
            .HDR    (8'hA5),
            .STATUS_ENABLE(1)
        ) u_rec_dump (
            .clk_i       (clk),
            .rst_n_i     (rst_n_sync),
            .req_i       (rd_start_w),
            //  ⭐ **层空闲**（⭐ `layer_state_o` 的 0 = 空闲 ✅）——
            // rd_lock additionally blocks R/L/C for the entire transaction.
            .idle_i      (~looper_layer_state && txf_idle),
            .cnt_i       (looper_evt_cnt),         // ⭐ 已录事件数 ✅
            .data_i      (looper_dump_data),       // ⭐ 线上 64 位（⭐ looper 已重打包 ✅）
            .clip_i      (looper_dump_clip),       // ⭐ 本条被截断过 ✅
            .reject_count_i(rd_reject_count),
            .ready_i     (~txf_busy && rd_busy),
            .push_o      (rd_push),
            .byte_o      (rd_byte),
            .dump_en_o   (rd_dump_en),
            .dump_addr_o (rd_dump_addr),
            .busy_o      (rd_busy),
            .done_o      (rd_done),
            .clip_cnt_o  (rd_clip_cnt),
            .frame_cnt_o (rd_frame_cnt)
        );

        //   ⭐⭐ 2026-10-03：⭐ **looper 状态码 → 指示层**（⭐ 用户语义：空闲 / 录音 / 回放）
        //     ⭐ 用 `top.v` 已有的两个开关寄存器（⭐ 它们才是"录/放"的真相）：
        //        `loop_rec_on_r`  = 1 ⇒ 录音中 ⇒ ⭐ 码 1（⭐ 红色快闪）
        //        `loop_play_on_r` = 1 ⇒ 回放中 ⇒ ⭐ 码 2（⭐ 绿色常亮）
        //        ⛔ 两者都 0         ⇒ 空闲   ⇒ ⭐ 码 0（⭐ 暗蓝常亮）
        //     ⚠️ 为什么⛔ 不用 `looper.layer_state_o`：⭐ 它只有 **1 位**
        //        （`0 = 空闲 · 1 = 录/放`）⇒ 🔴 **分不出"在录"还是"在放"**
        //        ⇒ ⭐ 满足不了用户要的**三态** ✅
        //     ⚠️ 优先级：⭐ **录音优先**（⭐ `looper` 自己也是"录的时候不放"）
        assign led_looper_st = loop_rec_on_r  ? 2'd1 :
                               loop_play_on_r ? 2'd2 : 2'd0;

        seq_arb #(
            .AXIS_W  (4),
            .PHASE_W (32),
            .VEL_W   (8),
            .KIND_W  (2),
            .DEPTH   (6)          // ⭐ 深度 6：3 源各 ≤1 条/拍，留足余量
        ) u_seq_arb (
            .clk_i            (clk),
            .rst_n_i          (rst_n_sync),
            // ── 源 1：手弹（⭐ W3a 采集链）—— ⭐ 最高优先 ──────────────────
            .live_valid_i     (w3a_evt_valid),
            .live_axis_i      (w3a_evt_axis),
            .live_phase_inc_i (w3a_evt_inc),
            .live_velocity_i  (w3a_evt_vel),
            .live_kind_i      (w3a_evt_kind),
            .live_timbre_valid_i(1'b0),
            .live_timbre_i    (2'd0),
            // ── 源 2：曲谱（⭐ `evt_uart_rx`）────────────────────────────────
            //   🔴🔴 **2026-09-28：⭐ 默认【禁用】—— 这是一条【已证明】的伪事件注入路径**
            //
            //   ⭐ 证据（仿真 `tb/w3c/tb_evt_uart_rx_screen.sv`，⛔ 不是推测）：
            //      · `top.v` 把**同一个 UART 字节流**（`ur_done`/`ur_data`）分给三路：
            //          `uart_ui`（串口屏）· `calib_cmd`（命令）· `evt_uart_rx`（曲谱事件）
            //      · `evt_uart_rx` 的帧头是 **`0xA5`**（9 字节定长），
            //        靠**字节计数 + 空闲间隔**维持同步
            //      · 🔴 而**其它两路的合法载荷里都可能出现 `0xA5`**
            //        （⭐ 串口屏 `0x71` 数值帧的 4 个数据字节、⭐ 命令流里的任意字节）
            //      · ⭐ 实测：喂 **8 个屏幕数值帧**（数据含 `0xA5`）⇒
            //        🔴 **产生了 8 条伪事件**，其中
            //           `axis = 15`（⭐ **保留轴**）· `inc = 0x1FFFFF` · `kind = 0`（note_on）
            //
            //   🔴 **为什么这是"挂音"的直接原因**（⭐ 2026-10-01 更正：⭐ 旧注释的两处依据
            //      都已被代码推翻 —— ⛔ 不是"axis 14/15 保留轴"、⛔ 也不是"键盘只有 0~13"）：
            //      ⭐ 伪事件带 **`score` 源**；⭐ 而 `note_off` 按 **`(axis, src)` 双条件**匹配
            //      （⭐ `note_manager.v` 里按 `(axis, src)` 清 voice 的循环）⇒ ⭐ 手弹（`live`）的 `note_off`
            //      **清不掉**它 ⇒ ⭐ **那个 voice 的 `gate_r` 永久为 1，⛔ 任何按键都清不掉** ✅
            //      📌 **键盘实际是 16 轴 0~15**（⭐ `u_axis_map` 例化的 `.N_KEY(16)`）；
            //         ⭐ 进保留池按**来源**、⛔ 不按轴号 ⇒ ⭐ 与"轴 14/15"无关
            //      📌 与用户实测完全吻合：「按同键不能清」「按所有键也不能清」
            //         「持续几分钟」「断电才清」「~50% 概率」「按一阵后累积」
            //
            //   ⭐ **修法（最小变量）**：⭐ 把曲谱通路做成**编译期开关，默认 0**
            //      · ⛔ 不动 `evt_uart_rx` 本身（它的 9 字节协议是对的）
            //      · ⛔ 不动 `uart_ui` / `calib_cmd`（队友/命令通路）
            //      · ⭐ 要恢复曲谱功能时：把本参数置 1 **且** 把曲谱源换到**独立 UART 线**
            //        （⚠️ 与串口屏共用一条线时，⛔ 任何"帧头猜同步"都会互相误判）
            //  ⭐⭐ 2026-09-30：⭐ **本口现在【只归曲谱 UART】**
            //     🔴 **改之前**：⭐ 这里是个"`SCORE_UART_ENABLE` 二选一"的 mux
            //        （⭐ `1` ⇒ 曲谱、⭐ `0` ⇒ looper）⇒ 🔴 **两者不能并存** ✅
            //     ✅ **改之后**：⭐ looper 搬到 `evt_merge` 的源 C（⭐ 见上方 §事件域 Looper）
            //        ⇒ ⭐ 本口**只剩曲谱一个来源** ⇒ ⭐ mux **整个删掉** ✅
            //     ⭐ `SCORE_UART_ENABLE = 0` 时接**常量 0**（⭐ 即"这条通路关闭"，
            //        ⚠️ 与 2026-09-28 那版"禁用曲谱"的语义**逐位一致**）✅
            //  ⭐⭐ 2026-10-11（`U-19`）：⭐ **源 = `play_seq` 的输出**（⛔ 不再是裸 `eu_evt_*`）✅
            //     🔴 改前直连 `evt_uart_rx` ⇒ ⚠️ `tick` 被忽略 ⇒ **事件一到就响** ✅
            .score_valid_i    (SCORE_UART_ENABLE ? ps_note_valid : 1'b0),
            .score_axis_i     (SCORE_UART_ENABLE ? ps_evt_axis : 4'd0),
            .score_phase_inc_i(SCORE_UART_ENABLE ? ps_evt_inc  : 32'd0),
            .score_velocity_i (SCORE_UART_ENABLE ? ps_evt_vel  : 8'd0),
            .score_kind_i     (SCORE_UART_ENABLE ? ps_evt_kind : 2'd0),
            //  ⭐⭐ 2026-09-29 新增（⭐ 用户需求）：⭐ **音色 sideband**
            //   ✅ 现在：⭐ 曲谱帧 `[8:7]` 的音色**照常**随事件走（⭐ 它本来就是这个用途）✅
            //   📌 looper 的音色**不再经过本口** —— ⭐ 它随源 C 走
            //      （⭐ `evt_merge.c_timbre_i` ⇒ `note_manager.evt_timbre_i`）✅
            .score_timbre_valid_i(SCORE_UART_ENABLE ? ps_evt_timbre_valid : 1'b0),
            .score_timbre_i   (SCORE_UART_ENABLE ? ps_evt_timbre : 2'd0),
            // ── 源 3：演示（⭐ 自检和弦）—— ⚠️ 自动让位 ───────────────────
            .demo_valid_i     (demo_note_valid),
            .demo_axis_i      (demo_note_axis),
            .demo_phase_inc_i (demo_note_inc),
            .demo_velocity_i  (demo_note_vel),
            .demo_kind_i      (demo_note_kind),
            .demo_timbre_valid_i(1'b0),
            .demo_timbre_i    (2'd0),
            // ── 仲裁出口 → `evt_merge` 源 A ────────────────────────────────
            .evt_valid_o      (sa_valid),
            .evt_axis_o       (sa_axis),
            .evt_phase_inc_o  (sa_inc),
            .evt_velocity_o   (sa_vel),
            .evt_kind_o       (sa_kind),
            .evt_timbre_valid_o(sa_timbre_valid),
            .evt_timbre_o     (sa_timbre),
            // ⭐⭐ A1：⭐ 来源标记（⭐ 与 `evt_valid_o` 同时序）⇒ ⭐ 下游按源区分 `note_off`
            .evt_src_o        (sa_src),
            // ── ⭐ 可观测性（`K-106`：⛔ 不许静默失效）──────────────────────
            .collision_cnt_o  (sa_collision_cnt),
            .merged_cnt_o     (sa_merged_cnt),
            .drop_cnt_o       (sa_drop_cnt),
            .overflow_o       (sa_overflow),
            .live_cnt_o       (sa_live_cnt),
            .score_cnt_o      (sa_score_cnt),
            .demo_cnt_o       (sa_demo_cnt)
        );

        // ⭐⭐ 旧 `SOURCE_A_SEL = 1` 的**强制档**（⭐ 保 `T57` 的 `tb_top_sound`）
        //   ⚠️ 它**绕过** `seq_arb`（⭐ 直接拿演示和弦）⇒ ⭐ 行为与改动前【完全一致】。
        wire        src_a_valid = (SOURCE_A_SEL == 1) ? demo_note_valid : sa_valid;
        wire [3:0]  src_a_axis  = (SOURCE_A_SEL == 1) ? demo_note_axis  : sa_axis;
        // ⭐⭐ 2026-10-01：⭐ **键盘打鼓模式**（⭐ `key_drum_r`，⭐ 串口 `'K'` 切换）
        //   ⭐ **布局依据**：⭐ `files/10-硬件/鼓垫.drawio.svg`（⭐ 用户提供的鼓垫图）
        //      ⭐ 16 键 = **2 板 × 8 通道**，⭐ 每板 2 行 × 4 列 ⇒ ⭐ **4 件乐器各占一个 2×2 块** ✅
        //      ⭐ 轴号 = 片号×8 + 通道（⭐ 见 `axis_map.v` 的 `axis_id_i` 端口注释）⇒ ⭐ **板1 = 轴 0-7 · 板2 = 轴 8-15** ✅
        //      ⭐ 图上 CH 排布：⭐ **左两列 = CH4~CH7 · 右两列 = CH0~CH3** ✅
        //   ⇒ ⭐ **映射恰好是 `axis[3:2]` 两位切片**（⭐ 零逻辑 ✅）：
        //      | ⭐ `axis[3:2]` | ⭐ 轴号 | ⭐ 位置 | ⭐ 乐器 | ⭐ `phase_inc` |
        //      |---|---|---|---|---|
        //      | `2'd0` | 0~3   | 板1 右两列 | ⭐ **嗵鼓** | `12_884_902`（≈150 Hz）|
        //      | `2'd1` | 4~7   | 板1 左两列 | ⭐ **底鼓** | `6_442_451`（≈75 Hz）|
        //      | `2'd2` | 8~11  | 板2 右两列 | ⭐ **军鼓** | `17_179_869`（≈200 Hz）|
        //      | `2'd3` | 12~15 | 板2 左两列 | ⭐ **踩镲** | `171_798_691`（≈2000 Hz）|
        //   📌 **分配理由（⭐ 用户要求"按【使用频率】均衡"）**：⭐ 使用频率排名
        //      = 踩镲 > 军鼓 > 底鼓 > 嗵鼓 ⇒ ⭐ 右手（板2）拿第 **1、3**；⭐ 左手（板1）拿第 **2、4**
        //      ⇒ ⭐ **每只手都有一件高频使用 + 一件低频使用** ✅
        //   ⚠️🔴 **这 4 个常量必须与 `rtl/w3c/drum_gen.v` 的 `INC_*` 逐字一致** ——
        //      ⭐ 因为"**是不是鼓、是哪件鼓**"是靠 **`phase_inc` 的频率范围**判的
        //      （⭐ `oscillator_bank.v` 用 `base_inc` 就地分档：`<10M` 底鼓 · `10M~15M` 嗵鼓 · `≥15M` 军鼓/踩镲）
        //      ⇒ 🔴 **抄错一个数就静默变成另一件乐器** ⚠️
        //      ⇒ ⭐ **判据**：⭐ `tb/w3c/tb_key_drum.sv` 直接拿 `drum_gen` 的**实际输出**逐件比对 ✅
        //   📌 **本处是【有意重复】的常量** —— ⚠️ 单一来源修法（⭐ 把 `INC_*` 提成形参）留待后续；
        //      ⭐ 本轮用"**能红的判据**"守住一致性（⭐ 比静默重复安全）✅
        //   ⭐ **新值（⭐ 2026-10-01 拉开，⭐ 相邻音程 14.3 / 19 / 32 个半音）**：
        //      ⚠️🔴 **必须与 `rtl/w3c/drum_gen.v` 的 `INC_*` 逐字一致**（⭐ 否则鼓机与键盘鼓不同音）
        //      ⭐ 判据：⭐ `tb_key_drum.sv` 直接拿 `u_drum_gen.INC_*` 当**单一来源**比对 ✅
        wire [1:0]  key_drum_sel = src_a_axis[3:2];
        //   ⭐⭐ **2026-10-01 二次拉开**（⭐ 用户："通鼓和底鼓感觉还差一点点区分度"）：
        //      ⭐ 底鼓 70 ⇒ **60 Hz** · ⭐ 嗵鼓 160 ⇒ **200 Hz** ⇒ ⭐ 比 **3.33×**（⭐ 原 2.29×）
        //      ⚠️ **嗵鼓 200 Hz 的前提**：⭐ 见下方 `u_oscillator_bank` 的
        //         `.DRUM_TOM_MAX(20_000_000)` 覆盖（⭐ 否则 17.9M 会被判成"军鼓/踩镲"档）✅
        wire [31:0] key_drum_inc = (key_drum_sel == 2'd0) ? 32'd17_895_697    // ⭐ 嗵鼓 ≈200 Hz
                                 : (key_drum_sel == 2'd1) ? 32'd5_368_709     // ⭐ 底鼓 ≈60 Hz
                                 : (key_drum_sel == 2'd2) ? 32'd42_949_673    // ⭐ 军鼓 ≈480 Hz
                                 :                          32'd171_798_691;  // ⭐ 踩镲 ≈1920 Hz
        //   ⭐⭐ 2026-10-01：⭐ **每件乐器的【基础力度】**（⭐ 用户裁定："各自基础力度 ＋ 键盘只往上加"）
        //      🔴 **为什么需要**（⭐ 用户上板："声音也有点小"）：
        //         ⭐ 原来直接拿**键盘力度**当鼓的力度 ⇒ ⚠️ 轻敲就轻
        //         ⭐ 而**鼓机**每件有固定力度（⭐ `drum_gen.v` 的 `VEL_*`）⇒ ⭐ 所以鼓机听着更"实" ✅
        //      ⭐ **策略**：⭐ `vel = max(键盘力度, 本件基础力度)` ——
        //         ⇒ ⭐ ① 轻敲也够响 ② ⭐ 重敲能到 255 ③ ⭐ **力度跟随保留** ✅
        //      📌 取值依据：⭐ 参照鼓机的 `VEL_*`（⭐ 底鼓 230 / 军鼓 200 / 嗵鼓 190 / 踩镲 140）
        //         ⚠️ 其中**踩镲 140 明显偏轻** ⇒ ⭐ 抬到 **175** ✅（⭐ 用户："背景要更响" ✅）
        wire [7:0]  key_drum_base_vel = (key_drum_sel == 2'd0) ? 8'd200    // ⭐ 嗵鼓
                                      : (key_drum_sel == 2'd1) ? 8'd230    // ⭐ 底鼓（⭐ 最重）
                                      : (key_drum_sel == 2'd2) ? 8'd210    // ⭐ 军鼓
                                      :                          8'd175;   // ⭐ 踩镲（⭐ 原 140 ⇒ 抬高）

        wire [31:0] src_a_inc   = key_drum_r ? key_drum_inc
                                             : ((SOURCE_A_SEL == 1) ? demo_note_inc : sa_inc);
        //  ⭐⭐ 2026-10-01：⭐ **打鼓模式下的力度下限**（⭐ 见上方 `key_drum_base_vel` 的说明）
        //     ⭐ `max(键盘力度, 本件基础力度)` —— ⭐ 保留力度跟随，⭐ 但轻敲也够响 ✅
        wire [7:0]  src_a_vel_raw = (SOURCE_A_SEL == 1) ? demo_note_vel : sa_vel;
        wire [7:0]  src_a_vel   = (key_drum_r && (src_a_vel_raw < key_drum_base_vel))
                                ? key_drum_base_vel : src_a_vel_raw;
        wire [1:0]  src_a_kind  = (SOURCE_A_SEL == 1) ? demo_note_kind  : sa_kind;
        //  ⭐⭐ 2026-10-01：⭐ 打鼓模式下用**固定的** `DRUM_TIMBRE`（⭐ 与源 B 同一手法）
        //     ⇒ ⭐ 鼓的音色与"键盘当前音色"**彻底解耦** ✅（⭐ 判据见 `tb_key_drum.sv`）
        wire        src_a_timbre_valid = key_drum_r ? 1'b1
                                       : ((SOURCE_A_SEL == 1) ? 1'b0 : sa_timbre_valid);
        wire [1:0]  src_a_timbre = key_drum_r ? DRUM_TIMBRE
                                 : ((SOURCE_A_SEL == 1) ? 2'd0 : sa_timbre);
        //  ⭐⭐ 2026-09-29（A1）：⭐ **源 A 的来源标记**
        //     ⚠️ 必须**跟着上面那个 mux 一起选** —— `SOURCE_A_SEL == 1` 时源 A 是
        //        **演示和弦**（⭐ 它绕过 `seq_arb`）⇒ ⭐ 标记必须是 `SRC_DEMO = 3'd2`，
        //        ⛔ 不能沿用 `sa_src`（⭐ 那一路此刻并没有在发事件 ⇒ 值是陈旧的）。
        //  ⭐⭐ 2026-09-30：⭐ **位宽 2 → 3**（⭐ 与 `evt_merge.a_src_i` 一致）✅
        //  ⭐⭐ 2026-10-01：⭐ **打鼓模式下把来源标成 `SRC_AUX(3)`** ——
        //     ⭐ 这一条是**整个功能的关键**：⭐ `note_manager` 靠 `cur_src == SRC_AUX`
        //        决定"**进保留池** + **走 perc 包络**"（⭐ 见 `top.v` 的 `env_level_mix` 与
        //        `perc_trig`）⇒ ⭐ 标上它就**自动变成鼓**，⛔ 不用改 `note_manager` 一行 ✅
        //     ⚠️ **代价（⭐ 已评估）**：⭐ 鼓垫与"源 B（节拍器/鼓机）"**共用保留池**
        //        （⭐ `RESERVED_N = 5`）⇒ ⚠️ 两者同时响时抢 5 个 voice；
        //        ⭐ 且**手敲 + 鼓机同时**最多 5 音（⭐ 超了按池内分配策略丢）
        //        📌 缓解：⭐ 手敲鼓时用 `'B'` 关掉源 B ✅
        //
        //  ⭐⭐⭐⭐ 2026-10-11（`P1-59`）：⭐ **改标 `SRC_KDRUM(3'd5)`** —— ⭐ **⛔ 不再与源 B 共用** ✅
        //
        //  🔴🔴 **为什么必须改**（⭐ 审查 `[P1-59]`，⭐ 而上面那段注释**漏了这条**）：
        //     ⭐ 上面只承认了"**共用保留池**"（⭐ 资源争用 ✅），
        //     🔴 **没有承认"共用【标签】⇒ `(轴, 源)` 隔离失效"** —— ⭐ 那是**另一个、更严重的后果** ✅
        //     ⭐ `note_manager` 的 `same_hit[sg] = (... ) && (axis_r[sg] == cur_axis)
        //        && (src_r[sg] == cur_src)` ⇒ ⭐ **同轴 + 同源 ⇒ 判成"同一个键还在响"** ✅
        //     🔴 而 `metronome.AXIS_ID = 14` · ⭐ `drum_gen.AXIS_ID = 15`
        //        ⇒ ⭐ 打鼓模式下**轴 14/15 是真实键**（⭐ 踩镲）
        //        ⇒ 🔴 **节拍器/鼓机每来一拍，就把用户在轴 14/15 那个 voice 改判/重触发** ✅
        //        📌 ⭐ 而 `SEL_DRUM = 1`（**鼓机**）是**交付默认档** ✅
        //     ⇒ ⭐ 症状：⭐ **打鼓模式下每来一拍，轴 14/15 的音被抢走/打断** ✅
        //     ✅ **改标 5 之后**：⭐ `cur_src` 不同 ⇒ ⭐ `same_hit` 不命中
        //        ⇒ ⭐ **各占各的 voice、互不打断** ✅
        //        📌 ⭐ 而"**进保留池 + 走 perc 包络**"**照旧**（⭐ `note_manager` 已把
        //           `SRC_KDRUM` 加进同一判据 ⇒ ⭐ 两处**同源派生**、⛔ 不会不一致 ✅）
        //     📌 ⭐ **代价**：⭐ 源标记是 3 位、⭐ `0~4` 已用 ⇒ ⭐ **`5` 空闲** ⇒ ⭐ 零位宽代价 ✅
        //     ⚠️ ⭐ **保留池仍共用**（⭐ `RESERVED_N = 5`）—— ⭐ 那一条**本条⛔ 不解决** ✅
        //        （⭐ 它只是**资源争用**，⭐ 而"抢音"那条**已解决** ✅）
        wire [2:0]  src_a_src = key_drum_r ? 3'd5
                              : ((SOURCE_A_SEL == 1) ? 3'd2 : sa_src);

        // ⭐⭐ 源 B 二选一（⭐ 节拍器 / 鼓机，⭐ `SEL_DRUM`，⭐ 默认节拍器）
        //   📌 用 `generate`+`localparam` 做**编译期选择** ⇒ ⚠️ 综合会把没选中的那路
        //      **优化掉**（⭐ 省资源）；⭐ 但两路都**例化** ⇒ ⭐ 将来改运行时只需换选择信号。
        wire        sel_drum = (SEL_DRUM == 1);
        //   🔴🔴 **2026-09-26：⭐ `METRONOME_ON=0` ⇒ 静音节拍器**
        //      ⭐ 手法：⭐ **与进 `valid`**（⭐ 数据线保持连接，⛔ 不用改别的）
        //      ⇒ ⭐ 节拍器/鼓机**照常运行**（⭐ 内部状态、`beat_gen`、心跳 LED 全不变）
        //        ⭐ 但**事件被挡在 `evt_merge` 之外** ⇒ 🔇 **确实不出声** ✅
        //      📌 `&` 对**多位线**是逐位与 ⇒ ⚠️ 但这里两端都是 **1 位** ⇒ ✅ 就是逻辑与
        //   ⚠️ **⚠️ 注意**：⭐ 本参数**同时管住鼓机**（⭐ 因为源 B 是二选一）
        //      ⇒ ⭐ `METRONOME_ON=0` 时**鼓机也不出声** —— ⭐ 语义上叫"源 B 静音"更准，
        //        ⭐ 但用户要的是"只听键盘"⇒ ⭐ 这正是想要的（⭐ 名字按用户的说法取）。
        //
        //   ⭐⭐ **2026-09-28：再串一级【运行时开关 `met_on_r`】**（⭐ `S2`/`AB13`）
        //      ⇒ ⭐ **两级串联**：
        //         · `METRONOME_ON`（⭐ 编译期总闸，⭐ 现为 1）
        //         · `met_on_r`（⭐ 运行时，⭐ 按一下开 / 再按一下关，⭐ 复位 = 关）
        //      📌 **为什么不在 `metronome` 内部拦**：⭐ 那里拦会停掉
        //         `beat_cnt_o`/`accent_cnt_o`（⭐ 上板诊断要用）；⭐ 且源 B 是二选一，
        //         在合流处拦**一处就够**（⭐ 鼓机也一并受控，⭐ 语义一致）。
        //      ⚠️ **`met_on_r` 是寄存器**（⭐ 复位由 `rst_n_sync` 保证）
        //         ⇒ ⛔ 不会像 `Z` 那样传播 `x`（⭐ 见上方 `met_btn_s` 的 Z-safe 处理）。
        wire        src_b_valid = (sel_drum ? drm_evt_valid : met_evt_valid)
                                  & (METRONOME_ON != 0)
                                  & met_on_r;
        wire [3:0]  src_b_axis  = sel_drum ? drm_evt_axis  : met_evt_axis;
        wire [31:0] src_b_inc   = sel_drum ? drm_evt_inc   : met_evt_inc;
        wire [7:0]  src_b_vel   = sel_drum ? drm_evt_vel   : met_evt_vel;
        wire [1:0]  src_b_kind  = sel_drum ? drm_evt_kind  : met_evt_kind;
        //   ⭐⭐ **2026-09-29：⭐ 源 B 用【自己的固定音色】`DRUM_TIMBRE`** ✅
        //      🔴 **改之前**：⭐ 这里恒 `1'b0` ⇒ ⭐ `note_manager` 走兜底
        //         `default_timbre_i`（⭐ = `timbre_sel_r` = **键盘当前音色**）
        //         ⇒ 🔴 **换键盘音色 ⇒ 鼓的音色跟着变**（⭐ 用户上板实测的 bug）
        //      ⭐ **改之后**：⭐ `valid = 1` + ⭐ 固定值 ⇒ ⭐ 鼓**永远用 `DRUM_TIMBRE`**
        //         ⇒ ⭐ 与键盘**彻底解耦**（⭐ 判据见 `tb_top_drum_timbre.sv`）。
        //      📌 **为什么是"喂 valid + 固定值"而⛔ 不是"在 `note_manager` 里判轴号"**：
        //         ⚠️ 那样要改**队友的 `note_manager`**（⭐ 而它是**冻结的事件格式消费者**）
        //         ⇒ ⭐ 本做法**只动 `top.v` 的接线** ⇒ ⭐ 零接口风险 ✅
        //         （⭐ 且 `evt_merge` 本来就为"每源带自己的音色"预留了这条 sideband ✅）
        wire        src_b_timbre_valid = 1'b1;
        wire [1:0]  src_b_timbre = DRUM_TIMBRE;

        // ⭐⭐ T36 / U-6：事件合流（手弹/曲谱 + 节拍器 → note_manager 的**唯一**事件口）
        //   🔴 **为什么必须加它**：`note_manager` 只有一个事件口，
        //      而原来两路是**直接或在一起**的 ⇒ ⚠️ **同拍相撞会静默丢一条**
        //      （`note_valid_i` 只响一拍）。⭐ 本模块保证**两路同拍不丢**。
        //   ⚠️ **代价（已评估）**：同拍时后发那条**晚 1 拍 = 20 ns**，
        //      ⭐ **远小于一个音频帧 20.48 µs** ⇒ 听感不可分辨。
        //   ⭐ 可观测：`mg_collision_cnt` / `mg_merged_cnt` / `mg_drop_cnt` / `mg_overflow`
        //      （`K-106` 纪律：⛔ 容量有限的路径不许静默失效）
        wire        mg_evt_valid;
        wire [3:0]  mg_evt_axis;
        wire [31:0] mg_evt_inc;
        wire [7:0]  mg_evt_vel;
        wire [1:0]  mg_evt_kind;
        wire        mg_evt_timbre_valid;
        wire [1:0]  mg_evt_timbre;
        //  ⭐⭐ A1：⭐ 合流后事件的**来源标记**（⭐ → `note_manager.note_src_i`）
        //  ⭐⭐ 2026-09-30：⭐ **位宽 2 → 3**（⭐ 5 个源：0/1/2/3/4）✅
        wire [2:0]  mg_evt_src;
        wire [15:0] mg_collision_cnt;
        wire [15:0] mg_merged_cnt;
        wire [15:0] mg_drop_cnt;
        wire        mg_overflow;
//  ⭐⭐ 2026-10-09（P0-29）：⭐ **"丢事件/溢出"汇合**（⭐ 6 个源，⭐ 全部在此处之前已声明）✅
//   📌 ⭐ 六个源：⭐ `ee_ovf`（event_extract，L3177）· ⭐ `sa_overflow`（seq_arb，L3614）
//      · ⭐ `looper_overflow`（looper，L3738）· ⭐ `mg_overflow`（evt_merge，L4055）
//      · ⭐ `txf_ovf`（uart_tx_fifo，L1124）· ⭐⭐ **`eb_ovf`（`U-19` 曲谱缓冲，2026-10-11 新增）** ✅
//   📌 ⭐ 这一位现在驱动 `fault_any_w` ⇒ ⭐ **心跳灯快闪** ✅
//      ⇒ ⭐ 上板时"**刚才是不是丢了事件**"**终于可判定** ✅
//   ⭐⭐ 2026-10-11：⭐ **新增 `eb_ovf`** —— ⭐ 曲谱缓冲只有 **1024 条**（8 KB）
//      ⇒ ⚠️ 若 PC 灌太快（⭐ 或"全曲一次性灌"）⇒ 🔴 **必然写满丢事件** ✅
//      ⇒ ⭐ 现在**必须能看见**（⭐ `K-106`：⛔ 不许静默丢 ✅）
//      📌 ⭐ 这也是"**必须滚动预灌**"的可观测证据：⭐ 全曲 92.6 KB ≫ 8 KB ✅
//   ⭐⭐ `| eb_drop`（⭐ 那个**饱和计数**）**也** OR 进来 —— ⚠️ 它在逻辑上**与 `eb_ovf` 等价**
//      （⭐ `ovf_clr_i` 在 `top.v` 里接 0 ⇒ ⭐ 两者同时置位、同时清零 ✅）
//      📌 ⭐ 那为什么还要 OR：⭐ **纯粹为了给它一个消费者** ——
//         🔴 否则综合会把"计数锥"整条剪掉（⭐ 这正是 `P0-29` 的教训：
//            ⭐ **K-106 的观测线没有消费者 ⇒ 在交付位流里根本不存在** ✅）
//      ⚠️ ⭐ 代价：⭐ 一个 16 位归约 OR ≈ 4 LUT（⭐ 换来"上板能看到**丢了几条**"✅）
//   ⚠️ **诚实标注**：⭐ `eb_cnt`（深度）/ `eb_low`（低水位）在 `top.v` 里**暂无消费者**
//      ⇒ ⭐ 它们**会被综合剪掉**（⭐ 可接受：⭐ 今天没有任何逻辑依赖它们；
//      ⭐ 将来做**反向流控**时接上消费者即可自动复活 ✅）
assign ovf_any = ee_ovf | (|ee_lost) | sa_overflow | looper_overflow | mg_overflow
               | txf_ovf | eb_ovf | (|eb_drop);

        //  ⭐⭐ 2026-09-30：⭐ **深度 4 → 6** —— ⭐ 因为**源从 2 个变成 3 个**（⭐ 多了源 C）
        //     🔴 **为什么**：⭐ 深度要按"**最坏在飞条数**"算（⭐ `evt_merge` 第一版的教训）——
        //        ⭐ 3 个源同拍各来 1 条 ⇒ ⭐ 需要 **≥ 3 槽**；⭐ 再留余量 ⇒ ⭐ 取 6
        //        （⭐ 与 `seq_arb` 的 3 源档取 6 是**同一个口径** ✅）
        //     ⚠️ **代价**：⭐ 每条记录 3+4+32+8+2+1+2 = **52 位** ⇒ 多 2 槽 = **+104 FF**
        //        （⭐ 相对本器件 60780 个 DFF 可忽略 ✅）
        //     📌 而**实际速率**远低于"每拍 3 条"：⭐ A ≤ 1/tick、⭐ C ≤ 1/tick、
        //        ⭐ B ≤ 1/960 tick ⇒ ⭐ 溢出实际不会发生（⭐ 真发生也有 `mg_overflow` 指示）✅
        evt_merge #(
            .AXIS_W  (4),
            .PHASE_W (32),
            .VEL_W   (8),
            .KIND_W  (2),
            .DEPTH   (6)
        ) u_evt_merge (
            .clk_i            (clk),
            .rst_n_i          (rst_n_sync),
            // ── ⭐⭐ 源 A：**仲裁后的来源**（⭐ 默认 W3a 手弹；⚠️ `T57` 档 = 演示和弦）──
            //   📌 依据：⭐ ESP32 清单 §四"唯一对接点 = `evt_merge` 源 A"
            //   ⚠️ 见上方 §源 A 仲裁（`SOURCE_A_SEL`）
            .a_valid_i        (src_a_valid),
            .a_axis_i         (src_a_axis),
            .a_phase_inc_i    (src_a_inc),
            .a_velocity_i     (src_a_vel),
            .a_kind_i         (src_a_kind),
            .a_timbre_valid_i (src_a_timbre_valid),
            .a_timbre_i       (src_a_timbre),
            // ⭐⭐ A1：⭐ 源 A 的来源标记（⭐ 手弹=0 / 回放=1 / 演示=2，⭐ 见 `src_a_src`）
            .a_src_i          (src_a_src),
            // ── ⭐⭐ 源 B：**节拍器 / 鼓机 二选一**（⭐ `SEL_DRUM`，⭐ 默认节拍器）──
            //   📌 两路都例化，⭐ 这里选谁进 `evt_merge`（⭐ 见上方 §源 B 二选一）
            .b_valid_i        (src_b_valid),
            .b_axis_i         (src_b_axis),
            .b_phase_inc_i    (src_b_inc),
            .b_velocity_i     (src_b_vel),
            .b_kind_i         (src_b_kind),
            .b_timbre_valid_i (src_b_timbre_valid),
            .b_timbre_i       (src_b_timbre),
            // ⭐⭐ A1：⭐ 源 B（节拍器 / 鼓机）的来源标记 = **常数 `3'd3`**
            //   ⭐ 为什么用 3：⭐ `seq_arb` 只用了 0/1/2 ⇒ ⭐ 3 是**空闲值**，
            //      天然与手弹/曲谱/演示**不同源** ⇒ ⛔ 节拍器的 `note_off`
            //      不会误杀手弹或曲谱的同轴 voice（⭐ 反之亦然）✅
            //   ⭐⭐ 2026-09-30：⭐ **值不变（仍是 3），只把位宽补到 3 位** ✅
            .b_src_i          (3'd3),
            // ── ⭐⭐ 源 C：**looper 回放**（⭐ 2026-09-30 新增，⭐ 用户需求）──────────
            //   🔴 **为什么新开一口**：⭐ 见上方 §事件域 Looper ——
            //      ⭐ A/B 两口都已占满，⭐ 而 looper 必须与**曲谱**并存 ⇒ ⭐ 只能新开 ✅
            //   ⭐ **来源标记 = 常数 `3'd4`**（⭐ 5 个源里唯一留给它的值）
            //      ⇒ ⭐ `note_manager` 按 (轴, 源) 隔离 ⇒ ⭐ 曲谱的 `note_off`
            //         ⛔ **不会清掉同轴 looper 的 voice**（⭐ 反之亦然）✅
            //   ⭐ 音色：⭐ 用 looper **录制时存下的**那个（⭐ `looper_play_timbre` ✅）
            .c_valid_i        (looper_play_valid),
            .c_axis_i         (looper_play_axis),
            .c_phase_inc_i    (looper_play_inc),
            .c_velocity_i     (looper_play_vel),
            .c_kind_i         (looper_play_kind),
            .c_timbre_valid_i (looper_play_timbre_valid),
            .c_timbre_i       (looper_play_timbre),
            .c_src_i          (3'd4),
            // ── 合流输出 → `note_manager` ────────────────────────────────
            .evt_valid_o      (mg_evt_valid),
            .evt_axis_o       (mg_evt_axis),
            .evt_phase_inc_o  (mg_evt_inc),
            .evt_velocity_o   (mg_evt_vel),
            .evt_kind_o       (mg_evt_kind),
            .evt_timbre_valid_o(mg_evt_timbre_valid),
            .evt_timbre_o     (mg_evt_timbre),
            // ⭐⭐ A1：⭐ 来源标记（⭐ 与 `evt_valid_o` 同时序，⭐ 已穿过 FIFO）
            .evt_src_o        (mg_evt_src),
            // ── 可观测性（⚠️ 未引到引脚，但综合时**不要**被优化掉：
            //    它们驱动的是寄存器 → 会保留；⭐ 上板可用调试核读）──────────
            .collision_cnt_o  (mg_collision_cnt),
            .merged_cnt_o     (mg_merged_cnt),
            .drop_cnt_o       (mg_drop_cnt),
            .overflow_o       (mg_overflow)
        );

        // ⭐ voice 分配 / 抢占 / 参数更新（T54）
        note_manager #(
            .POLY_TARGET (POLY_TARGET),
            //  ⭐⭐ 2026-10-08（`A3` 正确修法）：⭐ **鼓分类阈值必须与 `oscillator_bank` 【同值】**
            //   🔴 **为什么必须显式传**：⭐ `oscillator_bank` 那边被顶层覆盖成
            //      `.DRUM_TOM_MAX(20_000_000)`（⭐ 见下方例化处的说明：⭐ 为了让嗵鼓上到 200 Hz）⚠️
            //      ⇒ ⭐ 而 `note_manager` 的默认是 **15_000_000** ⇒
            //      🔴 **不传就会两处口径不一致** ⇒ ⭐ 分类与实际扫频档**对不上** ✅
            //   📌 `DRUM_KICK_MAX` 两边都用默认 **10_000_000**（⭐ 顶层没覆盖它）✅
            .DRUM_KICK_MAX (10_000_000),
            .DRUM_TOM_MAX  (20_000_000),
            .AXIS_W      (4),
            .PHASE_W     (32),
            .VEL_W       (8),
            .TIMBRE_W    (2),
            .ENV_W       (16),
            .AGE_W       (16),
            // ⭐⭐ T33b: metronome + drum machine need a voice that user
            //      notes cannot steal.  metronome emits axis_id 4'hE, and
            //      note_manager picks the reserved pool by SOURCE
            //      (src == SRC_AUX(3'd3) -- note_manager pool_mask assign), NOT by that
            //      axis, so this MUST be >= 1 or the metronome lands in the
            //      normal pool and gets stolen the moment 32 voices sound.
            //      It is deliberately PAIRED with metronome.AXIS_ID (see
            //      u_metronome below) (K-106 family: an unpaired setting
            //      fails silently).
            .RESERVED_N  (5),
            // ⭐⭐ 2026-10-04：⭐ **T3 变调总闸**（⭐ 交付档 = 1，⭐ 见 `T3_ENABLE` 的说明 ✅）
            .T3_EN       (T3_ENABLE)
        ) u_note_manager (
            .clk_i             (clk),
            .rst_n_i           (rst_n_sync),
            .sample_tick_i     (tick_audio),
            // ⭐⭐ T36 / U-6（2026-09-22）：两个源经 `evt_merge` 合流。
            //   🔴 这里原来是把两路**直接或在一起**：
            //        .note_valid_i (demo_note_valid | met_evt_valid)
            //        .note_axis_i  (demo_note_valid ? demo_note_axis : met_evt_axis)
            //      ⇒ ⚠️ **同拍相撞时 demo 赢、met 的事件【静默消失】**
            //        （`note_valid_i` 只响一拍，那一整条事件就永久没了）。
            //   ⭐ 现在由 `evt_merge` 仲裁：⭐ **两路同拍【不丢】**，
            //      后发的那条**晚 1 拍**（20 ns）—— 远小于一个音频帧 20.48 µs
            //      ⇒ ⭐ 听感不可分辨；而"丢一条"是永久损失。
            .note_valid_i      (mg_evt_valid),
            .note_axis_i       (mg_evt_axis),
            .note_phase_inc_i  (mg_evt_inc),
            .note_velocity_i   (mg_evt_vel),
            .note_kind_i       (mg_evt_kind),
            // ⭐⭐ 2026-09-29（A1）：⭐ **事件来源标记**（⭐ 手弹 0 / 回放 1 / 演示 2 / 源 B 3）
            //   🔴 修的缺陷：⭐ 原来 `note_off` 只按 `axis` 匹配 ⇒ ⭐ looper 回放时
            //      按**同一个轴**的手弹键 ⇒ 回放的 `note_off` 把**手弹**的 voice 也清了
            //      ⇒ ⭐ **手弹的音死掉且不再回来** ✅
            //   ✅ 现在：⭐ `note_manager` 只清**同源**的 voice ⇒ ⭐ 两者互不误杀 ✅
            .note_src_i        (mg_evt_src),
            // ⭐⭐ 2026-10-01：⭐ **T2 起始音（base note）** —— ⭐ 把【早就存在但悬空】的
            //    `ui_base_semi` / `ui_base_commit` 接上 ✅
            //   📌 **背景**：⭐ `uart_ui` 一直在解析它们（⭐ `rtl/w3c/uart_ui.v` 的 `mode_o`/`base_semi_o` 端口），
            //      `top.v` 也一直连着线（⭐ `u_uart_ui` 例化的 `ui_base_semi`/`ui_base_commit`），
            //      🔴 但**全 `rtl/` 里没有任何地方读它** ⇒ ⭐ **一根悬空线** ⚠️ ⇒ ⭐ **T2 = 把它接上** ✅
            //   ⭐ **语义**（⭐ `uart_ui.v` 的 `RET_NUM` 分支原文）：⭐ "起始音：限定八度级（每 12 半音取整）"
            //      ⇒ ⭐ **`base_semi` = 八度数 × 12**（⭐ `0` = C4 · `12` = C5 · `24` = C6 ✅）
            //   ⚠️ **安全重做**（⭐ 按 `files/00-总览/交接文档-20260930-补遗.md:54` 的 ①②③）
            //      —— ⭐ **换算、旁路 mux、范围校验都在 `note_manager` 内部** ✅
            //   📌 方案与判据：⭐ `files/00-总览/T2-起始音-实施方案-20261001.md` ✅
            .base_semi_i       (ui_base_semi),
            .base_commit_i     (ui_base_commit),
            // ⭐⭐ 2026-10-03（P2）：⭐ **T3 变调**（⭐ 串口 `'F'`/`'G'`/`'H'` ⇒ 上面的聚合寄存器）
            //   🔴 **本步之前这个端口是【悬空】的**（⭐ 老例化一个都不接 ⇒ `5'bzzzzz`）
            //      ⇒ ⭐ `note_manager` 内部靠 **Z-safe 解码**当 0 处理（⭐ 不变调 ✅）
            //   ⭐ 现在接上 ⇒ ⭐ `T3_EN = 0`（默认）时它**仍不参与综合**
            //      （⭐ `note_manager` 用 `generate if (T3_EN)` 门控了整段变调核心 ✅）
            //      ⇒ ⭐ 综合资源应与"无 T3 基线"逐字相同（⭐ `T_Lut 37026`）✅
            //   📌 口径出处：⭐ `files/20-代码/T3-后续计划-20261003.md` §六 ✅
            .transpose_semi_i  (transpose_semi),
        //  ⭐⭐ 2026-10-04（T5）：⭐ **延音踏板**（⭐ 1 = 踩住）
        //     ⭐ 模块层已完成 **同步 + 去抖 + 低有效翻正**（⭐ 见上面 §延音踏板）✅
        //     ⭐ 语义：⭐ 踩住期间手弹的 `note_off` 只关 gate、⛔ 不启动包络释放 ✅
        .sus_pedal_i       (sus_pedal_r),
            // ⭐⭐ 力度修正通路 —— ⭐ **2026-09-28 改接【位置式力度流】**
            //
            //   ⭐ 三段历史（⭐ 都保留，⛔ 不删 —— 每一步都有依据）：
            //     ① 2026-09-23：接 W3a `param_extract`（**敲击速度**式）
            //     ② 2026-09-27：🔴 暂时断开做诊断（硬接 `1'b0`，⛔ 不是删通路）——
            //        ⭐ 用户反馈"**感受不到力度反馈**"＋"**按住不松手时音量反复变大变小**"
            //        ⭐ 机理：当时 `vel_upd` **只允许调大**（`if value > vel_r[i]`），
            //          而起音已用 `DEFAULT_VEL=200` ⇒ ⚠️ 慢按给 64（被 `>` 挡掉）、
            //          快按给 255 才生效 ⇒ ⭐ **只有"快按"才有反馈**；
            //          且 `peak_level`/`sustain_level` 都由 `velocity_i` 派生
            //          ⇒ 🔴 改 `vel` 会让 sustain 目标**跳变** ⇒ 音量起伏。
            //     ③ ⭐⭐ **2026-09-28（本次）：换成【位置式】** —— ⭐ 用户已定的方案
            //        （`files/20-代码/位置式力度-方案-20260928.md`）
            //        · ⭐ 驱动源 = 上方 `vu_*`：每 `tick_audio` 扫一个轴 ·
            //          死区 16 码 · `pos > TRIG_TH` 才算"按下中"（⭐ 抬起即冻结）
            //        · ⭐ `note_manager` 侧同步去掉了"只允许调大"
            //          （⭐ 见 `note_manager.v` 的 `(d)` 段）⇒ ⭐ **可增可减 = 实时跟随**
            //        · ⭐ 上一条诊断里"音量起伏"的机理 ⛔ **在这里不再成立**：
            //          起伏来自"**敲击速度**式"的**只增不减 + 阈值附近抖动**
            //          （⭐ 一次跳到 255 就锁死，或反复发同一个包）；
            //          而位置式是**连续的、双向的**，⭐ 且**死区 16 码**
            //          （⭐ 实测帧间噪声 Δ≤6）把抖动挡住 ⇒ ⭐ 音量**平滑跟随**。
            //        · 📌 且 `adsr.v` 的 `ST_SUSTAIN` 本来就会**持续朝 `sustain_level` 收敛**，
            //          而 `sustain_level` 是 `velocity_i` 的组合输出
            //          ⇒ ⭐ 改 `vel_r` ⇒ 音量**立刻跟随**（⛔ 不需要改 `adsr.v`）✅
            //
            //   ⚠️ **`param_extract` 的力度三件套现在是【有意不使用】**（⛔ 不是漏接线）：
            //      · ⛔ **不删实例、⛔ 不动 `param_extract.v`** —— ⭐ 它的**音高**通路
            //        （`pe_pitch_v`/`pe_pitch_ax`/`pe_pitch` ⇒ 下方 `pitch_upd_*`）**仍在用** ✅
            //      · ⭐ 将来若要恢复"敲击速度"式力度 ⇒ 把下行换回
            //        `pe_vel_v`/`pe_vel_ax`/`pe_vel` 即可（⭐ 但得先把"只允许调大"的语义定案）
            //      · 📌 综合会把**无人使用**的力度输出**剪掉**（⭐ 省 LUT），⛔ 不影响功能。
            .vel_upd_valid_i   (vu_valid_r | lp_upd_valid),
            .vel_upd_axis_i    (vu_valid_r ? vu_axis_r : lp_upd_axis),
            .vel_upd_value_i   (vu_valid_r ? vu_val_r  : lp_upd_vel),
            //  ⭐⭐ 2026-09-29 新增：⭐ **更新通路的来源标记**（⭐ 0 = 手弹 · 4 = looper 回放）
            //   🔴 **为什么必须有**：⭐ `note_manager` 的 (d)/(e) 段原来**只按轴匹配**
            //      ⇒ 🔴 回放的插值更新会把**同一轴上手弹的 voice** 一起拖走
            //      （⭐ 音量/音高被别人的手势带着跑）—— ⭐ 与 A1 修的 `note_off`
            //      **是同一个缺陷类** ✅
            //   ⭐ 接法：⭐ 手弹那拍给 0、⭐ looper 那拍给 **4** ✅
            //   🔴🔴 **2026-09-30：⭐ 这里的 looper 标签【必须跟着事件标签一起改成 4】**
            //      ⚠️ **不能漏**：⭐ 事件标签（源 C）已经是 `3'd4` ⇒ ⭐ 而 `note_manager`
            //         的 (d)/(e) 段是**按 `src_r[i] == 更新源` 匹配**的
            //      ⇒ 🔴 若这里仍写 `3'd1`，⭐ looper 的插值更新会去改**曲谱**的 voice
            //         （⭐ 而 looper 自己的 voice **一个都收不到**）
            //      ⇒ 🔴 **症状**：⭐ loop 回放**又变回"只有起音力度"**
            //         （⭐ 即用户报过的"loop 的声音比键盘小 / 没有 release 尾音"）✅
            //      📌 **一句话**：⭐ **"事件源标签"与"更新源标签"必须成对** ✅
            //   📌 **两路结构上不会同拍**：⭐ `looper` 内部**主动避让**手弹流
            //      （⭐ 见 `looper.v` 的 `live_busy`）⇒ ⚠️ 这里的 mux 只是**兜底**，
            //      ⛔ 不承担"优先级仲裁"的语义 ✅
            .vel_upd_src_i     (vu_valid_r ? 3'd0 : 3'd4),
            .pitch_upd_valid_i (pe_pitch_v | lp_upd_valid),
            .pitch_upd_axis_i  (pe_pitch_v ? pe_pitch_ax : lp_upd_axis),
            .pitch_upd_value_i (pe_pitch_v ? pe_pitch    : lp_upd_inc),
            .pitch_upd_src_i   (pe_pitch_v ? 3'd0 : 3'd4),
            .default_timbre_i  (timbre_sel_r),   // ⭐ 2026-09-29：由串口 'I' 切换（⭐ 原来写死 2'd0）
            .evt_timbre_valid_i(mg_evt_timbre_valid),
            .evt_timbre_i      (mg_evt_timbre),
            .env_active_i      (env_active),
            .env_level_i       (env_level),
            .voice_gate_o      (nm_gate),
            .voice_active_o    (nm_active),
            .voice_releasing_o (),
            .voice_axis_o      (nm_axis),
            .voice_phase_inc_o (nm_phase),
            .voice_velocity_o  (nm_vel),
            .voice_timbre_o    (nm_timbre),
            //  ⭐⭐ 2026-09-29 新增：⭐ **每 voice 的"是鼓吗"** ⇒ 噪声表选择（⭐ 见上方声明）✅
            .voice_drum_o      (nm_drum),
        //  ⭐⭐ 2026-10-08（`A3` 正确修法）：⭐ **每 voice 2 位的鼓分类**（⭐ 提交时算好）✅
        .voice_drum_cls_o  (nm_drum_cls),
            .voice_age_o       (nm_age),
            .voice_retrig_reset_o(nm_retrig_reset),
            .alloc_valid_o     (nm_alloc_valid),
            .alloc_voice_o     (nm_alloc_voice),
            .event_lost_clr_i  (1'b0)
        );

        // ⭐ 64 路独立振荡器（T55）—— ⭐ 评分主体：评委可数出 64 份相位寄存器
        // T18: internal LFO output is Q1.15, matching oscillator_bank.
        wire signed [15:0] vibrato_mod;
        wire               vibrato_active;
        wire [31:0]        vibrato_rate_inc, vibrato_phase;
        vibrato_lfo #(
            .CTRL_SLEW_DIV(10) // ADC commits every 0.5 ms => 5 ms slew step
        ) u_vibrato_lfo (
            .clk_i            (clk),
            .rst_n_i          (rst_n_sync),
            .ctrl_valid_i     (vib_ctrl_valid),
            .depth_raw_i      (vib_depth_sel),
            .rate_raw_i       (vib_rate_sel),
            .mod_o            (vibrato_mod),
            .depth_active_o   (vibrato_active),
            .rate_inc_dbg_o   (vibrato_rate_inc),
            .phase_dbg_o      (vibrato_phase)
        );

        oscillator_bank #(
            .POLY_TARGET   (POLY_TARGET),
            .OSC_PER_VOICE (OSC_PER_VOICE),
            .PHASE_W       (32),
            .OSC_SAMPLE_W  (16),
            .TIMBRE_N      (4),
            .TIMBRE_W      (2),
            .ENABLE_FM     (0),
            //   ⭐⭐ **2026-09-27 新增：⭐ 失谐开关透传**
            //      ⭐ 用途：⭐ **A/B 对比**（⭐ `DETUNE_ON=0` 关失谐 vs `=1` 开失谐）
            //         ⇒ ⭐ 用来回答用户"按键声音为什么变低沉浑厚了"。
            //      📌 **为什么做成 `top` 参数而⛔ 不是写死**：
            //         ⚠️ 失谐改变音色（⭐ 两 lane 拍频 1.72 Hz ⇒ 每秒 1.72 次起伏）
            //         ⇒ ⭐ **用户主观听感需要能对比** ⇒ ⭐ 必须可切。
            //      ⭐ 默认 **1**（⭐ 开启，⭐ 与 `oscillator_bank` 的默认一致）。
            //      📌 关联：⭐ 若"太厚" ⇒ ⭐ 调 `oscillator_bank.DETUNE_SH`（⭐ **9→10**，⭐ 当前交付值已是 9，见 `parameter integer DETUNE_SH`）。
            .DETUNE_ON     (DETUNE_ON),
            //   ⭐⭐ **2026-09-28 新增：⭐ 失谐深度透传**（⭐ `Minimal-A` 的第 ① 项）
            //      ⭐ 默认 **9**（⭐ 原 `oscillator_bank` 内部默认是 8）
            //      ⚠️ **代码实查**：⭐ 原来 `DETUNE_SH` **没有透传** ⇒ 从顶层调不了。
            //      📌 **命名参数覆盖是合法用法** ⇒ ⭐ `oscillator_bank.v` **一字不改**
            //         （⭐ 满足"只动不碰队友文件"的约束）。
            .DETUNE_SH     (DETUNE_SH),
            //  ⭐⭐ 2026-09-29 合并（⭐ 队友版）：⭐ **力度只管响度，⛔ 不改音色** ✅
            //   ⭐ 固定取 **AKWF 的 soft 档**（⭐ `FIXED_BLEND_Q = 0` ✅）
            //   🔴 为什么：⭐ 旧的"力度→音色"在满行程时把波形推到 hard 成分 ⇒
            //      ⭐ 每个音色都变粗糙持续音 ＋ ⭐ 和弦里谐波堆积 ✅
            .VELOCITY_BLEND_EN(0),
            .FIXED_BLEND_Q (0),
            //  ⭐⭐ 2026-10-01：⭐ **鼓分档参数的【顶层覆盖】**（⭐ 用户："通鼓和底鼓还差一点区分度"）
            //   📌 **手法**：⭐ `oscillator_bank` 是**命名参数例化** ⇒ ⭐ 从 `top.v` 覆盖即可
            //      ⇒ ⭐ **`oscillator_bank.v` 一字不改** ✅（⭐ 与 `.DETUNE_SH` 同一手法 ✅）
            //   ⭐ **① `DRUM_TOM_MAX` 15M → 20M**（⭐ 嗵鼓档上界 167.6 → **223.3 Hz**）
            //      ⭐ **为什么**：⭐ 要让嗵鼓上到 **200 Hz**（⭐ = 17.9M）
            //         ⚠️ 而 15M 的旧上界会把它判成"军鼓/踩镲"档 ⇒ 🔴 **扫频直接没了** ⚠️
            //      ⚠️ **影响面**：⭐ [167.6, 223) Hz 从"军鼓/踩镲"改判成"嗵鼓"
            //         ⇒ ⭐ 而**军鼓 480 Hz、踩镲 1920 Hz** 都远在上界之上 ⇒ ⛔ **无冲突** ✅
            //      📌 **自检**：⭐ `oscillator_bank.v` 的 `sweep_q`"扫频深度截断"自检**只守 `DRUM_KICK_MAX`**
            //         ⇒ ⭐ 抬高 `DRUM_TOM_MAX` **不会**触发它 ✅
            //   ⭐ **② `DRUM_TOM_SWEEP_SH` 2 → 3**（⭐ 嗵鼓扫频深度 1/4 → **1/8**）
            //      ⭐ **为什么**：⭐ 让嗵鼓的"音高下滑"**更少** ⇒ ⭐ 与底鼓（⭐ **全深度** `>>0`）
            //         的**音高包络**差得更远 ⇒ ⭐ 这是"区分度"的第二个维度（⭐ 不止音高本身）✅
            .DRUM_TOM_MAX     (20_000_000),
            .DRUM_TOM_SWEEP_SH(3),
            //  ⭐⭐ 2026-10-08（`A3` 正确修法）：⭐ **鼓分类改由 `note_manager` 提交时算好** ✅
            //   ⭐ `1` ⇒ ⭐ 本模块**不再**自己比 `bv` ⇒ ⭐ 那 **64 个常量比较器整段不综合** ✅
            //   ⭐ 收益：⭐ ① **零窗口**（⭐ 分类当拍就绪，⛔ 不受 `phase_tr` 轮转 32 拍影响）✅
            //           ② ⭐ **净省 ~500 LUT**（⭐ 64 个 32 位常量比较器 ≈640 LUT
            //              换成 1 套 TDM 比较器 + 64 FF）✅
            //           ③ ⭐ **语义更对**：⭐ 鼓种由"**按的哪个键**"决定，⛔ 不被变调带走 ✅
            //   ⚠️ 阈值（`.DRUM_KICK_MAX`/`.DRUM_TOM_MAX`）⭐ 必须与 `note_manager` 的**同值** ✅
            .DRUM_CLS_EXT     (1)
        ) u_oscillator_bank (
            .clk_i              (clk),
            .rst_n_i            (rst_n_sync),
            .sample_tick_i      (tick_audio),
            .voice_active_i     (nm_active),
            //  ⭐⭐ K-169（2026-09-30）：⭐ **起音相位复位改挂 note_on 事件边沿** ✅
            //     ⭐ 源 = `note_manager.voice_retrig_reset_o`（⭐ 与 `envelope_bank`
            //        的 `retrig_reset_i` 是**同一个信号** ⇒ ⭐ "包络清零"与
            //        "相位复位"从此由**同一个事件、同一拍**驱动 ✅）
            //     🔴 **原来为什么不行**：⭐ `oscillator_bank` 靠 `nm_active`
            //        （⭐ = `live_mask`，**电平派生**）的**上升沿**自己判起音
            //        ⇒ ⭐ 上一个音**还在 Release 尾巴里**时重按同一轴
            //        ⇒ `nm_active` **恒为 1** ⇒ 🔴 **没有上升沿** ⇒ ⭐ 相位复位被跳过
            //        ⇒ 🔴 起音幅度随机（⭐ `K-169`）✅
            //     📌 `test_mode_i` 那一拍由 `oscillator_bank` 内部自行屏蔽
            //        （⭐ 与 `envelope_bank` 处的 `tm_enable_r ? 0 : ...` 等价）✅
            .voice_phase_rst_i  (nm_retrig_reset),
            .base_phase_inc_i   (nm_phase),
            .voice_timbre_i     (nm_timbre),
            //  ⭐⭐ 2026-09-29 新增（⭐ 鼓机噪声波表 · 阶段 2a）：⭐ **鼓 voice 走噪声表** ✅
            //   ⭐ 语义：⭐ **来源为 `SRC_AUX`** ⇒ ⭐ 打击乐 ⇒ ⭐ 读噪声表
            //   ⚠️ **副作用（⭐ 必须知道）**：⭐ 保留轴位有**两个**（⭐ 14 = 节拍器、
            //      15 = 鼓机）⇒ ⭐ **节拍器的"嘀嗒"也会变成噪声** ✅
            //      📌 这是本阶段判据（⭐ `src_r[i] == SRC_AUX`）的**直接推论**，
            //         ⭐ 且听感上"节拍器 = 噪声 click"通常**更接近真实节拍器** ⇒
            //         ⭐ 暂按现状保留，⛔ 不为此再引入第三条标志线（⭐ 保持最小改动 ✅）
            .voice_drum_i       (nm_drum),
            //  ⭐⭐ 2026-10-08（`A3` 正确修法）：⭐ **每 voice 2 位的鼓分类**（⭐ 提交时算好）✅
            //   📌 配 `.DRUM_CLS_EXT(1)` 使用 ⇒ ⭐ 本模块内部的 64 个比较器**不综合** ✅
            .drum_cls_i         (nm_drum_cls),
            .voice_velocity_i   (nm_vel),
            .vibrato_mod_i      (vibrato_mod),
            .test_mode_i        (tm_enable_r),
            .test_lane_active_i (tm_lane_active),
            .test_phase_inc_i   (tm_phase_inc),
            .fm_cfg_valid_i     (1'b0),
            .fm_ratio_i         (16'd0),
            .fm_index_i         (16'd0),
            .osc_sample_bus_o   (ob_samples),
            .osc_valid_o        (ob_valid),
            .phase_acc_dbg_o    (ob_phase_dbg)
        );

        // ⭐ TDM 混音 + 饱和（T56）—— ⭐ 全设计**只有 1 个 DSP**
        //    ⚠️ `render_start_i` 用 `ob_valid`（振荡器样本就绪）⇒ 天然串行、无竞争
        // ═══════════════════════════════════════════════════════════════════
        // ⭐⭐ 打击乐包络（`perc_env_bank`）—— ⭐ 2026-09-28 接通（⭐ 修 `K-144`）
        //
        //   🔴 **为什么必须接通**：⭐ `perc_env_bank.v` 是专为打击乐建的
        //      "**一击到底、衰到 0 自动结束**"包络，⭐ **但全工程从未例化**
        //      （⭐ `K-144`：孤儿模块）⇒ 节拍器/鼓机一直走**普通 `adsr`**
        //      ⇒ ⚠️ 衰到 sustain **就停住不再降**，而 `metronome.v` 的 `EVT_KIND`
        //         是**常量 note_on、⛔ 永不发 `note_off`**
        //      ⇒ 🔴 **voice 永久 held ⇒ 挂音**
        //      （⭐ 用户 2026-09-28 上板实测原话："**开了节拍器之后会挂音**"）
        //      📌 **为什么以前没暴露**：⭐ 因为 `METRONOME_ON=0`（⭐ 节拍器根本不响）
        //         ⇒ ⭐ 本轮把它改成 1，这个**潜伏缺陷立刻变成可听 bug**。
        //
        //   ⭐ **修法（⭐ 最小改动，⛔ 不动任何已验证模块的行为）**：
        //      ⭐ **只换【保留池 voice 的包络电平】** ——
        //         `env_level`（来自 `envelope_bank` 的 ADSR）在**保留池那几路**
        //         换成 `perc_env_bank` 的输出，⭐ 其余 `POLY_TARGET-RESERVED_N` 路
        //         **逐位不变**。
        //      ⇒ ⛔ `note_manager` / `oscillator_bank` / `tdm_render_mixer` /
        //         `envelope_bank` / `adsr` / `metronome` 的**逻辑一行不改** ✅
        //      ⇒ ⭐ 保留池 = 打击乐（节拍器 `axis 14` + 鼓机 `axis 15`）
        //         ⇒ ⭐ **语义正好对上**。
        //
        //   ⭐ **为什么键盘音量不受影响**（⭐ 已核实，⛔ 不是猜）：
        //      `tdm_render_mixer` 的归一化 `popcount` **本来就排除保留池**
        //      （`.RESERVED_N` ⇒ `NORMAL_N`，⭐ 见 `tdm_render_mixer.v` 的 `NORMAL_N` 定义：
        //       *"🔴 根因：`voice_active_i` 包含保留池"*）
        //      ⇒ ⭐ 节拍器响不响都**不改变 `1/√N`** ✅
        //
        //   ⚠️⚠️ **触发必须用【上升沿】**（⭐ 关键，⛔ 否则白改）：
        //      `nm_gate` 是**电平**（没有 `note_off` ⇒ 一直为 1）
        //      ⇒ ⛔ 若直接接 `trigger_i`，包络会**每拍都重新装载峰值**
        //      ⇒ 🔴 **又变成挂音**。
        //      ⭐ 而 `note_manager.voice_gate_o = gate_mask = gate_r & ~retrig_low`
        //         ⇒ ⭐ **同轴重触发时它会【真的压低再抬起】**（`retrig_low`）
        //         ⇒ ⭐ 上升沿检测**对"起音"和"重触发"都能触发** ✅
        //
        //   ⚠️ **`sample_tick_i` 接 `tick_audio`**（⭐ 冻结表 §〇 约定 1：时钟使能）
        //      ⭐ `DECAY_STEP=67`（`perc_env_bank` 默认）⇒ 满力度(255)：
        //         `65280/67 ≈ 975` 拍 ≈ **20 ms**
        //      ⇒ ⭐ 强拍(180) ≈ **14.1 ms** · 弱拍(108) ≈ **8.5 ms**（⭐ 打击乐的量级）
        //      📌 **2026-09-30 同步更新**：⭐ 节拍器力度 `120/72 ⇒ 180/108`
        //         （⭐ 用户："节拍器的声音有一点太小了"）⇒ ⭐ 两个时长**跟着变长**
        //         （⭐ 衰减时长 ∝ 峰值 —— ⭐ 见 `perc_env_bank.v` 的 `DECAY_STEP`）✅
        //         ⚠️ 改力度**必须同时改本注释**（⭐ 本项目"注释↔代码不一致"是复发缺陷）✅
        // ═══════════════════════════════════════════════════════════════════
        //  ⚠️ 下面这个 5 **必须**与 `u_note_manager` / `u_tdm_render_mixer` 的
        //     `.RESERVED_N(5)` 一致（⭐ 三处同源；⚠️ 保留池 = **最高**那几路）
        localparam integer PERC_N   = 5;
        localparam integer RES_BASE = POLY_TARGET - PERC_N;

        wire [PERC_N-1:0]    perc_trig;
        wire [PERC_N*8-1:0]  perc_vel;
        wire [PERC_N*16-1:0] perc_level;
        wire [PERC_N-1:0]    perc_active;
        wire [PERC_N-1:0]    perc_busy;
        wire [PERC_N*16-1:0] perc_retrig_cnt;

        //  ⭐ 上升沿检测：`nm_gate`（电平）⇒ 单周期脉冲
        reg [PERC_N-1:0] nm_gate_d;
        always @(posedge clk) begin
            if (!rst_n_sync) nm_gate_d <= {PERC_N{1'b0}};
            else             nm_gate_d <= nm_gate[POLY_TARGET-1:RES_BASE];
        end
        assign perc_trig = nm_gate[POLY_TARGET-1:RES_BASE] & ~nm_gate_d;

        //  ⭐ 力度：⭐ 保留池那 5 路
        //     ⚠️ **用纯位选，⛔ 不用 `generate` 循环** ——
        //        🔴 `g_sound` **本身就在 `generate` 块里**（`generate`@694 → `endgenerate`@2861）
        //        ⇒ ⛔ **generate/endgenerate 不能再嵌套**（iverilog 报
        //          "generate/endgenerate regions cannot nest"）⭐ 已实测踩到。
        //     ⭐ 宽度天然相等：`PERC_N*8` = `POLY_TARGET*8 - RES_BASE*8` ✅
        assign perc_vel = nm_vel[POLY_TARGET*8-1 : RES_BASE*8];

        perc_env_bank #(
            .N_PERC     (PERC_N),
            .ENV_W      (16),
            .VEL_W      (8),
            .DECAY_STEP (67)          // ⭐ 默认：满力度 ≈ 20 ms（见上）
        ) u_perc_env_bank (
            .clk_i         (clk),
            .rst_n_i       (rst_n_sync),
            .sample_tick_i (tick_audio),
            .trigger_i     (perc_trig),
            .velocity_i    (perc_vel),
            .level_o       (perc_level),
            .active_o      (perc_active),
            .busy_o        (perc_busy),
            .retrig_cnt_o  (perc_retrig_cnt)
        );

        //  ⭐⭐ 包络电平选择：⭐ 保留池 = 打击包络；⭐ 其余 = ADSR（**逐位不变**）
        //     ⚠️ **⛔ 不用 `generate` 循环**（⭐ 同上：`g_sound` 已在 generate 块内）
        //     ⭐ 两段**纯位选**就够，⭐ 且宽度天然相等（⭐ 无循环 ⇒ 综合器兼容性最好）
        wire [POLY_TARGET*16-1:0] env_level_mix;
        //  ① ⭐ 键盘那 `POLY_TARGET-RESERVED_N` = 27 路：⭐ 原样透传
        //     ⇒ ⭐ **与改动前逐位一致** ⇒ 键盘音色/音量**零变化** ✅
        assign env_level_mix[RES_BASE*16-1 : 0] = env_level[RES_BASE*16-1 : 0];
        //  ② ⭐ 保留池 5 路：⭐ 换成"一击到底"的打击包络
        assign env_level_mix[POLY_TARGET*16-1 : RES_BASE*16] = perc_level;

        // ═══════════════════════════════════════════════════════════════════
        // ⭐⭐ P5-1（2026-10-03）：⭐ **`tdm_render_mixer` 的帧起点推后 32 拍**
        //
        //   ⭐ **为什么**：⭐ `envelope_bank` 改成了**共享引擎 + 32 拍轮转**
        //      （⭐ 见 `rtl/w3b/envelope_bank.v` 的文件头）⇒ ⭐ 它那 512 位
        //      `env_level_o` **要 32 拍才全部更新完**（⭐ 第 v 路在 tick 后第
        //      (2+v) 拍落盘）。
        //      ⇒ ⭐ 给 `tdm_render_mixer` 的帧起点**留出这 32 拍的偏斜**，
        //        保证它扫到任何一个 voice 时看到的都是**本帧的新值** ✅
        //
        //   ⭐ **为什么选"推后帧起点"而⛔ 不是"攒够 32 位原子提交"**：
        //      · 原子提交要**再加 512 个 FF** 做影子寄存器，⭐ 且会把输出
        //        整体推迟 **1 帧**（⭐ 用户已拍板：⛔ 不要 1 帧延迟）
        //      · 推后 32 拍则**仍在同一个 1024 拍帧内**（⭐ mixer 只要 34 拍扫完，
        //        32 + 34 + 7 级流水 ≈ 73 拍 ⇒ ⭐ 余量 13×）✅
        //
        //   ⭐ **为什么 I2S 输出逐位不变**：⭐ 下游是**握手式**的 ——
        //      `mx_valid` 到 `master_mix` 再到 `top.v` 的输出寄存器
        //      （⭐ `sample_r <= mm_sample`，⭐ 见下方 `mm_valid` 那段），
        //      而 `i2s_tx` **只在 `frame_start` 装载一次**（⭐ `i2s_tx.v:184`）
        //      ⇒ ⭐ 只要在**下一个 `frame_start` 之前**给出即可 ✅
        //      （⭐ 32 拍 = 20.48 µs 的 3.1% ⇒ ⭐ 对采样值本身零影响 ✅）
        //
        //   ⚠️ **口径（⭐ 如实记录）**：⭐ 本次改动**同时**把这三种"帧边界快照"
        //      推后了 32 拍 —— `n_active_r`（归一化 popcount）、`norm_gain_r`
        //      的去拉链步进、`cnt` 起点。⭐ 前两者在**帧边界**取值，
        //      ⭐ 若那 32 拍内恰好有 note 事件落地，⭐ 归一化增益会差 1 档。
        //      📌 这是本改动的**已知代价**，⭐ 已跑全量回归复核（⭐ 见证据）。
        // ═══════════════════════════════════════════════════════════════════
        reg [31:0] mx_start_dly;
        always @(posedge clk) begin
            if (!rst_n_sync) mx_start_dly <= 32'd0;
            else             mx_start_dly <= {mx_start_dly[30:0], ob_valid};
        end
        wire mx_render_start = mx_start_dly[31];

        tdm_render_mixer #(
            .POLY_TARGET         (POLY_TARGET),
            .OSC_PER_VOICE       (OSC_PER_VOICE),
            .OSC_SAMPLE_W        (16),
            .ENV_W               (16),
            .SAMPLE_W            (SAMPLE_W),
            .CLK_PER_SAMPLE      (1024),
            .RENDER_DEADLINE_CYC (927),
            //   ⭐⭐ **2026-09-26 新增：⭐ 把保留池大小传进去**
            //      ⭐ 用途：⭐ **popcount 时排除保留池**（⭐ 节拍器/鼓机不该压低键盘音量）
            //      ⚠️ **必须与下面 `note_manager` 的 `RESERVED_N` 一致**（⭐ 两处都写 5）
            //      📌 语义：⭐ N 只数【演奏的 voice】⇒ ⭐ 音量不随节拍器跳动 ✅
            .RESERVED_N          (5),
            //  ⭐⭐ 2026-09-29 合并（⭐ 队友版）：⭐ **限幅器前留 6 dB 裕量**（⭐ `1` = −6.02 dB ✅）
            //   ⭐ 纯线性衰减：⭐ 保住 AKWF 样本 / 音色比 / 力度 / 失谐**全部不变** ✅
            //   🔴 为什么需要：⭐ AKWF 表**满幅** ⇒ 复音叠加会频繁触发软膝限幅 ⇒ ⭐ 音质变糙 ✅
            .OUTPUT_HEADROOM_SH  (1)
        ) u_tdm_render_mixer (
            .clk_i            (clk),
            .rst_n_i          (rst_n_sync),
            .render_start_i   (mx_render_start),
            .osc_sample_bus_i (ob_samples),
            //   ⭐⭐ **2026-09-28：`env_level` ⇒ `env_level_mix`**（⭐ 修 `K-144`）
            //      ⭐ 差别**只在保留池那 5 路**：⭐ 键盘那 27 路**逐位相同**
            //      ⇒ ⭐ 键盘音色/音量**零变化**（⭐ 已核实见上方 `perc_env_bank` 段）
            .env_level_i      (env_level_mix),
            //   🔴🔴🔴 **2026-09-26 上板实测【第六次】：⭐ 回退 `nm_gate` → `nm_active`**
            //
            //   ⭐⭐ **为什么回退（⭐ 本轮决定性证据）**：
            //      ⭐ 用户上板反馈：⭐ *"只有那个空灵沉闷的水怪低吼，也就是底噪"* +
            //         ⭐ 示波器：⭐ *"波动，最高 1.4V，有时有负值"*
            //      ⭐⭐ **仿真实测**（⭐ `build/exp/dbg_idle.sv`，⭐ 决定性）：
            //         ```
            //         ⭐ 静音时（⭐ 关节拍器 · 不按键）：
            //            · sample_mono 非零  = 100.0%  （⭐ 从不归零）
            //            · 峰值              = 34.8% 满幅
            //            · 均值(DC)          = 1235.77
            //            · 过零率            = 0.000007 ⇒ 等效 **0.2 Hz**
            //            · 有包络在响        = 100.0%  ⇒ 🔴 **有 voice 永不释放**
            //         ```
            //      ⇒ ⭐ **三方吻合**（⭐ 仿真 + 示波器 + 耳朵）：
            //         ⭐ 一个卡住的 voice **占了全部输出** ⇒ ⭐ **键盘声被淹没**。
            //
            //   🔴 **为什么先怀疑 `nm_gate`**：
            //      · ⚠️ 它是**唯一的未验证改动**（⭐ 接手时就在工作区，⛔ 无回归/PnR 证据）
            //      · 🔴 且 **`probe_headroom` 实测它削顶 99~100%**
            //      · ⭐ 回退**只需一行** ⇒ ⭐ **先排除这个变量**（⭐ 成本最低）
            //      📌 **⚠️ 注意**：⭐ 这**不等于**已证明它是元凶 ——
            //         ⚠️ `note_off` 链路也可能是断的。⭐ 回退是**排除变量**，⛔ 不是确诊。
            //
            //   ⭐ **回到交接文档记载的"已验证"状态**：
            //      · ⭐ `voice_active_o = live_mask`（⭐ 语义 = "还能出声"，⭐ 含 Release 尾巴）
            //      · ⚠️ 代价：⭐ `N` 会被 Release 尾巴撑大 ⇒ ⭐ 按键偏轻（⭐ 已知问题）
            //        ⇒ ⚠️ **但"偏轻"远好于"卡死占满输出"** ⇒ ⭐ 本轮先回退。
            //   📌 **待查**：⭐ 为什么 `nm_gate` 会让 voice 卡住
            //      （⭐ 怀疑：⭐ `gate_mask` 与 `env` 释放不同步 ⇒
            //       ⭐ `oscillator_bank` 的 `lane_active` 与 `envelope_bank` 的门控不一致）
            .voice_active_i   (nm_active),
            .dry_valid_o      (mx_valid),
            .dry_sample_o     (mx_sample),
            .deadline_fault_o (mx_fault),
            .n_active_o       (mx_n_active)
        );

        // ⭐⭐ 主混音 + 数字主音量 + 静音斜坡（master_mix，W3c 出声通路最后一级）
        //    ⚠️ 位置：`tdm_render_mixer` → `master_mix` → `i2s_tx`
        //    ⭐ 增益由 P4 CH1 的 64 点对数 LUT 提供；`RIGHT_ADC_ENABLE=0`
        //       时 `right_analog_ctrl` 输出 0x7FFF，保证旧硬件仍是满音量。
        //    ⭐ 静音斜坡：开机与调节均平滑，避免可闻"啪"声。
        wire signed [SAMPLE_W-1:0] mm_sample;
        wire                      mm_valid;
        master_mix #(
            .SAMPLE_W  (SAMPLE_W),
            .GAIN_W    (16),
            .RAMP_STEP (128)
        ) u_master_mix (
            .clk_i        (clk),
            .rst_n_i      (rst_n_sync),
            .sample_tick_i(tick_audio),
            .valid_i      (mx_valid),
            .sample_i     (mx_sample),
            .gain_i       (master_gain),
            .valid_o      (mm_valid),
            .sample_o     (mm_sample),
            .ramp_busy_o  ()
        );

        // ⭐ 输出寄存：`i2s_tx` 要求数据源**提前一帧**给出本帧样点
        //    ⚠️ 用 `mx_valid` 打一拍 ⇒ 整帧稳定，⛔ 不会在帧中途变化
        reg signed [SAMPLE_W-1:0] sample_r;
        always @(posedge clk) begin
            if (!rst_n_sync) sample_r <= {SAMPLE_W{1'b0}};
            else if (mm_valid) sample_r <= mm_sample;
        end

        //  🔴🔴 2026-10-11（乙）修 bug：⛔ **不能再让 `'Q'` 翻转 `scope_run_r`** ——
        //     原来 `'Q'` 同时翻转 `scope_mode_r`（模式）和 `scope_run_r`（冻结）：
        //       第 1 次 'Q' ⇒ 模式 1→0（切到波形）**并且** 冻结 1→0
        //       ⇒ `scope_valid = mm_valid & scope_run_r` 恒 0
        //       ⇒ ⭐ 采样流被切断 ⇒ 波形数据全空 ⇒ **屏幕上只有中央一条绿线** ✅
        //         （上板实测症状，与 tb 不符 —— 因为 tb 不经过这条命令路径）
        //     ✅ 修法：`'Q'` **只切显示模式**；冻结功能由模式切换取代（不再需要）
        //     📌 语义变更：`'Q'` = 波形 ↔ 李萨如 切换（⛔ 不再是冻结/恢复）
        // 2026-10-12: remove scope_run_r. The prior expression made it equal
        // to the new mode, so selecting mode 0 stopped all history writes.
        // Placement/timing must be revalidated after this functional fix.
        assign scope_sample = mm_sample;
        // Q selects the renderer. Both renderers keep collecting live audio;
        // mode selection must not double as a sample-stream freeze switch.
        assign scope_valid  = mm_valid;
        assign sample_mono = sample_r;

        // ── ⭐ 开机自检音：复位后延时起一个 A4+C#5+E5 和弦 ────────────────
        //    ⚠️ 等 `DEMO_NOTE_DELAY` 再起音（避开上电"啪"声）
        always @(posedge clk) begin
            if (!rst_n_sync) begin
                demo_cnt        <= 24'd0;
                demo_fired      <= 1'b0;
                demo_step       <= 3'd0;
                demo_note_valid <= 1'b0;
                demo_note_axis  <= 4'd0;
                demo_note_inc   <= 32'd0;
                demo_note_vel   <= 8'd0;
                demo_note_kind  <= 2'd0;
            end else begin
                demo_note_valid <= 1'b0;      // 单拍脉冲（冻结表 §〇 约定 4）

                if (!demo_fired) begin
                    if (demo_cnt < DEMO_DELAY_V) begin
                        demo_cnt <= demo_cnt + 1'b1;
                    end else begin
                        // ⭐ 逐拍发三个 note_on（axis 0/1/2 ⇒ 占 voice 0/1/2）
                        case (demo_step)
                            2'd0: begin
                                demo_note_axis  <= 4'd0;
                                demo_note_inc   <= INC_A4;
                                demo_note_vel   <= 8'd200;
                                demo_note_kind  <= 2'd0;
                                demo_note_valid <= 1'b1;
                                demo_step       <= 3'd1;
                            end
                            2'd1: begin
                                demo_note_axis  <= 4'd1;
                                demo_note_inc   <= INC_CS5;
                                demo_note_vel   <= 8'd200;
                                demo_note_kind  <= 2'd0;
                                demo_note_valid <= 1'b1;
                                demo_step       <= 3'd2;
                            end
                            2'd2: begin
                                demo_note_axis  <= 4'd2;
                                demo_note_inc   <= INC_E5;
                                demo_note_vel   <= 8'd200;
                                demo_note_kind  <= 2'd0;
                                demo_note_valid <= 1'b1;
                                demo_step       <= 3'd3;
                            end
                            default: begin
                                // ⭐⭐ **响 `DEMO_HOLD_CYC` 后【自己停】**（⭐ 2026-09-23 改）
                                //
                                //   🔴 **为什么必须停**（⭐ 用户拍板 + 实测发现）：
                                //      ⚠️ 原来这里是 **"一直响着"**（⛔ 不发 `note_off`），
                                //         注释理由是"便于示波器/耳朵确认"。
                                //      🔴 **但那带来一个真问题**：
                                //         · `SOURCE_A_SEL=0`（手弹档）只切了
                                //           **"新音符从哪来"**，⚠️ 而自检和弦在切换
                                //           **之前**就已经起音了
                                //         ⇒ 🔴 **它的 voice 一直占着、声音一直在**
                                //         ⇒ ⚠️ 手弹时会听到 **"自检和弦 + 我弹的音" 混在一起**
                                //      ⭐ 实测证据（e2e tb）：
                                //         `nm_gate = 0x08000000`（⭐ 有一个 voice 恒 held）
                                //         ⇒ ⭐ 等它"自己安静"是**永远等不到**的。
                                //
                                //   ⭐ **用户决定**：⭐ **响 1 秒就停** ——
                                //      ⭐ 它只需要起到【自检】作用（⭐ 上电听得到 ⇒
                                //      证明出声链通），⛔ 不需要一直响。
                                //
                                //   📌 **实现**：⭐ 分两段 ——
                                //      ① `demo_step==3` ⇒ 开始计时（⭐ 和弦正在响）
                                //      ② 计时到 `DEMO_HOLD_CYC` ⇒ ⭐ **逐个发 `note_off`**
                                //         （⭐ 用 `demo_step` 4/5/6 走三个轴 0/1/2）
                                if (demo_cnt < DEMO_HOLD_V) begin
                                    demo_cnt  <= demo_cnt + 1'b1;
                                    demo_step <= 3'd3;          // ⭐ 继续响
                                end else begin
                                    demo_step <= 3'd4;          // ⭐ 计时到 ⇒ 转去发 off
                                    demo_cnt  <= {DEMO_CW{1'b0}};
                                end
                            end
                            // ── ⭐ 逐个发 `note_off`（⭐ 轴 0/1/2，与起音时一致）──
                            3'd4: begin
                                demo_note_axis  <= 4'd0;
                                demo_note_inc   <= INC_A4;
                                demo_note_vel   <= 8'd0;
                                demo_note_kind  <= 2'd1;        // ⭐ 1 = note_off
                                demo_note_valid <= 1'b1;
                                demo_step       <= 3'd5;
                            end
                            3'd5: begin
                                demo_note_axis  <= 4'd1;
                                demo_note_inc   <= INC_CS5;
                                demo_note_vel   <= 8'd0;
                                demo_note_kind  <= 2'd1;
                                demo_note_valid <= 1'b1;
                                demo_step       <= 3'd6;
                            end
                            3'd6: begin
                                demo_note_axis  <= 4'd2;
                                demo_note_inc   <= INC_E5;
                                demo_note_vel   <= 8'd0;
                                demo_note_kind  <= 2'd1;
                                demo_note_valid <= 1'b1;
                                demo_step       <= 3'd7;
                            end
                            // ── ⭐ 收尾：⭐ `demo_fired` 自锁，⛔ 不再发任何音 ──
                            3'd7: begin
                                demo_fired <= 1'b1;
                            end
                        endcase
                    end
                end
            end
        end
    end
    endgenerate


    i2s_tx #(
        .SAMPLE_W  (SAMPLE_W),
        .DATA_BITS (DATA_BITS),
        .SLOT_BITS (32),          // 每声道 32 个 BCK（冻结口径 64 × fs）
        // ⭐ 2026-09-22 换板 Tang Console 60K：音频器件是 `MAX98357A`，
        //    ⭐ 按【标准 I2S / 左对齐】解析 ⇒ `JUSTIFY` 1 → **0**。
        //    ⚠️ 旧板 NEO Dock 的 `PT8211` 是 LSBJ/右对齐（原来这里是 1）。
        //    ⚠️ 两种都能出声、只是整体移位 ⇒ ⭐ 上板须用示波器对 `WS`/`DIN` 相位确认（`C-6`）。
        .JUSTIFY   (0),           // ⭐ 0 = 标准 I2S 左对齐（MAX98357A）
        .MSB_DELAY (1),           // 标准 I2S 的 MSB 延迟 = 1 BCK（⛔ 不用改）
        .LRCK_POL  (0)            // WS 低 = 左声道（⭐ 单声道通路，极性无影响）
    ) u_i2s_tx (
        .clk          (clk),
        .rst_n        (rst_n_sync),
        .bclk_en      (bclk_en),
        .bclk_half_en (bclk_half_en),
        .frame_start  (frame_start),
        .sample_l     (sample_mono),
        .sample_r     (sample_mono),
        .HP_BCK       (HP_BCK),
        .HP_WS        (HP_WS),
        .HP_DIN       (HP_DIN)
    );

    // ═══════════════════════════════════════════════════════════════════════
    //   ⭐⭐ 外置 DAC 通路（`PCM5102A` 模块，⭐ 2026-09-25 新增 · 路线 A）
    //
    //   ⭐ **与 `u_i2s_tx`【同参数、同数据源、同节拍】** ⇒ ⭐ 两路天然同步。
    //   🔴 **为什么单独一个实例而不是"一个 i2s_tx 驱动两组引脚"**：
    //      ⭐ `i2s_tx` 的输出是 `output reg`（⭐ 无法一驱二）
    //      ⚠️ 且两者**将来可能需要不同参数**（⭐ 例如外置模块要 `JUSTIFY=1`）
    //      ⇒ ⭐ **两个实例最灵活**，⭐ 代价仅 3 个引脚 + 少量逻辑。
    //
    //   ⚠️ **为什么不加 `AUDIO_OUT_SEL` 参数**（⭐ 路线 C）：
    //      ⭐ 两路**同时输出**没有副作用（⭐ 外置 DAC 不接就没影响）
    //      ⇒ ⭐ **不需要开关** ⇒ ⚠️ 少一个参数、少一个变异点。
    //
    //   📌 **`PCM5102A` 的 `JUSTIFY` 也是 0**（⭐ 它按标准 Philips I2S 解析）
    //      ⇒ ⭐ 与 `MAX98357A` **同一档** ⇒ ⭐ 这里直接沿用上面那组参数。
    //      ⚠️ 但**若上板听到"移位/噪声"** ⇒ ⭐ 优先调【这一路】的 `JUSTIFY`/`MSB_DELAY`
    //         （⭐ 板载那路已经验证过是对的）—— ⭐ 见 `C-6`。
    // ═══════════════════════════════════════════════════════════════════════
    i2s_tx #(
        .SAMPLE_W  (SAMPLE_W),
        .DATA_BITS (DATA_BITS),
        .SLOT_BITS (32),
        //   🔴🔴 **2026-09-26 上板实测更正**：⭐ 外置 `PCM5102A` 要的是
        //      ⭐ **MSB 无延后的左对齐**（⭐ 即 `MSB_DELAY = 0`），⛔ **不是标准 I2S**！
        //
        //   ⭐ **实测经过**（⭐ 决定性）：
        //      · 用 `bringup/dac_tone/dac_tone_top.v` 出的【三档】bitstream 逐个烧：
        //         `FORMAT_SEL=0`（标准 I2S，MSB 延后 1）⇒ 🔴 **没声**
        //         `FORMAT_SEL=1`（左对齐，MSB 无延后）⇒ ⭐ **出声了** ✅
        //      · 且模块的 `FMT` 脚接 **3V3**（⭐ = 手册的 "High = Left-justified"）
        //   📌 **术语陷阱**：⭐ `i2s_tx` 这个模块里的 `JUSTIFY=0` 指的是
        //      **"Philips 标准 I2S"**（⭐ 数据在 WS 翻转后【延迟】`MSB_DELAY` 位），
        //      ⚠️ ⛔ **不是**字面意义的"左对齐" —— ⚠️ 别被名字误导。
        //      ⭐ 真正要"左对齐" ⇒ ⭐ **`JUSTIFY=0` + `MSB_DELAY=0`**。
        //   ⚠️ **与板载那一路的区别**：⭐ 板载 `MAX98357A` 用 `MSB_DELAY=1`（标准 I2S）
        //      ⇒ ⭐ **两路参数不同，这是故意的**（⭐ 实测各自都对）。
        .JUSTIFY   (0),
        .MSB_DELAY (0),           // ⭐ 外置 PCM5102A：左对齐（⭐ 实测出声）
        .LRCK_POL  (0)            // ⭐ 与板载同极性（低 = 左声道）
    ) u_i2s_tx_ext (
        .clk          (clk),
        .rst_n        (rst_n_sync),
        .bclk_en      (bclk_en),
        .bclk_half_en (bclk_half_en),
        .frame_start  (frame_start),
        .sample_l     (sample_mono),
        .sample_r     (sample_mono),   // ⭐ 单声道 ⇒ 左右同源（⭐ 与板载一致）
        .HP_BCK       (I2S2_BCK),
        .HP_WS        (I2S2_LRCK),
        .HP_DIN       (I2S2_DIN)
    );

    // ── ⚠️⚠️ `PA_EN_n`：⭐ 换板后【语义变了】—— 从"低有效功放使能"变成"多电平模式选择" ──
    //
    //   🔴 **2026-09-22 换板 Tang Console 60K 的结论（U-25b）**：
    //      ⭐ **Console 上【不存在】** `PA_EN` 这个功放使能脚。
    //      ⚠️ `PA_EN` **网络** = SOM pin 52 = **`Y14`**，经 `R54 (0R)` 直连
    //         `MAX98357A` 的 **`SD_MODE`**，且该网络**只有 `R89 51K` 下拉**
    //         （⛔ **不是分压** ⇒ **电平完全由本脚决定**；⚠️ 芯片内部还有 `100 kΩ` 下拉
    //          ⇒ ⛔ **悬空也是 Shutdown**）。
    //      🔴 **`SD_MODE` 是多电平输入（手册）**：
    //         | 电平 | 模式 |
    //         | **`< 0.16 V`** | 🔴 **`Shutdown`（没声音）** |
    //         | `0.16~0.77 V` | `(L+R)/2` |
    //         | `0.77~1.4 V` | Right |
    //         | **`> 1.4 V`** | ⭐ **Left（我们要的）** |
    //      ⇒ ⭐⭐ **要出声必须驱动【高】、⛔ 不是低**（⭐ 低 = 静音）。
    //
    //   🔴 **本条就是"换板后板子没声音"的根因**：
    //      ⚠️ 旧代码（为 `NEO Dock` 的 `NS4263` 写的）在 `PA_ON_AFTER_RESET=1` 时
    //      **把 `PA_EN_n` 拉低** ⇒ ⭐ **落进 `Shutdown`** ⇒ 🔴 **板子不出声**。
    //      ⚠️ 而 `.cst` 已改对（`Y14`/`LVCMOS15`）⇒ ⭐ **只改 `.cst` 不改 RTL 依然没声音**。
    //
    //   ⭐ **本模块现在的做法**：
    //      ① ⭐ **`PA_ON_AFTER_RESET=1`（默认）⇒ 恒【高】** ⇒ `SD_MODE` 取 **Left**；
    //         ⭐ 我们 `sample_l`/`sample_r` 送的是**同一路单声道** ⇒ **取左或取右都一样**；
    //      ② ⛔ **不再产生任何"下降沿脉冲"**（⭐ 那套 `NS4263` 一线脉冲语义在 Console 上无意义）；
    //      ③ ⭐ **端口与引脚约束保留** ⇒ ⛔ **不用改冻结的端口列表**（§〇 约定 5 要通知全员）；
    //      ④ ⭐ **`PA_ON_AFTER_RESET=0` 保留为 `NEO Dock` 回退档**：那时它=**低**
    //         （⚠️ 旧板上 **低 = NS4263 的 AB 类桥式输出**，即"出声"那侧）。
    //
    //   ⚠️ **电平注意**：`Y14` 属 **`BANK9` = 1.5 V** ⇒ ⛔ 必须 `LVCMOS15`（`.cst` 已对），
    //      驱动高 ≈ `1.3~1.5 V` ⇒ ⭐ 仍 **> 1.4 V 门槛的临界/达标** ⇒ ⭐ **上板实测确认取 Left**。
    reg pa_en_n_r;

    generate
        if (PA_ON_AFTER_RESET == 0) begin : g_pa_off
            // ⭐ **NEO Dock 回退档**：旧板上"低"= AB 类桥式输出（出声）⇒ 恒低。
            //   ⚠️ 若把本档用到 Console 上 ⇒ 🔴 **`SD_MODE` < 0.16 V = Shutdown = 没声音**。
            always @(posedge clk) begin
                if (!rst_n_sync) pa_en_n_r <= 1'b0;
                else             pa_en_n_r <= 1'b0;
            end
        end else begin : g_pa_on
            // ⭐⭐ **Console 交付档（默认）**：恒【高】⇒ `SD_MODE` = Left ⇒ **出声**。
            //   ⚠️ 为什么【无条件恒高、⛔ 不要延时计数器】：
            //      ⭐ 旧逻辑是"等 `PA_ON_DELAY` 拍后拉低一次"（为 `NS4263` 造**恰好 1 个下降沿**）。
            //      🔴 在 Console 上**那个下降沿本身就是致命动作** —— 它把 `SD_MODE` 从
            //         "Left（出声）"打到 "Shutdown（静音）"。
            //      ⇒ ⭐ **正确做法是【从头到尾保持高】**：⭐ 复位期间就是高
            //        （⚠️ 这同时满足"上电无爆音"——`SD_MODE` 全程不出 Shutdown 跳变）。
            //   📌 `PA_ON_DELAY` 参数**保留**（⛔ 不删）⇒ ⚠️ 供回退档/将来需要时使用，
            //      但本档**不再使用它**（⭐ 若将来要"软启"应先确认不会跌破 `SD_MODE` 门槛）。
            always @(posedge clk) begin
                if (!rst_n_sync) pa_en_n_r <= 1'b1;   // ⭐ 复位期间即为高（配置期靠 .cst 的 PULL_UP=UP）
                else             pa_en_n_r <= 1'b1;   // ⭐ 永远保持高 ⇒ ⛔ 无任何下降沿
            end
        end
    endgenerate

    assign PA_EN_n = pa_en_n_r;

    // ── ⭐⭐ 参数自检（`R-16`，与 `clk_gen`/`tlc5916` 的 `PARAM_OK` 同一套路）──────────
    //   ⚠️ 为什么要有它：这两个档位的**错误选择会静默失效**，而且**现象极难定位**：
    //     ① `PA_ON_AFTER_RESET=0` ⇒ 在 **Console** 上 `SD_MODE` 被拉低 ⇒
    //        落进 **`Shutdown`（< 0.16 V）⇒ 没声音**，但 I2S 波形、DAC 输入、仿真结论
    //        **全都是对的** ⇒ 会让人去查 RTL，白费几小时；
    //     ② ⚠️ 反向：`=1` 若用到 **NEO Dock** 上 ⇒ 旧板 `SD` 高 = **低功耗关断** ⇒ 同样没声音。
    //   ⇒ 仿真启动时**明确打印状态**（⛔ 不是报错，因为两个档位各自对一块板合法）。
    //   ⚠️ 换算成 ms 时**先除后乘**（避免 `PA_ON_DELAY * 1000` 在 20 位/32 位里溢出；
    //      同 `tlc5916` 的 `PER_CLK_NS`，见 `K-63`）。
    localparam integer PA_CLK_HZ       = 50_000_000;                                // V22 = 50 MHz（已查实）
    localparam integer PA_MS_X10       = (PA_ON_DELAY / (PA_CLK_HZ / 10_000)) ;      // 0.1 ms 单位
    initial begin
        if (PA_ON_AFTER_RESET == 0)
            $display("NOTE [top] PA_ON_AFTER_RESET=0 => PA_EN_n held LOW. On NEO Dock that is AB-class (SOUNDS). On Console that is SD_MODE<0.16V = Shutdown = NO SOUND (U-25b). Use 1 for Console.");
        else
            $display("NOTE [top] PA_ON_AFTER_RESET=1 => PA_EN_n held HIGH forever (0 falling edges). On Console SD_MODE=Left => SOUNDS (U-25b). On NEO Dock high = shutdown, so only use 0 there.");
    end

    // ── 心跳 LED（活体见证 ＋ ⭐ 故障指示）───────────────────────────
    //  ⭐⭐ 2026-10-01 BATCH 8.3（⭐ 重做）：⭐ **心跳 LED 兼作【故障指示】** ⚠️
    //   🔴 **原缺陷**：⭐ `af_fault`（⭐ `adc_farm` 的 SPI/片选故障）与 `mx_fault`
    //      （⭐ `tdm_render_mixer` 的 `deadline_fault_o`）**都接上了，⭐ 但【没人消费】** ⚠️
    //      ⇒ 🔴 **出了故障也看不见** —— ⭐ 正是 `K-106` 家族的"**静默失败**" ✅
    //   ✅ **修法**：⭐ 锁存一个 sticky 故障位 ⇒ ⭐ **心跳灯改成"快闪"** ✅
    //      ⭐ **判据（⭐ 上板一眼可辨，⛔ 不用仪器）**：
    //         · ⭐ **无故障** ⇒ ⭐ **慢闪**（⭐ 半周期 `HEARTBEAT_DIV` = **0.5 s** ✅）
    //         · 🔴 **有故障** ⇒ ⭐ **快闪**（⭐ 半周期 `HEARTBEAT_DIV>>3` = **62.5 ms**，⭐ 8 Hz ✅）
    //      📌 **为什么选灯**：⭐ **零额外引脚** ＋ ⭐ **肉眼可辨** ✅（⭐ 比翻串口更直接 ✅）
    //      📌 **语义一致性**：⭐ `deadline_fault_o` 本来就是 **sticky**
    //         （⭐ 见 `tdm_render_mixer` 注释："一旦超时永久置位" ✅）
    //         ⇒ ⭐ 这里对 `af_fault` 也做锁存 ⇒ ⭐ **两者语义统一** ✅
    //      ⚠️ **只有复位才清**（⭐ 与 `deadline_fault_o` 同纪律 ✅）—— ⭐ 这样"曾经出过错"
    //         不会被后续正常帧掩盖 ✅
    //   ⚠️ **作用域纪律**（⭐ 第一次就栽在这 ✅）：⭐ `fault_any_w` 由 `g_sound` 块内的
    //      `assign` 驱动（⭐ 那里 `af_fault`/`mx_fault` 才可见 ✅）⇒ ⭐ 本块**只引它** ✅
    //   📌 **它的声明在【模块级、`generate` 之前】**（⭐ 见上方 `txf_*` 那批 wire 的后面 ✅）
    //      —— ⚠️ 一开始我声明在心跳灯那段 ⇒ 🔴 **声明晚于使用** ⇒ ⭐ 工具隐式建 wire
    //      ⇒ ⚠️ `warning: implicit definition`（⭐ `default_nettype none` 下会变硬错误 ✅）

    reg fault_sticky;
    always @(posedge clk) begin
        if (!rst_n_sync)         fault_sticky <= 1'b0;
        else if (fault_any_w)    fault_sticky <= 1'b1;   // ⭐ sticky
    end

    // ⭐ 有故障 ⇒ ⭐ 快闪（⭐ 半周期缩到 1/8 ✅）
    wire [31:0] hb_div_eff = fault_sticky ? (HEARTBEAT_DIV >> 3) : HEARTBEAT_DIV;

    reg [31:0] hb_cnt;
    reg        hb;

    always @(posedge clk) begin
        if (!rst_n_sync) begin
            hb_cnt <= 32'd0;
            hb     <= 1'b0;
        end else if (hb_cnt >= hb_div_eff - 1) begin
            hb_cnt <= 32'd0;
            hb     <= ~hb;
        end else begin
            hb_cnt <= hb_cnt + 1'b1;
        end
    end

    assign led_heartbeat = hb;

    // ═══════════════════════════════════════════════════════════════════════
    // ⭐⭐ LED 演奏指引链（⭐ 丙 · 2026-09-24 接入）
    //
    //   链：`led_data`（逻辑图案，CH 序）→ `tlc5916_bank`（CH→OUT 重映射
    //       + 共享总线三片逐写 + 分板 OE）→ 顶层 `led_*` 端口。
    //
    //   ⚠️ **输入源（key_active/guide_key）当前用占位**：
    //      · `key_active`（哪些键在响）→ 正确来源应是 `event_extract` 的 16 位
    //        `key_on`，但该信号**尚未引出成 16 bit 端口**（甲的 `event_extract.v`）。
    //      · `guide_key`（哪些键该按）→ 正确来源是 `play_seq`，但**尚未例化**（甲）。
    //      ⇒ 本版先接 `1'b0`，接口已留好，等甲补输入源时**只改这两根**，⛔ 不用动
    //        `led_data` / `tlc5916_bank` 本体。
    //   ⚠️ **blink 用 `bg_beat`**（四分音符拍点，低速单周期脉冲），
    //      "下一个键"跟随拍点闪烁。
    // ═══════════════════════════════════════════════════════════════════════
    wire [23:0] led_pattern;
    wire        led_pattern_commit;
    wire        led_busy;

    // ═══════════════════════════════════════════════════════════════════════
    //  ⭐⭐ 2026-10-11：⭐ **LED 指引链复活 —— `guide_lamp` 接入** ✅
    //
    //  🔴 **改前（⭐ 诚实记录）**：⭐ `led_data.guide_key_i` 是**占位 `16'd0`**
    //     ⇒ ⭐ "**该按哪个键**"那半**从来不工作**（⭐ 只有"正在响的键"亮 —— `P0-27` 修的）
    //     ⚠️ 根因不是 `led_data` 写错，⭐ 而是**它的上游从未被例化** ✅
    //
    //  ⭐ **缺的那一环是什么**：⭐ `play_seq` 吐的是**音符事件**（64 bit），
    //     ⚠️ 而 `led_data` 要的是 **16 位 one-hot 位图**（"哪个键该按"）
    //     ⇒ ⭐ `guide_lamp` 就做这一层 **事件 → 位图** 转换（⭐ 它早已写好并验收过 ✅）
    //     ⇒ ⭐ 而 `play_seq` 又必须先有 `U-19` 缓冲才能例化
    //     ⇒ ⭐ **本行就是"三级依赖链"的最后一环** ✅
    //        （⭐ `U-19 缓冲 ⇒ play_seq ⇒ guide_lamp ⇒ led_data.guide_key_i`）
    //
    //  ⭐ **为什么用 `guide_vis_o`（⭐ 消隐后）而⛔ 不是 `guide_key_o`**：
    //     ⭐ `guide_vis_o = guide_key_o & ~key_active_i`（⭐ `P0-28` 修的）
    //     ⇒ ⭐ **已经按下的键不再被指引** ⇒ ✅ 用户能分清"该按的"和"正在响的" ✅
    //     📌 ⭐ 而 `key_active_i` 用的是**同一个 `ee_key_on`**（⭐ 与 `led_data` 同源）
    //        ⇒ ⭐ 两边的"已按下"口径**必然一致** ✅
    //
    //  📌 ⭐ **闪烁**由 `led_data` 自己做（⭐ `blink_keys & blink_i`）——
    //     ⚠️ `guide_lamp` 的 `blink_i` 端口**已删**（⭐ `P0-28`：⭐ 两处都做会变成 25% 占空比 ✅）
    // ═══════════════════════════════════════════════════════════════════════
    wire [15:0] gl_guide_vis;

    guide_lamp #(
        .EVT_W  (64),
        .AXIS_N (16)
    ) u_guide_lamp (
        .clk_i          (clk),
        .rst_n_i        (rst_n_sync),
        //  ⭐ 来自 `g_sound.u_play_seq`（⭐ 模块级中间量 —— 跨 generate 作用域 ✅）
        .note_valid_i   (ps_note_valid),
        .note_data_i    (ps_note_data),
        //  ⭐ 消隐用：⭐ 与 `led_data` **同一个源**（⭐ 保证口径一致 ✅）
        .key_active_i   (ee_key_on),
        //  ⚠️ 未消隐的原图**无消费者** ⇒ ⭐ 留空（⭐ 消隐后的那根才是要接的 ✅）
        .guide_key_o    (),
        .guide_commit_o (),
        .guide_vis_o    (gl_guide_vis)
    );

    // 逻辑图案层：键灯（16，CH 序）+ 状态灯（8）→ 24 bit
    led_data #(
        .KEY_N    (16),
        .STATUS_N (8)
    ) u_led_data (
        .clk_i           (clk),
        .rst_n_i         (rst_n_sync),
        //  ⭐⭐ 2026-10-11：⭐ **占位换成真源**（⭐ 原来写的是 `16'd0`）✅
        //     ⇒ ⭐ **"该按哪个键"的指引灯从此真的会亮** ✅
        .guide_key_i     (gl_guide_vis),
        //  ⭐⭐ 2026-10-09（`P0-27`）：⭐ **接真源**（⭐ 原来是占位 `16'd0`）✅
        //   ✅ `ee_key_on` = `event_extract.key_on[]` 的打包版（⭐ 模块级 wire）
        //   📌 ⭐ 这一接 ⇒ ⭐ 按键就亮（⭐ 16 个键灯复活）✅
        //   ⚠️ **遗留**：⭐ `guide_key_i`（⭐ "该按的键"）**仍是占位** ——
        //      ⭐ 它的正确来源是 `play_seq`，⛔ 而 `play_seq` **尚未例化**（⭐ top.v 里的"甲"）
        //      ⇒ ⭐ 所以"指引"那半仍不工作（⭐ 见 P0-27 的诚实标注）✅
        .key_active_i    (ee_key_on),
        .status_i        (8'd0),             // ⭐ 占位：待 UI 状态总线
        .blink_i         (led_blink),        // ⭐ 四分音符拍点 = 闪烁节拍
        .pattern_o       (led_pattern),
        .pattern_commit_o(led_pattern_commit)
    );

    // 物理驱动层：CH→OUT 重映射 + 共享总线三片逐写 + 分板 OE
    tlc5916_bank #(
        .KEY_CHIPS    (2),
        .STATUS_CHIPS (1),
        .OE_N         (5)
    ) u_led_bank (
        .clk_i           (clk),
        .rst_n_i         (rst_n_sync),
        .pattern_i       (led_pattern),
        .pattern_commit_i(led_pattern_commit),
        .global_blank_i  (1'b0),
        .led_sdi_o       (led_sdi),
        .led_clk_o       (led_clk),
        .led_le_o        (led_le),
        .led_oe_n_o      (led_oe_n),
        .busy_o          (led_busy)
    );

    // ═══════════════════════════════════════════════════════════════════════
    // 🔴🔴 预留引脚（⭐ 2026-10-03 画板线申请单）—— ⭐ **只为"让脚活着"**，⛔ 不是功能逻辑
    //
    //   🔴 **为什么必须有这一段**：⭐ 综合会把**未使用的输入**优化掉、
    //      把**未驱动的输出**接死 ⇒ ⚠️ `constr/top.cst` 里那 20 条 `IO_LOC` 就**悬空**了
    //      （⭐ 引脚不进网表 ⇒ ⭐ 分配等于没写）。
    //
    //   ⭐ **11 个输入**：⭐ **异或归并**到一个 `syn_keep` 寄存器 `reserved_in_r`
    //      ⇒ ⭐ **任何一根输入翻转都会让它翻转** ⇒ ⭐ 综合**不能**把它们当常量去掉。
    //      📌 `syn_keep` = Synplify / Gowin 的"⛔ 不要优化掉这个信号"属性。
    //
    //   ⭐ **9 个输出**：⭐ 其中 **8 个由常量**驱动（⭐ 明确电平，⛔ 不是 `x`）；
    //      ⭐ `ctrl_ws_o` **已接真实驱动**（⭐ 2026-10-03 · 见下方 §WS2812）：
    //      · ⭐ `ctrl_row_o = 4'b0000` —— ⭐ 矩阵行**全 0 = 不扫描**；
    //        🔴 **为什么不给高**：⚠️ 行若给高，⭐ 同一列上按两个键会**把两个输出短接**
    //           （⭐ 推挽对打）⇒ ⭐ 全 0 是**无冲突**的安全态。
    //      · ⭐ `ws_strip_o = 3'b000` —— ⭐ 拓展板 3 路**预留**（⭐ WS2812 单线码空闲 = 低）✅
    //      · ⭐ `ctrl_ws_o` —— ⛔ **不再在此驱动**（⭐ 已由 `u_ws2812` 驱动）✅
    //      · ⭐ `esp_uart_tx_o = 1'b1` —— 🔴 **UART 空闲 = 高**（⭐ 串口线**静默**的正确态）；
    //        ⚠️ 若给 0 ⇒ ⭐ 一直处于 **break** ⇒ ⭐ ESP32 侧会看到**持续帧错误**。
    //
    //   🔴🔴 **接入功能逻辑时**（⭐ 按申请单 §6 分批）：
    //      ⇒ ⭐ **必须删掉该端口在这里的驱动行**（⛔ 否则**多驱动** ⇒ 综合报错）；
    //      ⇒ ⭐ 输入侧还要把它**从 `reserved_in_xor` 里摘掉**（⭐ 交给新逻辑消费）。
    //   📌 本段**不改任何现有行为**：⭐ 只多一个 FF `reserved_in_r`，
    //      ⛔ 不与任何现有信号相连（⭐ 现有 tb 的判据不受影响）。
    // ═══════════════════════════════════════════════════════════════════════

    // ── ⭐ 预留输入 · 异或归并（⭐ 预留，等控制板逻辑接入）───────────────────
    //  ⭐⭐ 2026-10-04（T5）：⭐ **`pedal_sus_i` 已从本行【摘掉】** —— ⭐ 它现在有真消费者了
    //     （⭐ `u_note_manager.sus_pedal_i`，见上面 §延音踏板）⇒ ⭐ 不再并进异或归并 ✅
    //     📌 依据本文件末段 §"接入功能逻辑时"的纪律：⭐ "输入侧还要把它从
    //        `reserved_in_xor` 里摘掉（交给新逻辑消费）" ✅
    //     📌 因此本行从 **11 个** 输入变成 **10 个**（⭐ 下面注释里的数字同步更正 ✅）
    (* syn_keep = 1 *) wire reserved_in_xor = ^{ctrl_col_i, enc_a_i, enc_b_i, enc_sw_i,
                                                pedal_loop_rec_i,
                                                pedal_loop_play_i};
    //  ⭐⭐ 2026-10-11：⭐ **`esp_uart_rx_i` 已从本行【摘掉】** ✅
    //     ⭐ 依据本文件 `:5390` 自己写明的接入纪律：
    //        *"输入侧还要把它从 `reserved_in_xor` 里摘掉（交给新逻辑消费）"* ✅
    //     ⭐ 它现在的消费者 = `u_uart_rx_esp` ⇒ ⭐ **曲谱接收器** ✅
    //     📌 因此本行从 **10 个** 输入变成 **9 个** ✅

    (* syn_keep = 1 *) reg  reserved_in_r;
    always @(posedge clk) begin
        if (!rst_n_sync) reserved_in_r <= 1'b0;
        else             reserved_in_r <= reserved_in_xor;
    end

    // ── 9 个预留输出 · 常量驱动（⭐ 明确电平，⛔ 不是 `x`）────────────────────
    assign ctrl_row_o    = 4'b0000;   // ⭐ 矩阵行全 0 = 不扫描（⛔ 不给高：⚠️ 同列两键会推挽）
    // ⭐ `ctrl_ws_o` 已由 `u_ws2812` 驱动（⭐ 见下方 §WS2812）—— ⛔ 常量驱动行已删除
    //  ⭐⭐ 2026-10-11：⭐ **`esp_uart_tx_o` 的常量驱动行【已删除】** ✅
    //     ⭐ 依据本文件 `:5390` 的接入纪律：*"接入功能逻辑时 ⇒ ⭐ **必须删掉该端口
    //        在这里的驱动行**（⛔ 否则**多驱动** ⇒ 综合报错）"* ✅
    //     ⭐ 它现在由 `u_uart_tx_esp` 驱动（⭐ 与板载口镜像同一份回包 ✅）
    //     📌 ⭐ **原值 `1'b1`（UART 空闲高）** —— ⚠️ 现在由 `uart_tx` 自己保证
    //        （⭐ 它空闲时输出高 ✅）⇒ ⭐ **行为等价、⛔ 不再有 break 风险** ✅
    // ═══════════════════════════════════════════════════════════════════════
    // ⭐ WS2812 · 控制板灯带驱动（2026-10-03 接入）
    //
    //   🔴 为什么现在接：⭐ `constr/top.cst` 里的 `ctrl_ws_o`（C22）原本只靠
    //      **常量驱动保活**（⭐ 目的仅是"让脚进网表"），⭐ 现在改由真驱动产生波形
    //      ⇒ ⛔ 它的常量驱动行必须删除（⭐ 否则与驱动模块**多驱动** ⇒ 综合报错）。
    //
    //   ⭐ 为什么只做 1 通道：⭐ 用户的 7 路指示灯**全部串在控制板这一条带**上
    //      ⇒ ⭐ 主通道 = `ctrl_ws_o`；⭐ 拓展板那 3 根（`ws_strip_o[2:0]`）
    //      是**预留** ⇒ ⛔ 暂不驱动，保持常量 `3'b000`（灭）✅
    //
    //   ⭐ 数据源（⭐ 2026-10-03 起）：⭐ **指示层 `u_led_indicator`**（⭐ 见下方）——
    //      ⚠️ 原来是"上电自检图案"（前 7 颗恒亮蓝）⇒ ⭐ 那个占位已被**真状态**取代
    //      （⭐ 上电后 led0 亮 / led4 暗蓝 / led6 绿 ⇒ ⭐ 照样看得见"板子活着"）✅
    //      📌 将来若要做 LED 演奏指引 / M7 灯效：⭐ 再加一路数据源进那个 `case` 即可
    //      （⭐ 位时序与 `start_i` 握手**不用改**）。
    //
    //   ⚠️ `wr_data_i` = `24'hRRGGBB`（⭐ 标准 RGB888）——
    //      ⭐ 到线上的 **GRB** 重排由 `ws2812_driver` 内部做（⭐ 只此一处定义，好测）。
    // ═══════════════════════════════════════════════════════════════════════
    localparam integer WS_LED_N = 16;     // ⭐ 控制板灯带灯数（⭐ 改灯数只改这一个参数）

    wire        ws_busy;
    wire        ws_start;
    reg  [1:0]  ws_ld_state;
    reg         ws_wr_en;
    reg  [4:0]  ws_wr_addr;
    reg  [23:0] ws_wr_data;   // ⭐ 2026-10-03：⭐ 改由 `always @*` 从 7 路颜色里选（原来是常量 assign）
    wire        ws_dout;

    localparam [1:0] WLS_WRITE = 2'd0;
    localparam [1:0] WLS_START = 2'd1;
    localparam [1:0] WLS_WAIT  = 2'd2;

    ws2812_driver #(.LED_N(WS_LED_N)) u_ws2812 (
        .clk       (clk),
        .rst_n     (rst_n_sync),
        .start_i   (ws_start),
        .busy_o    (ws_busy),
        .wr_en_i   (ws_wr_en),
        .wr_addr_i (ws_wr_addr),
        .wr_data_i (ws_wr_data),
        .dout_o    (ws_dout)
    );

    assign ctrl_ws_o  = ws_dout;          // ⭐ 控制板灯带（C22）
    assign ws_strip_o = 3'b000;           // ⭐ 拓展板 3 路【预留】= 灭（⛔ 暂不驱动）

    // ═══════════════════════════════════════════════════════════════════════
    // ⭐⭐ 2026-10-03：⭐ **指示层（第 2 层）** —— 状态码 → 颜色/闪烁
    //
    //   ⭐ 出处：`files/20-代码/WS2812指示层规格-20261003.md`（⭐ 用户给定的 7 路语义）
    //   ⭐ 三层：各子系统状态码（第 1 层）→ **本模块**（第 2 层）→ `ws2812_driver`（第 3 层）
    //
    //   ⭐ 7 路 = 灯带上**前 7 颗**（LED0..LED6），⭐ 一颗对一个东西：
    //       led0 音色 · led1 节拍器 · led2 鼓机 · led3 键盘打鼓 ·
    //       led4 looper · led5 推子功能 · led6 指板/键盘模式
    //
    //   🔴 **本段替换掉了原来的"上电自检图案"**（前 7 颗恒亮蓝 `24'h000020`）——
    //      ⭐ 那个占位的唯一目的（让 `ctrl_ws_o` 有**真实波形**）由**真状态**接管：
    //      ⭐ 上电后 led0 亮（音色 = 白）、led4 暗蓝（looper 空闲）、led6 绿（键盘模式）
    //      ⇒ ⭐ 眼睛/示波器照样看得见"板子活着"，⭐ 而且每颗灯现在**有语义** ✅
    //
    //   ⭐ `led_drum_on` 的取法（⭐ ⛔ 不新增状态机，⭐ 全部读现成信号）：
    //      ⭐ 源 B 是"节拍器 / 鼓机"**二选一**（`SEL_DRUM`）＋ 编译期总闸
    //      （`METRONOME_ON`）＋ 运行时开关（`met_on_r`）
    //      ⇒ ⭐ 只有三者都成立时，鼓机才**真的在出声** ⇒ ⭐ 那时才显示节奏型颜色
    //      🔴 **与 `g_sound` 里 `src_b_valid` 的算式逐项一致** ⇒ ⭐ 改一处必须改两处
    //         （⭐ 否则指示灯会说"鼓机在响"而实际不响 —— ⚠️ 比不亮更坏）
    // ═══════════════════════════════════════════════════════════════════════
    wire led_drum_on = (SEL_DRUM == 1) && (METRONOME_ON != 0) && met_on_r;

    led_indicator #(.N_CH(NCH_LED)) u_led_indicator (
        .clk        (clk),
        .rst_n      (rst_n_sync),
        .timbre_i   (timbre_sel_r),         // ⭐ 第 1 层：⭐ 全部是**现成**信号
        .metro_on_i (met_on_r),
        .beat_i     (led_beat),
        .drum_on_i  (led_drum_on),
        .drum_pat_i (drum_pattern_r),
        .keydrum_i  (key_drum_r),
        .looper_i   (led_looper_st),
        .gear_i     (led_gear_st),
        .fb_mode_i  (play_fretboard_mode),  // ⭐ 1 = 指板 · 0 = 键盘
        .led_col_o  (led_col_flat)
    );

    // ⭐ 7 路颜色 → 灯带写口（⭐ LED0..LED6）；⭐ LED7..LED15（`WS_LED_N=16`）恒灭
    //   ⚠️ 为什么用 `case` 而不是"按 `ws_wr_addr*24` 切 `led_col_flat`"：
    //      ⭐ 那样当地址 ≥ 7 时是**越界选择**（⭐ 仿真出 `x`）⇒ ⚠️ 靠外层三元挡住很脆；
    //      ⭐ `case` 的 `default` 把"其余灯"**明确**写成灭 ✅
    always @* begin
        case (ws_wr_addr)
            5'd0: ws_wr_data = led_col_flat[  0 +: 24];
            5'd1: ws_wr_data = led_col_flat[ 24 +: 24];
            5'd2: ws_wr_data = led_col_flat[ 48 +: 24];
            5'd3: ws_wr_data = led_col_flat[ 72 +: 24];
            5'd4: ws_wr_data = led_col_flat[ 96 +: 24];
            5'd5: ws_wr_data = led_col_flat[120 +: 24];
            5'd6: ws_wr_data = led_col_flat[144 +: 24];
            default: ws_wr_data = 24'h000000;
        endcase
    end

    // ⭐ 先把整帧写完，再发一个 `start_i` 脉冲；⭐ `busy_o` 高时什么都不做。
    //   ⚠️ `busy_o` **覆盖帧尾复位**（≥300 µs）⇒ "等 !busy 再启动"天然满足帧间隔，
    //      ⛔ 这里不需要（也不该）再写一个复位计数器。
    always @(posedge clk) begin
        if (!rst_n_sync) begin
            ws_ld_state <= WLS_WAIT;
            ws_wr_en    <= 1'b0;
            ws_wr_addr  <= 5'd0;
        end else begin
            ws_wr_en <= 1'b0;
            case (ws_ld_state)
                WLS_WAIT: if (!ws_busy) begin
                    ws_wr_en    <= 1'b1;
                    ws_wr_addr  <= 5'd0;
                    ws_ld_state <= WLS_WRITE;
                end
                WLS_WRITE: begin
                    if (ws_wr_addr == WS_LED_N - 1) begin
                        ws_ld_state <= WLS_START;
                    end else begin
                        ws_wr_en   <= 1'b1;
                        ws_wr_addr <= ws_wr_addr + 5'd1;
                    end
                end
                default: ws_ld_state <= WLS_WAIT;   // WLS_START：只停 1 拍 = start 脉冲
            endcase
        end
    end

    assign ws_start = (ws_ld_state == WLS_START);

endmodule